window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["教育部"] = {"jiaoshizigetiaolishishibanfa":[{"i":1,"n":"第一条","txt":"为实施教师资格制度，依据《中华人民共和国教师法》（以下简称《教师法》）和《教师资格条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"符合《教师法》规定学历的中国公民申请认定教师资格，适用本办法。"},{"i":3,"n":"第三条","txt":"中国公民在各级各类学校和其他教育机构中专门从事教育教学工作，应当具备教师资格。"},{"i":4,"n":"第四条","txt":"国务院教育行政部门负责全国教师资格制度的组织实施和协调监督工作；县级以上（包括县级，下同）地方人民政府教育行政部门根据《教师资格条例》规定权限负责本地教师资格认定和管理的组织、指导、监督和实施工作。"},{"i":5,"n":"第五条","txt":"依法受理教师资格认定申请的县级以上地方人民政府教育行政部门，为教师资格认定机构。"},{"i":6,"n":"第六条","txt":"申请认定教师资格者应当遵守宪法和法律，热爱教育事业，履行《教师法》规定的义务，遵守教师职业道德。"},{"i":7,"n":"第七条","txt":"中国公民依照本办法申请认定教师资格应当具备《教师法》规定的相应学历。 申请认定中等职业学校实习指导教师资格者应当具备中等职业学校毕业及其以上学历，对于确有特殊技艺者，经省级以上人民政府教育行政部门批准，其学历要求可适当放宽。"},{"i":8,"n":"第八条","txt":"申请认定教师资格者的教育教学能力应当符合下列要求： （一）具备承担教育教学工作所必须的基本素质和能力。具体测试办法和标准由省级教育行政部门制定。 （二）普通话水平应当达到国家语言文字工作委员会颁布的《普通话水平测试等级标准》二级乙等以上标准。 少数方言复杂地区的普通话水平应当达到三级甲等以上标准；使用汉语和当地民族语言教学的少数民族自治地区的普通话水平，由省级人民政府教育行政部门规定标准。 （三）具有良好的身体素质和心理素质，无传染性疾病，无精神病史，适应教育教学工作的需要，在教师资格认定机构指定的县级以上医院体检合格。"},{"i":9,"n":"第九条","txt":"高等学校拟聘任副教授以上教师职务或具有博士学位者申请认定高等学校教师资格，只需具备本办法第六条、第七条、第八条（三）项规定的条件。"},{"i":10,"n":"第十条","txt":"教师资格认定机构和依法接受委托的高等学校每年春季、秋季各受理一次教师资格认定申请。具体受理时间由省级人民政府教育行政部门统一规定，并通过新闻媒体等形式予以公布。"},{"i":11,"n":"第十一条","txt":"申请认定教师资格者，应当在受理申请期限内向相应的教师资格认定机构或者依法接受委托的高等学校提出申请，领取有关资料和表格。"},{"i":12,"n":"第十二条","txt":"申请认定教师资格者应当在规定时间向教师资格认定机构或者依法接受委托的高等学校提交下列基本材料: (一)由本人填写的《教师资格认定申请表》(见附件一)一式两份； (二)身份证原件和复印件； (三)学历证书原件和复印件； (四)由教师资格认定机构指定的县级以上医院出具的体格检查合格证明； (五)普通话水平测试等级证书原件和复印件； (六)思想品德情况的鉴定或者证明材料。"},{"i":13,"n":"第十三条","txt":"体检项目由省级人民政府教育行政部门规定，其中必须包含“传染病”、“精神病史”项目。 申请认定幼儿园和小学教师资格的，参照《中等师范学校招生体检标准》的有关规定执行；申请认定初级中学及其以上教师资格的，参照《高等师范学校招生体检标准》的有关规定执行。"},{"i":14,"n":"第十四条","txt":"普通话水平测试由教育行政部门和语言文字工作机构共同组织实施，对合格者颁发由国务院教育行政部门统一印制的《普通话水平测试等级证书》。"},{"i":15,"n":"第十五条","txt":"申请人思想品德情况的鉴定或者证明材料按照《申请人思想品德鉴定表》(见附件二)要求填写。在职申请人，该表由其工作单位填写；非在职申请人，该表由其户籍所在地街道办事处或者乡级人民政府填写。应届毕业生由毕业学校负责提供鉴定。必要时，有关单位可应教师资格认定机构要求提供更为详细的证明材料。"},{"i":16,"n":"第十六条","txt":"各级各类学校师范教育类专业毕业生可以持毕业证书，向任教学校所在地或户籍所在地教师资格认定机构申请直接认定相应的教师资格。"},{"i":17,"n":"第十七条","txt":"申请认定教师资格者应当按照国家规定缴纳费用。但各级各类学校师范教育类专业毕业生不缴纳认定费用。"},{"i":18,"n":"第十八条","txt":"教师资格认定机构或者依法接受委托的高等学校应当及时根据申请人提供的材料进行初步审查。"},{"i":19,"n":"第十九条","txt":"教师资格认定机构或者依法接受委托的高等学校应当组织成立教师资格专家审查委员会。教师资格专家审查委员会根据需要成立若干小组，按照省级教育行政部门制定的测试办法和标准组织面试、试讲，对申请人的教育教学能力进行考察，提出审查意见，报教师资格认定机构或者依法接受委托的高等学校。"},{"i":20,"n":"第二十条","txt":"教师资格认定机构根据教师资格专家审查委员会的审查意见，在受理申请期限终止之日起30个法定工作日内作出是否认定教师资格的结论，并将认定结果通知申请人。符合法定的认定条件者，颁发相应的《教师资格证书》。"},{"i":21,"n":"第二十一条","txt":"县级以上地方人民政府教育行政部门按照《教师资格条例》第十三条规定的权限，认定相应的教师资格。 高等学校教师资格，由申请人户籍所在地或者申请人拟受聘高等学校所在地的省级人民政府教育行政部门认定；省级人民政府教育行政部门可以委托本行政区域内经过国家批准实施本科学历教育的普通高等学校认定本校拟聘人员的高等学校教师资格。"},{"i":22,"n":"第二十二条","txt":"各级人民政府教育行政部门应当加强对教师资格证书的管理。教师资格证书作为持证人具备国家认定的教师资格的法定凭证，由国务院教育行政部门统一印制。《教师资格认定申请表》由国务院教育行政部门统一格式。 《教师资格证书》和《教师资格认定申请表》由教师资格认定机构按国家规定统一编号，加盖相应的政府教育行政部门公章、钢印后生效。"},{"i":23,"n":"第二十三条","txt":"取得教师资格的人员，其《教师资格认定申请表》一份存入本人的人事档案，其余材料由教师资格认定机构归档保存。教师资格认定机构建立教师资格管理数据库。"},{"i":24,"n":"第二十四条","txt":"教师资格证书遗失或者损毁影响使用的，由本人向原发证机关报告，申请补发。原发证机关应当在补发的同时收回损毁的教师资格证书。"},{"i":25,"n":"第二十五条","txt":"丧失教师资格者，由其工作单位或者户籍所在地相应的县级以上人民政府教育行政部门按教师资格认定权限会同原发证机关办理注销手续，收缴证书，归档备案。丧失教师资格者不得重新申请认定教师资格。"},{"i":26,"n":"第二十六条","txt":"按照《教师资格条例》应当被撤销教师资格者，由县级以上人民政府教育行政部门按教师资格认定权限会同原发证机关撤销资格，收缴证书，归档备案。被撤销教师资格者自撤销之日起5年内不得重新取得教师资格。"},{"i":27,"n":"第二十七条","txt":"对使用假资格证书的，一经查实，按弄虚作假、骗取教师资格处理，5年内不得申请认定教师资格，由教育行政部门没收假证书。对变造、买卖教师资格证书的，依法追究法律责任。"},{"i":28,"n":"第二十八条","txt":"省级人民政府教育行政部门依据本办法制定实施细则，并报国务院教育行政部门备案。"},{"i":29,"n":"第二十九条","txt":"本办法自发布之日起施行。"}],"zhongwaihezuobanxuetiaolishishibanfa":[{"i":1,"n":"第一条","txt":"为实施《中华人民共和国中外合作办学条例》(以下简称《中外合作办学条例》)，制定本办法。"},{"i":2,"n":"第二条","txt":"中外合作办学机构设立、活动及管理中的具体规范，以及依据《中外合作办学条例》举办实施学历教育和自学考试助学、文化补习、学前教育等的中外合作办学项目的审批与管理，适用本办法。 本办法所称中外合作办学项目是指中国教育机构与外国教育机构以不设立教育机构的方式，在学科、专业、课程等方面，合作开展的以中国公民为主要招生对象的教育教学活动。 根据《中外合作办学条例》的规定，举办实施职业技能培训的中外合作办学项目的具体审批和管理办法，由国务院劳动行政部门另行制定。"},{"i":3,"n":"第三条","txt":"国家鼓励中国教育机构与学术水平和教育教学质量得到普遍认可的外国教育机构合作办学；鼓励在国内新兴和急需的学科专业领域开展合作办学。 国家鼓励在中国西部地区、边远贫困地区开展中外合作办学。"},{"i":4,"n":"第四条","txt":"中外合作办学机构根据《中华人民共和国民办教育促进法实施条例》的规定，享受国家给予民办学校的扶持与奖励措施。 教育行政部门对发展中外合作办学做出突出贡献的社会组织或者个人给予奖励和表彰。"},{"i":5,"n":"第五条","txt":"中外合作办学者应当在平等协商的基础上签订合作协议。 合作协议应当包括拟设立的中外合作办学机构的名称、住所，中外合作办学者的名称、住所、法定代表人，办学宗旨和培养目标，合作内容和期限，各方投入数额、方式及资金缴纳期限，权利、义务，争议解决办法等内容。 合作协议应当有中文文本；有外文文本的，应当与中文文本的内容一致。"},{"i":6,"n":"第六条","txt":"申请设立中外合作办学机构的中外合作办学者应当具有相应的办学资格和较高的办学质量。 已举办中外合作办学机构的中外合作办学者申请设立新的中外合作办学机构的，其已设立的中外合作办学机构应当通过原审批机关组织或者其委托的社会中介组织进行的评估。"},{"i":7,"n":"第七条","txt":"中外合作办学机构不得设立分支机构，不得举办其他中外合作办学机构。"},{"i":8,"n":"第八条","txt":"经评估，确系引进外国优质教育资源的，中外合作办学者一方可以与其他社会组织或者个人签订协议，引入办学资金。该社会组织或者个人可以作为与其签订协议的中外合作办学者一方的代表，参加拟设立的中外合作办学机构的理事会、董事会或者联合管理委员会，但不得担任理事长、董事长或者主任，不得参与中外合作办学机构的教育教学活动。"},{"i":9,"n":"第九条","txt":"中外合作办学者投入的办学资金，应当与拟设立的中外合作办学机构的层次和规模相适应，并经依法验资。 中外合作办学者应当按照合作协议如期、足额投入办学资金。中外合作办学机构存续期间，中外合作办学者不得抽逃办学资金，不得挪用办学经费。"},{"i":10,"n":"第十条","txt":"中外合作办学者作为办学投入的知识产权，其作价由中外合作办学者双方按照公平合理的原则协商确定或者聘请双方同意的社会中介组织依法进行评估，并依法办理有关手续。 中国教育机构以国有资产作为办学投入举办中外合作办学机构的，应当根据国家有关规定，聘请具有评估资格的社会中介组织依法进行评估，根据评估结果合理确定国有资产的数额，并依法履行国有资产的管理义务。"},{"i":11,"n":"第十一条","txt":"中外合作办学者以知识产权作为办学投入的，应当提交该知识产权的有关资料，包括知识产权证书复印件、有效状况、实用价值、作价的计算根据、双方签订的作价协议等有关文件。"},{"i":12,"n":"第十二条","txt":"根据与外国政府部门签订的协议或者应中国教育机构的请求，国务院教育行政部门和省、自治区、直辖市人民政府可以邀请外国教育机构与中国教育机构合作办学。 被邀请的外国教育机构应当是国际上或者所在国著名的高等教育机构或者职业教育机构。"},{"i":13,"n":"第十三条","txt":"申请设立实施本科以上高等学历教育的中外合作办学机构，由拟设立机构所在地的省、自治区、直辖市人民政府提出意见后，报国务院教育行政部门审批。 申请举办颁发外国教育机构的学历、学位证书的中外合作办学机构的审批权限，参照《中外合作办学条例》第十二条和前款的规定执行。"},{"i":14,"n":"第十四条","txt":"申请筹备设立或者直接申请正式设立中外合作办学机构，应当由中国教育机构提交《中外合作办学条例》规定的文件。其中，申办报告或者正式设立申请书应当按照国务院教育行政部门根据《中外合作办学条例》第十四条第(一)项和第十七条第(一)项，制定的《中外合作办学机构申请表》所规定的内容和格式填写。"},{"i":15,"n":"第十五条","txt":"有下列情形之一的，审批机关不予批准筹备设立中外合作办学机构，并应当书面说明理由： （一）违背社会公共利益、历史文化传统和教育的公益性质，不符合国家或者地方教育事业发展需要的； （二）中外合作办学者有一方不符合条件的； （三）合作协议不符合法定要求，经指出仍不改正的； （四）申请文件有虚假内容的； （五）法律、行政法规规定的其他不予批准情形的。"},{"i":16,"n":"第十六条","txt":"中外合作办学机构的章程应当规定以下事项： （一）中外合作办学机构的名称、住所； （二）办学宗旨、规模、层次、类别等； （三）资产数额、来源、性质以及财务制度； （四）中外合作办学者是否要求取得合理回报； （五）理事会、董事会或者联合管理委员会的产生方法、人员构成、权限、任期、议事规则等； （六）法定代表人的产生和罢免程序； （七）民主管理和监督的形式； （八）机构终止事由、程序和清算办法； （九）章程修改程序； （十）其他需要由章程规定的事项。"},{"i":17,"n":"第十七条","txt":"中外合作办学机构只能使用一个名称，其外文译名应当与中文名称相符。 中外合作办学机构的名称应当反映中外合作办学机构的性质、层次和类型，不得冠以“中国”、“中华”、“全国”等字样，不得违反中国法律、行政法规，不得损害社会公共利益。 不具有法人资格的中外合作办学机构的名称前应当冠以中国高等学校的名称。"},{"i":18,"n":"第十八条","txt":"完成筹备，申请正式设立或者直接申请正式设立中外合作办学机构，除提交《中外合作办学条例》第十七条规定的相关材料外，还应当依据《中外合作办学条例》有关条款的规定，提交以下材料： （一）首届理事会、董事会或者联合管理委员会组成人员名单及相关证明文件； （二）聘任的外籍教师和外籍管理人员的相关资格证明文件。"},{"i":19,"n":"第十九条","txt":"申请设立实施学历教育的中外合作办学机构，应当于每年3月或者9月提出申请，审批机关应当组织专家评议。 专家评议的时间不计算在审批期限内，但审批机关应当将专家评议所需时间书面告知申请人。"},{"i":20,"n":"第二十条","txt":"完成筹备，申请正式设立中外合作办学机构，有下列情形之一的，审批机关应当不予批准，并书面说明理由： （一）不具备相应办学条件、未达到相应设置标准的； （二）理事会、董事会或者联合管理委员会的人员及其构成不符合法定要求，校长或者主要行政负责人、教师、财会人员不具备法定资格，经告知仍不改正的； （三）章程不符合《中外合作办学条例》和本办法规定要求，经告知仍不修改的； （四）在筹备设立期内有违反法律、法规行为的。 申请直接设立中外合作办学机构的，除前款规定的第（一）、（二）、（三）项外，有本办法第十五条规定情形之一的，审批机关不予批准。"},{"i":21,"n":"第二十一条","txt":"中外合作办学机构的理事会、董事会或者联合管理委员会的成员应当遵守中国法律、法规，热爱教育事业，品行良好，具有完全民事行为能力。 国家机关工作人员不得担任中外合作办学机构的理事会、董事会或者联合管理委员会的成员。"},{"i":22,"n":"第二十二条","txt":"中外合作办学机构应当聘任专职的校长或者主要行政负责人。 中外合作办学机构的校长或者主要行政负责人依法独立行使教育教学和行政管理职权。"},{"i":23,"n":"第二十三条","txt":"中外合作办学机构内部的组织机构设置方案由校长或者主要行政负责人提出，报理事会、董事会或者联合管理委员会批准。"},{"i":24,"n":"第二十四条","txt":"中外合作办学机构应当建立教师培训制度，为受聘教师接受相应的业务培训提供条件。"},{"i":25,"n":"第二十五条","txt":"中外合作办学机构应当按照招生简章或者招生广告的承诺，开设相应课程，开展教育教学活动，保证教育教学质量。 中外合作办学机构应当提供符合标准的校舍和教育教学设施、设备。"},{"i":26,"n":"第二十六条","txt":"中外合作办学机构可以依法自主确定招生范围、标准和方式；但实施中国学历教育的，应当遵守国家有关规定。"},{"i":27,"n":"第二十七条","txt":"实施高等学历教育的中外合作办学机构符合中国学位授予条件的，可以依照国家有关规定申请相应的学位授予资格。"},{"i":28,"n":"第二十八条","txt":"中外合作办学机构依法自主管理和使用中外合作办学机构的资产，但不得改变按照公益事业获得的土地及校舍的用途。 中外合作办学机构不得从事营利性经营活动。"},{"i":29,"n":"第二十九条","txt":"在每个会计年度结束时，中外合作办学者不要求取得合理回报的中外合作办学机构应当从年度净资产增加额中，中外合作办学者要求取得合理回报的中外合作办学机构应当从年度净收益中，按不低于年度净资产增加额或者净收益的25%的比例提取发展基金，用于中外合作办学机构的建设、维护和教学设备的添置、更新等。"},{"i":30,"n":"第三十条","txt":"中外合作办学机构资产中的国有资产的监督、管理，按照国家有关规定执行。 中外合作办学机构接受的捐赠财产的使用和管理，依照《中华人民共和国公益事业捐赠法》的有关规定执行。"},{"i":31,"n":"第三十一条","txt":"中外合作办学者要求取得合理回报的，应当按照《中华人民共和国民办教育促进法实施条例》的规定执行。"},{"i":32,"n":"第三十二条","txt":"中外合作办学机构有下列情形之一的，中外合作办学者不得取得回报： （一）发布虚假招生简章或者招生广告，骗取钱财的； （二）擅自增加收费项目或者提高收费标准，情节严重的； （三）非法颁发或者伪造学历、学位证书及其他学业证书的； （四）骗取办学许可证或者伪造、变造、买卖、出租、出借办学许可证的； （五）未依照《中华人民共和国会计法》和国家统一的会计制度进行会计核算、编制财务会计报告，财务、资产管理混乱的； （六）违反国家税收征管法律、行政法规的规定，受到税务机关处罚的； （七）校舍或者其他教育教学设施、设备存在重大安全隐患，未及时采取措施，致使发生重大伤亡事故的； （八）教育教学质量低下，产生恶劣社会影响的。 中外合作办学者抽逃办学资金或者挪用办学经费的，不得取得回报。"},{"i":33,"n":"第三十三条","txt":"中外合作办学项目的办学层次和类别，应当与中国教育机构和外国教育机构的办学层次和类别相符合，并一般应当在中国教育机构中已有或者相近专业、课程举办。合作举办新的专业或者课程的，中国教育机构应当基本具备举办该专业或者课程的师资、设备、设施等条件。"},{"i":34,"n":"第三十四条","txt":"中国教育机构可以采取与相应层次和类别的外国教育机构共同制定教育教学计划，颁发中国学历、学位证书或者外国学历、学位证书，在中国境外实施部分教育教学活动的方式，举办中外合作办学项目。"},{"i":35,"n":"第三十五条","txt":"举办中外合作办学项目，中国教育机构和外国教育机构应当参照本办法第五条的规定签订合作协议。"},{"i":36,"n":"第三十六条","txt":"申请举办实施本科以上高等学历教育的中外合作办学项目，由拟举办项目所在地的省、自治区、直辖市人民政府教育行政部门提出意见后，报国务院教育行政部门批准；申请举办实施高等专科教育、非学历高等教育和高级中等教育、自学考试助学、文化补习、学前教育的中外合作办学项目，报拟举办项目所在地的省、自治区、直辖市人民政府教育行政部门批准，并报国务院教育行政部门备案。 申请举办颁发外国教育机构的学历、学位证书以及引进外国教育机构的名称、标志或者教育服务商标的中外合作办学项目的审批，参照前款的规定执行。"},{"i":37,"n":"第三十七条","txt":"申请举办中外合作办学项目，应当由中国教育机构提交下列文件： （一)《中外合作办学项目申请表》； （二）合作协议； （三）中外合作办学者法人资格证明； （四）验资证明（有资产、资金投入的）； （五）捐赠资产协议及相关证明（有捐赠的）； 外国教育机构已在中国境内合作举办中外合作办学机构或者中外合作办学项目的，还应当提交原审批机关或者其委托的社会中介组织的评估报告。"},{"i":38,"n":"第三十八条","txt":"申请设立实施学历教育的中外合作办学项目，应当于每年3月或者9月提出申请，审批机关应当组织专家评议。 专家评议的时间不计算在审批期限内，但审批机关应当将专家评议所需时间书面告知申请人。"},{"i":39,"n":"第三十九条","txt":"申请设立中外合作办学项目的，审批机关应当按照《中华人民共和国行政许可法》规定的时限作出是否批准的决定。批准的，颁发统一格式、统一编号的中外合作办学项目批准书；不批准的，应当书面说明理由。 中外合作办学项目批准书由国务院教育行政部门制定式样并统一编号；编号办法由国务院教育行政部门参照中外合作办学许可证的编号办法确定。"},{"i":40,"n":"第四十条","txt":"中外合作办学项目是中国教育机构教育教学活动的组成部分，应当接受中国教育机构的管理。实施中国学历教育的中外合作办学项目，中国教育机构应当对外国教育机构提供的课程和教育质量进行评估。"},{"i":41,"n":"第四十一条","txt":"中外合作办学项目可以依法自主确定招生范围、标准和方式；但实施中国学历教育的，应当遵守国家有关规定。"},{"i":42,"n":"第四十二条","txt":"举办中外合作办学项目的中国教育机构应当依法对中外合作办学项目的财务进行管理，并在学校财务账户内设立中外合作办学项目专项，统一办理收支业务。"},{"i":43,"n":"第四十三条","txt":"中外合作办学项目收费项目和标准的确定，按照国家有关规定执行，并在招生简章或者招生广告中载明。 中外合作办学项目的办学结余，应当继续用于项目的教育教学活动和改善办学条件。"},{"i":44,"n":"第四十四条","txt":"中外合作办学机构和举办中外合作办学项目的中国教育机构作办学机构和举办中外合作办学项目的中国教育机构应当对开设课程和引进教材的内容进行审核，并将课程和教材清单及说明及时报审批机关备案。"},{"i":45,"n":"第四十五条","txt":"中外合作办学机构和举办中外合作办学项目的中国教育机构应当依法建立学籍管理制度，并报审批机关备案。"},{"i":46,"n":"第四十六条","txt":"中外合作办学机构和项目教师和管理人员的聘任，应当遵循双方地位平等的原则，由中外合作办学机构和举办中外合作办学项目的中国教育机构与教师和管理人员签订聘任合同，明确规定双方的权利、义务和责任。"},{"i":47,"n":"第四十七条","txt":"中外合作办学机构和项目的招生简章和招生广告的样本应当及时报审批机关备案。"},{"i":48,"n":"第四十八条","txt":"举办颁发外国教育机构的学历、学位证书的中外合作办学机构和项目，中方合作办学者应当是实施相应层次和类别学历教育的中国教育机构。 中外合作办学机构和项目颁发外国教育机构的学历、学位证书的，其课程设置、教学内容应当不低于该外国教育机构在其所属国的标准和要求。"},{"i":49,"n":"第四十九条","txt":"中外合作办学项目颁发的外国教育机构的学历、学位证书，应当与该外国教育机构在其所属国颁发的学历、学位证书相同，并在该国获得承认。"},{"i":50,"n":"第五十条","txt":"实施学历教育的中外合作办学机构和项目应当通过网络、报刊等渠道，将该机构或者项目的办学层次和类别、专业设置、课程内容、招生规模、收费项目和标准等情况，每年向社会公布。 中外合作办学机构应当于每年4月1日前公布经社会审计机构对其年度财务会计报告的审计结果。"},{"i":51,"n":"第五十一条","txt":"实施学历教育的中外合作办学机构和项目，应当按学年或者学期收费，不得跨学年或者学期预收。"},{"i":52,"n":"第五十二条","txt":"中外合作办学机构和举办中外合作办学项目的中国教育机构应当于每年3月底前向审批机关提交办学报告，内容应当包括中外合作办学机构和项目的招收学生、课程设置、师资配备、教学质量、财务状况等基本情况。"},{"i":53,"n":"第五十三条","txt":"审批机关应当组织或者委托社会中介组织本着公开、公正、公平的原则，对实施学历教育的中外合作办学项目进行办学质量评估，并将评估结果向社会公布。"},{"i":54,"n":"第五十四条","txt":"中外合作办学项目审批机关及其工作人员，利用职务上的便利收取他人财物或者获取其他利益，滥用职权、玩忽职守，对不符合本办法规定条件者颁发中外合作办学项目批准书，或者发现违法行为不予以查处，造成严重后果，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。"},{"i":55,"n":"第五十五条","txt":"违反本办法的规定，超越职权审批中外合作办学项目的，其批准文件无效，由上级机关责令改正；对负有责任的主管人员和其他直接责任人员，依法给予行政处分。"},{"i":56,"n":"第五十六条","txt":"违反本办法的规定，未经批准擅自举办中外合作办学项目的，由教育行政部门责令限期改正，并责令退还向学生收取的费用；对负有责任的主管人员和其他直接责任人员，依法给予行政处分。"},{"i":57,"n":"第五十七条","txt":"中外合作办学项目有下列情形之一的，由审批机关责令限期改正，并视情节轻重，处以警告或者3万元以下的罚款；对负有责任的主管人员和其他直接责任人员，依法给予行政处分。 （一）发布虚假招生简章或者招生广告，骗取钱财的； （二）擅自增加收费项目或者提高收费标准的； （三）管理混乱，教育教学质量低下的； （四）未按照国家有关规定进行财务管理的； （五）对办学结余进行分配的。"},{"i":58,"n":"第五十八条","txt":"中外合作办学机构和项目违反《中华人民共和国教育法》的规定，颁发学历、学位证书或者其他学业证书的，依照《中华人民共和国教育法》的有关规定进行处罚。"},{"i":59,"n":"第五十九条","txt":"在工商行政管理部门登记注册的经营性的中国培训机构与外国经营性的教育培训公司合作举办教育培训的活动，不适用本办法。"},{"i":60,"n":"第六十条","txt":"中国教育机构没有实质性引进外国教育资源，仅以互认学分的方式与外国教育机构开展学生交流的活动，不适用本办法。"},{"i":61,"n":"第六十一条","txt":"香港特别行政区、澳门特别行政区和台湾地区的教育机构与内地教育机构举办合作办学项目的，参照本办法的规定执行，国家另有规定的除外。"},{"i":62,"n":"第六十二条","txt":"《中外合作办学条例》实施前已经批准的中外合作办学项目，应当参照《中外合作办学条例》第六十三条规定的时限和程序，补办中外合作办学项目批准书。逾期未达到《中外合作办学条例》和本办法规定条件的，审批机关不予换发项目批准书。"},{"i":63,"n":"第六十三条","txt":"本办法自2004年7月1日起施行。原中华人民共和国国家教育委员会1995年1月26日发布的《中外合作办学暂行规定》同时废止。"}],"jiaoyubuzhongguoyuyanwenhuayouyijiangshezhiguiding":[{"i":1,"n":"第一条","txt":"为了推动世界汉语教学的发展和中国语言文化的传播，增进中国人民和世界各国人民的相互了解和友谊，中华人民共和国教育部设立“中国语言文化友谊奖”。"},{"i":2,"n":"第二条","txt":"“中国语言文化友谊奖”授予在汉语教学、汉学研究及中国语言文化传播方面做出突出贡献的外国友人。"},{"i":3,"n":"第三条","txt":"“中国语言文化友谊奖”每三年评选颁发一次，由教育部颁发或委托中国驻外外交机构等颁发。"},{"i":4,"n":"第四条","txt":"获奖者应符合下列条件之一： （一）在汉语教学方面有突出成绩； （二）在汉语和汉学研究方面有突出成就； （三）在传播中国语言文化方面有突出贡献； （四）在推广汉语和传播中国语言文化的组织、管理工作方面有突出作用。"},{"i":5,"n":"第五条","txt":"国内省部级教育行政部门、从事对外汉语教学的大专院校和著名专家、从事中国语言文化研究的单位和著名专家、从事对外教育和文化交流的机构、中国驻外外交机构均可以推荐候选人。"},{"i":6,"n":"第六条","txt":"本奖设评审委员会，负责评审并提出入选者名单，报教育部审定。"},{"i":7,"n":"第七条","txt":"对获奖者予以以下奖励： （一）授予中华人民共和国教育部颁发的荣誉证书和奖章； （二）邀请获奖者来华出席颁奖仪式和进行短期学术访问，或进行为期三个月的学术研究，费用由教育部专项基金提供。"},{"i":8,"n":"第八条","txt":"评奖和颁奖工作的具体事务由国家对外汉语教学领导小组办公室负责。"},{"i":9,"n":"第九条","txt":"本规定自发布之日起生效。"}],"zhongguohanyushuipingkaoshibanfa":[{"i":1,"n":"第一条","txt":"为了实施中华人民共和国汉语水平考试 ( han yu shui ping kao shi，缩写为 HSK)，特制定本办法。"},{"i":2,"n":"第二条","txt":"汉语水平考试(HSK)是测试母语非汉语者的汉语水平而设立的标准考试。"},{"i":3,"n":"第三条","txt":"汉语水平考试(HSK)是统一的标准化考试，实行统一命题、考试、阅卷、评分，并统一颁发证书。"},{"i":4,"n":"第四条","txt":"汉语水平考试(HSK)分为初等、中等汉语水平考试〔简称 HSK(初、中等)〕和高等汉语水平考试[简称HSK(高等)〕。凡考试成绩达到规定标准者，可获得相应等级的《汉语水平证书》。"},{"i":5,"n":"第五条","txt":"《汉语水平证书》分为：初等水平证书( A、B、 C三级， A级最高一一下同)，中等水平证书( A、 B、C三级)，高等水平证书( A、 B、 C三级)。"},{"i":6,"n":"第六条","txt":"《汉语水平证书》的效力是： (1) 作为到中国高等院校入系学习专业或报考研究生所要求的实际汉语水平的证明。 (2) 作为汉语水平达到某种等级或免修相应级别汉语课程的证明。 (3) 作为聘用机构录用人员汉语水平的依据。"},{"i":7,"n":"第七条","txt":"汉语水平考试(HSK)每年定期分别在国内和海外举行。国内考试在指定高等院校设立考试点，每年六月和十月举行一次；国外考试委托当地高等学校或学术团体承办，每年六月或十月举行一次。"},{"i":8,"n":"第八条","txt":"具有一定汉语基础，母语非汉语者均可向主考单位报名参加汉语水平考试。申请考试者需向主考单位缴纳考试费。考生持主考单位核发的“准考证”进入考场参加考试。考生应遵守考试规则，违反者将由主考单位给以直至取消考试资格的惩处。"},{"i":9,"n":"第九条","txt":"国家教育委员会设立汉语水平考试委员会，称国家汉语水平考试委员会，国家汉语水平考试委员会全权领导汉语水平考试，并颁发《汉语水平证书》。由国家对外汉语教学领导小组办公室和北京语言学院负责实施汉语水平考试(HSK)的考务工作。"},{"i":10,"n":"第十条","txt":"国家汉语水平考试委员会聘请若干专家、教授组成汉语水平考试顾问委员会，负责汉语水平考试(HSK)的咨询工作。"},{"i":11,"n":"第十一条","txt":"本办法自发布之日起施行。"}],"zhongxiaoxueyoueryuananquanguanlibanfa-2":[{"i":1,"n":"第一条","txt":"为加强中小学、幼儿园安全管理，保障学校及其学生和教职工的人身、财产安全，维护中小学、幼儿园正常的教育教学秩序，根据《中华人民共和国教育法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"普通中小学、中等职业学校、幼儿园(班)、特殊教育学校、工读学校(以下统称学校)的安全管理适用本办法。"},{"i":3,"n":"第三条","txt":"学校安全管理遵循积极预防、依法管理、社会参与、各负其责的方针。"},{"i":4,"n":"第四条","txt":"学校安全管理工作主要包括： （一）构建学校安全工作保障体系，全面落实安全工作责任制和事故责任追究制，保障学校安全工作规范、有序进行； （二）健全学校安全预警机制，制定突发事件应急预案，完善事故预防措施，及时排除安全隐患，不断提高学校安全工作管理水平； （三）建立校园周边整治协调工作机制，维护校园及周边环境安全； （四）加强安全宣传教育培训，提高师生安全意识和防护能力； （五）事故发生后启动应急预案、对伤亡人员实施救治和责任追究等。"},{"i":5,"n":"第五条","txt":"各级教育、公安、司法行政、建设、交通、文化、卫生、工商、质检、新闻出版等部门在本级人民政府的领导下，依法履行学校周边治理和学校安全的监督与管理职责。 学校应当按照本办法履行安全管理和安全教育职责。 社会团体、企业事业单位、其他社会组织和个人应当积极参与和支持学校安全工作，依法维护学校安全。"},{"i":6,"n":"第六条","txt":"地方各级人民政府及其教育、公安、司法行政、建设、交通、文化、卫生、工商、质检、新闻出版等部门应当按照职责分工，依法负责学校安全工作，履行学校安全管理职责。"},{"i":7,"n":"第七条","txt":"教育行政部门对学校安全工作履行下列职责： （一）全面掌握学校安全工作状况，制定学校安全工作考核目标，加强对学校安全工作的检查指导，督促学校建立健全并落实安全管理制度； （二）建立安全工作责任制和事故责任追究制，及时消除安全隐患，指导学校妥善处理学生伤害事故； （三）及时了解学校安全教育情况，组织学校有针对性地开展学生安全教育，不断提高教育实效； （四）制定校园安全的应急预案，指导、监督下级教育行政部门和学校开展安全工作； （五）协调政府其他相关职能部门共同做好学校安全管理工作，协助当地人民政府组织对学校安全事故的救援和调查处理。 教育督导机构应当组织学校安全工作的专项督导。"},{"i":8,"n":"第八条","txt":"公安机关对学校安全工作履行下列职责： （一）了解掌握学校及周边治安状况，指导学校做好校园保卫工作，及时依法查处扰乱校园秩序、侵害师生人身、财产安全的案件； （二）指导和监督学校做好消防安全工作； （三）协助学校处理校园突发事件。"},{"i":9,"n":"第九条","txt":"卫生部门对学校安全工作履行下列职责： （一）检查、指导学校卫生防疫和卫生保健工作，落实疾病预防控制措施； （二）监督、检查学校食堂、学校饮用水和游泳池的卫生状况。"},{"i":10,"n":"第十条","txt":"建设部门对学校安全工作履行下列职责： （一）加强对学校建筑、燃气设施设备安全状况的监管，发现安全事故隐患的，应当依法责令立即排除； （二）指导校舍安全检查鉴定工作； （三）加强对学校工程建设各环节的监督管理，发现校舍、楼梯护栏及其他教学、生活设施违反工程建设强制性标准的，应责令纠正； （四）依法督促学校定期检验、维修和更新学校相关设施设备。"},{"i":11,"n":"第十一条","txt":"质量技术监督部门应当定期检查学校特种设备及相关设施的安全状况。"},{"i":12,"n":"第十二条","txt":"公安、卫生、交通、建设等部门应当定期向教育行政部门和学校通报与学校安全管理相关的社会治安、疾病防治、交通等情况，提出具体预防要求。"},{"i":13,"n":"第十三条","txt":"文化、新闻出版、工商等部门应当对校园周边的有关经营服务场所加强管理和监督，依法查处违法经营者，维护有利于青少年成长的良好环境。 司法行政、公安等部门应当按照有关规定履行学校安全教育职责。"},{"i":14,"n":"第十四条","txt":"举办学校的地方人民政府、企业事业组织、社会团体和公民个人，应当对学校安全工作履行下列职责： （一）保证学校符合基本办学标准，保证学校围墙、校舍、场地、教学设施、教学用具、生活设施和饮用水源等办学条件符合国家安全质量标准； （二）配置紧急照明装置和消防设施与器材，保证学校教学楼、图书馆、实验室、师生宿舍等场所的照明、消防条件符合国家安全规定； （三）定期对校舍安全进行检查，对需要维修的，及时予以维修；对确认的危房，及时予以改造。 举办学校的地方人民政府应当依法维护学校周边秩序，保障师生和学校的合法权益，为学校提供安全保障。 有条件的，学校举办者应当为学校购买责任保险。"},{"i":15,"n":"第十五条","txt":"学校应当遵守有关安全工作的法律、法规和规章，建立健全校内各项安全管理制度和安全应急机制，及时消除隐患，预防发生事故。"},{"i":16,"n":"第十六条","txt":"学校应当建立校内安全工作领导机构，实行校长负责制；应当设立保卫机构，配备专职或者兼职安全保卫人员，明确其安全保卫职责。"},{"i":17,"n":"第十七条","txt":"学校应当健全门卫制度，建立校外人员入校的登记或者验证制度，禁止无关人员和校外机动车入内，禁止将非教学用易燃易爆物品、有毒物品、动物和管制器具等危险物品带入校园。 学校门卫应当由专职保安或者其他能够切实履行职责的人员担任。"},{"i":18,"n":"第十八条","txt":"学校应当建立校内安全定期检查制度和危房报告制度，按照国家有关规定安排对学校建筑物、构筑物、设备、设施进行安全检查、检验；发现存在安全隐患的，应当停止使用，及时维修或者更换；维修、更换前应当采取必要的防护措施或者设置警示标志。学校无力解决或者无法排除的重大安全隐患，应当及时书面报告主管部门和其他相关部门。 学校应当在校内高地、水池、楼梯等易发生危险的地方设置警示标志或者采取防护设施。"},{"i":19,"n":"第十九条","txt":"学校应当落实消防安全制度和消防工作责任制，对于政府保障配备的消防设施和器材加强日常维护，保证其能够有效使用，并设置消防安全标志，保证疏散通道、安全出口和消防车通道畅通。"},{"i":20,"n":"第二十条","txt":"学校应当建立用水、用电、用气等相关设施设备的安全管理制度，定期进行检查或者按照规定接受有关主管部门的定期检查，发现老化或者损毁的，及时进行维修或者更换。"},{"i":21,"n":"第二十一条","txt":"学校应当严格执行《学校食堂与学生集体用餐卫生管理规定》、《餐饮业和学生集体用餐配送单位卫生规范》，严格遵守卫生操作规范。建立食堂物资定点采购和索证、登记制度与饭菜留验和记录制度，检查饮用水的卫生安全状况，保障师生饮食卫生安全。"},{"i":22,"n":"第二十二条","txt":"学校应当建立实验室安全管理制度，并将安全管理制度和操作规程置于实验室显著位置。 学校应当严格建立危险化学品、放射物质的购买、保管、使用、登记、注销等制度，保证将危险化学品、放射物质存放在安全地点。"},{"i":23,"n":"第二十三条","txt":"学校应当按照国家有关规定配备具有从业资格的专职医务(保健)人员或者兼职卫生保健教师，购置必需的急救器材和药品，保障对学生常见病的治疗，并负责学校传染病疫情及其他突发公共卫生事件的报告。有条件的学校，应当设立卫生（保健）室。 新生入学应当提交体检证明。托幼机构与小学在入托、入学时应当查验预防接种证。学校应当建立学生健康档案，组织学生定期体检。"},{"i":24,"n":"第二十四条","txt":"学校应当建立学生安全信息通报制度，将学校规定的学生到校和放学时间、学生非正常缺席或者擅自离校情况、以及学生身体和心理的异常状况等关系学生安全的信息，及时告知其监护人。 对有特异体质、特定疾病或者其他生理、心理状况异常以及有吸毒行为的学生，学校应当做好安全信息记录，妥善保管学生的健康与安全信息资料，依法保护学生的个人隐私。"},{"i":25,"n":"第二十五条","txt":"有寄宿生的学校应当建立住宿学生安全管理制度，配备专人负责住宿学生的生活管理和安全保卫工作。 学校应当对学生宿舍实行夜间巡查、值班制度，并针对女生宿舍安全工作的特点，加强对女生宿舍的安全管理。 学校应当采取有效措施，保证学生宿舍的消防安全。"},{"i":26,"n":"第二十六条","txt":"学校购买或者租用机动车专门用于接送学生的，应当建立车辆管理制度，并及时到公安机关交通管理部门备案。接送学生的车辆必须检验用校车应当粘贴统一标识。标识样式由省级公安机关交通管理部门和教育行政部门制定。 学校不得租用拼装车、报废车和个人机动车接送学生。 接送学生的机动车驾驶员应当身体健康，具备相应准驾车型3年以上安全驾驶经历，最近3年内任一记分周期没有记满12分记录，无致人伤亡的交通责任事故。"},{"i":27,"n":"第二十七条","txt":"学校应当建立安全工作档案，记录日常安全工作、安全责任落实、安全检查、安全隐患消除等情况。 安全档案作为实施安全工作目标考核、责任追究和事故处理的重要依据。"},{"i":28,"n":"第二十八条","txt":"学校在日常的教育教学活动中应当遵循教学规范，落实安全管理要求，合理预见、积极防范可能发生的风险。 学校组织学生参加的集体劳动、教学实习或者社会实践活动，应当符合学生的心理、生理特点和身体健康状况。 学校以及接受学生参加教育教学活动的单位必须采取有效措施，为学生活动提供安全保障。"},{"i":29,"n":"第二十九条","txt":"学校组织学生参加大型集体活动，应当采取下列安全措施： （一）成立临时的安全管理组织机构； （二）有针对性地对学生进行安全教育； （三）安排必要的管理人员，明确所负担的安全职责； （四）制定安全应急预案，配备相应设施。"},{"i":30,"n":"第三十条","txt":"学校应当按照《学校体育工作条例》和教学计划组织体育教学和体育活动，并根据教学要求采取必要的保护和帮助措施。 学校组织学生开展体育活动，应当避开主要街道和交通要道；开展大型体育活动以及其他大型学生活动，必须经过主要街道和交通要道的，应当事先与公安机关交通管理部门共同研究并落实安全措施。"},{"i":31,"n":"第三十一条","txt":"小学、幼儿园应当建立低年级学生、幼儿上下学时接送的交接制度，不得将晚离学校的低年级学生、幼儿交与无关人员。"},{"i":32,"n":"第三十二条","txt":"学生在教学楼进行教学活动和晚自习时，学校应当合理安排学生疏散时间和楼道上下顺序，同时安排人员巡查，防止发生拥挤踩踏伤害事故。 晚自习学生没有离校之前，学校应当有负责人和教师值班、巡查。"},{"i":33,"n":"第三十三条","txt":"学校不得组织学生参加抢险等应当由专业人员或者成人从事的活动，不得组织学生参与制作烟花爆竹、有毒化学品等具有危险性的活动，不得组织学生参加商业性活动。"},{"i":34,"n":"第三十四条","txt":"学校不得将场地出租给他人从事易燃、易爆、有毒、有害等危险品的生产、经营活动。 学校不得出租校园内场地停放校外机动车辆；不得利用学校用地建设对社会开放的停车场。"},{"i":35,"n":"第三十五条","txt":"学校教职工应当符合相应任职资格和条件要求。学校不得聘用因故意犯罪而受到刑事处罚的人，或者有精神病史的人担任教职工。 学校教师应当遵守职业道德规范和工作纪律，不得侮辱、殴打、体罚或者变相体罚学生；发现学生行为具有危险性的，应当及时告诫、制止，并与学生监护人沟通。"},{"i":36,"n":"第三十六条","txt":"学生在校学习和生活期间，应当遵守学校纪律和规章制度，服从学校的安全教育和管理，不得从事危及自身或者他人安全的活动。"},{"i":37,"n":"第三十七条","txt":"监护人发现被监护人有特异体质、特定疾病或者异常心理状况的，应当及时告知学校。 学校对已知的有特异体质、特定疾病或者异常心理状况的学生，应当给予适当关注和照顾。生理、心理状况异常不宜在校学习的学生，应当休学，由监护人安排治疗、休养。"},{"i":38,"n":"第三十八条","txt":"学校应当按照国家课程标准和地方课程设置要求，将安全教育纳入教学内容，对学生开展安全教育，培养学生的安全意识，提高学生的自我防护能力。"},{"i":39,"n":"第三十九条","txt":"学校应当在开学初、放假前，有针对性地对学生集中开展安全教育。新生入校后，学校应当帮助学生及时了解相关的学校安全制度和安全规定。"},{"i":40,"n":"第四十条","txt":"学校应当针对不同课程实验课的特点与要求，对学生进行实验用品的防毒、防爆、防辐射、防污染等的安全防护教育。 学校应当对学生进行用水、用电的安全教育，对寄宿学生进行防火、防盗和人身防护等方面的安全教育。"},{"i":41,"n":"第四十一条","txt":"学校应当对学生开展安全防范教育，使学生掌握基本的自我保护技能，应对不法侵害。 学校应当对学生开展交通安全教育，使学生掌握基本的交通规则和行为规范。 学校应当对学生开展消防安全教育，有条件的可以组织学生到当地消防站参观和体验，使学生掌握基本的消防安全知识，提高防火意识和逃生自救的能力。 学校应当根据当地实际情况，有针对性地对学生开展到江河湖海、水库等地方戏水、游泳的安全卫生教育。"},{"i":42,"n":"第四十二条","txt":"学校可根据当地实际情况，组织师生开展多种形式的事故预防演练。 学校应当每学期至少开展一次针对洪水、地震、火灾等灾害事故的紧急疏散演练，使师生掌握避险、逃生、自救的方法。"},{"i":43,"n":"第四十三条","txt":"教育行政部门按照有关规定，与人民法院、人民检察院和公安、司法行政等部门以及高等学校协商，选聘优秀的法律工作者担任学校的兼职法制副校长或者法制辅导员。 兼职法制副校长或者法制辅导员应当协助学校检查落实安全制度和安全事故处理、定期对师生进行法制教育等，其工作成果纳入派出单位的工作考核内容。"},{"i":44,"n":"第四十四条","txt":"教育行政部门应当组织负责安全管理的主管人员、学校校长、幼儿园园长和学校负责安全保卫工作的人员，定期接受有关安全管理培训。"},{"i":45,"n":"第四十五条","txt":"学校应当制定教职工安全教育培训计划，通过多种途径和方法，使教职工熟悉安全规章制度、掌握安全救护常识，学会指导学生预防事故、自救、逃生、紧急避险的方法和手段。"},{"i":46,"n":"第四十六条","txt":"学生监护人应当与学校互相配合，在日常生活中加强对被监护人的各项安全教育。 学校鼓励和提倡监护人自愿为学生购买意外伤害保险。"},{"i":47,"n":"第四十七条","txt":"教育、公安、司法行政、建设、交通、文化、卫生、工商、质检、新闻出版等部门应当建立联席会议制度，定期研究部署学校安全管理工作，依法维护学校周边秩序；通过多种途径和方式，听取学校和社会各界关于学校安全管理工作的意见和建议。"},{"i":48,"n":"第四十八条","txt":"建设、公安等部门应当加强对学校周边建设工程的执法检查，禁止任何单位或者个人违反有关法律、法规、规章、标准，在学校围墙或者建筑物边建设工程，在校园周边设立易燃易爆、剧毒、放射性、腐蚀性等危险物品的生产、经营、储存、使用场所或者设施以及其他可能影响学校安全的场所或者设施。"},{"i":49,"n":"第四十九条","txt":"公安机关应当把学校周边地区作为重点治安巡逻区域，在治安情况复杂的学校周边地区增设治安岗亭和报警点，及时发现和消除各类安全隐患，处置扰乱学校秩序和侵害学生人身、财产安全的违法犯罪行为。"},{"i":50,"n":"第五十条","txt":"公安、建设和交通部门应当依法在学校门前道路设置规范的交通警示标志，施划人行横线，根据需要设置交通信号灯、减速带、过街天桥等设施。 在地处交通复杂路段的学校上下学时间，公安机关应当根据需要部署警力或者交通协管人员维护道路交通秩序。"},{"i":51,"n":"第五十一条","txt":"公安机关和交通部门应当依法加强对农村地区交通工具的监督管理，禁止没有资质的车船搭载学生。"},{"i":52,"n":"第五十二条","txt":"文化部门依法禁止在中学、小学校园周围200米范围内设立互联网上网服务营业场所，并依法查处接纳未成年人进入的互联网上网服务营业场所。工商行政管理部门依法查处取缔擅自设立的互联网上网服务营业场所。"},{"i":53,"n":"第五十三条","txt":"新闻出版、公安、工商行政管理等部门应当依法取缔学校周边兜售非法出版物的游商和无证照摊点，查处学校周边制售含有淫秽色情、凶杀暴力等内容的出版物的单位和个人。"},{"i":54,"n":"第五十四条","txt":"卫生、工商行政管理部门应当对校园周边饮食单位的卫生状况进行监督，取缔非法经营的小卖部、饮食摊点。"},{"i":55,"n":"第五十五条","txt":"在发生地震、洪水、泥石流、台风等自然灾害和重大治安、公共卫生突发事件时，教育等部门应当立即启动应急预案，及时转移、疏散学生，或者采取其他必要防护措施，保障学校安全和师生人身财产安全。"},{"i":56,"n":"第五十六条","txt":"校园内发生火灾、食物中毒、重大治安等突发安全事故以及自然灾害时，学校应当启动应急预案，及时组织教职工参与抢险、救助和防护，保障学生身体健康和人身、财产安全。"},{"i":57,"n":"第五十七条","txt":"发生学生伤亡事故时，学校应当按照《学生伤害事故处理办法》规定的原则和程序等，及时实施救助，并进行妥善处理。"},{"i":58,"n":"第五十八条","txt":"发生教职工和学生伤亡等安全事故的，学校应当及时报告主管教育行政部门和政府有关部门；属于重大事故的，教育行政部门应当按照有关规定及时逐级上报。"},{"i":59,"n":"第五十九条","txt":"省级教育行政部门应当在每年1月31日前向国务院教育行政部门书面报告上一年度学校安全工作和学生伤亡事故情况。"},{"i":60,"n":"第六十条","txt":"教育、公安、司法行政、建设、交通、文化、卫生、工商、质检、新闻出版等部门，对在学校安全工作中成绩显著或者做出突出贡献的单位和个人，应当视情况联合或者分别给予表彰、奖励。"},{"i":61,"n":"第六十一条","txt":"教育、公安、司法行政、建设、交通、文化、卫生、工商、质检、新闻出版等部门，不依法履行学校安全监督与管理职责的，由上级部门给予批评；对直接责任人员由上级部门和所在单位视情节轻重，给予批评教育或者行政处分；构成犯罪的，依法追究刑事责任。"},{"i":62,"n":"第六十二条","txt":"学校不履行安全管理和安全教育职责，对重大安全隐患未及时采取措施的，有关主管部门应当责令其限期改正；拒不改正或者有下列情形之一的，教育行政部门应当对学校负责人和其他直接责任人员给予行政处分；构成犯罪的，依法追究刑事责任： (一)发生重大安全事故、造成学生和教职工伤亡的； (二)发生事故后未及时采取适当措施、造成严重后果的； (三)瞒报、谎报或者缓报重大事故的； (四)妨碍事故调查或者提供虚假情况的； (五)拒绝或者不配合有关部门依法实施安全监督管理职责的。 《中华人民共和国民办教育促进法》及其实施条例另有规定的，依其规定执行。"},{"i":63,"n":"第六十三条","txt":"校外单位或者人员违反治安管理规定、引发学校安全事故的，或者在学校安全事故处理过程中，扰乱学校正常教育教学秩序、违反治安管理规定的，由公安机关依法处理；构成犯罪的，依法追究其刑事责任；造成学校财产损失的，依法承担赔偿责任。"},{"i":64,"n":"第六十四条","txt":"学生人身伤害事故的赔偿，依据有关法律法规、国家有关规定以及《学生伤害事故处理办法》处理。"},{"i":65,"n":"第六十五条","txt":"中等职业学校学生实习劳动的安全管理办法另行制定。"},{"i":66,"n":"第六十六条","txt":"本办法自2006年9月1日起施行。"}],"zhongxiaoxueyoueryuananquanguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强中小学、幼儿园安全管理，保障学校及其学生和教职工的人身、财产安全，维护中小学、幼儿园正常的教育教学秩序，根据《中华人民共和国教育法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"普通中小学、中等职业学校、幼儿园（班）、特殊教育学校、工读学校（以下统称学校）的安全管理适用本办法。"},{"i":3,"n":"第三条","txt":"学校安全管理遵循积极预防、依法管理、社会参与、各负其责的方针。"},{"i":4,"n":"第四条","txt":"学校安全管理工作主要包括： （一）构建学校安全工作保障体系，全面落实安全工作责任制和事故责任追究制，保障学校安全工作规范、有序进行； （二）健全学校安全预警机制，制定突发事件应急预案，完善事故预防措施，及时排除安全隐患，不断提高学校安全工作管理水平； （三）建立校园周边整治协调工作机制，维护校园及周边环境安全； （四）加强安全宣传教育培训，提高师生安全意识和防护能力； （五）事故发生后启动应急预案、对伤亡人员实施救治和责任追究等。"},{"i":5,"n":"第五条","txt":"各级教育、公安、司法行政、建设、交通、文化、卫生、工商、质检、新闻出版等部门在本级人民政府的领导下，依法履行学校周边治理和学校安全的监督与管理职责。 学校应当按照本办法履行安全管理和安全教育职责。 社会团体、企业事业单位、其他社会组织和个人应当积极参与和支持学校安全工作，依法维护学校安全。"},{"i":6,"n":"第六条","txt":"地方各级人民政府及其教育、公安、司法行政、建设、交通、文化、卫生、工商、质检、新闻出版等部门应当按照职责分工，依法负责学校安全工作，履行学校安全管理职责。"},{"i":7,"n":"第七条","txt":"教育行政部门对学校安全工作履行下列职责： （一）全面掌握学校安全工作状况，制定学校安全工作考核目标，加强对学校安全工作的检查指导，督促学校建立健全并落实安全管理制度； （二）建立安全工作责任制和事故责任追究制，及时消除安全隐患，指导学校妥善处理学生伤害事故； （三）及时了解学校安全教育情况，组织学校有针对性地开展学生安全教育，不断提高教育实效； （四）制定校园安全的应急预案，指导、监督下级教育行政部门和学校开展安全工作； （五）协调政府其他相关职能部门共同做好学校安全管理工作，协助当地人民政府组织对学校安全事故的救援和调查处理。 教育督导机构应当组织学校安全工作的专项督导。"},{"i":8,"n":"第八条","txt":"公安机关对学校安全工作履行下列职责： （一）了解掌握学校及周边治安状况，指导学校做好校园保卫工作，及时依法查处扰乱校园秩序、侵害师生人身、财产安全的案件； （二）指导和监督学校做好消防安全工作； （三）协助学校处理校园突发事件。"},{"i":9,"n":"第九条","txt":"卫生部门对学校安全工作履行下列职责： （一）检查、指导学校卫生防疫和卫生保健工作，落实疾病预防控制措施； （二）监督、检查学校食堂、学校饮用水和游泳池的卫生状况。"},{"i":10,"n":"第十条","txt":"建设部门对学校安全工作履行下列职责： （一）加强对学校建筑、燃气设施设备安全状况的监管，发现安全事故隐患的，应当依法责令立即排除； （二）指导校舍安全检查鉴定工作； （三）加强对学校工程建设各环节的监督管理，发现校舍、楼梯护栏及其他教学、生活设施违反工程建设强制性标准的，应责令纠正； （四）依法督促学校定期检验、维修和更新学校相关设施设备。"},{"i":11,"n":"第十一条","txt":"质量技术监督部门应当定期检查学校特种设备及相关设施的安全状况。"},{"i":12,"n":"第十二条","txt":"公安、卫生、交通、建设等部门应当定期向教育行政部门和学校通报与学校安全管理相关的社会治安、疾病防治、交通等情况，提出具体预防要求。"},{"i":13,"n":"第十三条","txt":"文化、新闻出版、工商等部门应当对校园周边的有关经营服务场所加强管理和监督，依法查处违法经营者，维护有利于青少年成长的良好环境。 司法行政、公安等部门应当按照有关规定履行学校安全教育职责。"},{"i":14,"n":"第十四条","txt":"举办学校的地方人民政府、企业事业组织、社会团体和公民个人，应当对学校安全工作履行下列职责： （一）保证学校符合基本办学标准，保证学校围墙、校舍、场地、教学设施、教学用具、生活设施和饮用水源等办学条件符合国家安全质量标准； （二）配置紧急照明装置和消防设施与器材，保证学校教学楼、图书馆、实验室、师生宿舍等场所的照明、消防条件符合国家安全规定； （三）定期对校舍安全进行检查，对需要维修的，及时予以维修；对确认的危房，及时予以改造。 举办学校的地方人民政府应当依法维护学校周边秩序，保障师生和学校的合法权益，为学校提供安全保障。 有条件的，学校举办者应当为学校购买责任保险。"},{"i":15,"n":"第十五条","txt":"学校应当遵守有关安全工作的法律、法规和规章，建立健全校内各项安全管理制度和安全应急机制，及时消除隐患，预防发生事故。"},{"i":16,"n":"第十六条","txt":"学校应当建立校内安全工作领导机构，实行校长负责制；应当设立保卫机构，配备专职或者兼职安全保卫人员，明确其安全保卫职责。"},{"i":17,"n":"第十七条","txt":"学校应当健全门卫制度，建立校外人员入校的登记或者验证制度，禁止无关人员和校外机动车入内，禁止将非教学用易燃易爆物品、有毒物品、动物和管制器具等危险物品带入校园。 学校门卫应当由专职保安或者其他能够切实履行职责的人员担任。"},{"i":18,"n":"第十八条","txt":"学校应当建立校内安全定期检查制度和危房报告制度，按照国家有关规定安排对学校建筑物、构筑物、设备、设施进行安全检查、检验；发现存在安全隐患的，应当停止使用，及时维修或者更换；维修、更换前应当采取必要的防护措施或者设置警示标志。学校无力解决或者无法排除的重大安全隐患，应当及时书面报告主管部门和其他相关部门。 学校应当在校内高地、水池、楼梯等易发生危险的地方设置警示标志或者采取防护设施。"},{"i":19,"n":"第十九条","txt":"学校应当落实消防安全制度和消防工作责任制，对于政府保障配备的消防设施和器材加强日常维护，保证其能够有效使用，并设置消防安全标志，保证疏散通道、安全出口和消防车通道畅通。"},{"i":20,"n":"第二十条","txt":"学校应当建立用水、用电、用气等相关设施设备的安全管理制度，定期进行检查或者按照规定接受有关主管部门的定期检查，发现老化或者损毁的，及时进行维修或者更换。"},{"i":21,"n":"第二十一条","txt":"学校应当严格执行《学校食堂与学生集体用餐卫生管理规定》、《餐饮业和学生集体用餐配送单位卫生规范》，严格遵守卫生操作规范。建立食堂物资定点采购和索证、登记制度与饭菜留验和记录制度，检查饮用水的卫生安全状况，保障师生饮食卫生安全。"},{"i":22,"n":"第二十二条","txt":"学校应当建立实验室安全管理制度，并将安全管理制度和操作规程置于实验室显著位置。 学校应当严格建立危险化学品、放射物质的购买、保管、使用、登记、注销等制度，保证将危险化学品、放射物质存放在安全地点。"},{"i":23,"n":"第二十三条","txt":"学校应当按照国家有关规定配备具有从业资格的专职医务（保健）人员或者兼职卫生保健教师，购置必需的急救器材和药品，保障对学生常见病的治疗，并负责学校传染病疫情及其他突发公共卫生事件的报告。有条件的学校，应当设立卫生（保健）室。 新生入学应当提交体检证明。托幼机构与小学在入托、入学时应当查验预防接种证。学校应当建立学生健康档案，组织学生定期体检。"},{"i":24,"n":"第二十四条","txt":"学校应当建立学生安全信息通报制度，将学校规定的学生到校和放学时间、学生非正常缺席或者擅自离校情况、以及学生身体和心理的异常状况等关系学生安全的信息，及时告知其监护人。 对有特异体质、特定疾病或者其他生理、心理状况异常以及有吸毒行为的学生，学校应当做好安全信息记录，妥善保管学生的健康与安全信息资料，依法保护学生的个人隐私。"},{"i":25,"n":"第二十五条","txt":"有寄宿生的学校应当建立住宿学生安全管理制度，配备专人负责住宿学生的生活管理和安全保卫工作。 学校应当对学生宿舍实行夜间巡查、值班制度，并针对女生宿舍安全工作的特点，加强对女生宿舍的安全管理。 学校应当采取有效措施，保证学生宿舍的消防安全。"},{"i":26,"n":"第二十六条","txt":"学校购买或者租用机动车专门用于接送学生的，应当建立车辆管理制度，并及时到公安机关交通管理部门备案。接送学生的车辆必须检验合格，并定期维护和检测。 接送学生专用校车应当粘贴统一标识。标识样式由省级公安机关交通管理部门和教育行政部门制定。 学校不得租用拼装车、报废车和个人机动车接送学生。 接送学生的机动车驾驶员应当身体健康，具备相应准驾车型3年以上安全驾驶经历，最近3年内任一记分周期没有记满12分记录，无致人伤亡的交通责任事故。"},{"i":27,"n":"第二十七条","txt":"学校应当建立安全工作档案，记录日常安全工作、安全责任落实、安全检查、安全隐患消除等情况。 安全档案作为实施安全工作目标考核、责任追究和事故处理的重要依据。"},{"i":28,"n":"第二十八条","txt":"学校在日常的教育教学活动中应当遵循教学规范，落实安全管理要求，合理预见、积极防范可能发生的风险。 学校组织学生参加的集体劳动、教学实习或者社会实践活动，应当符合学生的心理、生理特点和身体健康状况。 学校以及接受学生参加教育教学活动的单位必须采取有效措施，为学生活动提供安全保障。"},{"i":29,"n":"第二十九条","txt":"学校组织学生参加大型集体活动，应当采取下列安全措施： （一）成立临时的安全管理组织机构； （二）有针对性地对学生进行安全教育； （三）安排必要的管理人员，明确所负担的安全职责； （四）制定安全应急预案，配备相应设施。"},{"i":30,"n":"第三十条","txt":"学校应当按照《学校体育工作条例》和教学计划组织体育教学和体育活动，并根据教学要求采取必要的保护和帮助措施。 学校组织学生开展体育活动，应当避开主要街道和交通要道；开展大型体育活动以及其他大型学生活动，必须经过主要街道和交通要道的，应当事先与公安机关交通管理部门共同研究并落实安全措施。"},{"i":31,"n":"第三十一条","txt":"小学、幼儿园应当建立低年级学生、幼儿上下学时接送的交接制度，不得将晚离学校的低年级学生、幼儿交与无关人员。"},{"i":32,"n":"第三十二条","txt":"学生在教学楼进行教学活动和晚自习时，学校应当合理安排学生疏散时间和楼道上下顺序，同时安排人员巡查，防止发生拥挤踩踏伤害事故。 晚自习学生没有离校之前，学校应当有负责人和教师值班、巡查。"},{"i":33,"n":"第三十三条","txt":"学校不得组织学生参加抢险等应当由专业人员或者成人从事的活动，不得组织学生参与制作烟花爆竹、有毒化学品等具有危险性的活动，不得组织学生参加商业性活动。"},{"i":34,"n":"第三十四条","txt":"学校不得将场地出租给他人从事易燃、易爆、有毒、有害等危险品的生产、经营活动。 学校不得出租校园内场地停放校外机动车辆；不得利用学校用地建设对社会开放的停车场。"},{"i":35,"n":"第三十五条","txt":"学校教职工应当符合相应任职资格和条件要求。学校不得聘用因故意犯罪而受到刑事处罚的人，或者有精神病史的人担任教职工。 学校教师应当遵守职业道德规范和工作纪律，不得侮辱、殴打、体罚或者变相体罚学生；发现学生行为具有危险性的，应当及时告诫、制止，并与学生监护人沟通。"},{"i":36,"n":"第三十六条","txt":"学生在校学习和生活期间，应当遵守学校纪律和规章制度，服从学校的安全教育和管理，不得从事危及自身或者他人安全的活动。"},{"i":37,"n":"第三十七条","txt":"监护人发现被监护人有特异体质、特定疾病或者异常心理状况的，应当及时告知学校。 学校对已知的有特异体质、特定疾病或者异常心理状况的学生，应当给予适当关注和照顾。生理、心理状况异常不宜在校学习的学生，应当休学，由监护人安排治疗、休养。"},{"i":38,"n":"第三十八条","txt":"学校应当按照国家课程标准和地方课程设置要求，将安全教育纳入教学内容，对学生开展安全教育，培养学生的安全意识，提高学生的自我防护能力。"},{"i":39,"n":"第三十九条","txt":"学校应当在开学初、放假前，有针对性地对学生集中开展安全教育。新生入校后，学校应当帮助学生及时了解相关的学校安全制度和安全规定。"},{"i":40,"n":"第四十条","txt":"学校应当针对不同课程实验课的特点与要求，对学生进行实验用品的防毒、防爆、防辐射、防污染等的安全防护教育。 学校应当对学生进行用水、用电的安全教育，对寄宿学生进行防火、防盗和人身防护等方面的安全教育。"},{"i":41,"n":"第四十一条","txt":"学校应当对学生开展安全防范教育，使学生掌握基本的自我保护技能，应对不法侵害。 学校应当对学生开展交通安全教育，使学生掌握基本的交通规则和行为规范。 学校应当对学生开展消防安全教育，有条件的可以组织学生到当地消防站参观和体验，使学生掌握基本的消防安全知识，提高防火意识和逃生自救的能力。 学校应当根据当地实际情况，有针对性地对学生开展到江河湖海、水库等地方戏水、游泳的安全卫生教育。"},{"i":42,"n":"第四十二条","txt":"学校可根据当地实际情况，组织师生开展多种形式的事故预防演练。 学校应当每学期至少开展一次针对洪水、地震、火灾等灾害事故的紧急疏散演练，使师生掌握避险、逃生、自救的方法。"},{"i":43,"n":"第四十三条","txt":"教育行政部门按照有关规定，与人民法院、人民检察院和公安、司法行政等部门以及高等学校协商，选聘优秀的法律工作者担任学校的兼职法制副校长或者法制辅导员。 兼职法制副校长或者法制辅导员应当协助学校检查落实安全制度和安全事故处理、定期对师生进行法制教育等，其工作成果纳入派出单位的工作考核内容。"},{"i":44,"n":"第四十四条","txt":"教育行政部门应当组织负责安全管理的主管人员、学校校长、幼儿园园长和学校负责安全保卫工作的人员，定期接受有关安全管理培训。"},{"i":45,"n":"第四十五条","txt":"学校应当制定教职工安全教育培训计划，通过多种途径和方法，使教职工熟悉安全规章制度、掌握安全救护常识，学会指导学生预防事故、自救、逃生、紧急避险的方法和手段。"},{"i":46,"n":"第四十六条","txt":"学生监护人应当与学校互相配合，在日常生活中加强对被监护人的各项安全教育。 学校鼓励和提倡监护人自愿为学生购买意外伤害保险。"},{"i":47,"n":"第四十七条","txt":"教育、公安、司法行政、建设、交通、文化、卫生、工商、质检、新闻出版等部门应当建立联席会议制度，定期研究部署学校安全管理工作，依法维护学校周边秩序；通过多种途径和方式，听取学校和社会各界关于学校安全管理工作的意见和建议。"},{"i":48,"n":"第四十八条","txt":"建设、公安等部门应当加强对学校周边建设工程的执法检查，禁止任何单位或者个人违反有关法律、法规、规章、标准，在学校围墙或者建筑物边建设工程，在校园周边设立易燃易爆、剧毒、放射性、腐蚀性等危险物品的生产、经营、储存、使用场所或者设施以及其他可能影响学校安全的场所或者设施。"},{"i":49,"n":"第四十九条","txt":"公安机关应当把学校周边地区作为重点治安巡逻区域，在治安情况复杂的学校周边地区增设治安岗亭和报警点，及时发现和消除各类安全隐患，处置扰乱学校秩序和侵害学生人身、财产安全的违法犯罪行为。"},{"i":50,"n":"第五十条","txt":"公安、建设和交通部门应当依法在学校门前道路设置规范的交通警示标志，施划人行横线，根据需要设置交通信号灯、减速带、过街天桥等设施。 在地处交通复杂路段的学校上下学时间，公安机关应当根据需要部署警力或者交通协管人员维护道路交通秩序。"},{"i":51,"n":"第五十一条","txt":"公安机关和交通部门应当依法加强对农村地区交通工具的监督管理，禁止没有资质的车船搭载学生。"},{"i":52,"n":"第五十二条","txt":"文化部门依法禁止在中学、小学校园周围200米范围内设立互联网上网服务营业场所，并依法查处接纳未成年人进入的互联网上网服务营业场所。工商行政管理部门依法查处取缔擅自设立的互联网上网服务营业场所。"},{"i":53,"n":"第五十三条","txt":"新闻出版、公安、工商行政管理等部门应当依法取缔学校周边兜售非法出版物的游商和无证照摊点，查处学校周边制售含有淫秽色情、凶杀暴力等内容的出版物的单位和个人。"},{"i":54,"n":"第五十四条","txt":"卫生、工商行政管理部门应当对校园周边饮食单位的卫生状况进行监督，取缔非法经营的小卖部、饮食摊点。"},{"i":55,"n":"第五十五条","txt":"在发生地震、洪水、泥石流、台风等自然灾害和重大治安、公共卫生突发事件时，教育等部门应当立即启动应急预案，及时转移、疏散学生，或者采取其他必要防护措施，保障学校安全和师生人身财产安全。"},{"i":56,"n":"第五十六条","txt":"校园内发生火灾、食物中毒、重大治安等突发安全事故以及自然灾害时，学校应当启动应急预案，及时组织教职工参与抢险、救助和防护，保障学生身体健康和人身、财产安全。"},{"i":57,"n":"第五十七条","txt":"发生学生伤亡事故时，学校应当按照《学生伤害事故处理办法》规定的原则和程序等，及时实施救助，并进行妥善处理。"},{"i":58,"n":"第五十八条","txt":"发生教职工和学生伤亡等安全事故的，学校应当及时报告主管教育行政部门和政府有关部门；属于重大事故的，教育行政部门应当按照有关规定及时逐级上报。"},{"i":59,"n":"第五十九条","txt":"省级教育行政部门应当在每年1月31日前向国务院教育行政部门书面报告上一年度学校安全工作和学生伤亡事故情况。"},{"i":60,"n":"第六十条","txt":"教育、公安、司法行政、建设、交通、文化、卫生、工商、质检、新闻出版等部门，对在学校安全工作中成绩显著或者做出突出贡献的单位和个人，应当视情况联合或者分别给予表彰、奖励。"},{"i":61,"n":"第六十一条","txt":"教育、公安、司法行政、建设、交通、文化、卫生、工商、质检、新闻出版等部门，不依法履行学校安全监督与管理职责的，由上级部门给予批评；对直接责任人员由上级部门和所在单位视情节轻重，给予批评教育或者行政处分；构成犯罪的，依法追究刑事责任。"},{"i":62,"n":"第六十二条","txt":"学校不履行安全管理和安全教育职责，对重大安全隐患未及时采取措施的，有关主管部门应当责令其限期改正；拒不改正或者有下列情形之一的，教育行政部门应当对学校负责人和其他直接责任人员给予行政处分；构成犯罪的，依法追究刑事责任： （一）发生重大安全事故、造成学生和教职工伤亡的； （二）发生事故后未及时采取适当措施、造成严重后果的； （三）瞒报、谎报或者缓报重大事故的； （四）妨碍事故调查或者提供虚假情况的； （五）拒绝或者不配合有关部门依法实施安全监督管理职责的。 《中华人民共和国民办教育促进法》及其实施条例另有规定的，依其规定执行。"},{"i":63,"n":"第六十三条","txt":"校外单位或者人员违反治安管理规定、引发学校安全事故的，或者在学校安全事故处理过程中，扰乱学校正常教育教学秩序、违反治安管理规定的，由公安机关依法处理；构成犯罪的，依法追究其刑事责任；造成学校财产损失的，依法承担赔偿责任。"},{"i":64,"n":"第六十四条","txt":"学生人身伤害事故的赔偿，依据有关法律法规、国家有关规定以及《学生伤害事故处理办法》处理。"},{"i":65,"n":"第六十五条","txt":"中等职业学校学生实习劳动的安全管理办法另行制定。"},{"i":66,"n":"第六十六条","txt":"本办法自2006年9月1日起施行。"}],"zhongxiaoxuejiaoshijixujiaoyuguiding":[{"i":1,"n":"第一条","txt":"为了提高中小学教师队伍整体素质，适应基础教育改革发展和全面推进素质教育的需要，根据《中华人民共和国教育法》和《中华人民共和国教师法》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于国家和社会力量举办的中小学在职教师的继续教育工作。"},{"i":3,"n":"第三条","txt":"中小学教师继续教育，是指对取得教师资格的中小学在职教师为提高思想政治和业务素质进行的培训。"},{"i":4,"n":"第四条","txt":"参加继续教育是中小学教师的权利和义务。"},{"i":5,"n":"第五条","txt":"各级人民政府教育行政部门管理中小学教师继续教育工作，应当采取措施，依法保障中小学教师继续教育工作的实施。"},{"i":6,"n":"第六条","txt":"中小学教师继续教育应坚持因地制宜、分类指导、按需施教、学用结合的原则，采取多种形式，注重质量和实效。"},{"i":7,"n":"第七条","txt":"中小学教师继续教育原则上每五年为一个培训周期。"},{"i":8,"n":"第八条","txt":"中小学教师继续教育要以提高教师实施素质教育的能力和水平为重点。中小学教师继续教育的内容主要包括：思想政治教育和师德修养；专业知识及更新与扩展；现代教育理论与实践；教育科学研究；教育教学技能训练和现代教育技术；现代科技与人文社会科学知识等。"},{"i":9,"n":"第九条","txt":"中小学教师继续教育分为非学历教育和学历教育。 （一）非学历教育包括： 新任教师培训：为新任教师在试用期内适应教育教学工作需要而设置的培训。培训时间应不少于120学时。 教师岗位培训：为教师适应岗位要求而设置的培训。培训时间每五年累计不少于240学时。 骨干教师培训：对有培养前途的中青年教师按教育教学骨干的要求和对现有骨干教师按更高标准进行的培训。 （二）学历教育：对具备合格学历的教师进行的提高学历层次的培训。"},{"i":10,"n":"第十条","txt":"国务院教育行政部门宏观管理全国中小学教师继续教育工作；制定有关方针、政策；制定中小学教师继续教育教学基本文件，组织审定统编教材；建立中小学教师继续教育评估体系；指导各省、自治区、直辖市中小学教师继续教育工作。"},{"i":11,"n":"第十一条","txt":"省、自治区、直辖市人民政府教育行政部门主管本地区中小学教师继续教育工作；制定本地区中小学教师继续教育配套政策和规划；全面负责本地区中小学教师继续教育的实施、检查和评估工作。市（地、州、盟）、县（区、市、旗）人民政府教育行政部门在省级人民政府教育行政部门指导下，负责管理本地区中小学教师继续教育工作。"},{"i":12,"n":"第十二条","txt":"各级教师进修院校和普通师范院校在主管教育行政部门领导下，具体实施中小学教师继续教育的教育教学工作。中小学校应有计划地安排教师参加继续教育，并组织开展校内多种形式的培训。综合性高等学校、非师范类高等学校和其它教育机构，经教育行政部门批准，可参与中小学教师继续教育工作。经主管教育行政部门批准，社会力量可以举办中小学教师继续教育机构，但要符合国家规定的办学标准，保证中小学教师继续教育质量。"},{"i":13,"n":"第十三条","txt":"中小学教师继续教育经费以政府财政拨款为主，多渠道筹措，在地方教育事业费中专项列支。地方教育费附加应有一定比例用于义务教育阶段的教师培训。省、自治区、直辖市人民政府教育行政部门要制定中小学教师继续教育人均基本费用标准。中小学教师继续教育经费由县级及以上教育行政部门统一管理，不得截留或挪用。社会力量举办的中小学和其他教育机构教师的继续教育经费，由举办者自筹。"},{"i":14,"n":"第十四条","txt":"地方各级人民政府教育行政部门要按照国家规定的办学标准，保证对中小学教师培训机构的投入。"},{"i":15,"n":"第十五条","txt":"地方各级人民政府教育行政部门要加强中小学教师培训机构的教师队伍建设。"},{"i":16,"n":"第十六条","txt":"经教育行政部门和学校批准参加继续教育的中小学教师，学习期间享受国家规定的工资福利待遇。学费、差旅费按各地有关规定支付。"},{"i":17,"n":"第十七条","txt":"各级人民政府教育行政部门应当采取措施，大力扶持少数民族地区和边远贫困地区的中小学教师继续教育工作。"},{"i":18,"n":"第十八条","txt":"地方各级人民政府教育行政部门要建立中小学教师继续教育考核和成绩登记制度。考核成绩作为教师职务聘任、晋级的依据之一。"},{"i":19,"n":"第十九条","txt":"各级人民政府教育行政部门要对中小学教师继续教育工作成绩优异的单位和个人，予以表彰和奖励。"},{"i":20,"n":"第二十条","txt":"违反本规定，无正当理由拒不参加继续教育的中小学教师，所在学校应督促其改正，并视情节给予批评教育。"},{"i":21,"n":"第二十一条","txt":"对中小学教师继续教育质量达不到规定要求的，教育行政主管部门应责令其限期改正。对未按规定办理审批手续而举办中小学教师继续教育活动的，教育行政主管部门应责令其补办手续或停止其举办中小学教师继续教育活动。"},{"i":22,"n":"第二十二条","txt":"本规定所称中小学教师，是指幼儿园，特殊教育机构，普通中小学，成人初等、中等教育机构，职业中学以及其他教育机构的教师。"},{"i":23,"n":"第二十三条","txt":"各省、自治区、直辖市可根据本地区的实际情况，制定具体实施办法。"},{"i":24,"n":"第二十四条","txt":"本规定自发布之日起施行。"}],"zhongxiaoxuejiaoyuchengjieguize":[{"i":1,"n":"第一条","txt":"为落实立德树人根本任务，保障和规范学校、教师依法履行教育教学和管理职责，保护学生合法权益，促进学生健康成长、全面发展，根据教育法、教师法、未成年人保护法、预防未成年人犯罪法等法律法规和国家有关规定，制定本规则。"},{"i":2,"n":"第二条","txt":"普通中小学校、中等职业学校（以下称学校）及其教师在教育教学和管理过程中对学生实施教育惩戒，适用本规则。 本规则所称教育惩戒，是指学校、教师基于教育目的，对违规违纪学生进行管理、训导或者以规定方式予以矫治，促使学生引以为戒、认识和改正错误的教育行为。"},{"i":3,"n":"第三条","txt":"学校、教师应当遵循教育规律，依法履行职责，通过积极管教和教育惩戒的实施，及时纠正学生错误言行，培养学生的规则意识、责任意识。 教育行政部门应当支持、指导、监督学校及其教师依法依规实施教育惩戒。"},{"i":4,"n":"第四条","txt":"实施教育惩戒应当符合教育规律，注重育人效果；遵循法治原则，做到客观公正；选择适当措施，与学生过错程度相适应。"},{"i":5,"n":"第五条","txt":"学校应当结合本校学生特点，依法制定、完善校规校纪，明确学生行为规范，健全实施教育惩戒的具体情形和规则。 学校制定校规校纪，应当广泛征求教职工、学生和学生父母或者其他监护人（以下称家长）的意见；有条件的，可以组织有学生、家长及有关方面代表参加的听证。校规校纪应当提交家长委员会、教职工代表大会讨论，经校长办公会议审议通过后施行，并报主管教育部门备案。 教师可以组织学生、家长以民主讨论形式共同制定班规或者班级公约，报学校备案后施行。"},{"i":6,"n":"第六条","txt":"学校应当利用入学教育、班会以及其他适当方式，向学生和家长宣传讲解校规校纪。未经公布的校规校纪不得施行。 学校可以根据情况建立校规校纪执行委员会等组织机构，吸收教师、学生及家长、社会有关方面代表参加，负责确定可适用的教育惩戒措施，监督教育惩戒的实施，开展相关宣传教育等。"},{"i":7,"n":"第七条","txt":"学生有下列情形之一，学校及其教师应当予以制止并进行批评教育，确有必要的，可以实施教育惩戒： （一）故意不完成教学任务要求或者不服从教育、管理的； （二）扰乱课堂秩序、学校教育教学秩序的； （三）吸烟、饮酒，或者言行失范违反学生守则的； （四）实施有害自己或者他人身心健康的危险行为的； （五）打骂同学、老师，欺凌同学或者侵害他人合法权益的； （六）其他违反校规校纪的行为。 学生实施属于预防未成年人犯罪法规定的不良行为或者严重不良行为的，学校、教师应当予以制止并实施教育惩戒，加强管教；构成违法犯罪的，依法移送公安机关处理。"},{"i":8,"n":"第八条","txt":"教师在课堂教学、日常管理中，对违规违纪情节较为轻微的学生，可以当场实施以下教育惩戒： （一）点名批评； （二）责令赔礼道歉、做口头或者书面检讨； （三）适当增加额外的教学或者班级公益服务任务； （四）一节课堂教学时间内的教室内站立； （五）课后教导； （六）学校校规校纪或者班规、班级公约规定的其他适当措施。 教师对学生实施前款措施后，可以以适当方式告知学生家长。"},{"i":9,"n":"第九条","txt":"学生违反校规校纪，情节较重或者经当场教育惩戒拒不改正的，学校可以实施以下教育惩戒，并应当及时告知家长： （一）由学校德育工作负责人予以训导； （二）承担校内公益服务任务； （三）安排接受专门的校规校纪、行为规则教育； （四）暂停或者限制学生参加游览、校外集体活动以及其他外出集体活动； （五）学校校规校纪规定的其他适当措施。"},{"i":10,"n":"第十条","txt":"小学高年级、初中和高中阶段的学生违规违纪情节严重或者影响恶劣的，学校可以实施以下教育惩戒，并应当事先告知家长： （一）给予不超过一周的停课或者停学，要求家长在家进行教育、管教； （二）由法治副校长或者法治辅导员予以训诫； （三）安排专门的课程或者教育场所，由社会工作者或者其他专业人员进行心理辅导、行为干预。 对违规违纪情节严重，或者经多次教育惩戒仍不改正的学生，学校可以给予警告、严重警告、记过或者留校察看的纪律处分。对高中阶段学生，还可以给予开除学籍的纪律处分。 对有严重不良行为的学生，学校可以按照法定程序，配合家长、有关部门将其转入专门学校教育矫治。"},{"i":11,"n":"第十一条","txt":"学生扰乱课堂或者教育教学秩序，影响他人或者可能对自己及他人造成伤害的，教师可以采取必要措施，将学生带离教室或者教学现场，并予以教育管理。 教师、学校发现学生携带、使用违规物品或者行为具有危险性的，应当采取必要措施予以制止；发现学生藏匿违法、危险物品的，应当责令学生交出并可以对可能藏匿物品的课桌、储物柜等进行检查。 教师、学校对学生的违规物品可以予以暂扣并妥善保管，在适当时候交还学生家长；属于违法、危险物品的，应当及时报告公安机关、应急管理部门等有关部门依法处理。"},{"i":12,"n":"第十二条","txt":"教师在教育教学管理、实施教育惩戒过程中，不得有下列行为： （一）以击打、刺扎等方式直接造成身体痛苦的体罚； （二）超过正常限度的罚站、反复抄写，强制做不适的动作或者姿势，以及刻意孤立等间接伤害身体、心理的变相体罚； （三）辱骂或者以歧视性、侮辱性的言行侵犯学生人格尊严； （四）因个人或者少数人违规违纪行为而惩罚全体学生； （五）因学业成绩而教育惩戒学生； （六）因个人情绪、好恶实施或者选择性实施教育惩戒； （七）指派学生对其他学生实施教育惩戒； （八）其他侵害学生权利的。"},{"i":13,"n":"第十三条","txt":"教师对学生实施教育惩戒后，应当注重与学生的沟通和帮扶，对改正错误的学生及时予以表扬、鼓励。 学校可以根据实际和需要，建立学生教育保护辅导工作机制，由学校分管负责人、德育工作机构负责人、教师以及法治副校长（辅导员）、法律以及心理、社会工作等方面的专业人员组成辅导小组，对有需要的学生进行专门的心理辅导、行为矫治。"},{"i":14,"n":"第十四条","txt":"学校拟对学生实施本规则第十条所列教育惩戒和纪律处分的，应当听取学生的陈述和申辩。学生或者家长申请听证的，学校应当组织听证。 学生受到教育惩戒或者纪律处分后，能够诚恳认错、积极改正的，可以提前解除教育惩戒或者纪律处分。"},{"i":15,"n":"第十五条","txt":"学校应当支持、监督教师正当履行职务。教师因实施教育惩戒与学生及其家长发生纠纷，学校应当及时进行处理，教师无过错的，不得因教师实施教育惩戒而给予其处分或者其他不利处理。 教师违反本规则第十二条，情节轻微的，学校应当予以批评教育；情节严重的，应当暂停履行职责或者依法依规给予处分；给学生身心造成伤害，构成违法犯罪的，由公安机关依法处理。"},{"i":16,"n":"第十六条","txt":"学校、教师应当重视家校协作，积极与家长沟通，使家长理解、支持和配合实施教育惩戒，形成合力。家长应当履行对子女的教育职责，尊重教师的教育权利，配合教师、学校对违规违纪学生进行管教。 家长对教师实施的教育惩戒有异议或者认为教师行为违反本规则第十二条规定的，可以向学校或者主管教育行政部门投诉、举报。学校、教育行政部门应当按照师德师风建设管理的有关要求，及时予以调查、处理。家长威胁、侮辱、伤害教师的，学校、教育行政部门应当依法保护教师人身安全、维护教师合法权益；情形严重的，应当及时向公安机关报告并配合公安机关、司法机关追究责任。"},{"i":17,"n":"第十七条","txt":"学生及其家长对学校依据本规则第十条实施的教育惩戒或者给予的纪律处分不服的，可以在教育惩戒或者纪律处分作出后15个工作日内向学校提起申诉。 学校应当成立由学校相关负责人、教师、学生以及家长、法治副校长等校外有关方面代表组成的学生申诉委员会，受理申诉申请，组织复查。学校应当明确学生申诉委员会的人员构成、受理范围及处理程序等并向学生及家长公布。 学生申诉委员会应当对学生申诉的事实、理由等进行全面审查，作出维持、变更或者撤销原教育惩戒或者纪律处分的决定。"},{"i":18,"n":"第十八条","txt":"学生或者家长对学生申诉处理决定不服的，可以向学校主管教育部门申请复核；对复核决定不服的，可以依法提起行政复议或者行政诉讼。"},{"i":19,"n":"第十九条","txt":"学校应当有针对性地加强对教师的培训，促进教师更新教育理念、改进教育方式方法，提高教师正确履行职责的意识与能力。 每学期末，学校应当将学生受到本规则第十条所列教育惩戒和纪律处分的信息报主管教育行政部门备案。"},{"i":20,"n":"第二十条","txt":"本规则自2021年3月1日起施行。 各地可以结合本地实际，制定本地方实施细则或者指导学校制定实施细则。"}],"zhongxiaoxuexiaozhangpeixunguiding":[{"i":1,"n":"第一条","txt":"为了提高中小学校长队伍的整体素质，全面推进素质教育，促进基础教育的改革和发展，根据《中华人民共和国教育法》和国家有关规定，特定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于国家和社会力量举办的全日制普通中小学校长培训工作。"},{"i":3,"n":"第三条","txt":"各级人民政府教育行政部门根据教育事业发展的需要，按照校长任职要求，有计划地对校长进行培训。"},{"i":4,"n":"第四条","txt":"中小学校长培训要坚持为全面实施素质教育服务的宗旨，坚持因地制宜，分类指导和理论联系实际，学用一致，按需施教，讲求实效的原则。"},{"i":5,"n":"第五条","txt":"参加培训是中小学校长的权利和义务，新任校长必须取得“任职资格培训合格证书”，持证上岗。在职校长每五年必须接受国家规定时数的提高培训，并取得“提高培训合格证书”，作为继续任职的必备条件。"},{"i":6,"n":"第六条","txt":"中小学校长培训要以提高校长组织实施素质教育的能力和水平为重点。其内容主要包括政治理论、思想品德修养、教育政策法规、现代教育理论和实践、学校管理理论和实践、现代教育技术、现代科技和人文社会科学知识等方面。培训具体内容要视不同对象的实际需求有所侧重。"},{"i":7,"n":"第七条","txt":"中小学校长培训以在职或短期离岗的非学历培训为主，主要包括： 任职资格培训：按照中小学校长岗位规范要求，对新任校长或拟任校长进行以掌握履行岗位职责必备的知识和技能为主要内容的培训。培训时间累计不少于300学时。 在职校长提高培训：面向在职校长进行的以学习新知识、掌握新技能、提高管理能力、研究和交流办学经验为主要内容的培训。培训时间每五年累计不少于240学时。 骨干校长高级研修：对富有办学经验并且具有一定理论修养和研究能力的校长进行的，旨在培养学校教育、教学和管理专家的培训。"},{"i":8,"n":"第八条","txt":"中小学校长培训实施学时制，也可采用集中专题、分段教学、累计学分的办法。"},{"i":9,"n":"第九条","txt":"各级人民政府教育行政部门和有关培训机构，要充分利用国家提供的现代远程教育资源，并积极创造条件，运用现代教育技术手段开展中小学校长培训工作。"},{"i":10,"n":"第十条","txt":"国务院教育行政部门宏观管理全国中小学校长培训工作。主要职责是：制定保障、规范中小学校长培训工作的有关规章、政策；制订并组织实施培训工作总体规划；制定培训教学基本文件，组织推荐、审定培训教材；建立培训质量评估体系；指导各省、自治区、直辖市中小学校长培训工作。"},{"i":11,"n":"第十一条","txt":"省、自治区、直辖市政府教育行政部门主管本地区中小学校长培训工作；制定本地区中小学校长培训规划和配套政策；全面负责本地区中小学校长培训的实施、检查和评估工作。"},{"i":12,"n":"第十二条","txt":"省、自治区、直辖市政府教育行政部门对申请承担中小学校长培训任务的机构要进行资格认定。普通师范院校、教师进修院校、有条件的综合大学，经国务院教育行政部门或省、自治区、直辖市人民政府教育行政部门批准，可以承担中小学校长培训任务。"},{"i":13,"n":"第十三条","txt":"中小学校长培训施教机构的教师实行专兼结合。培训机构应当配备素质较高、适应培训工作需要的专职教师队伍，并聘请一定数量的校外专家学者、教育行政部门领导和优秀中小学校长作为兼职教师。"},{"i":14,"n":"第十四条","txt":"对参加培训并经考核合格的中小学校长，发给相应的培训证书。省、自治区、直辖市人民政府教育行政部门要加强对证书的管理。"},{"i":15,"n":"第十五条","txt":"经教育行政部门批准参加培训的中小学校长，培训期间享受国家规定的工资福利待遇，培训费、差旅费按财务制度规定执行。"},{"i":16,"n":"第十六条","txt":"中小学校长培训经费以政府财政拨款为主，多渠道筹措，地方教育费附加应有一定比例用于培训中小学校长工作。省、自治区、直辖市人民政府教育行政部门要制定中小学校长培训人均基本费用标准。"},{"i":17,"n":"第十七条","txt":"各级人民政府教育行政部门应当把中小学校长参加培训的情况纳入教育督导的重要内容。对培训工作成绩突出的单位和个人，予以表彰和奖励。"},{"i":18,"n":"第十八条","txt":"各级人民政府教育行政部门和学校要保障中小学校长接受培训的权利。中小学校长对有关组织或者个人侵犯其接受培训权利的，有权按有关程序向主管教育行政机关提出申诉。"},{"i":19,"n":"第十九条","txt":"违反本规定，无正当理由拒不按计划参加培训的中小学校长，学校主管行政机关应督促其改正，并视情节给予批评教育、行政处分、直至撤销其职务。"},{"i":20,"n":"第二十条","txt":"担任中小学校长者，应取得《任职资格培训合格证书》，或应在任职之日起六个月内，由校长任免机关 (或聘任机构)安排，接受任职资格培训，并取得《任职资格培训合格证书》。在职中小学校长没有按计划接受或者没有达到国家规定时数的提高培训，或者考核不合格者，中小学校长任免机关（或聘任机构），应令其在一年内补正。期满仍未能取得《提高培训合格证书》者，不能继续担任校长职务。"},{"i":21,"n":"第二十一条","txt":"经评估达不到培训要求的培训机构，主管教育行政机关要令其限期改正，逾期不改者，应责令其停止中小学校长培训工作。"},{"i":22,"n":"第二十二条","txt":"对未经批准自行设立、举办中小学校长培训机构或中小学校长培训班的，主管教育行政机关应根据有关法律法规的规定，给予相应的行政处罚。"},{"i":23,"n":"第二十三条","txt":"幼儿园园长、特殊教育学校校长培训参照本规定执行。中等职业学校及其他各类成人初、中等教育学校校长培训另行安排。"},{"i":24,"n":"第二十四条","txt":"各省、自治区、直辖市教育行政部门可以依据本规定制定具体的实施办法。"}],"zhongxiaoxuefazhifuxiaozhangpinrenyuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了完善中小学治理体系，健全学生权益保护机制，进一步规范中小学法治副校长聘任与管理，促进未成年人健康成长，根据教育法、未成年人保护法、预防未成年人犯罪法等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"普通中小学、中等职业学校、特殊教育学校、专门学校（以下统称学校）法治副校长的聘任与管理，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称法治副校长，是指由人民法院、人民检察院、公安机关、司法行政部门推荐或者委派，经教育行政部门或者学校聘任，在学校兼任副校长职务，协助开展法治教育、学生保护、安全管理、预防犯罪、依法治理等工作的人员。"},{"i":4,"n":"第四条","txt":"国务院教育行政部门会同最高人民法院、最高人民检察院、公安部、司法部制定学校法治副校长聘任与管理的宏观政策，统筹指导地方开展法治副校长的推荐、聘任、培训、考核、评价、奖励等工作。 县级以上地方人民政府教育行政部门会同人民法院、人民检察院、公安机关、司法行政部门负责本地区学校法治副校长聘任与管理工作。 有条件的地方，可以建立由教育行政部门、人民法院、人民检察院、公安机关、司法行政部门参加的学校法治副校长工作联席会议制度，统筹推进本地区学校法治副校长聘任与管理工作。"},{"i":5,"n":"第五条","txt":"法治副校长履职期间协助开展以下工作： （一）开展法治教育。推动习近平法治思想的学习宣传，参与制订学校法治教育工作计划，协助学校创新法治教育内容和形式，每年在任职学校承担或者组织落实不少于4课时的、以法治实践教育为主的法治教育任务，提高法治教育的针对性和实效性。面向教职工开展法治宣传，指导、帮助道德与法治等课程教师开展法治教育。 （二）保护学生权益。参与学校学生权益保护制度的制定、执行，参加学生保护委员会、学生欺凌治理等组织，指导、监督学校落实未成年人保护职责，依法保护学生权益。 （三）预防未成年人犯罪。指导学校对未成年学生进行有针对性的预防犯罪教育，对有不良行为的学生加强管理和教育。 （四）参与安全管理。指导学校完善安全管理制度，协调推动建立学校安全区域制度，协助学校健全安全事故预防与处置机制，主持或者参与学校安全事故的调解协商，指导学校依法处理安全事故纠纷，制止侵害学校和师生合法权益"},{"i":6,"n":"第六条","txt":"人民法院、人民检察院、公安机关和司法行政部门（以下称派出机关）应当遴选、推荐符合以下条件的在职工作人员担任法治副校长： （一）政治素质好，品德优秀，作风正派，责任心强； （二）有较丰富的法律专业知识与法治实践经历，从事法治工作三年以上； （三）身心健康，热心教育工作，了解教育教学规律和学生的身心特点，关心学生健康成长； （四）具有较强的语言表达能力、沟通交流能力和组织协调能力。 符合上述条件，年龄不超过65周岁的退休人员也可以经推荐担任一个任期的法治副校长。"},{"i":7,"n":"第七条","txt":"教育行政部门应当商有关部门制定法治副校长聘任计划，会同派出机关综合考虑学校需求和工作便利，协商确定、统筹安排法治副校长人选，优先为偏远地区、农村地区学校和城市薄弱学校配备法治副校长。"},{"i":8,"n":"第八条","txt":"每所学校应当配备至少1名法治副校长，师生人数多、有需求的学校，可以聘任2名以上5名以下法治副校长。 根据工作需要，1人可以同时担任2所学校的法治副校长。"},{"i":9,"n":"第九条","txt":"县级或者设区的市级人民政府教育行政部门可以商有关部门组建由不同派出机关人员组成的法治副校长工作团队，服务区域内学校。"},{"i":10,"n":"第十条","txt":"教育行政部门会同派出机关建立法治副校长人员库，推荐符合条件的人员入库并动态调整。 教育行政部门组织学校根据工作需要，参照就近就便的原则，从人员库中自主或者根据统一安排选聘法治副校长，经各方协商一致，确定聘任人选。"},{"i":11,"n":"第十一条","txt":"法治副校长由所聘学校颁发聘书。聘期一般为三年，期满后可以续聘。 学校已聘任的法治副校长因派出机关工作变动或其他原因不宜或者不能继续履职的，应当及时报告，由教育主管部门会同派出机关在30日内重新推荐或者委派。"},{"i":12,"n":"第十二条","txt":"教育行政部门应当会同派出机关制定法治副校长培训方案和规划，并纳入教师、校长培训规划，安排经费对法治副校长开展培训。培训应当包括政治理论、未成年人保护、教育法律政策、心理健康教育、学校安全管理等方面的内容。 法治副校长任职前，应当接受不少于8学时的培训。任职期间，根据实际安排参加相应的培训。"},{"i":13,"n":"第十三条","txt":"派出机关应当采取必要措施，保障所派出的法治副校长在任职学校有必要的工作时间和条件，鼓励、支持其履职尽责。 法治副校长应当按照本办法主动参与学校工作，积极参加培训，定期到校开展工作。鼓励法治副校长利用信息化手段，参与学校工作。"},{"i":14,"n":"第十四条","txt":"学校应当将支持法治副校长履职纳入整体工作规划，主动向法治副校长介绍学校有关情况，定期收集教职工、学生及学生家长的法律服务需求并及时向法治副校长反馈，配合法治副校长做好相关工作。涉及到法治副校长履职的会议、活动，应当事先与法治副校长沟通，并通知其参加。 学校应当结合实际为法治副校长履职提供必要的便利条件。 法治副校长的基本情况和工作职责等应当以适当方式在学校公示。"},{"i":15,"n":"第十五条","txt":"派出机关、教育行政部门可以根据有关规定，为在偏远农村地区、交通不便地区学校任职的法治副校长给予食宿、交通等补助。"},{"i":16,"n":"第十六条","txt":"学校应当建立法治副校长工作评价制度，按年度对法治副校长工作情况作出评价。 学校对法治副校长进行评价时，应当听取教职工、学生及学生家长意见，形成客观、公正的评价结果，并将结果报送教育主管部门，由教育主管部门反馈派出机关。"},{"i":17,"n":"第十七条","txt":"派出机关应当将担任法治副校长工作纳入相关工作人员的工作量，明确为考核内容，学校作出的工作评价以及法治副校长的述职报告等应当一并作为考核其工作、晋职、晋级和立功受奖的重要依据。"},{"i":18,"n":"第十八条","txt":"地方教育行政部门应当定期对本区域内法治副校长的履职情况进行考评，对工作成绩突出的法治副校长，应当予以表彰、奖励或者会同派出机关联合予以表彰、奖励。 司法行政部门应当将派出机关法治副校长履职情况作为落实“谁执法谁普法”普法责任制的重要方面，纳入普法工作考核内容。对推荐、聘任法治副校长工作成绩突出的派出机关、学校，应当作为普法工作评先评优的重要参考。 各级教育行政部门应当会同派出机关对组织开展中小学法治副校长工作有显著成绩的组织和个人，按照有关规定给予表彰、奖励。"},{"i":19,"n":"第十九条","txt":"学校从其他执法机关、法学教育和法律服务机构等单位聘任校外法治辅导员的，参照本办法执行。 幼儿园聘任法治副园长的，聘任与管理参照本办法执行。"},{"i":20,"n":"第二十条","txt":"本办法自2022年5月1日起施行。"}],"xinxijishuchanpinguojiatongyongyuyanwenzishiyonggu3794d9":[{"i":1,"n":"第一条","txt":"为规范信息技术产品国家通用语言文字使用，保障信息化条件下语言生活和谐健康发展，根据《中华人民共和国国家通用语言文字法》《中华人民共和国标准化法》《中华人民共和国产品质量法》《出版管理条例》《互联网信息服务管理办法》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内生产、销售、出版、发布、推广对国家通用语言文字进行信息化处理和使用国家通用语言文字进行内容编辑的信息技术产品，适用本规定。 本规定所称的信息技术产品主要有： （一）基础软件，包括字库、输入系统、操作系统、数据库系统、办公套件等； （二）语言文字智能处理软件，包括语音合成、语音转写、机器翻译、智能写作、智能校对、自动问答等功能软件； （三）数字和网络出版物。"},{"i":3,"n":"第三条","txt":"信息技术产品使用国家通用语言文字，应当有利于维护国家主权和民族尊严、有利于铸牢中华民族共同体意识，应当弘扬社会主义核心价值观、遵守公序良俗。 信息技术产品使用国家通用语言文字，应当符合国家颁布的语言文字规范标准。"},{"i":4,"n":"第四条","txt":"国务院语言文字工作部门负责统筹协调并会同有关主管部门对全国信息技术产品的国家通用语言文字使用进行监督管理和指导服务。 地方语言文字工作部门负责统筹协调并会同地方有关主管部门对本行政区域内信息技术产品的国家通用语言文字使用进行监督管理和指导服务。"},{"i":5,"n":"第五条","txt":"基础软件应当符合信息技术编码字符集等标准。汉字字库应当符合汉字字形规范。汉字输入系统应当依据汉语拼音方案、普通话语音、汉字笔画和部件等语言文字规范标准设计，并具备一定的规范用法提示功能。"},{"i":6,"n":"第六条","txt":"数字和网络出版物使用国家通用语言文字，应当符合汉语拼音、普通话语音、规范汉字、现代汉语词形、标点符号和数字用法等语言文字规范标准。需要使用汉语方言、繁体字、异体字的，应当符合《中华人民共和国国家通用语言文字法》相关规定。 教材、现代汉语语文工具书类数字和网络出版物使用国家通用语言文字，还应当在语言文字的排序、检索、注音、释义、用例及相关知识阐释等方面执行本条第一款规定的语言文字规范标准。需要变通的，应当以适当方式体现相关规范标准的规定。"},{"i":7,"n":"第七条","txt":"语言文字智能处理软件及其系统集成产品应当遵照汉语拼音、普通话语音、规范汉字、现代汉语词形、标点符号和数字用法等语言文字规范标准和现代汉语语法规律，持续优化语言文字处理功能，不断提升输出结果的规范化水平。"},{"i":8,"n":"第八条","txt":"办公套件、智能校对软件等应当视需要为用户提供以下提示功能： （一）规范汉字文本中夹用的繁体字、异体字； （二）错别字、错符； （三）现代汉语异形词非推荐词形； （四）其他可能影响语言文字规范使用的情况。"},{"i":9,"n":"第九条","txt":"嵌有语音合成、语音转写、机器翻译、智能写作、自动问答等语言文字智能处理功能的互联网信息服务平台应当设置信息反馈功能，及时受理用户关于语言文字不规范情况的反馈，并根据反馈信息进一步优化功能，不断提升语言文字智能处理结果的规范化水平。"},{"i":10,"n":"第十条","txt":"面向残疾人、老年人的信息技术产品，应当具备语言文字信息无障碍功能。面向少年儿童的信息技术产品，应当符合其身心特点和语言文字学习规律。"},{"i":11,"n":"第十一条","txt":"国务院语言文字工作部门和有关主管部门在信息技术产品国家通用语言文字使用监督管理和质量检查工作中，可以授权第三方机构对相关产品进行语言文字规范标准符合性检测。 鼓励有关检测认证机构为社会提供面向信息技术产品的语言文字规范标准符合性检测服务。"},{"i":12,"n":"第十二条","txt":"国务院语言文字工作部门会同有关主管部门，负责对现代汉语语文工具书类数字和网络出版物进行监督检查。"},{"i":13,"n":"第十三条","txt":"地方各级语言文字工作部门负责对本行政区域内除教材和现代汉语语文工具书之外的其他数字和网络出版物进行监督检查。检查结果通报同级主管部门，同时向上级语言文字工作部门报告。"},{"i":14,"n":"第十四条","txt":"国务院语言文字工作部门通过适当方式，为促进语言文字智能处理软件的研发和功能完善、提升现代汉语语文工具书类数字和网络出版物编纂质量提供指导与服务。"},{"i":15,"n":"第十五条","txt":"国务院语言文字工作部门依法制定、修订并主动公开语言文字规范标准，会同有关主管部门做好行业领域有关规范标准的研究、制定、修订及信息公开工作。"},{"i":16,"n":"第十六条","txt":"国务院语言文字工作部门对在信息技术产品国家通用语言文字使用的管理、服务及相关技术研发中作出突出贡献的组织和个人，依据《中华人民共和国国家通用语言文字法》的有关规定，予以表彰和奖励。"},{"i":17,"n":"第十七条","txt":"基础软件处理国家通用语言文字违反本规定第五条的，由国务院语言文字工作部门会同有关主管部门督促软件生产方限期改正。拒不改正的，由主管部门依据《中华人民共和国标准化法》《中华人民共和国产品质量法》等法律法规予以处理。"},{"i":18,"n":"第十八条","txt":"现代汉语语文工具书类数字和网络出版物使用国家通用语言文字违反本规定第六条的，由国务院语言文字工作部门会同有关主管部门督促出版方限期改正。拒不改正的，由主管部门依据《出版管理条例》等法律法规予以处理。"},{"i":19,"n":"第十九条","txt":"其他数字和网络出版物使用国家通用语言文字违反本规定第六条的，由县级以上地方语言文字工作部门会同同级主管部门督促出版方限期改正。拒不改正的，由主管部门依据《出版管理条例》等法律法规予以处理。"},{"i":20,"n":"第二十条","txt":"国务院语言文字工作部门应当加强信息技术产品国家通用语言文字使用情况的监测和研究，并会同有关部门组织开展宣传教育和业务指导。"},{"i":21,"n":"第二十一条","txt":"国务院和地方各级语言文字工作部门应当建立工作协同机制，为同级有关主管部门依法管理信息技术产品中使用国家通用语言文字提供咨询服务、执法协助等支持。"},{"i":22,"n":"第二十二条","txt":"本规定自2023年3月1日起施行。"}],"guojiajiaoyukaoshiweiguichulibanfa":[{"i":1,"n":"第一条","txt":"为规范对国家教育考试违规行为的认定与处理，维护国家教育考试的公平、公正，保障参加国家教育考试的人员(以下简称考生)、从事和参与国家教育考试工作的人员(以下简称考试工作人员)的合法权益，根据《中华人民共和国教育法》及相关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称国家教育考试是指普通和成人高等学校招生考试、全国硕士研究生招生考试、高等教育自学考试等，由国务院教育行政部门确定实施，由经批准的教育考试机构承办，在全国范围内统一举行的教育考试。"},{"i":3,"n":"第三条","txt":"对参加国家教育考试的考生以及考试工作人员、其他相关人员，违反考试管理规定和考场纪律，影响考试公平、公正行为的认定与处理，适用本办法。 对国家教育考试违规行为的认定与处理应当公开公平、合法适当。"},{"i":4,"n":"第四条","txt":"国务院教育行政部门及地方各级人民政府教育行政部门负责全国或者本地区国家教育考试组织工作的管理与监督。 承办国家教育考试的各级教育考试机构负责有关考试的具体实施，依据本办法，负责对考试违规行为的认定与处理。"},{"i":5,"n":"第五条","txt":"考生不遵守考场纪律，不服从考试工作人员的安排与要求，有下列行为之一的，应当认定为考试违纪： (一)携带规定以外的物品进入考场或者未放在指定位置的； (二)未在规定的座位参加考试的； (三)考试开始信号发出前答题或者考试结束信号发出后继续答题的； (四)在考试过程中旁窥、交头接耳、互打暗号或者手势的； (五)在考场或者教育考试机构禁止的范围内，喧哗、吸烟或者实施其他影响考场秩序的行为的； (六)未经考试工作人员同意在考试过程中擅自离开考场的； (七)将试卷、答卷(含答题卡、答题纸等，下同)、草稿纸等考试用纸带出考场的； (八)用规定以外的笔或者纸答题或者在试卷规定以外的地方书写姓名、考号或者以其他方式在答卷上标记信息的； (九)其他违反考场规则但尚未构成作弊的行为。"},{"i":6,"n":"第六条","txt":"考生违背考试公平、公正原则，以不正当手段获得或者试图获得试题答案、考试成绩，有下列行为之一的，应当认定为考试作弊： (一)携带与考试内容相关的文字材料或者存储有与考试内容相关资料的电子设备参加考试的； (二)抄袭或者协助他人抄袭试题答案或者与考试内容相关的资料的； (三)抢夺、窃取他人试卷、答卷或者强迫他人为自己抄袭提供方便的； (四)在考试过程中使用通讯设备的； (五)由他人冒名代替参加考试的； (六)故意销毁试卷、答卷或者考试材料的； (七)在答卷上填写与本人身份不符的姓名、考号等信息的； (八)传、接物品或者交换试卷、答卷、草稿纸的； (九)其他作弊行为。"},{"i":7,"n":"第七条","txt":"教育考试机构、考试工作人员在考试过程中或者在考试结束后发现下列行为之一的，应当认定相关的考生实施了考试作弊行为： (一)通过伪造证件、证明、档案及其他材料获得考试资格和考试成绩的； (二)评卷过程中被发现同一科目同一考场有两份以上(含两份)答卷答案雷同的； (三)考场纪律混乱、考试秩序失控，出现大面积考试作弊现象的； (四)考试工作人员协助实施作弊行为，事后查实的； (五)其他应认定为作弊的行为。"},{"i":8,"n":"第八条","txt":"考生及其他人员应当自觉维护考试工作场所的秩序，服从考试工作人员的管理，不得有下列扰乱考场及考试工作场所秩序的行为： (一)故意扰乱考点、考场、评卷场所等考试工作场所秩序； (二)拒绝、妨碍考试工作人员履行管理职责； (三)威胁、侮辱、诽谤、诬陷考试工作人员或其他考生； (四)其他扰乱考试管理秩序的行为。"},{"i":9,"n":"第九条","txt":"考生有第五条所列考试违纪行为之一的，取消该科目的考试成绩。 考生有第六条、第七条所列考试作弊行为之一的，其当次报名参加考试的各科成绩无效；参加高等教育自学考试考生，视情节轻重，可同时给予停考一至三年，或者延迟毕业时间一至三年的处理，停考期间考试成绩无效。"},{"i":10,"n":"第十条","txt":"考生有第八条所列行为之一的，应当终止其继续参加本科目考试，其当次报名参加考试的各科成绩无效；考生及其他人员的行为违反《治安管理处罚条例》的，由公安机关进行处理；构成犯罪的，由司法机关依法追究刑事责任。"},{"i":11,"n":"第十一条","txt":"考生以作弊行为获得的考试成绩并由此取得相应的学位证书、学历证书及其他学业证书、资格资质证书或者入学资格的，由证书颁发机关宣布证书无效，责令收回证书或者予以没收；已经被录取或者入学的，由录取学校取消录取资格或者其学籍。"},{"i":12,"n":"第十二条","txt":"代替他人或由他人代替参加国家教育考试，是在校生的，由所在学校按有关规定严肃处理，直至开除学籍；其他人员，由教育考试机构建议其所在单位给予行政处分，直至开除或解聘，教育考试机构按照作弊行为记录并向有关单位公开其个人基本信息。"},{"i":13,"n":"第十三条","txt":"考试工作人员应当认真履行工作职责，在考试管理、组织及评卷等工作过程中，有下列行为之一的，应当停止其参加当年及下一年度的国家教育考试工作，并由教育考试机构或者建议其所在单位视情节轻重分别给予相应的行政处分： (一)应回避考试工作却隐瞒不报的； (二)擅自变更考试时间、地点或者考试安排的； (三)提示或暗示考生答题的； (四)擅自将试题、答卷或者有关内容带出考场或者传递给他人的； (五)在评卷、统分中严重失职，造成明显的错评、漏评或者积分误差的； (六)在评卷中擅自更改评分细则或者不按评分细则进行评卷的； (七)因未认真履行职责，造成所负责考场出现雷同卷的； (八)擅自泄露评卷、统分等应予保密的情况的； (九)其他违反监考、评卷等管理规定的行为。"},{"i":14,"n":"第十四条","txt":"考试工作人员有下列作弊行为之一的，应当停止其参加国家教育考试工作，由教育考试机构或者其所在单位视情节轻重分别给予相应的行政处分，并调离考试工作岗位；情节严重，构成犯罪的，由司法机关依法追究刑事责任： (一)为不具备参加国家教育考试条件的人员提供假证明、证件、档案，使其取得考试资格或者考试工作人员资格的； (二)因玩忽职守，致使考生未能如期参加考试的或者使考试工作遭受重大损失的； (三)利用监考或者从事考试工作之便，为考生作弊提供条件的； (四)伪造、变造考生档案(含电子档案)的； (五)在场外组织答卷、为考生提供答案的； (六)指使、纵容或者伙同他人作弊的； (七)偷换、涂改考生答卷、考试成绩或者考场原始记录材料的； (八)擅自更改或者编造、虚报考试数据、信息的； (九)利用考试工作便利，索贿、受贿、以权徇私的； (十)诬陷、打击报复考生的。"},{"i":15,"n":"第十五条","txt":"因教育考试机构管理混乱、考试工作人员玩忽职守，造成考点或者考场纪律混乱，作弊现象严重；或者同一考点同一时间的考试有五分之一(含五分之一)以上考场存在雷同卷的，由教育行政部门取消该考点当年及下一年度承办国家教育考试的资格；高等教育自学考试考区内一个或者一个以上专业考试纪律混乱，作弊现象严重，由高等教育自学考试管理机构给予该考区警告或者停考该考区相应专业一至三年的处理。 对出现大规模作弊情况的考场、考点的相关责任人、负责人及所属考区的负责人，有关部门应当分别给予相应的行政处分；情节严重，构成犯罪的，由司法机关依法追究刑事责任。"},{"i":16,"n":"第十六条","txt":"违反保密规定，造成国家教育考试的试题、答案及评分参考(包括副题及其答案及评分参考，下同)丢失、泄密，或者使考生答卷在保密期限内发生重大事故的，由有关部门视情节轻重，分别给予责任人和有关负责人行政处分；构成犯罪的，由司法机关依法追究刑事责任。 盗窃、损毁、传播在保密期限内的国家教育考试试题、答案及评分参考、考生答卷、考试成绩的，由有关部门依法追究有关人员的责任；构成犯罪的，由司法机关依法追究刑事责任。"},{"i":17,"n":"第十七条","txt":"在职人员及其他人员有下列行为之一的，由教育考试机构建议其所在单位给予行政处分或者由有关部门处理；构成犯罪的，由司法机关依法追究刑事责任： (二)代替他人或者由他人代替参加国家教育考试的； (三)参与或者组织他人进行考试作弊的； (四)利用职权，包庇、掩盖作弊行为或者胁迫他人作弊的； (五)以打击、报复、诬陷、威胁等手段侵犯考试工作人员、考生人身权利的； (六)向考试工作人员行贿的； (七)故意损坏考试设施的； (八)扰乱、妨害考场、评卷点及有关考试工作场所秩序后果严重的。"},{"i":18,"n":"第十八条","txt":"考试工作人员在考试过程中发现考生实施本办法第五条、第六条所列考试违纪、作弊行为的，应当及时予以纠正并如实记录；对考生用于作弊的材料、工具等，应予暂扣。 考生违规记录作为认定考生违规事实的依据，应当由两名以上(含两名)监考员或者考场巡视员、督考员签字确认。 考试工作人员应当向违纪考生告知违规记录的内容，对暂扣的考生物品应填写收据。"},{"i":19,"n":"第十九条","txt":"教育考试机构发现本办法第七条、第八条所列行为的，应当由两名以上(含两名)工作人员进行事实调查，收集、保存相应的证据材料，并在调查事实和证据的基础上，对所涉及考生的违规行为进行认定。"},{"i":20,"n":"第二十条","txt":"考点汇总考生违规记录，汇总情况经考点主考签字认定后，报送上级教育考试机构依据本办法的规定进行处理。"},{"i":21,"n":"第二十一条","txt":"考生在普通和成人高等学校招生考试、高等教育自学考试中，出现第五条所列考试违纪行为的，由省级教育考试机构或者地(市)级教育考试机构做出处理决定，由地(市)级教育考试机构做出的处理决定应报省级教育考试机构备案；出现第六条、第七条所列考试作弊行为的，由地(市)级教育考试机构签署意见，报省级教育考试机构处理，省级教育考试机构也可以要求地(市)级教育考试机构报送材料及证据，直接进行处理；出现本办法第八条所列扰乱考试秩序行为的，由地(市)级教育考试机构签署意见，报省级教育考试机构按照前款规定处理，对考生及其他人员违反治安管理法律法规的行为，由当地公安部门处理；评卷过程中发现考生有本办法第七条所列考试作弊行为的，由省级教育考试机构做出处理决定，并通知地(市)级教育考试机构。 参加其他国家教育考试考生违规行为的处理由承办有关国家教育考试的考试机构参照前款规定具体确定。"},{"i":22,"n":"第二十二条","txt":"教育行政部门和其他有关部门在考点、考场出现大面积作弊情况或者需要对教育考试机构实施监督的情况下，应当直接介入调查和处理。 发生第十四、十五、十六条所列案件，情节严重的，由省级教育行政部门会同有关部门共同处理，并及时报告国务院教育行政部门；必要时，国务院教育行政部门参与或者直接进行处理。"},{"i":23,"n":"第二十三条","txt":"考试工作人员在考场、考点及评卷过程中有违反本办法的行为的，考点主考、评卷点负责人应当暂停其工作，并报相应的教育考试机构处理。"},{"i":24,"n":"第二十四条","txt":"在其他与考试相关的场所违反有关规定的考生，由地(市)级教育考试机构或者省级教育考试机构做出处理决定；地(市)级教育考试机构做出的处理决定应报省级教育考试机构备案。 在其他与考试相关的场所违反有关规定的考试工作人员，由所在单位根据地(市)级教育考试机构或者省级教育考试机构提出的处理意见，进行处理，处理结果应当向提出处理的教育考试机构通报。"},{"i":25,"n":"第二十五条","txt":"教育考试机构在对考试违规的个人或者单位做出处理决定前，应当复核违规事实和相关证据，告知被处理人或者单位做出处理决定的理由和依据；被处理人或者单位对所认定的违规事实认定存在异议的，应当给予其陈述和申辩的机会。 被处理人受到停考处理的，可以要求举行听证。"},{"i":26,"n":"第二十六条","txt":"教育考试机构做出处理决定应制作考试违规处理决定书，载明被处理人的姓名或者单位名称、处理事实根据和法律依据、处理决定的内容、救济途径以及做出处理决定的机构名称和做出处理决定的时间。 考试违规处理决定书应当及时送达被处理人。"},{"i":27,"n":"第二十七条","txt":"考生或者考试工作人员对教育考试机构做出的违规处理决定不服的，可以在收到处理决定之日起十五日内，向其上一级教育考试机构提出复核申请；对省级教育考试机构或者承办国家教育考试的机构做出的处理决定不服的，也可以向省级教育行政部门或者授权承担国家教育考试的主管部门提出复核申请。"},{"i":28,"n":"第二十八条","txt":"受理复核申请的教育考试机构、教育行政部门应对处理决定所认定的违规事实和适用的依据等进行审查，并在受理后三十日内，按照下列规定作出复核决定： (一)处理决定认定事实清楚、证据确凿，适用依据正确，程序合法，内容适当的，决定维持； (二)处理决定有下列情况之一的，决定撤销或者变更： 1．违规事实认定不清、证据不足的； 2．适用依据错误的； 3．违反本办法规定的处理程序的。 做出决定的教育考试机构对因错误的处理决定给考生造成的损失，应当予以补救。"},{"i":29,"n":"第二十九条","txt":"申请人对复核决定或者处理决定不服的，可以依据《行政复议法》和《行政诉讼法》的有关规定，申请行政复议或者行政诉讼。"},{"i":30,"n":"第三十条","txt":"教育考试机构应当建立考生诚信档案，记录、保留在国家教育考试中作弊考生的相关信息。 教育考试机构应当接受社会有关方面对考生诚信档案的查询，并及时向招生机构提供相关信息。"},{"i":31,"n":"第三十一条","txt":"省级教育考试机构应当及时汇总本地区违反规定的考生及考试工作人员的处理情况，并向国家教育考试机构报告。"},{"i":32,"n":"第三十二条","txt":"本办法所称考场是指实施考试的封闭空间；所称考点是指设置若干考场独立进行考务活动的特定场所；所称考区是指由省级教育考试机构设置，由若干考点组成，进行国家教育考试实施工作的特定地区。"},{"i":33,"n":"第三十三条","txt":"非全日制攻读硕士学位全国考试、中国人民解放军高等教育自学考试及其他各级各类教育考试的违规处理可以参照本办法执行。"},{"i":34,"n":"第三十四条","txt":"本办法自发布之日起施行。此前教育部颁布的各有关国家教育考试的违规处理规定同时废止。"}],"xueweilunwenzuojiaxingweichulibanfa":[{"i":1,"n":"第一条","txt":"为规范学位论文管理，推进建立良好学风，提高人才培养质量，严肃处理学位论文作假行为，根据《中华人民共和国学位条例》、《中华人民共和国高等教育法》，制定本办法。"},{"i":2,"n":"第二条","txt":"向学位授予单位申请博士、硕士、学士学位所提交的博士学位论文、硕士学位论文和本科学生毕业论文（毕业设计或其他毕业实践环节）（统称为学位论文），出现本办法所列作假情形的，依照本办法的规定处理。"},{"i":3,"n":"第三条","txt":"本办法所称学位论文作假行为包括下列情形： （一）购买、出售学位论文或者组织学位论文买卖的； （二）由他人代写、为他人代写学位论文或者组织学位论文代写的； （三）剽窃他人作品和学术成果的； （四）伪造数据的； （五）有其他严重学位论文作假行为的。"},{"i":4,"n":"第四条","txt":"学位申请人员应当恪守学术道德和学术规范，在指导教师指导下独立完成学位论文。"},{"i":5,"n":"第五条","txt":"指导教师应当对学位申请人员进行学术道德、学术规范教育，对其学位论文研究和撰写过程予以指导，对学位论文是否由其独立完成进行审查。"},{"i":6,"n":"第六条","txt":"学位授予单位应当加强学术诚信建设，健全学位论文审查制度，明确责任、规范程序，审核学位论文的真实性、原创性。"},{"i":7,"n":"第七条","txt":"学位申请人员的学位论文出现购买、由他人代写、剽窃或者伪造数据等作假情形的，学位授予单位可以取消其学位申请资格；已经获得学位的，学位授予单位可以依法撤销其学位，并注销学位证书。取消学位申请资格或者撤销学位的处理决定应当向社会公布。从做出处理决定之日起至少3年内，各学位授予单位不得再接受其学位申请。 前款规定的学位申请人员为在读学生的，其所在学校或者学位授予单位可以给予开除学籍处分；为在职人员的，学位授予单位除给予纪律处分外，还应当通报其所在单位。"},{"i":8,"n":"第八条","txt":"为他人代写学位论文、出售学位论文或者组织学位论文买卖、代写的人员，属于在读学生的，其所在学校或者学位授予单位可以给予开除学籍处分；属于学校或者学位授予单位的教师和其他工作人员的，其所在学校或者学位授予单位可以给予开除处分或者解除聘任合同。"},{"i":9,"n":"第九条","txt":"指导教师未履行学术道德和学术规范教育、论文指导和审查把关等职责，其指导的学位论文存在作假情形的，学位授予单位可以给予警告、记过处分；情节严重的，可以降低岗位等级直至给予开除处分或者解除聘任合同。"},{"i":10,"n":"第十条","txt":"学位授予单位应当将学位论文审查情况纳入对学院（系）等学生培养部门的年度考核内容。多次出现学位论文作假或者学位论文作假行为影响恶劣的，学位授予单位应当对该学院（系）等学生培养部门予以通报批评，并可以给予该学院（系）负责人相应的处分。"},{"i":11,"n":"第十一条","txt":"学位授予单位制度不健全、管理混乱，多次出现学位论文作假或者学位论文作假行为影响恶劣的，国务院学位委员会或者省、自治区、直辖市人民政府学位委员会可以暂停或者撤销其相应学科、专业授予学位的资格；国务院教育行政部门或者省、自治区、直辖市人民政府教育行政部门可以核减其招生计划；并由有关主管部门按照国家有关规定对负有直接管理责任的学位授予单位负责人进行问责。"},{"i":12,"n":"第十二条","txt":"发现学位论文有作假嫌疑的，学位授予单位应当确定学术委员会或者其他负有相应职责的机构，必要时可以委托专家组成的专门机构，对其进行调查认定。"},{"i":13,"n":"第十三条","txt":"对学位申请人员、指导教师及其他有关人员做出处理决定前，应当告知并听取当事人的陈述和申辩。 当事人对处理决定不服的，可以依法提出申诉、申请行政复议或者提起行政诉讼。"},{"i":14,"n":"第十四条","txt":"社会中介组织、互联网站和个人，组织或者参与学位论文买卖、代写的，由有关主管机关依法查处。 学位论文作假行为违反有关法律法规规定的，依照有关法律法规的规定追究法律责任。"},{"i":15,"n":"第十五条","txt":"学位授予单位应当依据本办法，制定、完善本单位的相关管理规定。"},{"i":16,"n":"第十六条","txt":"本办法自2013年1月1日起施行。"}],"xuexiaozhaoshouhepeiyangguojixueshengguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范学校招收、培养、管理国际学生的行为，为国际学生在中国境内学校学习提供便利，增进教育对外交流与合作，提高中国教育国际化水平，根据《中华人民共和国教育法》《中华人民共和国出境入境管理法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称学校，是指中华人民共和国境内实施学前教育、初等教育、中等教育和高等教育的学校。 本办法所称国际学生，是指根据《中华人民共和国国籍法》不具有中国国籍且在学校接受教育的外国学生。 本办法第二至五章适用于高等学校。实施学前、初等、中等教育的学校，其对国际学生的招生、教学和校内管理，按照省、自治区、直辖市的规定执行。"},{"i":3,"n":"第三条","txt":"学校招收和培养国际学生，应当遵守中国法律法规和国家政策；应当维护国家主权、安全和社会公共利益；应当规范管理、保证质量。 国际学生应当遵守中国法律法规，尊重中国风俗习惯，遵守学校规章制度，完成学校学习任务。"},{"i":4,"n":"第四条","txt":"国务院教育行政部门统筹管理全国国际学生工作，负责制定招收、培养国际学生的宏观政策，指导、协调省、自治区、直辖市人民政府教育行政部门和学校开展国际学生工作，并可委托有关单位和行业组织承担国际学生的管理和服务工作。 国务院外交、公安等行政部门按照职责分工，做好国际学生的相关管理工作。"},{"i":5,"n":"第五条","txt":"省、自治区、直辖市人民政府教育行政部门对本行政区域内国际学生工作进行指导、协调和监管，负责研究制定本行政区域内学前、初等、中等教育阶段国际学生工作的相关政策。 省、自治区、直辖市人民政府外事、公安等行政部门按照职责分工，做好国际学生的相关管理工作。"},{"i":6,"n":"第六条","txt":"招收国际学生的学校，应当建立健全国际学生招收、培养、管理和服务制度，具体负责国际学生的招收与培养。"},{"i":7,"n":"第七条","txt":"招收国际学生的高等学校，应当具备相应的教育教学条件和培养能力，并依照国家有关规定自主招收国际学生。"},{"i":8,"n":"第八条","txt":"招收国际学生的高等学校，应当按照国务院教育行政部门规定的事项和程序进行备案。"},{"i":9,"n":"第九条","txt":"高等学校招收国际学生，接受学历教育的类别为：专科生、本科生、硕士研究生和博士研究生；接受非学历教育的类别为：预科生、进修生和研究学者。"},{"i":10,"n":"第十条","txt":"高等学校按照其办学条件和培养能力自主确定国际学生招生计划和专业，国家另有规定的除外。"},{"i":11,"n":"第十一条","txt":"高等学校按照国家招生规定，制定和公布本校国际学生招生简章，并按照招生简章规定的条件和程序招收国际学生。"},{"i":12,"n":"第十二条","txt":"高等学校应当对报名申请的外国公民的入学资格和经济保证证明进行审查，对其进行考试或者考核。国际学生的录取由学校决定；对不符合招生条件的，学校不得招收。"},{"i":13,"n":"第十三条","txt":"高等学校经征得原招生学校同意，可以接收由其他学校录取或者转学的国际学生。"},{"i":14,"n":"第十四条","txt":"高等学校对国际学生的收费项目和标准，按照国家有关规定执行。 高等学校应当公布对国际学生的收费项目、收费标准和退学、转学的退费规定。收费、退费以人民币计价。"},{"i":15,"n":"第十五条","txt":"高等学校应当将国际学生教学计划纳入学校总体教学计划，选派适合国际学生教学的师资，建立健全教育教学质量保障制度。"},{"i":16,"n":"第十六条","txt":"国际学生应当按照高等学校的课程安排和教学计划参加课程学习，并应当按照规定参加相应的毕业考试或者考核。学校应当如实记录其学习成绩和日常表现。 汉语和中国概况应当作为高等学历教育的必修课；政治理论应当作为学习哲学、政治学专业的国际学生的必修课。"},{"i":17,"n":"第十七条","txt":"国际学生入学后，经学生申请、高等学校同意，国际学生可以转专业。转专业条件和程序由学校规定。"},{"i":18,"n":"第十八条","txt":"中华人民共和国通用语言文字是高等学校培养国际学生的基本教学语言。对国家通用语言文字水平达不到学习要求的国际学生，学校可以提供必要的补习条件。"},{"i":19,"n":"第十九条","txt":"具备条件的高等学校，可以为国际学生开设使用外国语言进行教学的专业课程。使用外国语言接受高等学历教育的国际学生，学位论文可以使用相应的外国文字撰写,论文摘要应为中文；学位论文答辩是否使用外国语言，由学校确定。"},{"i":20,"n":"第二十条","txt":"高等学校按照教学计划组织国际学生参加教学实习和社会实践，选择实习、实践地点应当遵守国家有关规定。"},{"i":21,"n":"第二十一条","txt":"高等学校根据国家有关规定为国际学生颁发学历证书或者其他学业证书。对接受高等学历教育的国际学生，高等学校应当及时为其办理学籍和毕业证书电子注册。 高等学校为符合学位授予条件的国际学生颁发学位证书。"},{"i":22,"n":"第二十二条","txt":"高等学校应当明确承担国际学生管理职能的工作机构，负责统筹协调国际学生的招收、教学、日常管理和服务以及毕业后的校友联系等工作。"},{"i":23,"n":"第二十三条","txt":"高等学校应当向国际学生公开学校基本情况、教育教学情况、招生简章以及国际学生管理与服务制度，方便国际学生获取信息。"},{"i":24,"n":"第二十四条","txt":"高等学校应当为国际学生提供食宿等必要的生活服务设施，建立健全并公布服务设施使用管理制度。国际学生在学校宿舍外居住的，应当及时到居住地公安部门办理登记手续。"},{"i":25,"n":"第二十五条","txt":"高等学校应当对国际学生开展中国法律法规、校纪校规、国情校情、中华优秀传统文化和风俗习惯等方面内容的教育，帮助其尽快熟悉和适应学习、生活环境。 高等学校应当设置国际学生辅导员岗位，了解国际学生的学习、生活需求，及时做好信息、咨询、文体活动等方面服务工作。国际学生辅导员配备比例不低于中国学生辅导员比例，与中国学生辅导员享有同等待遇。"},{"i":26,"n":"第二十六条","txt":"高等学校鼓励国际学生参加有益于身心健康的文体活动，为其参加文体活动提供便利条件。国际学生可以自愿参加公益活动、中国重大节日的庆祝活动。 高等学校一般不组织国际学生参加军训、政治性活动。"},{"i":27,"n":"第二十七条","txt":"国际学生经高等学校同意，可以在校内指定的地点和范围举行庆祝本国重要传统节日的活动，但不得有反对、攻击其他国家、民族的内容或者违反公共道德的言行。"},{"i":28,"n":"第二十八条","txt":"国际学生经高等学校批准，可以在学校内成立联谊团体，在中国法律、法规规定的范围内活动，并接受学校的指导和管理。"},{"i":29,"n":"第二十九条","txt":"高等学校应当尊重国际学生的民族习俗和宗教信仰，但不提供宗教活动场所。学校内不得进行传教、宗教聚会等任何宗教活动。"},{"i":30,"n":"第三十条","txt":"国际学生在高等学校学习期间可以参加勤工助学活动，但不得就业、经商或从事其他经营性活动。 国际学生勤工助学的具体管理规定，由国务院教育行政部门会同有关部门另行制订。"},{"i":31,"n":"第三十一条","txt":"高等学校参照中国学生学籍管理规定开展国际学生学籍管理工作。学校对国际学生做出退学处理或者开除学籍处分的，应当按照国务院教育行政部门的规定进行备案。"},{"i":32,"n":"第三十二条","txt":"中国政府为接受高等教育的国际学生设立中国政府奖学金，并鼓励地方人民政府设立国际学生奖学金。 中国政府奖学金的管理办法，由国务院有关行政部门制定。"},{"i":33,"n":"第三十三条","txt":"国务院教育行政部门择优委托高等学校培养中国政府奖学金生。承担中国政府奖学金生培养任务的高等学校，应当优先招收中国政府奖学金生。"},{"i":34,"n":"第三十四条","txt":"高等学校可以为国际学生设立奖学金。鼓励企事业单位、社会团体及其他社会组织和个人设立国际学生奖学金，但不得附加不合理条件。"},{"i":35,"n":"第三十五条","txt":"外国人申请到本办法第二条所指的学校学习的，应当在入境前根据其学习期限向中国驻其国籍国或居住地国使领馆或外交部委托的其他驻外机构申请办理X1字或X2字签证，按照规定提交经教育主管部门备案的证明和学校出具的录取通知书等相关材料。"},{"i":36,"n":"第三十六条","txt":"国际学生所持学习类签证注明入境后需要办理居留证件的，应当自入境之日起三十日内，向拟居留地公安机关出入境管理部门申请办理学习类外国人居留证件。"},{"i":37,"n":"第三十七条","txt":"外交部对外国驻华外交代表机构、领事机构及国际组织驻华代表机构人员及其随任家属申请到学校学习另有规定的，依照外交部规定执行。未按规定办理相关手续的，学校不得招收。"},{"i":38,"n":"第三十八条","txt":"学校招收未满十八周岁且父母不在中国境内常住的国际学生，须要求其父母正式委托在中国境内常住的外国人或者中国人作为该国际学生的监护人，并提供相关证明材料。 学校可以接受以团组形式短期学习的国际学生，但应当预先与外方派遣单位签订协议。实施初等、中等教育的学校接受团组形式短期学习国际学生的，外方派遣单位应当按照其所在国法律规定，预先办理有关组织未成年人出入境所需的法律手续，并应当派人随团并担任国际学生在学校学习期间的监护人。"},{"i":39,"n":"第三十九条","txt":"国际学生入学时应当按照中国卫生行政部门的规定到中国卫生检疫部门办理《外国人体格检查记录》确认手续或者进行体检。经体检确认患有《中华人民共和国出境入境管理法》规定的严重精神障碍、传染性肺结核病或者有可能对公共卫生造成重大危害的其他传染病的，由公安部门依法处理。"},{"i":40,"n":"第四十条","txt":"学校实行国际学生全员保险制度。国际学生必须按照国家有关规定和学校要求投保。对未按照规定购买保险的，应限期投保，逾期不投保的，学校不予录取；对于已在学校学习的，应予退学或不予注册。"},{"i":41,"n":"第四十一条","txt":"国务院教育行政部门建立健全国际学生培养质量监督制度。省、自治区、直辖市教育行政部门应当对本行政区域的国际学生培养进行监督。"},{"i":42,"n":"第四十二条","txt":"负有国际学生管理职责的国务院教育、公安、外交等行政部门，应当利用现代信息技术建立国际学生信息管理系统，推进信息共享工作机制，不断完善国际学生的管理与服务工作。"},{"i":43,"n":"第四十三条","txt":"对违反《中华人民共和国出境入境管理法》《中华人民共和国治安管理处罚法》以及《中华人民共和国外国人入境出境管理条例》《中华人民共和国境内外国人宗教活动管理规定》等法律法规规定的国际学生，公安等主管部门应当依法处理。"},{"i":44,"n":"第四十四条","txt":"高等学校在国际学生招收和培养过程中出现以下行为的，主管教育行政部门应当责令其整改，按照《中华人民共和国教育法》的有关规定追究法律责任，并可以限制其招收国际学生： （一）违反国家规定和学校招生规定招生的； （二）在招生过程中存在牟利行为的； （三）未公开收费项目、标准和未按项目、标准收费的； （四）违规颁发学位证书、学历证书或其他学业证书的； （五）教学质量低劣或管理与服务不到位，造成不良社会影响的； （六）其他违法违规行为。"},{"i":45,"n":"第四十五条","txt":"本办法中的短期学习是指在中国学校学习时间不超过180日（含），长期学习是指在中国学校学习时间超过180日。"},{"i":46,"n":"第四十六条","txt":"中国境内经批准承担研究生教育任务的科学研究机构招收国际学生的，按照本办法执行。 教育行政部门批准的实施非学历教育的教育机构招收国际学生的，参照本办法执行。 香港特别行政区、澳门特别行政区、台湾地区学生的招收、培养和管理，以及中国境内外籍人员子女学校的招生、培养和管理，按照国家其他有关规定执行。"},{"i":47,"n":"第四十七条","txt":"省、自治区、直辖市人民政府教育、外事、公安等部门，应当根据本办法，制定本省、自治区、直辖市的管理规定。"},{"i":48,"n":"第四十八条","txt":"本办法自2017年7月1日起施行。 教育部、外交部、公安部2000年1月31日发布的《高等学校接受外国留学生管理规定》、教育部1999年7月21日发布的《中小学接受外国学生管理暂行办法》同时废止。"}],"xuexiaojiaozhigongdaibiaodahuiguiding":[{"i":1,"n":"第一条","txt":"为依法保障教职工参与学校民主管理和监督，完善现代学校制度，促进学校依法治校，依据教育法、教师法、工会法等法律，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于中国境内公办的幼儿园和各级各类学校（以下统称学校）。 民办学校、中外合作办学机构参照本规定执行。"},{"i":3,"n":"第三条","txt":"学校教职工代表大会（以下简称教职工代表大会）是教职工依法参与学校民主管理和监督的基本形式。 学校应当建立和完善教职工代表大会制度。"},{"i":4,"n":"第四条","txt":"教职工代表大会应当高举中国特色社会主义伟大旗帜，以马克思列宁主义、毛泽东思想、邓小平理论和“三个代表”重要思想为指导，深入贯彻落实科学发展观，全面贯彻执行党的基本路线和教育方针，认真参与学校民主管理和监督。"},{"i":5,"n":"第五条","txt":"教职工代表大会和教职工代表大会代表应当遵守国家法律法规，遵守学校规章制度，正确处理国家、学校、集体和教职工的利益关系。"},{"i":6,"n":"第六条","txt":"教职工代表大会在中国共产党学校基层组织的领导下开展工作。教职工代表大会的组织原则是民主集中制。"},{"i":7,"n":"第七条","txt":"教职工代表大会的职权是： （一）听取学校章程草案的制定和修订情况报告，提出修改意见和建议； （二）听取学校发展规划、教职工队伍建设、教育教学改革、校园建设以及其他重大改革和重大问题解决方案的报告，提出意见和建议； （三）听取学校年度工作、财务工作、工会工作报告以及其他专项工作报告，提出意见和建议； （四）讨论通过学校提出的与教职工利益直接相关的福利、校内分配实施方案以及相应的教职工聘任、考核、奖惩办法； （五）审议学校上一届（次）教职工代表大会提案的办理情况报告； （六）按照有关工作规定和安排评议学校领导干部； （七）通过多种方式对学校工作提出意见和建议，监督学校章程、规章制度和决策的落实，提出整改意见和建议； （八）讨论法律法规规章规定的以及学校与学校工会商定的其他事项。 教职工代表大会的意见和建议，以会议决议的方式做出。"},{"i":8,"n":"第八条","txt":"学校应当建立健全沟通机制，全面听取教职工代表大会提出的意见和建议，并合理吸收采纳；不能吸收采纳的，应当做出说明。"},{"i":9,"n":"第九条","txt":"凡与学校签订聘任聘用合同、具有聘任聘用关系的教职工，均可当选为教职工代表大会代表。 教职工代表大会代表占全体教职工的比例，由地方省级教育等部门确定；地方省级教育等部门没有确定的，由学校自主确定。"},{"i":10,"n":"第十条","txt":"教职工代表大会代表以学院、系（所、年级）、室（组）等为单位，由教职工直接选举产生。 教职工代表大会代表可以按照选举单位组成代表团（组），并推选出团（组）长。"},{"i":11,"n":"第十一条","txt":"教职工代表大会代表以教师为主体，教师代表不得低于代表总数的60%，并应当根据学校实际，保证一定比例的青年教师和女教师代表。民族地区的学校和民族学校，少数民族代表应当占有一定比例。 教职工代表大会代表接受选举单位教职工的监督。"},{"i":12,"n":"第十二条","txt":"教职工代表大会代表实行任期制，任期3年或5年，可以连选连任。 选举、更换和撤换教职工代表大会代表的程序，由学校根据相关规定，并结合本校实际予以明确规定。"},{"i":13,"n":"第十三条","txt":"教职工代表大会代表享有以下权利： （一）在教职工代表大会上享有选举权、被选举权和表决权； （二）在教职工代表大会上充分发表意见和建议； （三）提出提案并对提案办理情况进行询问和监督； （四）就学校工作向学校领导和学校有关机构反映教职工的意见和要求； （五）因履行职责受到压制、阻挠或者打击报复时，向有关部门提出申诉和控告。"},{"i":14,"n":"第十四条","txt":"教职工代表大会代表应当履行以下义务： （一）努力学习并认真执行党的路线方针政策、国家的法律法规、党和国家关于教育改革发展的方针政策，不断提高思想政治素质和参与民主管理的能力； （二）积极参加教职工代表大会的活动，认真宣传、贯彻教职工代表大会决议，完成教职工代表大会交给的任务； （三）办事公正，为人正派，密切联系教职工群众，如实反映群众的意见和要求； （四）及时向本部门教职工通报参加教职工代表大会活动和履行职责的情况，接受评议监督； （五）自觉遵守学校的规章制度和职业道德，提高业务水平，做好本职工作。"},{"i":15,"n":"第十五条","txt":"有教职工80人以上的学校，应当建立教职工代表大会制度；不足80人的学校，建立由全体教职工直接参加的教职工大会制度。 学校根据实际情况，可在其内部单位建立教职工代表大会制度或者教职工大会制度，在该范围内行使相应的职权。 教职工大会制度的性质、领导关系、组织制度、运行规则等，与教职工代表大会制度相同。"},{"i":16,"n":"第十六条","txt":"学校应当遵守教职工代表大会的组织规则，定期召开教职工代表大会，支持教职工代表大会的活动。"},{"i":17,"n":"第十七条","txt":"教职工代表大会每学年至少召开一次。 遇有重大事项，经学校、学校工会或1/3以上教职工代表大会代表提议，可以临时召开教职工代表大会。"},{"i":18,"n":"第十八条","txt":"教职工代表大会每3年或5年为一届。期满应当进行换届选举。"},{"i":19,"n":"第十九条","txt":"教职工代表大会须有2/3以上教职工代表大会代表出席。 教职工代表大会根据需要可以邀请离退休教职工等非教职工代表大会代表，作为特邀或列席代表参加会议。特邀或列席代表在教职工代表大会上不具有选举权、被选举权和表决权。"},{"i":20,"n":"第二十条","txt":"教职工代表大会的议题，应当根据学校的中心工作、教职工的普遍要求，由学校工会提交学校研究确定，并提请教职工代表大会表决通过。"},{"i":21,"n":"第二十一条","txt":"教职工代表大会的选举和表决，须经教职工代表大会代表总数半数以上通过方为有效。"},{"i":22,"n":"第二十二条","txt":"教职工代表大会在教职工代表大会代表中推选人员，组成主席团主持会议。 主席团应当由学校各方面人员组成，其中包括学校、学校工会主要领导，教师代表应占多数。"},{"i":23,"n":"第二十三条","txt":"教职工代表大会可根据实际情况和需要设立若干专门委员会（工作小组），完成教职工代表大会交办的有关任务。专门委员会（工作小组）对教职工代表大会负责。"},{"i":24,"n":"第二十四条","txt":"教职工代表大会根据实际情况和需要，可以在教职工代表大会代表中选举产生执行委员会。执行委员会中，教师代表应占多数。 教职工代表大会闭会期间，遇有急需解决的重要问题，可由执行委员会联系有关专门委员会（工作小组）与学校有关机构协商处理。其结果向下一次教职工代表大会报告。"},{"i":25,"n":"第二十五条","txt":"学校工会为教职工代表大会的工作机构。"},{"i":26,"n":"第二十六条","txt":"学校工会承担以下与教职工代表大会相关的工作职责： （一）做好教职工代表大会的筹备工作和会务工作，组织选举教职工代表大会代表，征集和整理提案，提出会议议题、方案和主席团建议人选； （二）教职工代表大会闭会期间，组织传达贯彻教职工代表大会精神，督促检查教职工代表大会决议的落实，组织各代表团（组）及专门委员会（工作小组）的活动，主持召开教职工代表团（组）长、专门委员会（工作小组）负责人联席会议； （三）组织教职工代表大会代表的培训，接受和处理教职工代表大会代表的建议和申诉； （四）就学校民主管理工作向学校党组织汇报，与学校沟通； （五）完成教职工代表大会委托的其他任务。 选举产生执行委员会的学校，其执行委员会根据教职工代表大会的授权，可承担前款有关职责。"},{"i":27,"n":"第二十七条","txt":"学校应当为学校工会承担教职工代表大会工作机构的职责提供必要的工作条件和经费保障。"},{"i":28,"n":"第二十八条","txt":"学校可以在其下属单位建立教职工代表大会制度，在该单位范围内实行民主管理和监督。"},{"i":29,"n":"第二十九条","txt":"省、自治区、直辖市人民政府教育行政部门，可以与本地区有关组织联合制定本行政区域内学校教职工代表大会的相关规定。 有关学校根据本规定和所在地区的相关规定，可以制定相应的教职工代表大会或者教职工大会的实施办法。"},{"i":30,"n":"第三十条","txt":"本规定自2012年1月1日起施行。1985年1月28日教育部、原中国教育工会印发的《高等学校教职工代表大会暂行条例》同时废止。"}],"xuexiaoyishujiaoyugongzuoguicheng":[{"i":1,"n":"第一条","txt":"为全面贯彻国家的教育方针，加强学校艺术教育工作，促进学生全面发展，根据《中华人民共和国教育法》，制定本规程。"},{"i":2,"n":"第二条","txt":"本规程适用于小学、初级中学、普通高级中学、中等和高等职业学校、普通高等学校。"},{"i":3,"n":"第三条","txt":"艺术教育是学校实施美育的重要途径和内容，是素质教育的有机组成部分。 学校艺术教育工作包括：艺术类课程教学，课外、校外艺术教育活动，校园文化艺术环境建设。"},{"i":4,"n":"第四条","txt":"学校艺术教育工作应以马克思列宁主义、毛泽东思想、邓小平理论为指导，坚持面向现代化、面向世界、面向未来，贯彻面向全体学生、分类指导、因地制宜、讲求实效的方针，遵循普及与提高相结合、课内与课外相结合、学习与实践相结合的原则。通过艺术教育，使学生了解我国优秀的民族艺术文化传统和外国的优秀艺术成果，提高文化艺术素养，增强爱国主义精神；培养感受美、表现美、鉴赏美、创造美的能力，树立正确的审美观念，抵制不良文化的影响；陶冶情操，发展个性，启迪智慧，激发创新意识和创造能力，促进学生全面发展。"},{"i":5,"n":"第五条","txt":"国务院教育行政部门主管和指导全国的学校艺术教育工作。 地方各级人民政府教育行政部门主管和协调本行政区域内的学校艺术教育工作。 各级教育部门应当建立对学校艺术教育工作进行督导、评估的制度。"},{"i":6,"n":"第六条","txt":"各级各类学校应当加强艺术类课程教学，按照国家的规定和要求开齐开足艺术课程。职业学校应当开设满足不同学生需要的艺术课程。普通高等学校应当开设艺术类必修课或者选修课。"},{"i":7,"n":"第七条","txt":"小学、初级中学、普通高级中学开设的艺术课程，应当按照国家或者授权的省级教育行政部门颁布的艺术课程标准进行教学。教学中使用经国家或者授权的省级教育行政部门审定通过的教材。 职业学校、普通高等学校应当结合实际情况制定艺术类必修课或选修课的教学计划（课程方案）进行教学。"},{"i":8,"n":"第八条","txt":"小学、初级中学、普通高级中学的艺术课程列入期末考查和毕业考核科目。 职业学校和普通高等学校的艺术课程应当进行考试或者考查，考试或者考查方式由学校自行决定。实行学分制的学校应将成绩计入学分。"},{"i":9,"n":"第九条","txt":"课外、校外艺术教育活动是学校艺术教育的重要组成部分。学校应当面向全体学生组织艺术社团或者艺术活动小组，每个学生至少要参加一项艺术活动。"},{"i":10,"n":"第十条","txt":"学校每年应当根据自身条件，举办经常性、综合性、多样性的艺术活动，与艺术课程教学相结合，扩展和丰富学校艺术教育的内容和形式。 省、地、县各级教育行政部门应当定期举办学生艺术展演活动。各级各类学校在艺术教育中应当结合重大节日庆典活动对学生进行爱国主义和集体主义教育。 全国每三年举办一次中学生（包括中等职业学校的学生）艺术展演活动，每三年举办一次全国大学生（包括高等职业学校的学生）艺术展演活动。 国务院教育行政部门根据需要组织学生参加国际学生艺术活动。"},{"i":11,"n":"第十一条","txt":"学校应当充分利用社会艺术教育资源，补充和完善艺术教育活动内容，促进艺术教育活动质量和水平的提高，推动校园文化艺术环境建设。 任何部门和学校不得组织学生参与各种商业性艺术活动或者商业性的庆典活动。 学校组织学生参加社会团体、社会文化部门和其他社会组织举办的艺术比赛或活动，应向上级主管部门报告或者备案。"},{"i":12,"n":"第十二条","txt":"学校应当为学生创造良好的校园文化艺术环境。校园的广播、演出、展览、展示以及校园的整体设计应当有利于营造健康、高雅的学校文化艺术氛围，有利于对学生进行审美教育。 校园内不得进行文化艺术产品的推销活动。"},{"i":13,"n":"第十三条","txt":"各级教育行政部门应当明确学校艺术教育管理机构，配备艺术教育管理人员和教研人员，规划、管理、指导学校艺术教育工作。 学校应当有一位校级领导主管学校艺术教育工作，并明确校内艺术教育管理部门。 学校应当注意发挥共青团、少先队、学生会在艺术教育活动中的作用。"},{"i":14,"n":"第十四条","txt":"各级教育部门和学校应当根据国家有关规定配备专职或者兼职艺术教师，做好艺术教师的培训、管理工作，为艺术教师提供必要的工作条件。 学校的艺术教师必须具备教师资格，兼职教师应当相对稳定，非艺术类专业毕业的兼职教师要接受艺术专业的培训。 艺术教师组织、指导学校课外艺术活动，应当计入教师工作量。"},{"i":15,"n":"第十五条","txt":"学校应当设置艺术教室和艺术活动室，并按照国务院教育行政部门制定的器材配备目录配备艺术课程教学和艺术活动器材。"},{"i":16,"n":"第十六条","txt":"各级教育行政部门和学校应当在年度工作经费预算内保证艺术教育经费。 鼓励社会各界及个人捐资支持学校艺术教育事业。"},{"i":17,"n":"第十七条","txt":"教育行政部门和学校对于在学校艺术教育工作中取得突出成绩的单位和个人，应当给予表彰和奖励。"},{"i":18,"n":"第十八条","txt":"对违反本规程，拒不履行艺术教育责任的，按照隶属关系，分别由上级教育行政部门或者所属教育行政部门、学校给予批评教育并责令限期改正；经教育不改的，视情节轻重，对直接负责人给予行政处分。"},{"i":19,"n":"第十九条","txt":"对侵占、破坏艺术教育场所、设施和其他财产的，依法追究法律责任。"},{"i":20,"n":"第二十条","txt":"工读学校、特殊教育学校、成人学校的艺术教育工作参照本规程执行；中等、高等专业艺术学校（学院）的艺术教育工作另行规定。"},{"i":21,"n":"第二十一条","txt":"省级教育行政部门可根据本规程制定实施细则。"},{"i":22,"n":"第二十二条","txt":"本规程自公布之日起30日后施行。"}],"xuexiaoshipinanquanyuyingyangjiankangguanliguiding-2":[{"i":1,"n":"第一条","txt":"为保障学生和教职工在校集中用餐的食品安全与营养健康，加强监督管理，根据《中华人民共和国食品安全法》（以下简称食品安全法）、《中华人民共和国教育法》《中华人民共和国食品安全法实施条例》等法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"实施学历教育的各级各类学校、幼儿园（以下统称学校）集中用餐的食品安全与营养健康管理，适用本规定。 本规定所称集中用餐是指学校通过食堂供餐或者外购食品（包括从供餐单位订餐）等形式，集中向学生和教职工提供食品的行为。"},{"i":3,"n":"第三条","txt":"学校集中用餐实行预防为主、全程监控、属地管理、学校落实的原则，建立教育、食品安全监督管理、卫生健康等部门分工负责的工作机制。"},{"i":4,"n":"第四条","txt":"学校集中用餐应当坚持公益便利的原则，围绕采购、贮存、加工、配送、供餐等关键环节，健全学校食品安全风险防控体系，保障食品安全，促进营养健康。"},{"i":5,"n":"第五条","txt":"学校应当按照食品安全法律法规规定和健康中国战略要求，建立健全相关制度，落实校园食品安全责任，开展食品安全与营养健康的宣传教育。"},{"i":6,"n":"第六条","txt":"县级以上地方人民政府依法统一领导、组织、协调学校食品安全监督管理工作以及食品安全突发事故应对工作，将学校食品安全纳入本地区食品安全事故应急预案和学校安全风险防控体系建设。"},{"i":7,"n":"第七条","txt":"教育部门应当指导和督促学校建立健全食品安全与营养健康相关管理制度，将学校食品安全与营养健康管理工作作为学校落实安全风险防控职责、推进健康教育的重要内容，加强评价考核；指导、监督学校加强食品安全教育和日常管理，降低食品安全风险，及时消除食品安全隐患，提升营养健康水平，积极协助相关部门开展工作。"},{"i":8,"n":"第八条","txt":"食品安全监督管理部门应当加强学校集中用餐食品安全监督管理，依法查处涉及学校的食品安全违法行为；建立学校食堂食品安全信用档案，及时向教育部门通报学校食品安全相关信息；对学校食堂食品安全管理人员进行抽查考核，指导学校做好食品安全管理和宣传教育；依法会同有关部门开展学校食品安全事故调查处理。"},{"i":9,"n":"第九条","txt":"卫生健康主管部门应当组织开展校园食品安全风险和营养健康监测，对学校提供营养指导，倡导健康饮食理念，开展适应学校需求的营养健康专业人员培训；指导学校开展食源性疾病预防和营养健康的知识教育,依法开展相关疫情防控处置工作；组织医疗机构救治因学校食品安全事故导致人身伤害的人员。"},{"i":10,"n":"第十条","txt":"区域性的中小学卫生保健机构、妇幼保健机构、疾病预防控制机构，根据职责或者相关主管部门要求，组织开展区域内学校食品安全与营养健康的监测、技术培训和业务指导等工作。 鼓励有条件的地区成立学生营养健康专业指导机构，根据不同年龄阶段学生的膳食营养指南和健康教育的相关规定，指导学校开展学生营养健康相关活动，引导合理搭配饮食。"},{"i":11,"n":"第十一条","txt":"食品安全监督管理部门应当将学校校园及周边地区作为监督检查的重点，定期对学校食堂、供餐单位和校园内以及周边食品经营者开展检查；每学期应当会同教育部门对本行政区域内学校开展食品安全专项检查，督促指导学校落实食品安全责任。"},{"i":12,"n":"第十二条","txt":"学校食品安全实行校长（园长）负责制。 学校应当将食品安全作为学校安全工作的重要内容，建立健全并落实有关食品安全管理制度和工作要求，定期组织开展食品安全隐患排查。"},{"i":13,"n":"第十三条","txt":"中小学、幼儿园应当建立集中用餐陪餐制度，每餐均应当有学校相关负责人与学生共同用餐，做好陪餐记录，及时发现和解决集中用餐过程中存在的问题。 有条件的中小学、幼儿园应当建立家长陪餐制度，健全相应工作机制，对陪餐家长在学校食品安全与营养健康等方面提出的意见建议及时进行研究反馈。"},{"i":14,"n":"第十四条","txt":"学校应当配备专（兼）职食品安全管理人员和营养健康管理人员，建立并落实集中用餐岗位责任制度，明确食品安全与营养健康管理相关责任。 有条件的地方应当为中小学、幼儿园配备营养专业人员或者支持学校聘请营养专业人员，对膳食营养均衡等进行咨询指导，推广科学配餐、膳食营养等理念。"},{"i":15,"n":"第十五条","txt":"学校食品安全与营养健康管理相关工作人员应当按照有关要求，定期接受培训与考核，学习食品安全与营养健康相关法律、法规、规章、标准和其他相关专业知识。"},{"i":16,"n":"第十六条","txt":"学校应当建立集中用餐信息公开制度，利用公共信息平台等方式及时向师生家长公开食品进货来源、供餐单位等信息，组织师生家长代表参与食品安全与营养健康的管理和监督。"},{"i":17,"n":"第十七条","txt":"学校应当根据卫生健康主管部门发布的学生餐营养指南等标准，针对不同年龄段在校学生营养健康需求，因地制宜引导学生科学营养用餐。 有条件的中小学、幼儿园应当每周公布学生餐带量食谱和营养素供给量。"},{"i":18,"n":"第十八条","txt":"学校应当加强食品安全与营养健康的宣传教育，在全国食品安全宣传周、全民营养周、中国学生营养日、全国碘缺乏病防治日等重要时间节点，开展相关科学知识普及和宣传教育活动。 学校应当将食品安全与营养健康相关知识纳入健康教育教学内容，通过主题班会、课外实践等形式开展经常性宣传教育活动。"},{"i":19,"n":"第十九条","txt":"中小学、幼儿园应当培养学生健康的饮食习惯，加强对学生营养不良与超重、肥胖的监测、评价和干预，利用家长学校等方式对学生家长进行食品安全与营养健康相关知识的宣传教育。"},{"i":20,"n":"第二十条","txt":"中小学、幼儿园一般不得在校内设置小卖部、超市等食品经营场所，确有需要设置的，应当依法取得许可，并避免售卖高盐、高糖及高脂食品。"},{"i":21,"n":"第二十一条","txt":"学校在食品采购、食堂管理、供餐单位选择等涉及学校集中用餐的重大事项上，应当以适当方式听取家长委员会或者学生代表大会、教职工代表大会意见，保障师生家长的知情权、参与权、选择权、监督权。 学校应当畅通食品安全投诉渠道，听取师生家长对食堂、外购食品以及其他有关食品安全的意见、建议。"},{"i":22,"n":"第二十二条","txt":"鼓励学校参加食品安全责任保险。"},{"i":23,"n":"第二十三条","txt":"有条件的学校应当根据需要设置食堂，为学生和教职工提供服务。 学校自主经营的食堂应当坚持公益性原则，不以营利为目的。实施营养改善计划的农村义务教育学校食堂不得对外承包或者委托经营。 引入社会力量承包或者委托经营学校食堂的，应当以招投标等方式公开选择依法取得食品经营许可、能承担食品安全责任、社会信誉良好的餐饮服务单位或者符合条件的餐饮管理单位。 学校应当与承包方或者受委托经营方依法签订合同，明确双方在食品安全与营养健康方面的权利和义务，承担管理责任，督促其落实食品安全管理制度、履行食品安全与营养健康责任。承包方或者受委托经营方应当依照法律、法规、规章、食品安全标准以及合同约定进行经营，对食品安全负责，并接受委托方的监督。"},{"i":24,"n":"第二十四条","txt":"学校食堂应当依法取得食品经营许可证，严格按照食品经营许可证载明的经营项目进行经营，并在食堂显著位置悬挂或者摆放许可证。"},{"i":25,"n":"第二十五条","txt":"学校食堂应当建立食品安全与营养健康状况自查制度。经营条件发生变化，不再符合食品安全要求的，学校食堂应当立即整改；有发生食品安全事故潜在风险的，应当立即停止食品经营活动，并及时向所在地食品安全监督管理部门和教育部门报告。"},{"i":26,"n":"第二十六条","txt":"学校食堂应当建立健全并落实食品安全管理制度，按照规定制定并执行场所及设施设备清洗消毒、维修保养校验、原料采购至供餐全过程控制管理、餐具饮具清洗消毒、食品添加剂使用管理等食品安全管理制度。"},{"i":27,"n":"第二十七条","txt":"学校食堂应当建立并执行从业人员健康管理制度和培训制度。患有国家卫生健康委规定的有碍食品安全疾病的人员，不得从事接触直接入口食品的工作。从事接触直接入口食品工作的从业人员应当每年进行健康检查，取得健康证明后方可上岗工作，必要时应当进行临时健康检查。 学校食堂从业人员的健康证明应当在学校食堂显著位置进行统一公示。 学校食堂从业人员应当养成良好的个人卫生习惯，加工操作直接入口食品前应当洗手消毒，进入工作岗位前应当穿戴清洁的工作衣帽。 学校食堂从业人员不得有在食堂内吸烟等行为。"},{"i":28,"n":"第二十八条","txt":"学校食堂应当建立食品安全追溯体系，如实、准确、完整记录并保存食品进货查验等信息，保证食品可追溯。鼓励食堂采用信息化手段采集、留存食品经营信息。"},{"i":29,"n":"第二十九条","txt":"学校食堂应当具有与所经营的食品品种、数量、供餐人数相适应的场所并保持环境整洁，与有毒、有害场所以及其他污染源保持规定的距离。"},{"i":30,"n":"第三十条","txt":"学校食堂应当根据所经营的食品品种、数量、供餐人数，配备相应的设施设备，并配备消毒、更衣、盥洗、采光、照明、通风、防腐、防尘、防蝇、防鼠、防虫、洗涤以及处理废水、存放垃圾和废弃物的设备或者设施。就餐区或者就餐区附近应当设置供用餐者清洗手部以及餐具、饮具的用水设施。 食品加工、贮存、陈列、转运等设施设备应当定期维护、清洗、消毒；保温设施及冷藏冷冻设施应当定期清洗、校验。"},{"i":31,"n":"第三十一条","txt":"学校食堂应当具有合理的设备布局和工艺流程，防止待加工食品与直接入口食品、原料与成品或者半成品交叉污染，避免食品接触有毒物、不洁物。制售冷食类食品、生食类食品、裱花蛋糕、现榨果蔬汁等，应当按照有关要求设置专间或者专用操作区，专间应当在加工制作前进行消毒，并由专人加工操作。"},{"i":32,"n":"第三十二条","txt":"学校食堂采购食品及原料应当遵循安全、健康、符合营养需要的原则。有条件的地方或者学校应当实行大宗食品公开招标、集中定点采购制度，签订采购合同时应当明确供货者食品安全责任和义务，保证食品安全。"},{"i":33,"n":"第三十三条","txt":"学校食堂应当建立食品、食品添加剂和食品相关产品进货查验记录制度，如实准确记录名称、规格、数量、生产日期或者生产批号、保质期、进货日期以及供货者名称、地址、联系方式等内容，并保留载有上述信息的相关凭证。 进货查验记录和相关凭证保存期限不得少于产品保质期满后六个月；没有明确保质期的，保存期限不得少于二年。食用农产品的记录和凭证保存期限不得少于六个月。"},{"i":34,"n":"第三十四条","txt":"学校食堂采购食品及原料，应当按照下列要求查验许可相关文件，并留存加盖公章（或者签字）的复印件或者其他凭证： （一）从食品生产者采购食品的，应当查验其食品生产许可证和产品合格证明文件等； （二）从食品经营者（商场、超市、便利店等）采购食品的，应当查验其食品经营许可证等； （三）从食用农产品生产者直接采购的，应当查验并留存其社会信用代码或者身份证复印件； （四）从集中交易市场采购食用农产品的，应当索取并留存由市场开办者或者经营者加盖公章（或者负责人签字）的购货凭证； （五）采购肉类的应当查验肉类产品的检疫合格证明;采购肉类制品的应当查验肉类制品的检验合格证明。"},{"i":35,"n":"第三十五条","txt":"学校食堂禁止采购、使用下列食品、食品添加剂、食品相关产品： （一）超过保质期的食品、食品添加剂； （二）腐败变质、油脂酸败、霉变生虫、污秽不洁、混有异物、掺假掺杂或者感官性状异常的食品、食品添加剂； （三）未按规定进行检疫或者检疫不合格的肉类，或者未经检验或者检验不合格的肉类制品； （四）不符合食品安全标准的食品原料、食品添加剂以及消毒剂、洗涤剂等食品相关产品； （五）法律、法规、规章规定的其他禁止生产经营或者不符合食品安全标准的食品、食品添加剂、食品相关产品。 学校食堂在加工前应当检查待加工的食品及原料，发现有前款规定情形的，不得加工或者使用。"},{"i":36,"n":"第三十六条","txt":"学校食堂提供蔬菜、水果以及按照国际惯例或者民族习惯需要提供的食品应当符合食品安全要求。 学校食堂不得采购、贮存、使用亚硝酸盐（包括亚硝酸钠、亚硝酸钾）。 中小学、幼儿园食堂不得制售冷荤类食品、生食类食品、裱花蛋糕，不得加工制作四季豆、鲜黄花菜、野生蘑菇、发芽土豆等高风险食品。省、自治区、直辖市食品安全监督管理部门可以结合实际制定本地区中小学、幼儿园集中用餐不得制售的高风险食品目录。"},{"i":37,"n":"第三十七条","txt":"学校食堂应当按照保证食品安全的要求贮存食品，做到通风换气、分区分架分类、离墙离地存放、防蝇防鼠防虫设施完好，并定期检查库存，及时清理变质或者超过保质期的食品。 贮存散装食品，应当在贮存位置标明食品的名称、生产日期或者生产批号、保质期、生产者名称以及联系方式等内容。用于保存食品的冷藏冷冻设备，应当贴有标识，原料、半成品和成品应当分柜存放。 食品库房不得存放有毒、有害物品。"},{"i":38,"n":"第三十八条","txt":"学校食堂应当设置专用的备餐间或者专用操作区，制定并在显著位置公示人员操作规范；备餐操作时应当避免食品受到污染。食品添加剂应当专人专柜（位）保管，按照有关规定做到标识清晰、计量使用、专册记录。 学校食堂制作的食品在烹饪后应当尽量当餐用完，需要熟制的食品应当烧熟煮透。需要再次利用的，应当按照相关规范采取热藏或者冷藏方式存放，并在确认没有腐败变质的情况下，对需要加热的食品经高温彻底加热后食用。"},{"i":39,"n":"第三十九条","txt":"学校食堂用于加工动物性食品原料、植物性食品原料、水产品原料、半成品或者成品等的容器、工具应当从形状、材质、颜色、标识上明显区分，做到分开使用，固定存放，用后洗净并保持清洁。 学校食堂的餐具、饮具和盛放或者接触直接入口食品的容器、工具，使用前应当洗净、消毒。"},{"i":40,"n":"第四十条","txt":"中小学、幼儿园食堂应当对每餐次加工制作的每种食品成品进行留样，每个品种留样量应当满足检验需要，不得少于125克，并记录留样食品名称、留样量、留样时间、留样人员等。留样食品应当由专柜冷藏保存48小时以上。 高等学校食堂加工制作的大型活动集体用餐，批量制售的热食、非即做即售的热食、冷食类食品、生食类食品、裱花蛋糕应当按照前款规定留样，其他加工食品根据相关规定留样。"},{"i":41,"n":"第四十一条","txt":"学校食堂用水应当符合国家规定的生活饮用水卫生标准。"},{"i":42,"n":"第四十二条","txt":"学校食堂产生的餐厨废弃物应当在餐后及时清除，并按照环保要求分类处理。 食堂应当设置专门的餐厨废弃物收集设施并明显标识，按照规定收集、存放餐厨废弃物，建立相关制度及台账，按照规定交由符合要求的生活垃圾运输单位或者餐厨垃圾处理单位处理。"},{"i":43,"n":"第四十三条","txt":"学校食堂应当建立安全保卫制度,采取措施，禁止非食堂从业人员未经允许进入食品处理区。 学校在校园安全信息化建设中，应当优先在食堂食品库房、烹饪间、备餐间、专间、留样间、餐具饮具清洗消毒间等重点场所实现视频监控全覆盖。"},{"i":44,"n":"第四十四条","txt":"有条件的学校食堂应当做到明厨亮灶，通过视频或者透明玻璃窗、玻璃墙等方式，公开食品加工过程。鼓励运用互联网等信息化手段，加强对食品来源、采购、加工制作全过程的监督。"},{"i":45,"n":"第四十五条","txt":"学校从供餐单位订餐的，应当建立健全校外供餐管理制度，选择取得食品经营许可、能承担食品安全责任、社会信誉良好的供餐单位。 学校应当与供餐单位签订供餐合同（或者协议），明确双方食品安全与营养健康的权利和义务，存档备查。"},{"i":46,"n":"第四十六条","txt":"供餐单位应当严格遵守法律、法规和食品安全标准，当餐加工，并遵守本规定的要求,确保食品安全。"},{"i":47,"n":"第四十七条","txt":"学校应当对供餐单位提供的食品随机进行外观查验和必要检验，并在供餐合同（或者协议）中明确约定不合格食品的处理方式。"},{"i":48,"n":"第四十八条","txt":"学校需要现场分餐的，应当建立分餐管理制度。在教室分餐的，应当保障分餐环境卫生整洁。"},{"i":49,"n":"第四十九条","txt":"学校外购食品的，应当索取相关凭证，查验产品包装标签，查看生产日期、保质期和保存条件。不能即时分发的，应当按照保证食品安全的要求贮存。"},{"i":50,"n":"第五十条","txt":"学校应当建立集中用餐食品安全应急管理和突发事故报告制度，制定食品安全事故处置方案。发生集中用餐食品安全事故或者疑似食品安全事故时，应当立即采取下列措施： （一）积极协助医疗机构进行救治； （二）停止供餐，并按照规定向所在地教育、食品安全监督管理、卫生健康等部门报告； （三）封存导致或者可能导致食品安全事故的食品及其原料、工具、用具、设备设施和现场，并按照食品安全监督管理部门要求采取控制措施； （四）配合食品安全监管部门进行现场调查处理； （五）配合相关部门对用餐师生进行调查，加强与师生家长联系，通报情况，做好沟通引导工作。"},{"i":51,"n":"第五十一条","txt":"教育部门接到学校食品安全事故报告后，应当立即赶往现场协助相关部门进行调查处理，督促学校采取有效措施，防止事故扩大，并向上级人民政府教育部门报告。 学校发生食品安全事故需要启动应急预案的，教育部门应当立即向同级人民政府以及上一级教育部门报告，按照规定进行处置。"},{"i":52,"n":"第五十二条","txt":"食品安全监督管理部门会同卫生健康、教育等部门依法对食品安全事故进行调查处理。 县级以上疾病预防控制机构接到报告后应当对事故现场进行卫生处理，并对与事故有关的因素开展流行病学调查，及时向同级食品安全监督管理、卫生健康等部门提交流行病学调查报告。 学校食品安全事故的性质、后果及其调查处理情况由食品安全监督管理部门会同卫生健康、教育等部门依法发布和解释。"},{"i":53,"n":"第五十三条","txt":"教育部门和学校应当按照国家食品安全信息统一公布制度的规定建立健全学校食品安全信息公布机制，主动关注涉及本地本校食品安全舆情，除由相关部门统一公布的食品安全信息外，应当准确、及时、客观地向社会发布相关工作信息，回应社会关切。"},{"i":54,"n":"第五十四条","txt":"违反本规定第二十五条、第二十六条、第二十七条第一款、第三十三条,以及第三十四条第（一）项、第（二）项、第（五）项，学校食堂（或者供餐单位）未按规定建立食品安全管理制度，或者未按规定制定、实施餐饮服务经营过程控制要求的，由县级以上人民政府食品安全监督管理部门依照食品安全法第一百二十六条第一款的规定处罚。 违反本规定第三十四条第（三）项、第（四）项，学校食堂（或者供餐单位）未查验或者留存食用农产品生产者、集中交易市场开办者或者经营者的社会信用代码或者身份证复印件或者购货凭证、合格证明文件的，由县级以上人民政府食品安全监督管理部门责令改正；拒不改正的，给予警告，并处5000元以上3万元以下罚款。"},{"i":55,"n":"第五十五条","txt":"违反本规定第三十六条第二款，学校食堂（或者供餐单位）采购、贮存亚硝酸盐（包括亚硝酸钠、亚硝酸钾）的,由县级以上人民政府食品安全监督管理部门责令改正，给予警告，并处5000元以上3万元以下罚款。 违反本规定第三十六条第三款，中小学、幼儿园食堂（或者供餐单位）制售冷荤类食品、生食类食品、裱花蛋糕，或者加工制作四季豆、鲜黄花菜、野生蘑菇、发芽土豆等高风险食品的，由县级以上人民政府食品安全监督管理部门责令改正；拒不改正的，给予警告，并处5000元以上3万元以下罚款。"},{"i":56,"n":"第五十六条","txt":"违反本规定第四十条，学校食堂（或者供餐单位）未按要求留样的,由县级以上人民政府食品安全监督管理部门责令改正，给予警告；拒不改正的，处5000元以上3万元以下罚款。"},{"i":57,"n":"第五十七条","txt":"有食品安全法以及本规定的违法情形，学校未履行食品安全管理责任，由县级以上人民政府食品安全管理部门会同教育部门对学校主要负责人进行约谈，由学校主管教育部门视情节对学校直接负责的主管人员和其他直接责任人员给予相应的处分。 实施营养改善计划的学校违反食品安全法律法规以及本规定的，应当从重处理。"},{"i":58,"n":"第五十八条","txt":"学校食品安全的相关工作人员、相关负责人有下列行为之一的，由学校主管教育部门给予警告或者记过处分；情节较重的，应当给予降低岗位等级或者撤职处分；情节严重的，应当给予开除处分；构成犯罪的，依法移送司法机关处理： （一）知道或者应当知道食品、食品原料劣质或者不合格而采购的，或者利用工作之便以其他方式谋取不正当利益的； （二）在招投标和物资采购工作中违反有关规定，造成不良影响或者损失的； （三）怠于履行职责或者工作不负责任、态度恶劣，造成不良影响的； （四）违规操作致使师生人身遭受损害的； （五）发生食品安全事故，擅离职守或者不按规定报告、不采取措施处置或者处置不力的； （六）其他违反本规定要求的行为。"},{"i":59,"n":"第五十九条","txt":"学校食品安全管理直接负责的主管人员和其他直接责任人员有下列情形之一的，由学校主管教育部门会同有关部门视情节给予相应的处分；构成犯罪的，依法移送司法机关处理： （一）隐瞒、谎报、缓报食品安全事故的； （二）隐匿、伪造、毁灭、转移不合格食品或者有关证据，逃避检查、使调查难以进行或者责任难以追究的； （三）发生食品安全事故，未采取有效控制措施、组织抢救工作致使食物中毒事态扩大，或者未配合有关部门进行食物中毒调查、保留现场的； （四）其他违反食品安全相关法律法规规定的行为。"},{"i":60,"n":"第六十条","txt":"对于出现重大以上学校食品安全事故的地区，由国务院教育督导机构或者省级人民政府教育督导机构对县级以上地方人民政府相关负责人进行约谈，并依法提请有关部门予以追责。"},{"i":61,"n":"第六十一条","txt":"县级以上人民政府食品安全监督管理、卫生健康、教育等部门未按照食品安全法等法律法规以及本规定要求履行监督管理职责，造成所辖区域内学校集中用餐发生食品安全事故的，应当依据食品安全法和相关规定，对直接负责的主管人员和其他直接责任人员，给予相应的处分；构成犯罪的，依法移送司法机关处理。"},{"i":62,"n":"第六十二条","txt":"本规定下列用语的含义： 学校食堂，指学校为学生和教职工提供就餐服务，具有相对独立的原料存放、食品加工制作、食品供应及就餐空间的餐饮服务提供者。 供餐单位，指根据服务对象订购要求，集中加工、分送食品但不提供就餐场所的食品经营者。 学校食堂从业人员，指食堂中从事食品采购、加工制作、供餐、餐饮具清洗消毒等与餐饮服务有关的工作人员。 现榨果蔬汁，指以新鲜水果、蔬菜为主要原料，经压榨、粉碎等方法现场加工制作的供消费者直接饮用的果蔬汁饮品，不包括采用浓浆、浓缩汁、果蔬粉调配成的饮料。 冷食类食品、生食类食品、裱花蛋糕的定义适用《食品经营许可管理办法》的有关规定。"},{"i":63,"n":"第六十三条","txt":"供餐人数较少，难以建立食堂的学校，以及以简单加工学生自带粮食、蔬菜或者以为学生热饭为主的小规模农村学校的食品安全，可以参照食品安全法第三十六条的规定实施管理。 对提供用餐服务的教育培训机构，可以参照本规定管理。"},{"i":64,"n":"第六十四条","txt":"本规定自2019年4月1日起施行，2002年9月20日教育部、原卫生部发布的《学校食堂与学生集体用餐卫生管理规定》同时废止。"}],"xuexiaoshipinanquanyuyingyangjiankangguanliguiding":[{"i":1,"n":"第一条","txt":"为保障学生和教职工在校集中用餐的食品安全与营养健康，加强监督管理，根据《中华人民共和国食品安全法》（以下简称食品安全法）、《中华人民共和国教育法》《中华人民共和国食品安全法实施条例》等法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"实施学历教育的各级各类学校、幼儿园（以下统称学校）集中用餐的食品安全与营养健康管理，适用本规定。 本规定所称集中用餐是指学校通过食堂供餐或者外购食品（包括从供餐单位订餐）等形式，集中向学生和教职工提供食品的行为。"},{"i":3,"n":"第三条","txt":"学校集中用餐实行预防为主、全程监控、属地管理、学校落实的原则，建立教育、食品安全监督管理、卫生健康等部门分工负责的工作机制。"},{"i":4,"n":"第四条","txt":"学校集中用餐应当坚持公益便利的原则，围绕采购、贮存、加工、配送、供餐等关键环节，健全学校食品安全风险防控体系，保障食品安全，促进营养健康。"},{"i":5,"n":"第五条","txt":"学校应当按照食品安全法律法规规定和健康中国战略要求，建立健全相关制度，落实校园食品安全责任，开展食品安全与营养健康的宣传教育。"},{"i":6,"n":"第六条","txt":"县级以上地方人民政府依法统一领导、组织、协调学校食品安全监督管理工作以及食品安全突发事故应对工作，将学校食品安全纳入本地区食品安全事故应急预案和学校安全风险防控体系建设。"},{"i":7,"n":"第七条","txt":"教育部门应当指导和督促学校建立健全食品安全与营养健康相关管理制度，将学校食品安全与营养健康管理工作作为学校落实安全风险防控职责、推进健康教育的重要内容，加强评价考核；指导、监督学校加强食品安全教育和日常管理，降低食品安全风险，及时消除食品安全隐患，提升营养健康水平，积极协助相关部门开展工作。"},{"i":8,"n":"第八条","txt":"食品安全监督管理部门应当加强学校集中用餐食品安全监督管理，依法查处涉及学校的食品安全违法行为；建立学校食堂食品安全信用档案，及时向教育部门通报学校食品安全相关信息；对学校食堂食品安全管理人员进行抽查考核，指导学校做好食品安全管理和宣传教育；依法会同有关部门开展学校食品安全事故调查处理。"},{"i":9,"n":"第九条","txt":"卫生健康主管部门应当组织开展校园食品安全风险和营养健康监测，对学校提供营养指导，倡导健康饮食理念，开展适应学校需求的营养健康专业人员培训；指导学校开展食源性疾病预防和营养健康的知识教育，依法开展相关疫情防控处置工作；组织医疗机构救治因学校食品安全事故导致人身伤害的人员。"},{"i":10,"n":"第十条","txt":"区域性的中小学卫生保健机构、妇幼保健机构、疾病预防控制机构，根据职责或者相关主管部门要求，组织开展区域内学校食品安全与营养健康的监测、技术培训和业务指导等工作。 鼓励有条件的地区成立学生营养健康专业指导机构，根据不同年龄阶段学生的膳食营养指南和健康教育的相关规定，指导学校开展学生营养健康相关活动，引导合理搭配饮食。"},{"i":11,"n":"第十一条","txt":"食品安全监督管理部门应当将学校校园及周边地区作为监督检查的重点，定期对学校食堂、供餐单位和校园内以及周边食品经营者开展检查；每学期应当会同教育部门对本行政区域内学校开展食品安全专项检查，督促指导学校落实食品安全责任。"},{"i":12,"n":"第十二条","txt":"学校食品安全实行校长（园长）负责制。 学校应当将食品安全作为学校安全工作的重要内容，建立健全并落实有关食品安全管理制度和工作要求，定期组织开展食品安全隐患排查。"},{"i":13,"n":"第十三条","txt":"中小学、幼儿园应当建立集中用餐陪餐制度，每餐均应当有学校相关负责人与学生共同用餐，做好陪餐记录，及时发现和解决集中用餐过程中存在的问题。 有条件的中小学、幼儿园应当建立家长陪餐制度，健全相应工作机制，对陪餐家长在学校食品安全与营养健康等方面提出的意见建议及时进行研究反馈。"},{"i":14,"n":"第十四条","txt":"学校应当配备专（兼）职食品安全管理人员和营养健康管理人员，建立并落实集中用餐岗位责任制度，明确食品安全与营养健康管理相关责任。 有条件的地方应当为中小学、幼儿园配备营养专业人员或者支持学校聘请营养专业人员，对膳食营养均衡等进行咨询指导，推广科学配餐、膳食营养等理念。"},{"i":15,"n":"第十五条","txt":"学校食品安全与营养健康管理相关工作人员应当按照有关要求，定期接受培训与考核，学习食品安全与营养健康相关法律、法规、规章、标准和其他相关专业知识。"},{"i":16,"n":"第十六条","txt":"学校应当建立集中用餐信息公开制度，利用公共信息平台等方式及时向师生家长公开食品进货来源、供餐单位等信息，组织师生家长代表参与食品安全与营养健康的管理和监督。"},{"i":17,"n":"第十七条","txt":"学校应当根据卫生健康主管部门发布的学生餐营养指南等标准，针对不同年龄段在校学生营养健康需求，因地制宜引导学生科学营养用餐。 有条件的中小学、幼儿园应当每周公布学生餐带量食谱和营养素供给量。"},{"i":18,"n":"第十八条","txt":"学校应当加强食品安全与营养健康的宣传教育，在全国食品安全宣传周、全民营养周、中国学生营养日、全国碘缺乏病防治日等重要时间节点，开展相关科学知识普及和宣传教育活动。 学校应当将食品安全与营养健康相关知识纳入健康教育教学内容，通过主题班会、课外实践等形式开展经常性宣传教育活动。"},{"i":19,"n":"第十九条","txt":"中小学、幼儿园应当培养学生健康的饮食习惯，加强对学生营养不良与超重、肥胖的监测、评价和干预，利用家长学校等方式对学生家长进行食品安全与营养健康相关知识的宣传教育。"},{"i":20,"n":"第二十条","txt":"中小学、幼儿园一般不得在校内设置小卖部、超市等食品经营场所，确有需要设置的，应当依法取得许可，并避免售卖高盐、高糖及高脂食品。"},{"i":21,"n":"第二十一条","txt":"学校在食品采购、食堂管理、供餐单位选择等涉及学校集中用餐的重大事项上，应当以适当方式听取家长委员会或者学生代表大会、教职工代表大会意见，保障师生家长的知情权、参与权、选择权、监督权。 学校应当畅通食品安全投诉渠道，听取师生家长对食堂、外购食品以及其他有关食品安全的意见、建议。"},{"i":22,"n":"第二十二条","txt":"鼓励学校参加食品安全责任保险。"},{"i":23,"n":"第二十三条","txt":"有条件的学校应当根据需要设置食堂，为学生和教职工提供服务。 学校自主经营的食堂应当坚持公益性原则，不以营利为目的。实施营养改善计划的农村义务教育学校食堂不得对外承包或者委托经营。 引入社会力量承包或者委托经营学校食堂的，应当以招投标等方式公开选择依法取得食品经营许可、能承担食品安全责任、社会信誉良好的餐饮服务单位或者符合条件的餐饮管理单位。 学校应当与承包方或者受委托经营方依法签订合同，明确双方在食品安全与营养健康方面的权利和义务，承担管理责任，督促其落实食品安全管理制度、履行食品安全与营养健康责任。承包方或者受委托经营方应当依照法律、法规、规章、食品安全标准以及合同约定进行经营，对食品安全负责，并接受委托方的监督。"},{"i":24,"n":"第二十四条","txt":"学校食堂应当依法取得食品经营许可证，严格按照食品经营许可证载明的经营项目进行经营，并在食堂显著位置悬挂或者摆放许可证。"},{"i":25,"n":"第二十五条","txt":"学校食堂应当建立食品安全与营养健康状况自查制度。经营条件发生变化，不再符合食品安全要求的，学校食堂应当立即整改；有发生食品安全事故潜在风险的，应当立即停止食品经营活动，并及时向所在地食品安全监督管理部门和教育部门报告。"},{"i":26,"n":"第二十六条","txt":"学校食堂应当建立健全并落实食品安全管理制度，按照规定制定并执行场所及设施设备清洗消毒、维修保养校验、原料采购至供餐全过程控制管理、餐具饮具清洗消毒、食品添加剂使用管理等食品安全管理制度。"},{"i":27,"n":"第二十七条","txt":"学校食堂应当建立并执行从业人员健康管理制度和培训制度。患有国家卫生健康委规定的有碍食品安全疾病的人员，不得从事接触直接入口食品的工作。从事接触直接入口食品工作的从业人员应当每年进行健康检查，取得健康证明后方可上岗工作，必要时应当进行临时健康检查。 学校食堂从业人员的健康证明应当在学校食堂显著位置进行统一公示。 学校食堂从业人员应当养成良好的个人卫生习惯，加工操作直接入口食品前应当洗手消毒，进入工作岗位前应当穿戴清洁的工作衣帽。 学校食堂从业人员不得有在食堂内吸烟等行为。"},{"i":28,"n":"第二十八条","txt":"学校食堂应当建立食品安全追溯体系，如实、准确、完整记录并保存食品进货查验等信息，保证食品可追溯。鼓励食堂采用信息化手段采集、留存食品经营信息。"},{"i":29,"n":"第二十九条","txt":"学校食堂应当具有与所经营的食品品种、数量、供餐人数相适应的场所并保持环境整洁，与有毒、有害场所以及其他污染源保持规定的距离。"},{"i":30,"n":"第三十条","txt":"学校食堂应当根据所经营的食品品种、数量、供餐人数，配备相应的设施设备，并配备消毒、更衣、盥洗、采光、照明、通风、防腐、防尘、防蝇、防鼠、防虫、洗涤以及处理废水、存放垃圾和废弃物的设备或者设施。就餐区或者就餐区附近应当设置供用餐者清洗手部以及餐具、饮具的用水设施。 食品加工、贮存、陈列、转运等设施设备应当定期维护、清洗、消毒；保温设施及冷藏冷冻设施应当定期清洗、校验。"},{"i":31,"n":"第三十一条","txt":"学校食堂应当具有合理的设备布局和工艺流程，防止待加工食品与直接入口食品、原料与成品或者半成品交叉污染，避免食品接触有毒物、不洁物。制售冷食类食品、生食类食品、裱花蛋糕、现榨果蔬汁等，应当按照有关要求设置专间或者专用操作区，专间应当在加工制作前进行消毒，并由专人加工操作。"},{"i":32,"n":"第三十二条","txt":"学校食堂采购食品及原料应当遵循安全、健康、符合营养需要的原则。有条件的地方或者学校应当实行大宗食品公开招标、集中定点采购制度，签订采购合同时应当明确供货者食品安全责任和义务，保证食品安全。"},{"i":33,"n":"第三十三条","txt":"学校食堂应当建立食品、食品添加剂和食品相关产品进货查验记录制度，如实准确记录名称、规格、数量、生产日期或者生产批号、保质期、进货日期以及供货者名称、地址、联系方式等内容，并保留载有上述信息的相关凭证。 进货查验记录和相关凭证保存期限不得少于产品保质期满后六个月；没有明确保质期的，保存期限不得少于二年。食用农产品的记录和凭证保存期限不得少于六个月。"},{"i":34,"n":"第三十四条","txt":"学校食堂采购食品及原料，应当按照下列要求查验许可相关文件，并留存加盖公章（或者签字）的复印件或者其他凭证： （一）从食品生产者采购食品的，应当查验其食品生产许可证和产品合格证明文件等； （二）从食品经营者（商场、超市、便利店等）采购食品的，应当查验其食品经营许可证等； （三）从食用农产品生产者直接采购的，应当查验并留存其社会信用代码或者身份证复印件； （四）从集中交易市场采购食用农产品的，应当索取并留存由市场开办者或者经营者加盖公章（或者负责人签字）的购货凭证； （五）采购肉类的应当查验肉类产品的检疫合格证明；采购肉类制品的应当查验肉类制品的检验合格证明。"},{"i":35,"n":"第三十五条","txt":"学校食堂禁止采购、使用下列食品、食品添加剂、食品相关产品： （一）超过保质期的食品、食品添加剂； （二）腐败变质、油脂酸败、霉变生虫、污秽不洁、混有异物、掺假掺杂或者感官性状异常的食品、食品添加剂； （三）未按规定进行检疫或者检疫不合格的肉类，或者未经检验或者检验不合格的肉类制品； （四）不符合食品安全标准的食品原料、食品添加剂以及消毒剂、洗涤剂等食品相关产品； （五）法律、法规、规章规定的其他禁止生产经营或者不符合食品安全标准的食品、食品添加剂、食品相关产品。 学校食堂在加工前应当检查待加工的食品及原料，发现有前款规定情形的，不得加工或者使用。"},{"i":36,"n":"第三十六条","txt":"学校食堂提供蔬菜、水果以及按照国际惯例或者民族习惯需要提供的食品应当符合食品安全要求。 学校食堂不得采购、贮存、使用亚硝酸盐（包括亚硝酸钠、亚硝酸钾）。 中小学、幼儿园食堂不得制售冷荤类食品、生食类食品、裱花蛋糕，不得加工制作四季豆、鲜黄花菜、野生蘑菇、发芽土豆等高风险食品。省、自治区、直辖市食品安全监督管理部门可以结合实际制定本地区中小学、幼儿园集中用餐不得制售的高风险食品目录。"},{"i":37,"n":"第三十七条","txt":"学校食堂应当按照保证食品安全的要求贮存食品，做到通风换气、分区分架分类、离墙离地存放、防蝇防鼠防虫设施完好，并定期检查库存，及时清理变质或者超过保质期的食品。 贮存散装食品，应当在贮存位置标明食品的名称、生产日期或者生产批号、保质期、生产者名称以及联系方式等内容。用于保存食品的冷藏冷冻设备，应当贴有标识，原料、半成品和成品应当分柜存放。 食品库房不得存放有毒、有害物品。"},{"i":38,"n":"第三十八条","txt":"学校食堂应当设置专用的备餐间或者专用操作区，制定并在显著位置公示人员操作规范；备餐操作时应当避免食品受到污染。食品添加剂应当专人专柜（位）保管，按照有关规定做到标识清晰、计量使用、专册记录。 学校食堂制作的食品在烹饪后应当尽量当餐用完，需要熟制的食品应当烧熟煮透。需要再次利用的，应当按照相关规范采取热藏或者冷藏方式存放，并在确认没有腐败变质的情况下，对需要加热的食品经高温彻底加热后食用。"},{"i":39,"n":"第三十九条","txt":"学校食堂用于加工动物性食品原料、植物性食品原料、水产品原料、半成品或者成品等的容器、工具应当从形状、材质、颜色、标识上明显区分，做到分开使用，固定存放，用后洗净并保持清洁。 学校食堂的餐具、饮具和盛放或者接触直接入口食品的容器、工具，使用前应当洗净、消毒。"},{"i":40,"n":"第四十条","txt":"中小学、幼儿园食堂应当对每餐次加工制作的每种食品成品进行留样，每个品种留样量应当满足检验需要，不得少于125克，并记录留样食品名称、留样量、留样时间、留样人员等。留样食品应当由专柜冷藏保存48小时以上。 高等学校食堂加工制作的大型活动集体用餐，批量制售的热食、非即做即售的热食、冷食类食品、生食类食品、裱花蛋糕应当按照前款规定留样，其他加工食品根据相关规定留样。"},{"i":41,"n":"第四十一条","txt":"学校食堂用水应当符合国家规定的生活饮用水卫生标准。"},{"i":42,"n":"第四十二条","txt":"学校食堂产生的餐厨废弃物应当在餐后及时清除，并按照环保要求分类处理。 食堂应当设置专门的餐厨废弃物收集设施并明显标识，按照规定收集、存放餐厨废弃物，建立相关制度及台账，按照规定交由符合要求的生活垃圾运输单位或者餐厨垃圾处理单位处理。"},{"i":43,"n":"第四十三条","txt":"学校食堂应当建立安全保卫制度，采取措施，禁止非食堂从业人员未经允许进入食品处理区。 学校在校园安全信息化建设中，应当优先在食堂食品库房、烹饪间、备餐间、专间、留样间、餐具饮具清洗消毒间等重点场所实现视频监控全覆盖。"},{"i":44,"n":"第四十四条","txt":"有条件的学校食堂应当做到明厨亮灶，通过视频或者透明玻璃窗、玻璃墙等方式，公开食品加工过程。鼓励运用互联网等信息化手段，加强对食品来源、采购、加工制作全过程的监督。"},{"i":45,"n":"第四十五条","txt":"学校从供餐单位订餐的，应当建立健全校外供餐管理制度，选择取得食品经营许可、能承担食品安全责任、社会信誉良好的供餐单位。 学校应当与供餐单位签订供餐合同（或者协议），明确双方食品安全与营养健康的权利和义务，存档备查。"},{"i":46,"n":"第四十六条","txt":"供餐单位应当严格遵守法律、法规和食品安全标准，当餐加工，并遵守本规定的要求，确保食品安全。"},{"i":47,"n":"第四十七条","txt":"学校应当对供餐单位提供的食品随机进行外观查验和必要检验，并在供餐合同（或者协议）中明确约定不合格食品的处理方式。"},{"i":48,"n":"第四十八条","txt":"学校需要现场分餐的，应当建立分餐管理制度。在教室分餐的，应当保障分餐环境卫生整洁。"},{"i":49,"n":"第四十九条","txt":"学校外购食品的，应当索取相关凭证，查验产品包装标签，查看生产日期、保质期和保存条件。不能即时分发的，应当按照保证食品安全的要求贮存。"},{"i":50,"n":"第五十条","txt":"学校应当建立集中用餐食品安全应急管理和突发事故报告制度，制定食品安全事故处置方案。发生集中用餐食品安全事故或者疑似食品安全事故时，应当立即采取下列措施： （一）积极协助医疗机构进行救治； （二）停止供餐，并按照规定向所在地教育、食品安全监督管理、卫生健康等部门报告； （三）封存导致或者可能导致食品安全事故的食品及其原料、工具、用具、设备设施和现场，并按照食品安全监督管理部门要求采取控制措施； （四）配合食品安全监管部门进行现场调查处理； （五）配合相关部门对用餐师生进行调查，加强与师生家长联系，通报情况，做好沟通引导工作。"},{"i":51,"n":"第五十一条","txt":"教育部门接到学校食品安全事故报告后，应当立即赶往现场协助相关部门进行调查处理，督促学校采取有效措施，防止事故扩大，并向上级人民政府教育部门报告。 学校发生食品安全事故需要启动应急预案的，教育部门应当立即向同级人民政府以及上一级教育部门报告，按照规定进行处置。"},{"i":52,"n":"第五十二条","txt":"食品安全监督管理部门会同卫生健康、教育等部门依法对食品安全事故进行调查处理。 县级以上疾病预防控制机构接到报告后应当对事故现场进行卫生处理，并对与事故有关的因素开展流行病学调查，及时向同级食品安全监督管理、卫生健康等部门提交流行病学调查报告。 学校食品安全事故的性质、后果及其调查处理情况由食品安全监督管理部门会同卫生健康、教育等部门依法发布和解释。"},{"i":53,"n":"第五十三条","txt":"教育部门和学校应当按照国家食品安全信息统一公布制度的规定建立健全学校食品安全信息公布机制，主动关注涉及本地本校食品安全舆情，除由相关部门统一公布的食品安全信息外，应当准确、及时、客观地向社会发布相关工作信息，回应社会关切。"},{"i":54,"n":"第五十四条","txt":"违反本规定第二十五条、第二十六条、第二十七条第一款、第三十三条，以及第三十四条第（一）项、第（二）项、第（五）项，学校食堂（或者供餐单位）未按规定建立食品安全管理制度，或者未按规定制定、实施餐饮服务经营过程控制要求的，由县级以上人民政府食品安全监督管理部门依照食品安全法第一百二十六条第一款的规定处罚。 违反本规定第三十四条第（三）项、第（四）项，学校食堂（或者供餐单位）未查验或者留存食用农产品生产者、集中交易市场开办者或者经营者的社会信用代码或者身份证复印件或者购货凭证、合格证明文件的，由县级以上人民政府食品安全监督管理部门责令改正；拒不改正的，给予警告，并处5000元以上3万元以下罚款。"},{"i":55,"n":"第五十五条","txt":"违反本规定第三十六条第二款，学校食堂（或者供餐单位）采购、贮存亚硝酸盐（包括亚硝酸钠、亚硝酸钾）的，由县级以上人民政府食品安全监督管理部门责令改正，给予警告，并处5000元以上3万元以下罚款。 违反本规定第三十六条第三款，中小学、幼儿园食堂（或者供餐单位）制售冷荤类食品、生食类食品、裱花蛋糕，或者加工制作四季豆、鲜黄花菜、野生蘑菇、发芽土豆等高风险食品的，由县级以上人民政府食品安全监督管理部门责令改正；拒不改正的，给予警告，并处5000元以上3万元以下罚款。"},{"i":56,"n":"第五十六条","txt":"违反本规定第四十条，学校食堂（或者供餐单位）未按要求留样的，由县级以上人民政府食品安全监督管理部门责令改正，给予警告；拒不改正的，处5000元以上3万元以下罚款。"},{"i":57,"n":"第五十七条","txt":"有食品安全法以及本规定的违法情形，学校未履行食品安全管理责任，由县级以上人民政府食品安全管理部门会同教育部门对学校主要负责人进行约谈，由学校主管教育部门视情节对学校直接负责的主管人员和其他直接责任人员给予相应的处分。 实施营养改善计划的学校违反食品安全法律法规以及本规定的，应当从重处理。"},{"i":58,"n":"第五十八条","txt":"学校食品安全的相关工作人员、相关负责人有下列行为之一的，由学校主管教育部门给予警告或者记过处分；情节较重的，应当给予降低岗位等级或者撤职处分；情节严重的，应当给予开除处分；构成犯罪的，依法移送司法机关处理： （一）知道或者应当知道食品、食品原料劣质或者不合格而采购的，或者利用工作之便以其他方式谋取不正当利益的； （二）在招投标和物资采购工作中违反有关规定，造成不良影响或者损失的； （三）怠于履行职责或者工作不负责任、态度恶劣，造成不良影响的； （四）违规操作致使师生人身遭受损害的； （五）发生食品安全事故，擅离职守或者不按规定报告、不采取措施处置或者处置不力的； （六）其他违反本规定要求的行为。"},{"i":59,"n":"第五十九条","txt":"学校食品安全管理直接负责的主管人员和其他直接责任人员有下列情形之一的，由学校主管教育部门会同有关部门视情节给予相应的处分；构成犯罪的，依法移送司法机关处理： （一）隐瞒、谎报、缓报食品安全事故的； （二）隐匿、伪造、毁灭、转移不合格食品或者有关证据，逃避检查、使调查难以进行或者责任难以追究的； （三）发生食品安全事故，未采取有效控制措施、组织抢救工作致使食物中毒事态扩大，或者未配合有关部门进行食物中毒调查、保留现场的； （四）其他违反食品安全相关法律法规规定的行为。"},{"i":60,"n":"第六十条","txt":"对于出现重大以上学校食品安全事故的地区，由国务院教育督导机构或者省级人民政府教育督导机构对县级以上地方人民政府相关负责人进行约谈，并依法提请有关部门予以追责。"},{"i":61,"n":"第六十一条","txt":"县级以上人民政府食品安全监督管理、卫生健康、教育等部门未按照食品安全法等法律法规以及本规定要求履行监督管理职责，造成所辖区域内学校集中用餐发生食品安全事故的，应当依据食品安全法和相关规定，对直接负责的主管人员和其他直接责任人员，给予相应的处分；构成犯罪的，依法移送司法机关处理。"},{"i":62,"n":"第六十二条","txt":"本规定下列用语的含义： 学校食堂，指学校为学生和教职工提供就餐服务，具有相对独立的原料存放、食品加工制作、食品供应及就餐空间的餐饮服务提供者。 供餐单位，指根据服务对象订购要求，集中加工、分送食品但不提供就餐场所的食品经营者。 学校食堂从业人员，指食堂中从事食品采购、加工制作、供餐、餐饮具清洗消毒等与餐饮服务有关的工作人员。 现榨果蔬汁，指以新鲜水果、蔬菜为主要原料，经压榨、粉碎等方法现场加工制作的供消费者直接饮用的果蔬汁饮品，不包括采用浓浆、浓缩汁、果蔬粉调配成的饮料。 冷食类食品、生食类食品、裱花蛋糕的定义适用《食品经营许可管理办法》的有关规定。"},{"i":63,"n":"第六十三条","txt":"供餐人数较少，难以建立食堂的学校，以及以简单加工学生自带粮食、蔬菜或者以为学生热饭为主的小规模农村学校的食品安全，可以参照食品安全法第三十六条的规定实施管理。 对提供用餐服务的教育培训机构，可以参照本规定管理。"},{"i":64,"n":"第六十四条","txt":"本规定自2019年4月1日起施行，2002年9月20日教育部、原卫生部发布的《学校食堂与学生集体用餐卫生管理规定》同时废止。"}],"xueshengshanghaishiguchulibanfa":[{"i":1,"n":"第一条","txt":"为积极预防、妥善处理在校学生伤害事故，保护学生、学校的合法权益，根据《中华人民共和国教育法》、《中华人民共和国未成年人保护法》和其他相关法律、行政法规及有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"在学校实施的教育教学活动或者学校组织的校外活动中，以及在学校负有管理责任的校舍、场地、其他教育教学设施、生活设施内发生的，造成在校学生人身损害后果的事故的处理，适用本办法。"},{"i":3,"n":"第三条","txt":"学生伤害事故应当遵循依法、客观公正、合理适当的原则，及时、妥善地处理。"},{"i":4,"n":"第四条","txt":"学校的举办者应当提供符合安全标准的校舍、场地、其他教育教学设施和生活设施。 教育行政部门应当加强学校安全工作，指导学校落实预防学生伤害事故的措施，指导、协助学校妥善处理学生伤害事故，维护学校正常的教育教学秩序。"},{"i":5,"n":"第五条","txt":"学校应当对在校学生进行必要的安全教育和自护自救教育；应当按照规定，建立健全安全制度，采取相应的管理措施，预防和消除教育教学环境中存在的安全隐患；当发生伤害事故时，应当及时采取措施救助受伤害学生。 学校对学生进行安全教育、管理和保护，应当针对学生年龄、认知能力和法律行为能力的不同，采用相应的内容和预防措施。"},{"i":6,"n":"第六条","txt":"学生应当遵守学校的规章制度和纪律；在不同的受教育阶段，应当根据自身的年龄、认知能力和法律行为能力，避免和消除相应的危险。"},{"i":7,"n":"第七条","txt":"未成年学生的父母或者其他监护人（以下称为监护人）应当依法履行监护职责，配合学校对学生进行安全教育、管理和保护工作。 学校对未成年学生不承担监护职责,但法律有规定的或者学校依法接受委托承担相应监护职责的情形除外。"},{"i":8,"n":"第八条","txt":"发生学生伤害事故，造成学生人身损害的，学校应当按照《中华人民共和国侵权责任法》及相关法律、法规的规定，承担相应的事故责任。"},{"i":9,"n":"第九条","txt":"因下列情形之一造成的学生伤害事故，学校应当依法承担相应的责任： （一）学校的校舍、场地、其他公共设施，以及学校提供给学生使用的学具、教育教学和生活设施、设备不符合国家规定的标准，或者有明显不安全因素的； （二）学校的安全保卫、消防、设施设备管理等安全管理制度有明显疏漏，或者管理混乱，存在重大安全隐患，而未及时采取措施的； （三）学校向学生提供的药品、食品、饮用水等不符合国家或者行业的有关标准、要求的； （四）学校组织学生参加教育教学活动或者校外活动，未对学生进行相应的安全教育，并未在可预见的范围内采取必要的安全措施的； （五）学校知道教师或者其他工作人员患有不适宜担任教育教学工作的疾病，但未采取必要措施的； （六）学校违反有关规定，组织或者安排未成年学生从事不宜未成年人参加的劳动、体育运动或者其他活动的； （七）学生有特异体质或者特定疾病，不宜参加某种教育教学活动，学校知道或者应当知道"},{"i":10,"n":"第十条","txt":"学生或者未成年学生监护人由于过错，有下列情形之一，造成学生伤害事故，应当依法承担相应的责任： （一）学生违反法律法规的规定，违反社会公共行为准则、学校的规章制度或者纪律，实施按其年龄和认知能力应当知道具有危险或者可能危及他人的行为的； （二）学生行为具有危险性，学校、教师已经告诫、纠正，但学生不听劝阻、拒不改正的； （三）学生或者其监护人知道学生有特异体质，或者患有特定疾病，但未告知学校的； （四）未成年学生的身体状况、行为、情绪等有异常情况，监护人知道或者已被学校告知，但未履行相应监护职责的； （五）学生或者未成年学生监护人有其他过错的。"},{"i":11,"n":"第十一条","txt":"学校安排学生参加活动，因提供场地、设备、交通工具、食品及其他消费与服务的经营者，或者学校以外的活动组织者的过错造成的学生伤害事故，有过错的当事人应当依法承担相应的责任。"},{"i":12,"n":"第十二条","txt":"因下列情形之一造成的学生伤害事故，学校已履行了相应职责，行为并无不当的，无法律责任： （一）地震、雷击、台风、洪水等不可抗的自然因素造成的； （二）来自学校外部的突发性、偶发性侵害造成的； （三）学生有特异体质、特定疾病或者异常心理状态，学校不知道或者难于知道的； （四）学生自杀、自伤的； （五）在对抗性或者具有风险性的体育竞赛活动中发生意外伤害的； （六）其他意外因素造成的。"},{"i":13,"n":"第十三条","txt":"下列情形下发生的造成学生人身损害后果的事故，学校行为并无不当的，不承担事故责任；事故责任应当按有关法律法规或者其他有关规定认定： （一）在学生自行上学、放学、返校、离校途中发生的； （二）在学生自行外出或者擅自离校期间发生的； （三）在放学后、节假日或者假期等学校工作时间以外，学生自行滞留学校或者自行到校发生的； （四）其他在学校管理职责范围外发生的。"},{"i":14,"n":"第十四条","txt":"因学校教师或者其他工作人员与其职务无关的个人行为，或者因学生、教师及其他个人故意实施的违法犯罪行为，造成学生人身损害的，由致害人依法承担相应的责任。"},{"i":15,"n":"第十五条","txt":"发生学生伤害事故，学校应当及时救助受伤害学生，并应当及时告知未成年学生的监护人；有条件的，应当采取紧急救援等方式救助。"},{"i":16,"n":"第十六条","txt":"发生学生伤害事故，情形严重的，学校应当及时向主管教育行政部门及有关部门报告；属于重大伤亡事故的，教育行政部门应当按照有关规定及时向同级人民政府和上一级教育行政部门报告。"},{"i":17,"n":"第十七条","txt":"学校的主管教育行政部门应学校要求或者认为必要，可以指导、协助学校进行事故的处理工作，尽快恢复学校正常的教育教学秩序。"},{"i":18,"n":"第十八条","txt":"发生学生伤害事故，学校与受伤害学生或者学生家长可以通过协商方式解决；双方自愿，可以书面请求主管教育行政部门进行调解。 成年学生或者未成年学生的监护人也可以依法直接提起诉讼。"},{"i":19,"n":"第十九条","txt":"教育行政部门收到调解申请，认为必要的，可以指定专门人员进行调解，并应当在受理申请之日起60日内完成调解。"},{"i":20,"n":"第二十条","txt":"经教育行政部门调解，双方就事故处理达成一致意见的，应当在调解人员的见证下签订调解协议，结束调解；在调解期限内，双方不能达成一致意见，或者调解过程中一方提起诉讼，人民法院已经受理的，应当终止调解。 调解结束或者终止，教育行政部门应当书面通知当事人。"},{"i":21,"n":"第二十一条","txt":"对经调解达成的协议，一方当事人不履行或者反悔的，双方可以依法提起诉讼。"},{"i":22,"n":"第二十二条","txt":"事故处理结束，学校应当将事故处理结果书面报告主管的教育行政部门；重大伤亡事故的处理结果，学校主管的教育行政部门应当向同级人民政府和上一级教育行政部门报告。"},{"i":23,"n":"第二十三条","txt":"对发生学生伤害事故负有责任的组织或者个人，应当按照法律法规的有关规定，承担相应的损害赔偿责任。"},{"i":24,"n":"第二十四条","txt":"学生伤害事故赔偿的范围与标准，按照有关行政法规、地方性法规或者最高人民法院司法解释中的有关规定确定。 教育行政部门进行调解时，认为学校有责任的，可以依照有关法律法规及国家有关规定，提出相应的调解方案。"},{"i":25,"n":"第二十五条","txt":"对受伤害学生的伤残程度存在争议的，可以委托当地具有相应鉴定资格的医院或者有关机构，依据国家规定的人体伤残标准进行鉴定。"},{"i":26,"n":"第二十六条","txt":"学校对学生伤害事故负有责任的，根据责任大小，适当予以经济赔偿，但不承担解决户口、住房、就业等与救助受伤害学生、赔偿相应经济损失无直接关系的其他事项。 学校无责任的，如果有条件,可以根据实际情况，本着自愿和可能的原则，对受伤害学生给予适当的帮助。"},{"i":27,"n":"第二十七条","txt":"因学校教师或者其他工作人员在履行职务中的故意或者重大过失造成的学生伤害事故，学校予以赔偿后，可以向有关责任人员追偿。"},{"i":28,"n":"第二十八条","txt":"未成年学生对学生伤害事故负有责任的，由其监护人依法承担相应的赔偿责任。 学生的行为侵害学校教师及其他工作人员以及其他组织、个人的合法权益,造成损失的，成年学生或者未成年学生的监护人应当依法予以赔偿。"},{"i":29,"n":"第二十九条","txt":"根据双方达成的协议、经调解形成的协议或者人民法院的生效判决，应当由学校负担的赔偿金，学校应当负责筹措；学校无力完全筹措的，由学校的主管部门或者举办者协助筹措。"},{"i":30,"n":"第三十条","txt":"县级以上人民政府教育行政部门或者学校举办者有条件的，可以通过设立学生伤害赔偿准备金等多种形式，依法筹措伤害赔偿金。"},{"i":31,"n":"第三十一条","txt":"学校有条件的，应当依据保险法的有关规定，参加学校责任保险。 教育行政部门可以根据实际情况，鼓励中小学参加学校责任保险。 提倡学生自愿参加意外伤害保险。在尊重学生意愿的前提下，学校可以为学生参加意外伤害保险创造便利条件，但不得从中收取任何费用。"},{"i":32,"n":"第三十二条","txt":"发生学生伤害事故，学校负有责任且情节严重的，教育行政部门应当根据有关规定，对学校的直接负责的主管人员和其他直接责任人员，分别给予相应的行政处分；有关责任人的行为触犯刑律的，应当移送司法机关依法追究刑事责任。"},{"i":33,"n":"第三十三条","txt":"学校管理混乱，存在重大安全隐患的，主管的教育行政部门或者其他有关部门应当责令其限期整顿；对情节严重或者拒不改正的，应当依据法律法规的有关规定，给予相应的行政处罚。"},{"i":34,"n":"第三十四条","txt":"教育行政部门未履行相应职责，对学生伤害事故的发生负有责任的，由有关部门对直接负责的主管人员和其他直接责任人员分别给予相应的行政处分；有关责任人的行为触犯刑律的，应当移送司法机关依法追究刑事责任。"},{"i":35,"n":"第三十五条","txt":"违反学校纪律，对造成学生伤害事故负有责任的学生，学校可以给予相应的处分；触犯刑律的，由司法机关依法追究刑事责任。"},{"i":36,"n":"第三十六条","txt":"受伤害学生的监护人、亲属或者其他有关人员，在事故处理过程中无理取闹，扰乱学校正常教育教学秩序，或者侵犯学校、学校教师或者其他工作人员的合法权益的，学校应当报告公安机关依法处理；造成损失的，可以依法要求赔偿。"},{"i":37,"n":"第三十七条","txt":"本办法所称学校，是指国家或者社会力量举办的全日制的中小学（含特殊教育学校）、各类中等职业学校、高等学校。 本办法所称学生是指在上述学校中全日制就读的受教育者。"},{"i":38,"n":"第三十八条","txt":"幼儿园发生的幼儿伤害事故,应当根据幼儿为完全无行为能力人的特点，参照本办法处理。"},{"i":39,"n":"第三十九条","txt":"其他教育机构发生的学生伤害事故，参照本办法处理。 在学校注册的其他受教育者在学校管理范围内发生的伤害事故，参照本办法处理。"},{"i":40,"n":"第四十条","txt":"本办法自2002年9月1日起实施，原国家教委、教育部颁布的与学生人身安全事故处理有关的规定，与本办法不符的，以本办法为准。 在本办法实施之前已处理完毕的学生伤害事故不再重新处理。"}],"youeryuangongzuoguicheng":[{"i":1,"n":"第一条","txt":"为了加强幼儿园的科学管理，规范办园行为，提高保育和教育质量，促进幼儿身心健康，依据《中华人民共和国教育法》等法律法规，制定本规程。"},{"i":2,"n":"第二条","txt":"幼儿园是对3周岁以上学龄前幼儿实施保育和教育的机构。幼儿园教育是基础教育的重要组成部分，是学校教育制度的基础阶段。"},{"i":3,"n":"第三条","txt":"幼儿园的任务是：贯彻国家的教育方针，按照保育与教育相结合的原则，遵循幼儿身心发展特点和规律，实施德、智、体、美等方面全面发展的教育，促进幼儿身心和谐发展。 幼儿园同时面向幼儿家长提供科学育儿指导。"},{"i":4,"n":"第四条","txt":"幼儿园适龄幼儿一般为3周岁至6周岁。 幼儿园一般为三年制。"},{"i":5,"n":"第五条","txt":"幼儿园保育和教育的主要目标是： （一）促进幼儿身体正常发育和机能的协调发展，增强体质，促进心理健康，培养良好的生活习惯、卫生习惯和参加体育活动的兴趣。 （二）发展幼儿智力，培养正确运用感官和运用语言交往的基本能力，增进对环境的认识，培养有益的兴趣和求知欲望，培养初步的动手探究能力。 （三）萌发幼儿爱祖国、爱家乡、爱集体、爱劳动、爱科学的情感，培养诚实、自信、友爱、勇敢、勤学、好问、爱护公物、克服困难、讲礼貌、守纪律等良好的品德行为和习惯，以及活泼开朗的性格。 （四）培养幼儿初步感受美和表现美的情趣和能力。"},{"i":6,"n":"第六条","txt":"幼儿园教职工应当尊重、爱护幼儿，严禁虐待、歧视、体罚和变相体罚、侮辱幼儿人格等损害幼儿身心健康的行为。"},{"i":7,"n":"第七条","txt":"幼儿园可分为全日制、半日制、定时制、季节制和寄宿制等。上述形式可分别设置，也可混合设置。"},{"i":8,"n":"第八条","txt":"幼儿园每年秋季招生。平时如有缺额，可随时补招。 幼儿园对烈士子女、家中无人照顾的残疾人子女、孤儿、家庭经济困难幼儿、具有接受普通教育能力的残疾儿童等入园，按照国家和地方的有关规定予以照顾。"},{"i":9,"n":"第九条","txt":"企业、事业单位和机关、团体、部队设置的幼儿园，除招收本单位工作人员的子女外，应当积极创造条件向社会开放，招收附近居民子女入园。"},{"i":10,"n":"第十条","txt":"幼儿入园前，应当按照卫生部门制定的卫生保健制度进行健康检查，合格者方可入园。 幼儿入园除进行健康检查外，禁止任何形式的考试或测查。"},{"i":11,"n":"第十一条","txt":"幼儿园规模应当有利于幼儿身心健康，便于管理，一般不超过360人。 幼儿园每班幼儿人数一般为：小班（3周岁至4周岁）25人，中班（4周岁至5周岁）30人，大班（5周岁至6周岁）35人，混合班30人。寄宿制幼儿园每班幼儿人数酌减。 幼儿园可以按年龄分别编班，也可以混合编班。"},{"i":12,"n":"第十二条","txt":"幼儿园应当严格执行国家和地方幼儿园安全管理的相关规定，建立健全门卫、房屋、设备、消防、交通、食品、药物、幼儿接送交接、活动组织和幼儿就寝值守等安全防护和检查制度，建立安全责任制和应急预案。"},{"i":13,"n":"第十三条","txt":"幼儿园的园舍应当符合国家和地方的建设标准，以及相关安全、卫生等方面的规范，定期检查维护，保障安全。幼儿园不得设置在污染区和危险区，不得使用危房。 幼儿园的设备设施、装修装饰材料、用品用具和玩教具材料等，应当符合国家相关的安全质量标准和环保要求。 入园幼儿应当由监护人或者其委托的成年人接送。"},{"i":14,"n":"第十四条","txt":"幼儿园应当严格执行国家有关食品药品安全的法律法规，保障饮食饮水卫生安全。"},{"i":15,"n":"第十五条","txt":"幼儿园教职工必须具有安全意识，掌握基本急救常识和防范、避险、逃生、自救的基本方法，在紧急情况下应当优先保护幼儿的人身安全。 幼儿园应当把安全教育融入一日生活，并定期组织开展多种形式的安全教育和事故预防演练。 幼儿园应当结合幼儿年龄特点和接受能力开展反家庭暴力教育，发现幼儿遭受或者疑似遭受家庭暴力的，应当依法及时向公安机关报案。"},{"i":16,"n":"第十六条","txt":"幼儿园应当投保校方责任险。"},{"i":17,"n":"第十七条","txt":"幼儿园必须切实做好幼儿生理和心理卫生保健工作。 幼儿园应当严格执行《托儿所幼儿园卫生保健管理办法》以及其他有关卫生保健的法规、规章和制度。"},{"i":18,"n":"第十八条","txt":"幼儿园应当制定合理的幼儿一日生活作息制度。正餐间隔时间为3.5－4小时。在正常情况下，幼儿户外活动时间（包括户外体育活动时间）每天不得少于2小时，寄宿制幼儿园不得少于3小时；高寒、高温地区可酌情增减。"},{"i":19,"n":"第十九条","txt":"幼儿园应当建立幼儿健康检查制度和幼儿健康卡或档案。每年体检一次，每半年测身高、视力一次，每季度量体重一次；注意幼儿口腔卫生，保护幼儿视力。 幼儿园对幼儿健康发展状况定期进行分析、评价，及时向家长反馈结果。 幼儿园应当关注幼儿心理健康，注重满足幼儿的发展需要，保持幼儿积极的情绪状态，让幼儿感受到尊重和接纳。"},{"i":20,"n":"第二十条","txt":"幼儿园应当建立卫生消毒、晨检、午检制度和病儿隔离制度，配合卫生部门做好计划免疫工作。 幼儿园应当建立传染病预防和管理制度，制定突发传染病应急预案，认真做好疾病防控工作。 幼儿园应当建立患病幼儿用药的委托交接制度，未经监护人委托或者同意，幼儿园不得给幼儿用药。幼儿园应当妥善管理药品，保证幼儿用药安全。 幼儿园内禁止吸烟、饮酒。"},{"i":21,"n":"第二十一条","txt":"供给膳食的幼儿园应当为幼儿提供安全卫生的食品，编制营养平衡的幼儿食谱，定期计算和分析幼儿的进食量和营养素摄取量，保证幼儿合理膳食。 幼儿园应当每周向家长公示幼儿食谱，并按照相关规定进行食品留样。"},{"i":22,"n":"第二十二条","txt":"幼儿园应当配备必要的设备设施，及时为幼儿提供安全卫生的饮用水。 幼儿园应当培养幼儿良好的大小便习惯，不得限制幼儿便溺的次数、时间等。"},{"i":23,"n":"第二十三条","txt":"幼儿园应当积极开展适合幼儿的体育活动，充分利用日光、空气、水等自然因素以及本地自然环境，有计划地锻炼幼儿肌体，增强身体的适应和抵抗能力。正常情况下，每日户外体育活动不得少于1小时。 幼儿园在开展体育活动时，应当对体弱或有残疾的幼儿予以特殊照顾。"},{"i":24,"n":"第二十四条","txt":"幼儿园夏季要做好防暑降温工作，冬季要做好防寒保暖工作，防止中暑和冻伤。"},{"i":25,"n":"第二十五条","txt":"幼儿园教育应当贯彻以下原则和要求： （一）德、智、体、美等方面的教育应当互相渗透，有机结合。 （二）遵循幼儿身心发展规律，符合幼儿年龄特点，注重个体差异，因人施教，引导幼儿个性健康发展。 （三）面向全体幼儿，热爱幼儿，坚持积极鼓励、启发引导的正面教育。 （四）综合组织健康、语言、社会、科学、艺术各领域的教育内容，渗透于幼儿一日生活的各项活动中，充分发挥各种教育手段的交互作用。 （五）以游戏为基本活动，寓教育于各项活动之中。 （六）创设与教育相适应的良好环境，为幼儿提供活动和表现能力的机会与条件。"},{"i":26,"n":"第二十六条","txt":"幼儿一日活动的组织应当动静交替，注重幼儿的直接感知、实际操作和亲身体验，保证幼儿愉快的、有益的自由活动。"},{"i":27,"n":"第二十七条","txt":"幼儿园日常生活组织，应当从实际出发，建立必要、合理的常规，坚持一贯性和灵活性相结合，培养幼儿的良好习惯和初步的生活自理能力。"},{"i":28,"n":"第二十八条","txt":"幼儿园应当为幼儿提供丰富多样的教育活动。 教育活动内容应当根据教育目标、幼儿的实际水平和兴趣确定，以循序渐进为原则，有计划地选择和组织。 教育活动的组织应当灵活地运用集体、小组和个别活动等形式，为每个幼儿提供充分参与的机会，满足幼儿多方面发展的需要，促进每个幼儿在不同水平上得到发展。 教育活动的过程应注重支持幼儿的主动探索、操作实践、合作交流和表达表现，不应片面追求活动结果。"},{"i":29,"n":"第二十九条","txt":"幼儿园应当将游戏作为对幼儿进行全面发展教育的重要形式。 幼儿园应当因地制宜创设游戏条件，提供丰富、适宜的游戏材料，保证充足的游戏时间，开展多种游戏。 幼儿园应当根据幼儿的年龄特点指导游戏，鼓励和支持幼儿根据自身兴趣、需要和经验水平，自主选择游戏内容、游戏材料和伙伴，使幼儿在游戏过程中获得积极的情绪情感，促进幼儿能力和个性的全面发展。"},{"i":30,"n":"第三十条","txt":"幼儿园应当将环境作为重要的教育资源，合理利用室内外环境，创设开放的、多样的区域活动空间，提供适合幼儿年龄特点的丰富的玩具、操作材料和幼儿读物，支持幼儿自主选择和主动学习，激发幼儿学习的兴趣与探究的愿望。 幼儿园应当营造尊重、接纳和关爱的氛围，建立良好的同伴和师生关系。 幼儿园应当充分利用家庭和社区的有利条件，丰富和拓展幼儿园的教育资源。"},{"i":31,"n":"第三十一条","txt":"幼儿园的品德教育应当以情感教育和培养良好行为习惯为主，注重潜移默化的影响，并贯穿于幼儿生活以及各项活动之中。"},{"i":32,"n":"第三十二条","txt":"幼儿园应当充分尊重幼儿的个体差异，根据幼儿不同的心理发展水平，研究有效的活动形式和方法，注重培养幼儿良好的个性心理品质。 幼儿园应当为在园残疾儿童提供更多的帮助和指导。"},{"i":33,"n":"第三十三条","txt":"幼儿园和小学应当密切联系，互相配合，注意两个阶段教育的相互衔接。 幼儿园不得提前教授小学教育内容，不得开展任何违背幼儿身心发展规律的活动。"},{"i":34,"n":"第三十四条","txt":"幼儿园应当按照国家的相关规定设活动室、寝室、卫生间、保健室、综合活动室、厨房和办公用房等，并达到相应的建设标准。有条件的幼儿园应当优先扩大幼儿游戏和活动空间。 寄宿制幼儿园应当增设隔离室、浴室和教职工值班室等。"},{"i":35,"n":"第三十五条","txt":"幼儿园应当有与其规模相适应的户外活动场地，配备必要的游戏和体育活动设施，创造条件开辟沙地、水池、种植园地等，并根据幼儿活动的需要绿化、美化园地。"},{"i":36,"n":"第三十六条","txt":"幼儿园应当配备适合幼儿特点的桌椅、玩具架、盥洗卫生用具，以及必要的玩教具、图书和乐器等。 玩教具应当具有教育意义并符合安全、卫生要求。幼儿园应当因地制宜，就地取材，自制玩教具。"},{"i":37,"n":"第三十七条","txt":"幼儿园的建筑规划面积、建筑设计和功能要求，以及设施设备、玩教具配备，按照国家和地方的相关规定执行。"},{"i":38,"n":"第三十八条","txt":"幼儿园按照国家相关规定设园长、副园长、教师、保育员、卫生保健人员、炊事员和其他工作人员等岗位，配足配齐教职工。"},{"i":39,"n":"第三十九条","txt":"幼儿园教职工应当贯彻国家教育方针，具有良好品德，热爱教育事业，尊重和爱护幼儿，具有专业知识和技能以及相应的文化和专业素养，为人师表，忠于职责，身心健康。 幼儿园教职工患传染病期间暂停在幼儿园的工作。有犯罪、吸毒记录和精神病史者不得在幼儿园工作。"},{"i":40,"n":"第四十条","txt":"幼儿园园长应当符合本规程第三十九条规定，并应当具有《教师资格条例》规定的教师资格、具备大专以上学历、有三年以上幼儿园工作经历和一定的组织管理能力，并取得幼儿园园长岗位培训合格证书。 幼儿园园长由举办者任命或者聘任，并报当地主管的教育行政部门备案。 幼儿园园长负责幼儿园的全面工作，主要职责如下： （一）贯彻执行国家的有关法律、法规、方针、政策和地方的相关规定，负责建立并组织执行幼儿园的各项规章制度； （二）负责保育教育、卫生保健、安全保卫工作； （三）负责按照有关规定聘任、调配教职工，指导、检查和评估教师以及其他工作人员的工作，并给予奖惩； （四）负责教职工的思想工作，组织业务学习，并为他们的学习、进修、教育研究创造必要的条件； （五）关心教职工的身心健康，维护他们的合法权益，改善他们的工作条件； （六）组织管理园舍、设备和经费； （七）组织和指导家长工作； （八）负责与社区的联系和合作"},{"i":41,"n":"第四十一条","txt":"幼儿园教师必须具有《教师资格条例》规定的幼儿园教师资格，并符合本规程第三十九条规定。 幼儿园教师实行聘任制。 幼儿园教师对本班工作全面负责，其主要职责如下： （一）观察了解幼儿，依据国家有关规定，结合本班幼儿的发展水平和兴趣需要，制订和执行教育工作计划，合理安排幼儿一日生活； （二）创设良好的教育环境，合理组织教育内容，提供丰富的玩具和游戏材料，开展适宜的教育活动； （三）严格执行幼儿园安全、卫生保健制度，指导并配合保育员管理本班幼儿生活，做好卫生保健工作； （四）与家长保持经常联系，了解幼儿家庭的教育环境，商讨符合幼儿特点的教育措施，相互配合共同完成教育任务； （五）参加业务学习和保育教育研究活动； （六）定期总结评估保教工作实效，接受园长的指导和检查。"},{"i":42,"n":"第四十二条","txt":"幼儿园保育员应当符合本规程第三十九条规定，并应当具备高中毕业以上学历，受过幼儿保育职业培训。 幼儿园保育员的主要职责如下： （一）负责本班房舍、设备、环境的清洁卫生和消毒工作； （二）在教师指导下，科学照料和管理幼儿生活，并配合本班教师组织教育活动； （三）在卫生保健人员和本班教师指导下，严格执行幼儿园安全、卫生保健制度； （四）妥善保管幼儿衣物和本班的设备、用具。"},{"i":43,"n":"第四十三条","txt":"幼儿园卫生保健人员除符合本规程第三十九条规定外，医师应当取得卫生行政部门颁发的《医师执业证书》；护士应当取得《护士执业证书》；保健员应当具有高中毕业以上学历，并经过当地妇幼保健机构组织的卫生保健专业知识培训。 幼儿园卫生保健人员对全园幼儿身体健康负责，其主要职责如下： （一）协助园长组织实施有关卫生保健方面的法规、规章和制度，并监督执行； （二）负责指导调配幼儿膳食，检查食品、饮水和环境卫生； （三）负责晨检、午检和健康观察，做好幼儿营养、生长发育的监测和评价；定期组织幼儿健康体检，做好幼儿健康档案管理； （四）密切与当地卫生保健机构的联系，协助做好疾病防控和计划免疫工作； （五）向幼儿园教职工和家长进行卫生保健宣传和指导。 （六）妥善管理医疗器械、消毒用具和药品。"},{"i":44,"n":"第四十四条","txt":"幼儿园其他工作人员的资格和职责，按照国家和地方的有关规定执行。"},{"i":45,"n":"第四十五条","txt":"对认真履行职责、成绩优良的幼儿园教职工，应当按照有关规定给予奖励。 对不履行职责的幼儿园教职工，应当视情节轻重，依法依规给予相应处分。"},{"i":46,"n":"第四十六条","txt":"幼儿园的经费由举办者依法筹措，保障有必备的办园资金和稳定的经费来源。 按照国家和地方相关规定接受财政扶持的提供普惠性服务的国有企事业单位办园、集体办园和民办园等幼儿园，应当接受财务、审计等有关部门的监督检查。"},{"i":47,"n":"第四十七条","txt":"幼儿园收费按照国家和地方的有关规定执行。 幼儿园实行收费公示制度，收费项目和标准向家长公示，接受社会监督，不得以任何名义收取与新生入园相挂钩的赞助费。 幼儿园不得以培养幼儿某种专项技能、组织或参与竞赛等为由，另外收取费用；不得以营利为目的组织幼儿表演、竞赛等活动。"},{"i":48,"n":"第四十八条","txt":"幼儿园的经费应当按照规定的使用范围合理开支，坚持专款专用，不得挪作他用。"},{"i":49,"n":"第四十九条","txt":"幼儿园举办者筹措的经费，应当保证保育和教育的需要，有一定比例用于改善办园条件和开展教职工培训。"},{"i":50,"n":"第五十条","txt":"幼儿膳食费应当实行民主管理制度，保证全部用于幼儿膳食，每月向家长公布账目。"},{"i":51,"n":"第五十一条","txt":"幼儿园应当建立经费预算和决算审核制度，经费预算和决算应当提交园务委员会审议，并接受财务和审计部门的监督检查。 幼儿园应当依法建立资产配置、使用、处置、产权登记、信息管理等管理制度，严格执行有关财务制度。"},{"i":52,"n":"第五十二条","txt":"幼儿园应当主动与幼儿家庭沟通合作，为家长提供科学育儿宣传指导，帮助家长创设良好的家庭教育环境，共同担负教育幼儿的任务。"},{"i":53,"n":"第五十三条","txt":"幼儿园应当建立幼儿园与家长联系的制度。幼儿园可采取多种形式，指导家长正确了解幼儿园保育和教育的内容、方法，定期召开家长会议，并接待家长的来访和咨询。 幼儿园应当认真分析、吸收家长对幼儿园教育与管理工作的意见与建议。 幼儿园应当建立家长开放日制度。"},{"i":54,"n":"第五十四条","txt":"幼儿园应当成立家长委员会。 家长委员会的主要任务是：对幼儿园重要决策和事关幼儿切身利益的事项提出意见和建议；发挥家长的专业和资源优势，支持幼儿园保育教育工作；帮助家长了解幼儿园工作计划和要求，协助幼儿园开展家庭教育指导和交流。 家长委员会在幼儿园园长指导下工作。"},{"i":55,"n":"第五十五条","txt":"幼儿园应当加强与社区的联系与合作，面向社区宣传科学育儿知识，开展灵活多样的公益性早期教育服务，争取社区对幼儿园的多方面支持。"},{"i":56,"n":"第五十六条","txt":"幼儿园实行园长负责制。 幼儿园应当建立园务委员会。园务委员会由园长、副园长、党组织负责人和保教、卫生保健、财会等方面工作人员的代表以及幼儿家长代表组成。园长任园务委员会主任。 园长定期召开园务委员会会议，遇重大问题可临时召集，对规章制度的建立、修改、废除，全园工作计划，工作总结，人员奖惩，财务预算和决算方案，以及其他涉及全园工作的重要问题进行审议。"},{"i":57,"n":"第五十七条","txt":"幼儿园应当加强党组织建设，充分发挥党组织政治核心作用、战斗堡垒作用。幼儿园应当为工会、共青团等其他组织开展工作创造有利条件，充分发挥其在幼儿园工作中的作用。"},{"i":58,"n":"第五十八条","txt":"幼儿园应当建立教职工大会制度或者教职工代表大会制度，依法加强民主管理和监督。"},{"i":59,"n":"第五十九条","txt":"幼儿园应当建立教研制度，研究解决保教工作中的实际问题。"},{"i":60,"n":"第六十条","txt":"幼儿园应当制订年度工作计划，定期部署、总结和报告工作。每学年年末应当向教育等行政主管部门报告工作，必要时随时报告。"},{"i":61,"n":"第六十一条","txt":"幼儿园应当接受上级教育、卫生、公安、消防等部门的检查、监督和指导，如实报告工作和反映情况。 幼儿园应当依法接受教育督导部门的督导。"},{"i":62,"n":"第六十二条","txt":"幼儿园应当建立业务档案、财务管理、园务会议、人员奖惩、安全管理以及与家庭、小学联系等制度。 幼儿园应当建立信息管理制度，按照规定采集、更新、报送幼儿园管理信息系统的相关信息，每年向主管教育行政部门报送统计信息。"},{"i":63,"n":"第六十三条","txt":"幼儿园教师依法享受寒暑假期的带薪休假。幼儿园应当创造条件，在寒暑假期间，安排工作人员轮流休假。具体办法由举办者制定。"},{"i":64,"n":"第六十四条","txt":"本规程适用于城乡各类幼儿园。"},{"i":65,"n":"第六十五条","txt":"省、自治区、直辖市教育行政部门可根据本规程，制订具体实施办法。"},{"i":66,"n":"第六十六条","txt":"本规程自2016年3月1日起施行。1996年3月9日由原国家教育委员会令第25号发布的《幼儿园工作规程》同时废止。"}],"jiaoyuxitongneibushenjigongzuoguiding":[{"i":1,"n":"第一条","txt":"为加强教育系统内部审计工作，提升内部审计工作质量，充分发挥内部审计作用，推动教育事业科学发展，根据《中华人民共和国教育法》《中华人民共和国审计法》《中华人民共和国审计法实施条例》《审计署关于内部审计工作的规定》及其他有关法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"依法属于审计机关审计监督对象的各级教育行政部门、学校和其他教育事业单位、企业等（以下简称单位）内部审计工作适用本规定。"},{"i":3,"n":"第三条","txt":"本规定所称内部审计，是指对本单位及所属单位财政财务收支、经济活动、内部控制、风险管理等实施独立、客观的监督、评价和建议，以促进单位完善治理、实现目标的活动。"},{"i":4,"n":"第四条","txt":"单位应当依照有关法律法规、本规定和内部审计职业规范，结合本单位实际情况，建立健全内部审计制度，明确内部审计工作的领导体制、职责权限、工作机构、人员配备、经费保障、审计结果运用和责任追究等。 单位应当加强本单位党组织对内部审计工作的领导，健全党领导相关工作的体制机制。"},{"i":5,"n":"第五条","txt":"教育系统内部审计工作应当接受国家审计机关的业务指导和监督。"},{"i":6,"n":"第六条","txt":"单位应当根据国家编制管理相关规定和管理需要，设置独立的机构或明确相关内设机构作为内部审计机构，履行内部审计职责。"},{"i":7,"n":"第七条","txt":"内部审计机构应当在本单位主要负责人的直接领导下开展内部审计工作，向其负责并报告工作。"},{"i":8,"n":"第八条","txt":"单位可以根据工作需要成立审计委员会，加强党对审计工作的领导，负责部署内部审计工作，审议年度审计工作报告，研究制定内部审计改革方案、重大政策和发展战略，审议决策内部审计重大事项等。"},{"i":9,"n":"第九条","txt":"单位可以根据工作需要建立总审计师制度。总审计师协助主要负责人管理内部审计工作。"},{"i":10,"n":"第十条","txt":"单位应当保证内部审计工作所需人员编制，严格内部审计人员录用标准，合理配备具有审计、财务、经济、法律、管理、工程、信息技术等专业知识的内部审计人员。总审计师、内部审计机构负责人应当具备审计、财务、经济、法律、管理等专业背景或工作经历。"},{"i":11,"n":"第十一条","txt":"单位应当根据内部审计工作特点，完善内部审计人员考核评价制度和专业技术岗位评聘制度，保障内部审计人员享有相应的晋升、交流、任职、薪酬及相关待遇。"},{"i":12,"n":"第十二条","txt":"单位应当支持和保障内部审计人员通过参加业务培训、考取职业资格、以审代训等多种途径接受继续教育，提高专业胜任能力。"},{"i":13,"n":"第十三条","txt":"内部审计机构的变动和总审计师、内部审计机构负责人的任免或调动，应当向上一级内部审计机构备案。"},{"i":14,"n":"第十四条","txt":"内部审计机构和内部审计人员依法独立履行职责，任何单位和个人不得干涉和打击报复。"},{"i":15,"n":"第十五条","txt":"内部审计机构履行内部审计职责所需经费，应当列入本单位预算。"},{"i":16,"n":"第十六条","txt":"内部审计人员应当严格遵守有关法律法规和内部审计职业规范，独立、客观、公正地履行职责，保守工作秘密。"},{"i":17,"n":"第十七条","txt":"内部审计机构和内部审计人员不得参与可能影响独立、客观履行审计职责的工作，不得参与被审计单位业务活动的决策和执行。"},{"i":18,"n":"第十八条","txt":"在不违反国家保密规定的情况下，内部审计机构可以根据工作需要向社会中介机构购买审计服务。内部审计机构应当对中介机构开展的受托业务进行指导、监督、检查和评价，并对采用的审计结果负责。"},{"i":19,"n":"第十九条","txt":"单位应当对认真履职、成绩显著的内部审计人员予以表彰。"},{"i":20,"n":"第二十条","txt":"内部审计机构应当按照国家有关规定和本单位的要求，对本单位及所属单位以下事项进行审计： （一）贯彻落实国家重大政策措施情况； （二）发展规划、战略决策、重大措施和年度业务计划执行情况； （三）财政财务收支和预算管理情况； （四）固定资产投资项目情况； （五）内部控制及风险管理情况； （六）资金、资产、资源的管理和效益情况； （七）办学、科研、后勤保障等主要业务活动的管理和效益情况； （八）本单位管理的领导人员履行经济责任情况； （九）自然资源资产管理和生态环境保护责任的履行情况； （十）境外机构、境外资产和境外经济活动情况； （十一）国家有关规定和本单位要求办理的其他事项。"},{"i":21,"n":"第二十一条","txt":"内部审计机构应当协助本单位主要负责人督促落实审计发现问题的整改工作。"},{"i":22,"n":"第二十二条","txt":"教育部负责指导和监督全国教育系统内部审计工作。地方各级教育行政部门负责指导和监督本行政区域内教育系统内部审计工作。 教育行政部门指导和监督内部审计工作的主要职责是： （一）制定内部审计规章制度； （二）督促建立健全内部审计制度； （三）指导开展内部审计工作，突出审计重点； （四） 监督内部审计职责履行情况，检查内部审计业务质量； （五）开展业务培训、组织内部审计工作交流研讨； （六）指导教育系统内部审计自律组织开展工作； （七）维护内部审计机构和内部审计人员的合法权益； （八）法律、法规规定的其他职责。"},{"i":23,"n":"第二十三条","txt":"内部审计机构应当对所属单位内部审计工作进行管理、指导和监督。"},{"i":24,"n":"第二十四条","txt":"内部审计机构具有下列权限： （一）要求被审计单位按时报送审计所需的有关资料、相关电子数据，以及必要的计算机技术文档； （二）参加或列席有关会议，召开与审计事项有关的会议； （三）参与研究有关规章制度，提出制定内部审计规章制度的建议； （四）检查有关财政财务收支、经济活动、内部控制、风险管理的资料、文件和现场勘察实物； （五）检查有关计算机系统及其电子数据和资料； （六）就审计事项中的有关问题，向有关单位和个人开展调查和询问，取得相关证明材料； （七）对正在进行的严重违法违规、严重损失浪费行为及时向单位主要负责人报告，经同意作出临时制止决定； （八）对可能被转移、隐匿、篡改、毁弃的会计凭证、会计账簿、会计报表以及与经济活动有关的资料，经本单位主要负责人批准，有权予以暂时封存； （九）提出纠正、处理违法违规行为的意见和改进管理、提高绩效的建议； （十）对违法违规和造成损失浪费的被审计单位和"},{"i":25,"n":"第二十五条","txt":"单位主要负责人应当定期听取内部审计工作汇报，加强对内部审计发展战略、年度审计计划、审计质量控制、审计发现问题整改和审计队伍建设等重要事项的管理。总审计师、内部审计机构负责人应当及时向本单位主要负责人报告内部审计结果和重大事项。"},{"i":26,"n":"第二十六条","txt":"内部审计机构应当依照审计法律法规、行业准则和实务指南等建立健全内部审计工作规范，并按规范实施审计。"},{"i":27,"n":"第二十七条","txt":"内部审计机构应当根据单位发展目标、治理结构、管理体制、风险状况等，科学合理地确定内部审计发展战略、制定内部审计计划。"},{"i":28,"n":"第二十八条","txt":"内部审计机构应当运用现代审计理念和方法，坚持风险和问题导向，优化审计业务组织方式，加强审计信息化建设，全面提高审计效率。"},{"i":29,"n":"第二十九条","txt":"内部审计机构应当着眼于促进问题解决，立足于促进机制建设，对审计发现问题做到事实清楚、定性准确，并在分析根本原因的基础上提出审计建议，通过与相关单位合作促进单位事业发展。"},{"i":30,"n":"第三十条","txt":"内部审计机构应当加强自身内部控制建设，合理设置审计岗位和职责分工、优化审计业务流程，完善审计全面质量控制。"},{"i":31,"n":"第三十一条","txt":"内部审计机构应当建立健全本单位及所属单位内部审计工作评价制度，促进提升审计业务与审计管理的专业化水平。"},{"i":32,"n":"第三十二条","txt":"内部审计机构实施领导人员经济责任审计时，应当参照执行国家有关经济责任审计的规定。"},{"i":33,"n":"第三十三条","txt":"单位应当建立健全审计发现问题整改机制，明确被审计单位主要负责人为整改第一责任人，完善审计整改结果报告制度、审计整改情况跟踪检查制度、审计整改约谈制度，推动审计发现问题的整改落实。"},{"i":34,"n":"第三十四条","txt":"单位应当建立健全审计结果及整改情况在一定范围内公开制度。"},{"i":35,"n":"第三十五条","txt":"单位应当对审计发现的典型性、普遍性问题，及时分析研究，制定和完善相关管理制度，建立健全内部控制措施；对审计发现的倾向性问题，开展审计调查，出具审计管理建议书，为科学决策提供建议。"},{"i":36,"n":"第三十六条","txt":"单位应当加强内部审计机构、纪检监察、巡视巡察、组织人事等内部监督力量的协作配合，建立信息共享、结果共用、重要事项共同实施、整改问责共同落实等工作机制。"},{"i":37,"n":"第三十七条","txt":"单位应当将内部审计结果及整改情况作为相关决策、预算安排、干部考核、人事任免和奖惩的重要依据。"},{"i":38,"n":"第三十八条","txt":"单位在对所属单位开展审计时，应当有效利用所属单位内部审计力量和成果。对所属单位内部审计发现且已经纠正的问题不再在审计报告中反映。"},{"i":39,"n":"第三十九条","txt":"对内部审计发现的重大违纪违法问题线索，在向本单位党组织、主要负责人报告的同时，应当及时向上一级内部审计机构报告，并按照管辖权限依法依规及时移送纪检监察机关、司法机关。"},{"i":40,"n":"第四十条","txt":"被审计单位有下列情形之一的，由单位党组织、主要负责人责令改正，并对直接负责的主管人员和其他直接责任人员进行处理： （一）拒绝接受或者不配合内部审计工作的； （二）拒绝、拖延提供与内部审计事项有关的资料，或者提供资料不真实、不完整的； （三）拒不纠正审计发现问题的； （四）整改不力、屡审屡犯的； （五）违反国家规定或者本单位内部规定的其他情形。"},{"i":41,"n":"第四十一条","txt":"内部审计机构和内部审计人员有下列情形之一的，由单位对直接负责的主管人员和其他直接责任人员进行处理；涉嫌犯罪的，依法追究刑事责任： （一）玩忽职守、不认真履行审计职责造成严重后果的； （二）隐瞒审计查出的问题或者提供虚假审计报告的； （三）泄露国家秘密或者商业秘密的； （四）利用职权谋取私利的； （五）违反国家规定或者本单位内部规定的其他情形。"},{"i":42,"n":"第四十二条","txt":"内部审计人员因履行职责受到打击、报复、陷害的，主要负责人应当及时采取保护措施，并对相关责任人员进行处理；涉嫌犯罪的，移送司法机关依法追究刑事责任。"},{"i":43,"n":"第四十三条","txt":"单位可以根据本规定，制定本地方、本单位内部审计管理规定。民办学校可以根据实际情况参照本规定执行。"},{"i":44,"n":"第四十四条","txt":"本规定所称企业是指教育行政部门、学校及其他教育事业单位管理的国有和国有资本占控股地位或主导地位的企业。"},{"i":45,"n":"第四十五条","txt":"本规定由教育部负责解释。"},{"i":46,"n":"第四十六条","txt":"本规定自2020年5月1日起施行。教育部于2004年4月13日发布的《教育系统内部审计工作规定》（教育部令第17号）同时废止。"}],"jiaoyutongjiguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强教育统计工作，保障统计资料的真实性、准确性、完整性和及时性，发挥统计在教育管理、科学决策和服务社会发展中的重要作用，根据《中华人民共和国统计法》《中华人民共和国教育法》《中华人民共和国统计法实施条例》等法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"国务院教育行政部门依法部署并组织县级以上地方人民政府教育行政部门、各级各类学校和其他有关机构实施的教育统计活动，适用本规定。"},{"i":3,"n":"第三条","txt":"教育统计的基本任务是对教育发展情况进行统计调查、统计分析，提供统计资料和统计咨询意见，实行统计监督。"},{"i":4,"n":"第四条","txt":"国务院教育行政部门在国家统计局的业务指导下，依法领导、管理和组织协调教育领域的部门统计调查项目。 县级以上地方人民政府教育行政部门应当加强对教育统计工作的组织领导，落实相关职责，为实施教育统计活动提供必要的保障。"},{"i":5,"n":"第五条","txt":"教育行政部门应当根据需要，将教育统计工作所需经费列入本单位的年度预算，按时拨付到位，保障教育统计工作正常、有效开展。 对在教育统计工作中做出突出贡献、取得显著成绩的单位和个人，按照国家有关规定给予表彰和奖励。"},{"i":6,"n":"第六条","txt":"教育行政部门应当加强教育统计科学研究，健全科学的教育统计指标体系，不断改进统计调查方法，提高教育统计的科学性；应当加强教育统计信息化建设，积极利用互联网、大数据、云计算等现代信息技术，推进教育统计信息搜集、处理、传输、共享、存储技术和统计数据库体系的现代化。"},{"i":7,"n":"第七条","txt":"接受教育统计调查的教育行政部门、学校和其他有关机构以及个人等教育统计调查对象，应当遵守统计法律法规，真实、准确、完整、及时地提供统计调查资料。"},{"i":8,"n":"第八条","txt":"教育统计调查中获得的能够识别或者推断单个统计调查对象身份的资料应当依法严格管理，除作为统计执法依据外，不得直接作为对统计调查对象实施行政许可、行政处罚等具体行政行为的依据，不得用于完成统计任务以外的目的。"},{"i":9,"n":"第九条","txt":"教育行政部门、各级各类学校和其他有关机构中负有教育统计职责的机构为教育统计机构，直接负责教育统计的专兼职工作人员为教育统计人员。 教育统计机构和统计人员依法独立行使统计调查、统计报告、统计监督的职权，不受侵犯。"},{"i":10,"n":"第十条","txt":"国务院教育行政部门成立综合统计机构，统筹组织和协调管理全国教育统计工作，组织制定教育统计工作的规划、规章制度等，统一组织、管理和协调本部门各项统计调查活动。"},{"i":11,"n":"第十一条","txt":"国务院教育行政部门综合统计机构，具体负责实施以下工作： （一）依法拟定教育统计调查项目，组织制定统计调查制度、计划和方案、标准并部署实施； （二）组织协调各有关内设机构和直属事业单位的统计工作； （三）归口管理和公布教育统计资料，统一对外提供和发布数据，提供统计咨询，组织开展统计分析； （四）对教育统计工作进行监督、检查，组织开展数据质量核查与评估工作； （五）加强教育统计队伍建设，组织教育统计人员的业务培训； （六）其他法定职责和工作事项。"},{"i":12,"n":"第十二条","txt":"省级人民政府教育行政部门应当明确主管统计工作的职能部门或者统计负责人，执行本单位的综合统计职能，主要包括： （一）按照教育统计调查制度，制定本地区教育统计管理制度、统计调查方案并组织实施； （二）对本地区教育发展情况进行统计分析，提供统计报告和统计咨询意见； （三）组织实施和指导本地区教育统计人员的专业学习、技能培训和职业道德教育，配合有关部门进行统计人员专业技术职务评定； （四）监督、检查本地区教育行政部门、各级各类学校和其他有关机构统计工作实施情况； （五）其他法定职责和工作事项。"},{"i":13,"n":"第十三条","txt":"设区的市及县级人民政府教育行政部门、高等学校和其他有关机构应当在相关职能部门明确负责统计工作的机构或岗位，配备统计人员，明确统计负责人，依法实施统计调查、分析、资料管理和公布等职责范围内的统计工作。"},{"i":14,"n":"第十四条","txt":"高等学校以外的各级各类学校根据统计任务的需要，设置统计工作岗位，配备专兼职统计人员，依法管理、开展统计工作，实施统计调查。"},{"i":15,"n":"第十五条","txt":"教育统计人员应当加强学习，具备与其从事的教育统计工作相适应的专业知识和业务能力；应当恪守职业道德，如实整理、报送统计资料，对其负责搜集、审核、录入的统计资料与统计调查对象报送的统计资料的一致性负责。"},{"i":16,"n":"第十六条","txt":"教育统计机构应当加强对教育统计人员的专业培训和职业道德教育，按照国家规定加强统计人员资质和信用建设，提高教育统计人员的专业素质，保障统计人员的稳定性。"},{"i":17,"n":"第十七条","txt":"教育统计机构和统计人员不得伪造、篡改统计资料，不得以任何方式要求任何单位和个人提供不真实的统计资料。"},{"i":18,"n":"第十八条","txt":"国务院教育行政部门依照统计相关法律法规和规章规定，制定教育统计调查项目。调查对象属于教育行政部门管辖系统的，依法报国家统计局备案；调查对象超出教育行政部门管辖系统的，依法报国家统计局审批。 制定教育统计调查项目，应当就项目的必要性、可行性、科学性进行论证，征求有关地方、部门、统计调查对象和专家的意见，并按照会议制度集体讨论决定。 教育统计调查项目和统计调查制度，应当根据教育改革发展的实践需要适时予以调整，并按规定重新申请审批或者备案。"},{"i":19,"n":"第十九条","txt":"国务院教育行政部门综合统计机构依法按照教育统计调查项目，制定教育统计调查制度，组织编制教育统计调查计划和统计调查方案。 县级以上地方人民政府教育行政部门增加或者减少补充性教育统计调查内容，应当依法报本级人民政府统计机构审批，并报上级教育行政部门备案。"},{"i":20,"n":"第二十条","txt":"教育统计调查制度应当对调查目的、调查内容、调查方法、调查对象、调查组织方式、调查表式、统计资料的报送和公布等作出规定。"},{"i":21,"n":"第二十一条","txt":"统计调查表必须标明表号、制定机关、批准或者备案文号、有效期限等标志。对未标明标志或者超过有效期限的统计调查表，教育统计调查对象有权拒绝填报。"},{"i":22,"n":"第二十二条","txt":"教育统计机构和统计人员应当执行国家统计标准和补充性的部门统计标准，统计调查指标涵义、计算方法、分类目录、调查表式和统计编码等不得与国家统计标准相抵触。"},{"i":23,"n":"第二十三条","txt":"搜集、整理教育统计资料，应当以周期性普查为基础，综合运用全面调查、重点调查、抽样调查等方法，并充分利用行政记录、电子注册信息等资料。"},{"i":24,"n":"第二十四条","txt":"教育统计机构应当根据统计资料，对本地区或者本单位的教育事业发展进行统计分析和监测，提供咨询意见和决策建议。建立教育统计数据解读、预测预警机制，加强数据分析，增强教育统计分析的时效性、针对性和实用性。"},{"i":25,"n":"第二十五条","txt":"教育统计机构和统计人员应当运用现代信息技术手段，深入挖掘数据资源，综合运用多种统计分析方法，提高统计分析和应用能力。 教育统计机构可委托专门机构承担教育统计任务，通过向社会购买服务组织实施统计调查和资料开发，可以引入第三方机构对教育统计工作进行评估。"},{"i":26,"n":"第二十六条","txt":"教育统计机构和统计人员应当按照教育统计调查制度，及时报送其组织实施统计调查取得的资料。"},{"i":27,"n":"第二十七条","txt":"各级各类学校和其他有关机构等教育统计调查对象应当按照国家有关规定设置原始记录、统计台账，建立健全统计资料的审核、签署、交接、归档等管理制度。上报的统计资料必须由统计人员、审核人、本单位负责人签名，并加盖单位印章。 统计资料的审核、签署人对其审核、签署的统计资料的真实性、准确性和完整性负责。"},{"i":28,"n":"第二十八条","txt":"教育行政部门制定政策规划、督查工作进展、评价发展水平等，凡涉及统计数据的，应当优先使用教育统计资料，并以教育统计机构提供的统计资料为准。"},{"i":29,"n":"第二十九条","txt":"教育统计资料实行分级管理。 教育行政部门应当按照国家有关规定建立健全教育统计资料的保存、管理制度和教育统计信息共享机制。"},{"i":30,"n":"第三十条","txt":"教育统计调查取得的统计资料，除依法应当保密的外，应当及时公开，便于查询利用。 国务院教育行政部门通过门户网站、统计公报、统计年鉴、统计信息平台等途径按照国家有关规定公布统计资料；依法公开数据生产的过程和结果，提升数据共享和公开水平。 地方各级人民政府教育行政部门应当按照国家有关规定公布教育统计资料，供社会公众查询。"},{"i":31,"n":"第三十一条","txt":"教育统计机构和统计人员应当按照国家保密规定，建立健全教育统计保密制度，完善教育统计内控机制，做好有关统计资料的保密工作。 教育统计调查中获得的能够识别或者推断单个统计调查对象身份的资料，任何单位和个人不得对外提供、泄露。"},{"i":32,"n":"第三十二条","txt":"教育行政部门、各级各类学校和其他有关机构及其负责人不得自行修改教育统计机构和统计人员依法搜集、整理的教育统计资料，不得以任何方式要求统计人员伪造、篡改教育统计资料，不得对依法履行职责或者拒绝、抵制统计违法行为的统计人员打击报复。"},{"i":33,"n":"第三十三条","txt":"教育统计应当接受社会公众的监督。教育统计资料应当真实、准确，任何单位和个人不得利用虚假教育统计资料骗取荣誉称号、物质利益或者职务晋升。"},{"i":34,"n":"第三十四条","txt":"上级教育行政部门应当定期对下级教育行政部门及其所辖学校、其他有关机构进行统计工作检查。统计工作检查的内容主要包括： （一）统计法律、法规、规章和有关文件的贯彻落实情况； （二）统计规章制度的建设及其组织实施情况； （三）单位内负责统计工作的机构和岗位的设置情况； （四）统计经费和统计工作设备配置的保障情况； （五）统计资料的管理情况； （六）其他需要检查的内容。"},{"i":35,"n":"第三十五条","txt":"国务院教育行政部门依法建立教育统计数据质量监控和评估制度，建立健全责任体系，对各省、自治区、直辖市重要教育统计数据进行监控和评估。 省级人民政府教育行政部门应当健全统计数据质量保障体系，建立专家参与的统计数据质量核查机制，通过自查、抽查、互查等方式，开展统计数据质量核查，保证统计数据质量。 县级以上教育行政部门可以建立教育统计数据抽查制度，制定抽查事项清单，合理确定抽查的比例和频次，随机对下级教育行政部门或其所辖学校、其他有关机构报送的教育统计数据进行核查。"},{"i":36,"n":"第三十六条","txt":"教育行政部门、各级各类学校和其他有关机构的相关工作人员在教育统计工作中有统计违法行为的，移交县级以上人民政府统计机构依法查处；有违纪行为的，由上级教育行政部门依据有关规定，根据违法违纪行为的情节轻重，向有关责任人员的任免机关、纪检监察机关、组织（人事）部门提出处分处理建议。"},{"i":37,"n":"第三十七条","txt":"教育行政部门、各级各类学校和其他有关机构的领导人员有下列行为之一的，按照有关规定，给予记过或者记大过处分；情节较重的，给予降级或者撤职处分；情节严重的，给予开除处分： （一）自行修改教育统计资料、编造虚假数据的； （二）强令、授意本部门、本单位统计机构、统计人员或者其他有关机构、人员拒报、虚报、瞒报或者篡改教育统计资料、编造虚假数据的； （三）对拒绝、抵制篡改教育统计资料或者对拒绝、抵制编造虚假数据的人员进行打击报复的； （四）对揭发、检举统计违法违纪行为的人员进行打击报复的。 有前款第（三）项、第（四）项规定行为的，应当从重处分。"},{"i":38,"n":"第三十八条","txt":"教育统计机构及相关人员有下列行为之一的，应当按照《中华人民共和国统计法》等法律法规和相关规定，追究相应的法律或者行政等责任，并记入相关单位、相关责任人的诚信档案： （一）未经批准擅自组织实施统计调查的； （二）自行修改、篡改、伪造、编造统计资料的； （三）不按时提供、拒绝提供或提供不真实、不完整的统计资料或者要求统计调查对象提供不真实统计资料的； （四）违法公布统计资料的； （五）泄漏统计资料导致单个统计调查对象身份被识别的； （六）违反规定导致统计资料毁损、灭失的； （七）其他统计违法行为。"},{"i":39,"n":"第三十九条","txt":"违反统计法及其他相关规定，利用虚假统计资料骗取荣誉称号、物质利益或者职务晋升的，除对其编造虚假统计资料或者要求他人编造虚假统计资料的行为依法追究法律责任外，由作出有关决定的单位或者其上级单位、监察机关取消其荣誉称号，追缴获得的物质利益，撤销晋升的职务。"},{"i":40,"n":"第四十条","txt":"省级人民政府教育行政部门可以根据本规定制定相应的实施细则，并报国务院教育行政部门备案。"},{"i":41,"n":"第四十一条","txt":"本规定自2018年8月1日起施行。1986年国家教委发布的《教育统计工作暂行规定》（〔86〕教计字034号）同时废止。"}],"xinshidaigaodengxuexiaosixiangzhengzhililunkejiaosda3d57":[{"i":1,"n":"第一条","txt":"为深入贯彻落实习近平新时代中国特色社会主义思想和党的十九大精神，贯彻落实习近平总书记关于教育的重要论述，全面贯彻党的教育方针，加强新时代高等学校思想政治理论课（以下简称思政课）教师队伍建设，根据《中华人民共和国教师法》，中共中央办公厅、国务院办公厅印发的《关于深化新时代学校思想政治理论课改革创新的若干意见》，制定本规定。"},{"i":2,"n":"第二条","txt":"思政课是高等学校落实立德树人根本任务的关键课程，是必须按照国家要求设置的课程。 思政课教师是指承担高等学校思政课教育教学和研究职责的专兼职教师，是高等学校教师队伍中承担开展马克思主义理论教育、用习近平新时代中国特色社会主义思想铸魂育人的中坚力量。"},{"i":3,"n":"第三条","txt":"主管教育部门、高等学校应当加强思政课教师队伍建设，把思政课教师队伍建设纳入教育事业发展和干部人才队伍建设总体规划，在师资建设上优先考虑，在资金投入上优先保障，在资源配置上优先满足。"},{"i":4,"n":"第四条","txt":"高等学校应当落实全员育人、全程育人、全方位育人要求，构建完善立德树人工作体系，调动广大教职工参与思想政治理论教育的积极性、主动性，动员各方面力量支持、配合思政课教师开展教学科研、组织学生社会实践等工作，提升思政课教学效果。"},{"i":5,"n":"第五条","txt":"思政课教师的首要岗位职责是讲好思政课。思政课教师要引导学生立德成人、立志成才，树立正确世界观、人生观、价值观，坚定对马克思主义的信仰，坚定对社会主义和共产主义的信念，增强中国特色社会主义道路自信、理论自信、制度自信、文化自信，厚植爱国主义情怀，把爱国情、强国志、报国行自觉融入坚持和发展中国特色社会主义事业、建设社会主义现代化强国、实现中华民族伟大复兴的奋斗之中，为培养德智体美劳全面发展的社会主义建设者和接班人作出积极贡献。"},{"i":6,"n":"第六条","txt":"对思政课教师的岗位要求是： （一）思政课教师应当增强“四个意识”，坚定“四个自信”，做到“两个维护”，始终在政治立场、政治方向、政治原则、政治道路上同以习近平同志为核心的党中央保持高度一致，模范践行高等学校教师师德规范。做到信仰坚定、学识渊博、理论功底深厚，努力做到政治强、情怀深、思维新、视野广、自律严、人格正，自觉用习近平新时代中国特色社会主义思想武装头脑，做学习和实践马克思主义的典范，做为学为人的表率。 （二）思政课教师应当用好国家统编教材。以讲好用好教材为基础，认真参加教材使用培训和集体备课，深入研究教材内容，吃准吃透教材基本精神，全面把握教材重点、难点，认真做好教材转化工作，编写好教案，切实推动教材体系向教学体系转化。 （三）思政课教师应当加强教学研究。坚持以思政课教学为核心的科研导向，紧紧围绕马克思主义理论学科内涵开展科研，深入研究思政课教学方法和教学重点难点问题，深入研究坚"},{"i":7,"n":"第七条","txt":"高等学校应当配齐建强思政课专职教师队伍，建设专职为主、专兼结合、数量充足、素质优良的思政课教师队伍。 高等学校应当根据全日制在校生总数，严格按照师生比不低于1:350的比例核定专职思政课教师岗位。公办高等学校要在编制内配足，且不得挪作他用。"},{"i":8,"n":"第八条","txt":"高等学校应当根据思政课教师工作职责、岗位要求，制定任职资格标准和选聘办法。 高等学校可以在与思政课教学内容相关的学科遴选优秀教师进行培训后加入思政课教师队伍，专职从事思政课教学；并可以探索胜任思政课教学的党政管理干部转岗为专职思政课教师，积极推动符合条件的辅导员参与思政课教学，鼓励政治素质过硬的相关学科专家转任思政课教师。"},{"i":9,"n":"第九条","txt":"高等学校可以实行思政课特聘教师、兼职教师制度。鼓励高等学校统筹地方党政领导干部、企事业单位管理专家、社科理论界专家、各行业先进模范以及高等学校党委书记校长、院（系）党政负责人、名家大师和专业课骨干、日常思想政治教育骨干等讲授思政课。支持高等学校建立两院院士、国有企业领导等人士经常性进高校、上思政课讲台的长效机制。"},{"i":10,"n":"第十条","txt":"主管教育部门应当加大高等学校思政课校际协作力度，加强区域内高等学校思政课教师柔性流动和协同机制建设，支持高水平思政课教师采取多种方式开展思政课教学工作。采取派驻支援或组建讲师团等形式支持民办高等学校配备思政课教师。"},{"i":11,"n":"第十一条","txt":"高等学校应当严把思政课教师政治关、师德关、业务关，明确思政课教师任职条件，根据国家有关规定和本规定要求，制定思政课教师规范或者在聘任合同中明确思政课教师权利义务与职责。"},{"i":12,"n":"第十二条","txt":"高等学校应当设置独立的马克思主义学院等思政课教学科研二级机构，统筹思政课教学科研和教师队伍的管理、培养、培训。 思政课教学科研机构负责人应当是中国共产党党员，并有长期从事思政课教学或者马克思主义理论学科研究的经历。缺少合适人选的高等学校可以采取兼职等办法，从相关单位聘任思政课教学科研机构负责人。"},{"i":13,"n":"第十三条","txt":"主管教育部门和高等学校应当加强思政课教师队伍后备人才培养。 国务院教育行政部门应当制定马克思主义理论专业类教学质量国家标准，加强本硕博课程教材体系建设，可统筹推进马克思主义理论本硕博一体化人才培养工作。实施“高校思政课教师队伍后备人才培养专项支持计划”，专门招收马克思主义理论学科研究生，不断为思政课教师队伍输送高水平人才。高等学校应当注重选拔高素质人才从事马克思主义理论学习研究和教育教学，加强思政课教师队伍后备人才思想政治工作。"},{"i":14,"n":"第十四条","txt":"建立国家、省（区、市）、高等学校三级思政课教师培训体系。国务院教育行政部门建立高等学校思政课教师研修基地，开展国家级示范培训，建立思政课教师教学研究交流平台。主管教育部门和高等学校应当建立健全思政课教师专业发展体系，定期组织开展教学研讨，保证思政课专职教师每3年至少接受一次专业培训，新入职教师应参加岗前专项培训。"},{"i":15,"n":"第十五条","txt":"主管教育部门和高等学校应当拓展思政课教师培训渠道，设立思政课教师研学基地，定期安排思政课教师实地了解中国改革发展成果、组织思政课教师实地考察和比较分析国内外经济社会发展状况，创造条件支持思政课教师到地方党政机关、企事业单位、基层等开展实践锻炼。 高等学校应当根据全日制在校生总数，按照本科院校每生每年不低于40元、专科院校每生每年不低于30元的标准安排专项经费，用于保障思政课教师的学术交流、实践研修等，并根据实际情况逐步加大支持力度。"},{"i":16,"n":"第十六条","txt":"主管教育部门和高等学校应当加大对思政课教师科学研究的支持力度。教育部人文社科研究项目要设立专项课题，主管教育部门要设立相关项目，持续有力支持思政课教师开展教学研究。主管教育部门和高等学校应当加强马克思主义理论教学科研成果学术阵地建设，支持新创办思政课研究学术期刊，相关哲学社会科学类学术期刊要设立思政课研究栏目。"},{"i":17,"n":"第十七条","txt":"高等学校应当科学设置思政课教师专业技术职务（职称）岗位，按教师比例核定思政课教师专业技术职务（职称）各类岗位占比，高级岗位比例不低于学校平均水平，不得挪作他用。"},{"i":18,"n":"第十八条","txt":"高等学校应当制定符合思政课教师职业特点和岗位要求的专业技术职务（职称）评聘标准，提高教学和教学研究在评聘条件中的占比。 高等学校可以结合实际分类设置教学研究型、教学型思政课教师专业技术职务（职称），两种类型都要在教学方面设置基本任务要求，要将教学效果作为思政课教师专业技术职务（职称）评聘的根本标准，同时要重视考查科研成果。 高等学校可以设置具体条件，将承担思政课教学的基本情况以及教学实效作为思政课教师参加高一级专业技术职务（职称）评聘的首要考查条件和必要条件。将为本专科生上思政课作为思政课教师参加高级专业技术职务（职称）评聘的必要条件。将至少一年兼任辅导员、班主任等日常思想政治教育工作经历并考核合格作为青年教师晋升高一级专业技术职务（职称）的必要条件。 思政课教师指导1个马克思主义理论类学生社团1年以上，且较好履行政治把关、理论学习、业务指导等职责的，在专业技术职务（职称）评聘中同等条"},{"i":19,"n":"第十九条","txt":"高等学校应当完善思政课教师教学和科研成果认定制度，推行科研成果代表作制度，制定思政课教师发表文章的重点报刊目录，将思政课教师在中央和地方主要媒体发表的理论文章纳入学术成果范围，细化相关认定办法。教学和科研成果可以是专著、论文、教学参考资料、调查报告、教书育人经验总结等。在制定思政课教师专业技术职务（职称）评聘指标和排次定序依据时，要结合实际设置规则，不得将国外期刊论文发表情况和出国访学留学情况作为必要条件。"},{"i":20,"n":"第二十条","txt":"高等学校应当健全思政课教师专业技术职务（职称）评价机制，建立以同行专家评价为主的评价机制，突出思政课的政治性、思想性、学术性、专业性、实效性，评价专家应以马克思主义理论学科为主，同时可适当吸收相关学科专家参加。 思政课教师专业技术职务（职称）评审委员会应当包含学校党委有关负责同志、思政课教学科研部门负责人，校内专业技术职务（职称）评聘委员会应有同比例的马克思主义理论学科专家。 高等学校应当制定思政课教师专业技术职务（职称）管理办法。完善专业技术职务（职称）退出机制，加强聘期考核，加大激励力度，准聘与长聘相结合。"},{"i":21,"n":"第二十一条","txt":"高等学校应当切实提高专职思政课教师待遇，要因地制宜设立思政课教师岗位津贴。高等学校要为思政课教师的教学科研工作创造便利条件，配备满足教学科研需要的办公空间、硬件设备和图书资料。"},{"i":22,"n":"第二十二条","txt":"高等学校思政课教师由马克思主义学院等思政课教学科研机构统一管理。每门课程都应当建立相应的教学科研组织，并可以根据需要配备管理人员。"},{"i":23,"n":"第二十三条","txt":"主管教育部门和高等学校要大力培养、推荐、表彰思政课教师中的先进典型。全国教育系统先进个人表彰中对思政课教师比例或名额作出规定；国家级教学成果奖、高等学校科学研究优秀成果奖（人文社科）中加大力度支持思政课；“长江学者奖励计划”等高层次人才项目中加大倾斜支持优秀思政课教师的力度。"},{"i":24,"n":"第二十四条","txt":"主管教育部门和高等学校应当加强宣传、引导，并采取设立奖励基金等方式支持高等学校思政课教师队伍建设，以各种方式定期对优秀思政课教师和马克思主义理论学科学生给予奖励。"},{"i":25,"n":"第二十五条","txt":"高等学校应当加强对思政课教师的考核，健全退出机制，对政治立场、政治方向、政治原则、政治道路上不能同党中央保持一致的，或理论素养、教学水平达不到标准的教师，不得继续担任思政课教师或马克思主义理论学科研究生导师。"},{"i":26,"n":"第二十六条","txt":"本规定适用于普通高等学校（包括民办高等学校）思政课教师队伍建设。其他类型高等学校的思政课教师队伍建设可以参照本规定执行。"},{"i":27,"n":"第二十七条","txt":"省级教育部门可以根据本规定，结合本地实际制定相关实施细则。"},{"i":28,"n":"第二十八条","txt":"本规定自2020年3月1日起施行。"}],"putonghuashuipingceshiguanliguiding":[{"i":1,"n":"第一条","txt":"为规范普通话水平测试管理，促进国家通用语言文字的推广普及和应用，根据《中华人民共和国国家通用语言文字法》，制定本规定。"},{"i":2,"n":"第二条","txt":"普通话水平测试（以下简称测试）是考查应试人运用国家通用语言的规范、熟练程度的专业测评。"},{"i":3,"n":"第三条","txt":"国务院语言文字工作部门主管全国的测试工作，制定测试政策和规划，发布测试等级标准和测试大纲，制定测试规程，实施证书管理。 省、自治区、直辖市人民政府语言文字工作部门主管本行政区域内的测试工作。"},{"i":4,"n":"第四条","txt":"国务院语言文字工作部门设立或者指定国家测试机构，负责全国测试工作的组织实施、质量监管和测试工作队伍建设，开展科学研究、信息化建设等，对地方测试机构进行业务指导、监督、检查。"},{"i":5,"n":"第五条","txt":"省级语言文字工作部门可根据需要设立或者指定省级及以下测试机构。省级测试机构在省级语言文字工作部门领导下，负责本行政区域内测试工作的组织实施、质量监管，设置测试站点，开展科学研究和测试工作队伍建设，对省级以下测试机构和测试站点进行管理、监督、检查。"},{"i":6,"n":"第六条","txt":"各级测试机构和测试站点依据测试规程组织开展测试工作，根据需要合理配备测试员和考务人员。 测试员和考务人员应当遵守测试工作纪律，按照测试机构和测试站点的组织和安排完成测试任务，保证测试质量。"},{"i":7,"n":"第七条","txt":"测试机构和测试站点要为测试员和考务人员开展测试提供必要的条件，合理支付其因测试工作产生的通信、交通、食宿、劳务等费用。"},{"i":8,"n":"第八条","txt":"测试机构和测试站点应当健全财务管理制度，按照标准收取测试费用。"},{"i":9,"n":"第九条","txt":"测试员分为省级测试员和国家级测试员，具体条件和产生办法由国家测试机构另行规定。"},{"i":10,"n":"第十条","txt":"以普通话为工作语言的下列人员，在取得相应职业资格或者从事相应岗位工作前，应当根据法律规定或者职业准入条件的要求接受测试： （一）教师； （二）广播电台、电视台的播音员、节目主持人； （三）影视话剧演员； （四）国家机关工作人员； （五）行业主管部门规定的其他应该接受测试的人员。"},{"i":11,"n":"第十一条","txt":"师范类专业、播音与主持艺术专业、影视话剧表演专业以及其他与口语表达密切相关专业的学生应当接受测试。 高等学校、职业学校应当为本校师生接受测试提供支持和便利。"},{"i":12,"n":"第十二条","txt":"社会其他人员可自愿申请参加测试。 在境内学习、工作或生活3个月及以上的港澳台人员和外籍人员可自愿申请参加测试。"},{"i":13,"n":"第十三条","txt":"应试人可根据实际需要，就近就便选择测试机构报名参加测试。 视障、听障人员申请参加测试的，省级测试机构应积极组织测试，并为其提供必要的便利。视障、听障人员测试办法由国务院语言文字工作部门另行制定。"},{"i":14,"n":"第十四条","txt":"普通话水平等级分为三级，每级分为甲、乙两等。一级甲等须经国家测试机构认定，一级乙等及以下由省级测试机构认定。 应试人测试成绩达到等级标准，由国家测试机构颁发相应的普通话水平测试等级证书。 普通话水平测试等级证书全国通用。"},{"i":15,"n":"第十五条","txt":"普通话水平测试等级证书分为纸质证书和电子证书，二者具有同等效力。纸质证书由国务院语言文字工作部门统一印制，电子证书执行《国家政务服务平台标准》中关于普通话水平测试等级证书电子证照的行业标准。 纸质证书遗失的，不予补发，可以通过国家政务服务平台查询测试成绩，查询结果与证书具有同等效力。"},{"i":16,"n":"第十六条","txt":"应试人对测试成绩有异议的，可以在测试成绩发布后15个工作日内向原测试机构提出复核申请。 测试机构接到申请后，应当在15个工作日内作出是否受理的决定。如受理，须在受理后15个工作日内作出复核决定。 具体受理条件和复核办法由国家测试机构制定。"},{"i":17,"n":"第十七条","txt":"测试机构徇私舞弊或者疏于管理，造成测试秩序混乱、作弊情况严重的，由主管的语言文字工作部门给予警告、暂停测试资格直至撤销测试机构的处理，并由主管部门依法依规对直接负责的主管人员或者其他直接责任人员给予处分；构成犯罪的，依法追究刑事责任。"},{"i":18,"n":"第十八条","txt":"测试工作人员徇私舞弊、违反测试规定的，可以暂停其参与测试工作或者取消测试工作资格，并通报其所在单位予以处理；构成犯罪的，依法追究刑事责任。"},{"i":19,"n":"第十九条","txt":"应试人在测试期间作弊或者实施其他严重违反考场纪律行为的，组织测试的测试机构或者测试站点应当取消其考试资格或者考试成绩，并报送国家测试机构记入全国普通话水平测试违纪人员档案。测试机构认为有必要的，还可以通报应试人就读学校或者所在单位。"},{"i":20,"n":"第二十条","txt":"本规定自2022年1月1日起施行。2003年5月21日发布的《普通话水平测试管理规定》（教育部令第16号）同时废止。"}],"putonggaodengxuexiaoxueshengguanliguiding":[{"i":1,"n":"第一条","txt":"为规范普通高等学校学生管理行为，维护普通高等学校正常的教育教学秩序和生活秩序，保障学生合法权益，培养德、智、体、美等方面全面发展的社会主义建设者和接班人,依据教育法、高等教育法以及有关法律、法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于普通高等学校、承担研究生教育任务的科学研究机构（以下称学校）对接受普通高等学历教育的研究生和本科、专科（高职）学生（以下称学生）的管理。"},{"i":3,"n":"第三条","txt":"学校要坚持社会主义办学方向，坚持马克思主义的指导地位,全面贯彻国家教育方针；要坚持以立德树人为根本，以理想信念教育为核心,培育和践行社会主义核心价值观，弘扬中华优秀传统文化和革命文化、社会主义先进文化，培养学生的社会责任感、创新精神和实践能力；要坚持依法治校，科学管理，健全和完善管理制度，规范管理行为，将管理与育人相结合，不断提高管理和服务水平。"},{"i":4,"n":"第四条","txt":"学生应当拥护中国共产党领导，努力学习马克思列宁主义、毛泽东思想、中国特色社会主义理论体系，深入学习习近平总书记系列重要讲话精神和治国理政新理念新思想新战略，坚定中国特色社会主义道路自信、理论自信、制度自信、文化自信，树立中国特色社会主义共同理想；应当树立爱国主义思想，具有团结统一、爱好和平、勤劳勇敢、自强不息的精神；应当增强法治观念，遵守宪法、法律、法规，遵守公民道德规范，遵守学校管理制度，具有良好的道德品质和行为习惯；应当刻苦学习，勇于探索，积极实践，努力掌握现代科学文化知识和专业技能；应当积极锻炼身体，增进身心健康，提高个人修养，培养审美情趣。"},{"i":5,"n":"第五条","txt":"实施学生管理，应当尊重和保护学生的合法权利，教育和引导学生承担应尽的义务与责任，鼓励和支持学生实行自我管理、自我服务、自我教育、自我监督。"},{"i":6,"n":"第六条","txt":"学生在校期间依法享有下列权利： （一）参加学校教育教学计划安排的各项活动，使用学校提供的教育教学资源； （二）参加社会实践、志愿服务、勤工助学、文娱体育及科技文化创新等活动，获得就业创业指导和服务； （三）申请奖学金、助学金及助学贷款； （四）在思想品德、学业成绩等方面获得科学、公正评价，完成学校规定学业后获得相应的学历证书、学位证书； （五）在校内组织、参加学生团体，以适当方式参与学校管理，对学校与学生权益相关事务享有知情权、参与权、表达权和监督权； （六）对学校给予的处理或者处分有异议，向学校、教育行政部门提出申诉，对学校、教职员工侵犯其人身权、财产权等合法权益的行为，提出申诉或者依法提起诉讼； （七）法律、法规及学校章程规定的其他权利。"},{"i":7,"n":"第七条","txt":"学生在校期间依法履行下列义务： （一）遵守宪法和法律、法规； （二）遵守学校章程和规章制度； （三）恪守学术道德，完成规定学业； （四）按规定缴纳学费及有关费用，履行获得贷学金及助学金的相应义务； （五）遵守学生行为规范，尊敬师长，养成良好的思想品德和行为习惯； （六）法律、法规及学校章程规定的其他义务。"},{"i":8,"n":"第八条","txt":"按国家招生规定录取的新生，持录取通知书，按学校有关要求和规定的期限到校办理入学手续。因故不能按期入学的，应当向学校请假。未请假或者请假逾期的，除因不可抗力等正当事由以外，视为放弃入学资格。"},{"i":9,"n":"第九条","txt":"学校应当在报到时对新生入学资格进行初步审查，审查合格的办理入学手续，予以注册学籍；审查发现新生的录取通知、考生信息等证明材料，与本人实际情况不符，或者有其他违反国家招生考试规定情形的，取消入学资格。"},{"i":10,"n":"第十条","txt":"新生可以申请保留入学资格。保留入学资格期间不具有学籍。保留入学资格的条件、期限等由学校规定。 新生保留入学资格期满前应向学校申请入学，经学校审查合格后，办理入学手续。审查不合格的，取消入学资格；逾期不办理入学手续且未有因不可抗力延迟等正当理由的，视为放弃入学资格。"},{"i":11,"n":"第十一条","txt":"学生入学后，学校应当在3个月内按照国家招生规定进行复查。复查内容主要包括以下方面： （一）录取手续及程序等是否合乎国家招生规定； （二）所获得的录取资格是否真实、合乎相关规定； （三）本人及身份证明与录取通知、考生档案等是否一致； （四）身心健康状况是否符合报考专业或者专业类别体检要求，能否保证在校正常学习、生活； （五）艺术、体育等特殊类型录取学生的专业水平是否符合录取要求。 复查中发现学生存在弄虚作假、徇私舞弊等情形的，确定为复查不合格，应当取消学籍；情节严重的，学校应当移交有关部门调查处理。 复查中发现学生身心状况不适宜在校学习，经学校指定的二级甲等以上医院诊断，需要在家休养的，可以按照第十条的规定保留入学资格。 复查的程序和办法，由学校规定。"},{"i":12,"n":"第十二条","txt":"每学期开学时，学生应当按学校规定办理注册手续。不能如期注册的，应当履行暂缓注册手续。未按学校规定缴纳学费或者有其他不符合注册条件的，不予注册。 家庭经济困难的学生可以申请助学贷款或者其他形式资助，办理有关手续后注册。 学校应当按照国家有关规定为家庭经济困难学生提供教育救助，完善学生资助体系，保证学生不因家庭经济困难而放弃学业。"},{"i":13,"n":"第十三条","txt":"学生应当参加学校教育教学计划规定的课程和各种教育教学环节（以下统称课程）的考核，考核成绩记入成绩册，并归入学籍档案。 考核分为考试和考查两种。考核和成绩评定方式，以及考核不合格的课程是否重修或者补考，由学校规定。"},{"i":14,"n":"第十四条","txt":"学生思想品德的考核、鉴定，以本规定第四条为主要依据，采取个人小结、师生民主评议等形式进行。 学生体育成绩评定要突出过程管理，可以根据考勤、课内教学、课外锻炼活动和体质健康等情况综合评定。"},{"i":15,"n":"第十五条","txt":"学生每学期或者每学年所修课程或者应修学分数以及升级、跳级、留级、降级等要求，由学校规定。"},{"i":16,"n":"第十六条","txt":"学生根据学校有关规定，可以申请辅修校内其他专业或者选修其他专业课程；可以申请跨校辅修专业或者修读课程，参加学校认可的开放式网络课程学习。学生修读的课程成绩（学分），学校审核同意后，予以承认。"},{"i":17,"n":"第十七条","txt":"学生参加创新创业、社会实践等活动以及发表论文、获得专利授权等与专业学习、学业要求相关的经历、成果，可以折算为学分，计入学业成绩。具体办法由学校规定。 学校应当鼓励、支持和指导学生参加社会实践、创新创业活动，可以建立创新创业档案、设置创新创业学分。"},{"i":18,"n":"第十八条","txt":"学校应当健全学生学业成绩和学籍档案管理制度，真实、完整地记载、出具学生学业成绩，对通过补考、重修获得的成绩，应当予以标注。 学生严重违反考核纪律或者作弊的，该课程考核成绩记为无效，并应视其违纪或者作弊情节，给予相应的纪律处分。给予警告、严重警告、记过及留校察看处分的，经教育表现较好，可以对该课程给予补考或者重修机会。 学生因退学等情况中止学业，其在校学习期间所修课程及已获得学分，应当予以记录。学生重新参加入学考试、符合录取条件，再次入学的，其已获得学分，经录取学校认定，可以予以承认。具体办法由学校规定。"},{"i":19,"n":"第十九条","txt":"学生应当按时参加教育教学计划规定的活动。不能按时参加的，应当事先请假并获得批准。无故缺席的，根据学校有关规定给予批评教育，情节严重的，给予相应的纪律处分。"},{"i":20,"n":"第二十条","txt":"学校应当开展学生诚信教育，以适当方式记录学生学业、学术、品行等方面的诚信信息，建立对失信行为的约束和惩戒机制；对有严重失信行为的，可以规定给予相应的纪律处分，对违背学术诚信的，可以对其获得学位及学术称号、荣誉等作出限制。"},{"i":21,"n":"第二十一条","txt":"学生在学习期间对其他专业有兴趣和专长的，可以申请转专业；以特殊招生形式录取的学生，国家有相关规定或者录取前与学校有明确约定的，不得转专业。 学校应当制定学生转专业的具体办法，建立公平、公正的标准和程序，健全公示制度。学校根据社会对人才需求情况的发展变化，需要适当调整专业的，应当允许在读学生转到其他相关专业就读。 休学创业或退役后复学的学生，因自身情况需要转专业的，学校应当优先考虑。"},{"i":22,"n":"第二十二条","txt":"学生一般应当在被录取学校完成学业。因患病或者有特殊困难、特别需要，无法继续在本校学习或者不适应本校学习要求的，可以申请转学。有下列情形之一，不得转学： （一）入学未满一学期或者毕业前一年的； （二）高考成绩低于拟转入学校相关专业同一生源地相应年份录取成绩的； （三）由低学历层次转为高学历层次的； （四）以定向就业招生录取的； （五）研究生拟转入学校、专业的录取控制标准高于其所在学校、专业的； （六）无正当转学理由的。 学生因学校培养条件改变等非本人原因需要转学的，学校应当出具证明，由所在地省级教育行政部门协调转学到同层次学校。"},{"i":23,"n":"第二十三条","txt":"学生转学由学生本人提出申请，说明理由，经所在学校和拟转入学校同意，由转入学校负责审核转学条件及相关证明，认为符合本校培养要求且学校有培养能力的，经学校校长办公会或者专题会议研究决定，可以转入。研究生转学还应当经拟转入专业导师同意。 跨省转学的，由转出地省级教育行政部门商转入地省级教育行政部门，按转学条件确认后办理转学手续。须转户口的由转入地省级教育行政部门将有关文件抄送转入学校所在地的公安机关。"},{"i":24,"n":"第二十四条","txt":"学校应当按照国家有关规定，建立健全学生转学的具体办法；对转学情况应当及时进行公示，并在转学完成后3个月内，由转入学校报所在地省级教育行政部门备案。 省级教育行政部门应当加强对区域内学校转学行为的监督和管理，及时纠正违规转学行为。"},{"i":25,"n":"第二十五条","txt":"学生可以分阶段完成学业，除另有规定外，应当在学校规定的最长学习年限（含休学和保留学籍）内完成学业。 学生申请休学或者学校认为应当休学的，经学校批准，可以休学。休学次数和期限由学校规定。"},{"i":26,"n":"第二十六条","txt":"学校可以根据情况建立并实行灵活的学习制度。对休学创业的学生，可以单独规定最长学习年限，并简化休学批准程序。"},{"i":27,"n":"第二十七条","txt":"新生和在校学生应征参加中国人民解放军（含中国人民武装警察部队），学校应当保留其入学资格或者学籍至退役后2年。 学生参加学校组织的跨校联合培养项目，在联合培养学校学习期间，学校同时为其保留学籍。 学生保留学籍期间，与其实际所在的部队、学校等组织建立管理关系。"},{"i":28,"n":"第二十八条","txt":"休学学生应当办理手续离校。学生休学期间，学校应为其保留学籍，但不享受在校学习学生待遇。因病休学学生的医疗费按国家及当地的有关规定处理。"},{"i":29,"n":"第二十九条","txt":"学生休学期满前应当在学校规定的期限内提出复学申请，经学校复查合格，方可复学。"},{"i":30,"n":"第三十条","txt":"学生有下列情形之一，学校可予退学处理： （一）学业成绩未达到学校要求或者在学校规定的学习年限内未完成学业的； （二）休学、保留学籍期满，在学校规定期限内未提出复学申请或者申请复学经复查不合格的； （三）根据学校指定医院诊断，患有疾病或者意外伤残不能继续在校学习的； （四）未经批准连续两周未参加学校规定的教学活动的； （五）超过学校规定期限未注册而又未履行暂缓注册手续的； （六）学校规定的不能完成学业、应予退学的其他情形。 学生本人申请退学的，经学校审核同意后，办理退学手续。"},{"i":31,"n":"第三十一条","txt":"退学学生，应当按学校规定期限办理退学手续离校。退学的研究生，按已有毕业学历和就业政策可以就业的，由学校报所在地省级毕业生就业部门办理相关手续；在学校规定期限内没有聘用单位的，应当办理退学手续离校。 退学学生的档案由学校退回其家庭所在地，户口应当按照国家相关规定迁回原户籍地或者家庭户籍所在地。"},{"i":32,"n":"第三十二条","txt":"学生在学校规定学习年限内，修完教育教学计划规定内容，成绩合格，达到学校毕业要求的，学校应当准予毕业，并在学生离校前发给毕业证书。 符合学位授予条件的，学位授予单位应当颁发学位证书。 学生提前完成教育教学计划规定内容，获得毕业所要求的学分，可以申请提前毕业。学生提前毕业的条件，由学校规定。"},{"i":33,"n":"第三十三条","txt":"学生在学校规定学习年限内，修完教育教学计划规定内容，但未达到学校毕业要求的，学校可以准予结业，发给结业证书。 结业后是否可以补考、重修或者补作毕业设计、论文、答辩，以及是否颁发毕业证书、学位证书，由学校规定。合格后颁发的毕业证书、学位证书，毕业时间、获得学位时间按发证日期填写。 对退学学生,学校应当发给肄业证书或者写实性学习证明。"},{"i":34,"n":"第三十四条","txt":"学校应当严格按照招生时确定的办学类型和学习形式，以及学生招生录取时填报的个人信息，填写、颁发学历证书、学位证书及其他学业证书。 学生在校期间变更姓名、出生日期等证书需填写的个人信息的，应当有合理、充分的理由，并提供有法定效力的相应证明文件。学校进行审查，需要学生生源地省级教育行政部门及有关部门协助核查的，有关部门应当予以配合。"},{"i":35,"n":"第三十五条","txt":"学校应当执行高等教育学籍学历电子注册管理制度，完善学籍学历信息管理办法，按相关规定及时完成学生学籍学历电子注册。"},{"i":36,"n":"第三十六条","txt":"对完成本专业学业同时辅修其他专业并达到该专业辅修要求的学生，由学校发给辅修专业证书。"},{"i":37,"n":"第三十七条","txt":"对违反国家招生规定取得入学资格或者学籍的，学校应当取消其学籍，不得发给学历证书、学位证书；已发的学历证书、学位证书，学校应当依法予以撤销。对以作弊、剽窃、抄袭等学术不端行为或者其他不正当手段获得学历证书、学位证书的，学校应当依法予以撤销。 被撤销的学历证书、学位证书已注册的，学校应当予以注销并报教育行政部门宣布无效。"},{"i":38,"n":"第三十八条","txt":"学历证书和学位证书遗失或者损坏，经本人申请，学校核实后应当出具相应的证明书。证明书与原证书具有同等效力。"},{"i":39,"n":"第三十九条","txt":"学校、学生应当共同维护校园正常秩序，保障学校环境安全、稳定，保障学生的正常学习和生活。"},{"i":40,"n":"第四十条","txt":"学校应当建立和完善学生参与管理的组织形式，支持和保障学生依法、依章程参与学校管理。"},{"i":41,"n":"第四十一条","txt":"学生应当自觉遵守公民道德规范，自觉遵守学校管理制度，创造和维护文明、整洁、优美、安全的学习和生活环境，树立安全风险防范和自我保护意识，保障自身合法权益。"},{"i":42,"n":"第四十二条","txt":"学生不得有酗酒、打架斗殴、赌博、吸毒，传播、复制、贩卖非法书刊和音像制品等违法行为；不得参与非法传销和进行邪教、封建迷信活动；不得从事或者参与有损大学生形象、有悖社会公序良俗的活动。 学校发现学生在校内有违法行为或者严重精神疾病可能对他人造成伤害的，可以依法采取或者协助有关部门采取必要措施。"},{"i":43,"n":"第四十三条","txt":"学校应当坚持教育与宗教相分离原则。任何组织和个人不得在学校进行宗教活动。"},{"i":44,"n":"第四十四条","txt":"学校应当建立健全学生代表大会制度，为学生会、研究生会等开展活动提供必要条件，支持其在学生管理中发挥作用。 学生可以在校内成立、参加学生团体。学生成立团体，应当按学校有关规定提出书面申请，报学校批准并施行登记和年检制度。 学生团体应当在宪法、法律、法规和学校管理制度范围内活动，接受学校的领导和管理。学生团体邀请校外组织、人员到校举办讲座等活动，需经学校批准。"},{"i":45,"n":"第四十五条","txt":"学校提倡并支持学生及学生团体开展有益于身心健康、成长成才的学术、科技、艺术、文娱、体育等活动。 学生进行课外活动不得影响学校正常的教育教学秩序和生活秩序。 学生参加勤工助学活动应当遵守法律、法规以及学校、用工单位的管理制度，履行勤工助学活动的有关协议。"},{"i":46,"n":"第四十六条","txt":"学生举行大型集会、游行、示威等活动，应当按法律程序和有关规定获得批准。对未获批准的，学校应当依法劝阻或者制止。"},{"i":47,"n":"第四十七条","txt":"学生应当遵守国家和学校关于网络使用的有关规定，不得登录非法网站和传播非法文字、音频、视频资料等，不得编造或者传播虚假、有害信息；不得攻击、侵入他人计算机和移动通讯网络系统。"},{"i":48,"n":"第四十八条","txt":"学校应当建立健全学生住宿管理制度。学生应当遵守学校关于学生住宿管理的规定。鼓励和支持学生通过制定公约，实施自我管理。"},{"i":49,"n":"第四十九条","txt":"学校、省（区、市）和国家有关部门应当对在德、智、体、美等方面全面发展或者在思想品德、学业成绩、科技创造、体育竞赛、文艺活动、志愿服务及社会实践等方面表现突出的学生，给予表彰和奖励。"},{"i":50,"n":"第五十条","txt":"对学生的表彰和奖励可以采取授予“三好学生”称号或者其他荣誉称号、颁发奖学金等多种形式，给予相应的精神鼓励或者物质奖励。 学校对学生予以表彰和奖励，以及确定推荐免试研究生、国家奖学金、公派出国留学人选等赋予学生利益的行为，应当建立公开、公平、公正的程序和规定，建立和完善相应的选拔、公示等制度。"},{"i":51,"n":"第五十一条","txt":"对有违反法律法规、本规定以及学校纪律行为的学生，学校应当给予批评教育，并可视情节轻重，给予如下纪律处分： （一）警告； （二）严重警告； （三）记过； （四）留校察看； （五）开除学籍。"},{"i":52,"n":"第五十二条","txt":"学生有下列情形之一，学校可以给予开除学籍处分： （一）违反宪法，反对四项基本原则、破坏安定团结、扰乱社会秩序的； （二）触犯国家法律，构成刑事犯罪的； （三）受到治安管理处罚，情节严重、性质恶劣的； （四）代替他人或者让他人代替自己参加考试、组织作弊、使用通讯设备或其他器材作弊、向他人出售考试试题或答案牟取利益，以及其他严重作弊或扰乱考试秩序行为的； （五）学位论文、公开发表的研究成果存在抄袭、篡改、伪造等学术不端行为，情节严重的，或者代写论文、买卖论文的； （六）违反本规定和学校规定，严重影响学校教育教学秩序、生活秩序以及公共场所管理秩序的； （七）侵害其他个人、组织合法权益，造成严重后果的； （八）屡次违反学校规定受到纪律处分，经教育不改的。"},{"i":53,"n":"第五十三条","txt":"学校对学生作出处分，应当出具处分决定书。处分决定书应当包括下列内容： （一）学生的基本信息； （二）作出处分的事实和证据； （三）处分的种类、依据、期限； （四）申诉的途径和期限； （五）其他必要内容。"},{"i":54,"n":"第五十四条","txt":"学校给予学生处分，应当坚持教育与惩戒相结合，与学生违法、违纪行为的性质和过错的严重程度相适应。学校对学生的处分，应当做到证据充分、依据明确、定性准确、程序正当、处分适当。"},{"i":55,"n":"第五十五条","txt":"在对学生作出处分或者其他不利决定之前，学校应当告知学生作出决定的事实、理由及依据，并告知学生享有陈述和申辩的权利，听取学生的陈述和申辩。 处理、处分决定以及处分告知书等，应当直接送达学生本人，学生拒绝签收的，可以以留置方式送达；已离校的，可以采取邮寄方式送达；难于联系的，可以利用学校网站、新闻媒体等以公告方式送达。"},{"i":56,"n":"第五十六条","txt":"对学生作出取消入学资格、取消学籍、退学、开除学籍或者其他涉及学生重大利益的处理或者处分决定的，应当提交校长办公会或者校长授权的专门会议研究决定，并应当事先进行合法性审查。"},{"i":57,"n":"第五十七条","txt":"除开除学籍处分以外，给予学生处分一般应当设置6到12个月期限，到期按学校规定程序予以解除。解除处分后，学生获得表彰、奖励及其他权益，不再受原处分的影响。"},{"i":58,"n":"第五十八条","txt":"对学生的奖励、处理、处分及解除处分材料，学校应当真实完整地归入学校文书档案和本人档案。 被开除学籍的学生，由学校发给学习证明。学生按学校规定期限离校，档案由学校退回其家庭所在地，户口应当按照国家相关规定迁回原户籍地或者家庭户籍所在地。"},{"i":59,"n":"第五十九条","txt":"学校应当成立学生申诉处理委员会，负责受理学生对处理或者处分决定不服提起的申诉。 学生申诉处理委员会应当由学校相关负责人、职能部门负责人、教师代表、学生代表、负责法律事务的相关机构负责人等组成，可以聘请校外法律、教育等方面专家参加。 学校应当制定学生申诉的具体办法,健全学生申诉处理委员会的组成与工作规则，提供必要条件，保证其能够客观、公正地履行职责。"},{"i":60,"n":"第六十条","txt":"学生对学校的处理或者处分决定有异议的，可以在接到学校处理或者处分决定书之日起10日内，向学校学生申诉处理委员会提出书面申诉。"},{"i":61,"n":"第六十一条","txt":"学生申诉处理委员会对学生提出的申诉进行复查，并在接到书面申诉之日起15日内作出复查结论并告知申诉人。情况复杂不能在规定限期内作出结论的，经学校负责人批准，可延长15日。学生申诉处理委员会认为必要的，可以建议学校暂缓执行有关决定。 学生申诉处理委员会经复查，认为做出处理或者处分的事实、依据、程序等存在不当，可以作出建议撤销或变更的复查意见，要求相关职能部门予以研究，重新提交校长办公会或者专门会议作出决定。"},{"i":62,"n":"第六十二条","txt":"学生对复查决定有异议的，在接到学校复查决定书之日起15日内，可以向学校所在地省级教育行政部门提出书面申诉。 省级教育行政部门应当在接到学生书面申诉之日起30个工作日内，对申诉人的问题给予处理并作出决定。"},{"i":63,"n":"第六十三条","txt":"省级教育行政部门在处理因对学校处理或者处分决定不服提起的学生申诉时，应当听取学生和学校的意见，并可根据需要进行必要的调查。根据审查结论，区别不同情况，分别作出下列处理： (一) 事实清楚、依据明确、定性准确、程序正当、处分适当的，予以维持； (二) 认定事实不存在，或者学校超越职权、违反上位法规定作出决定的，责令学校予以撤销； (三) 认定事实清楚，但认定情节有误、定性不准确，或者适用依据有错误的，责令学校变更或者重新作出决定； (四) 认定事实不清、证据不足，或者违反本规定以及学校规定的程序和权限的，责令学校重新作出决定。"},{"i":64,"n":"第六十四条","txt":"自处理、处分或者复查决定书送达之日起，学生在申诉期内未提出申诉的视为放弃申诉，学校或者省级教育行政部门不再受理其提出的申诉。 处理、处分或者复查决定书未告知学生申诉期限的，申诉期限自学生知道或者应当知道处理或者处分决定之日起计算，但最长不得超过6个月。"},{"i":65,"n":"第六十五条","txt":"学生认为学校及其工作人员违反本规定，侵害其合法权益的；或者学校制定的规章制度与法律法规和本规定抵触的，可以向学校所在地省级教育行政部门投诉。 教育主管部门在实施监督或者处理申诉、投诉过程中，发现学校及其工作人员有违反法律、法规及本规定的行为或者未按照本规定履行相应义务的，或者学校自行制定的相关管理制度、规定，侵害学生合法权益的，应当责令改正；发现存在违法违纪的，应当及时进行调查处理或者移送有关部门，依据有关法律和相关规定，追究有关责任人的责任。"},{"i":66,"n":"第六十六条","txt":"学校对接受高等学历继续教育的学生、港澳台侨学生、留学生的管理，参照本规定执行。"},{"i":67,"n":"第六十七条","txt":"学校应当根据本规定制定或修改学校的学生管理规定或者纪律处分规定，报主管教育行政部门备案（中央部委属校同时抄报所在地省级教育行政部门），并及时向学生公布。 省级教育行政部门根据本规定，指导、检查和监督本地区高等学校的学生管理工作。"},{"i":68,"n":"第六十八条","txt":"本规定自2017年9月1日起施行。原《普通高等学校学生管理规定》（教育部令第21号）同时废止。其他有关文件规定与本规定不一致的，以本规定为准。"}],"putonggaodengxuexiaozhaoshengweiguixingweichulizanad7e14":[{"i":1,"n":"第一条","txt":"为规范对普通高等学校招生违规行为的处理，保证招生公开、公平、公正，根据《中华人民共和国教育法》《中华人民共和国高等教育法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称普通高等学校（以下简称高校）招生，是指高校通过国家教育考试或者国家认可的入学方式选拔录取本科、专科学生的活动。 高校、高级中等学校（含中等职业学校，以下简称高中）、招生考试机构、主管教育行政部门及其招生工作人员、考生等，在高校招生工作过程中，违反国家有关教育法律法规和国家高等教育招生管理规定的行为认定及处理，适用本办法。"},{"i":3,"n":"第三条","txt":"国务院教育行政部门主管全国高校招生工作。 县级以上各级人民政府教育行政部门按照职责分工，依法处理各类违反国家高等教育招生管理制度的行为。 国务院有关主管部门在职责范围内加强对所属高校招生的监督管理。"},{"i":4,"n":"第四条","txt":"高校招生应当遵循公开、公平、公正原则，接受考生、社会的监督。 高校招生接受监察部门的监督。"},{"i":5,"n":"第五条","txt":"对高校招生违规行为的处理，应当事实清楚、证据确凿、依据明确、程序合法、处理适当。"},{"i":6,"n":"第六条","txt":"高校违反国家招生管理规定，有下列情形之一的，由主管教育行政部门责令限期改正，给予警告或者通报批评；情节严重的，给予减少招生计划、暂停特殊类型招生试点项目或者依法给予停止招生的处理。对直接负责的主管人员和其他直接责任人员，视情节轻重依法给予相应处分；涉嫌犯罪的，依法移送司法机关处理。 （一）发布违反国家规定的招生简章，或者进行虚假宣传、骗取钱财的； （二）未按照信息公开的规定公开招生信息的； （三）超出核定办学规模招生或者擅自调整招生计划的； （四）违反规定降低标准录取考生或者拒绝录取符合条件的考生的； （五）在特殊类型招生中出台违反国家规定的报考条件，或者弄虚作假、徇私舞弊，录取不符合条件的考生的； （六）违规委托中介机构进行招生录取，或者以承诺录取为名向考生收取费用的； （七）其他违反国家招生管理规定的行为。"},{"i":7,"n":"第七条","txt":"高中有下列情形之一的，由主管教育行政部门责令限期改正，给予警告或者通报批评。对直接负责的主管人员和其他直接责任人员，视情节轻重依法给予相应处分；涉嫌犯罪的，依法移送司法机关处理。 （一）未按照规定的标准和程序，以照顾特定考生为目的，滥用推荐评价权力的； （二）未按规定公示享受优惠政策的考生名单、各类推荐考生的名额、名单及相关证明材料的； （三）在考生报名、推荐等工作过程中出具与事实不符的成绩单、推荐材料、证明材料等虚假材料，在学生综合素质档案中虚构事实或者故意隐瞒事实的； （四）违规办理学籍档案、违背考生意愿为考生填报志愿或者有偿推荐、组织生源的； （五）其他违反国家招生管理规定的行为。"},{"i":8,"n":"第八条","txt":"招生考试机构违反国家招生管理规定，有下列情形之一的，由主管教育行政部门责令限期改正，给予警告或者通报批评。对直接负责的主管人员和其他直接责任人员，视情节轻重依法给予相应处分；涉嫌犯罪的，依法移送司法机关处理。 （一）为高校擅自超计划招生办理录取手续的； （二）对降低标准违规录取考生进行投档的； （三）违反录取程序投档操作的； （四）在招生结束后违规补录的； （五）未按照信息公开的规定公开招生工作信息的； （六）对高校录取工作监督不力、造成严重不良后果的； （七）其他违反国家招生管理规定的行为。"},{"i":9,"n":"第九条","txt":"省级教育行政部门违反有关管理职责，有下列情形之一的，由国务院教育行政部门责令限期改正，并可给予通报批评。对直接负责的主管人员和其他直接责任人员，由有关主管部门依法给予处分；涉嫌犯罪的，依法移送司法机关处理。 （一）出台与国家招生政策相抵触的招生规定或者超越职权制定招生优惠政策的； （二）擅自扩大国家核定的招生规模和追加招生计划，擅自改变招生计划类型的； （三）要求招生考试机构和高校违规录取考生的； （四）对高校和招生考试机构招生工作监管不力、造成严重不良后果的； （五）其他违反国家招生管理规定的行为。"},{"i":10,"n":"第十条","txt":"招生工作人员有下列情形之一的，其所在单位应当立即责令暂停其负责的招生工作，由有关部门视情节轻重依法给予相应处分或者其他处理；涉嫌犯罪的，依法移送司法机关处理。 （一）违规更改考生报名、志愿、资格、分数、录取等信息的； （二）对已录取考生违规变更录取学校或者专业的； （三）在特殊类型招生中泄露面试考核考官名单或者利用职务便利请托考核评价的教师，照顾特定考生的； （四）泄露尚未公布的考生成绩、考生志愿、录取分数线等可能影响录取公正信息的，或者对外泄露、倒卖考生个人信息的； （五）为考生获得相关招生资格弄虚作假、徇私舞弊的； （六）违反回避制度，应当回避而没有回避的； （七）索取或收受考生及家长财物，接受宴请等可能影响公正履职活动安排的； （八）参与社会中介机构或者个人非法招生活动的； （九）其他影响高校招生公平、公正的行为。"},{"i":11,"n":"第十一条","txt":"考生有下列情形之一的，应当如实记入其考试诚信档案。下列行为在报名阶段发现的，取消报考资格；在入学前发现的，取消入学资格；入学后发现的，取消录取资格或者学籍；毕业后发现的，由教育行政部门宣布学历、学位证书无效，责令收回或者予以没收；涉嫌犯罪的，依法移送司法机关处理。 （一）提供虚假姓名、年龄、民族、户籍等个人信息，伪造、非法获得证件、成绩证明、荣誉证书等，骗取报名资格、享受优惠政策的； （二）在综合素质评价、相关申请材料中提供虚假材料、影响录取结果的； （三）冒名顶替入学，由他人替考入学或者取得优惠资格的； （四）其他严重违反高校招生规定的弄虚作假行为。 违反国家教育考试规定、情节严重受到停考处罚，在处罚结束后继续报名参加国家教育考试的，由学校决定是否予以录取。"},{"i":12,"n":"第十二条","txt":"实行高校招生工作问责制。高校校长、招生考试机构主要负责人、教育行政部门主要负责人是招生工作的第一责任人，对本校、本部门、本地区的招生工作负全面领导责任。 在招生工作中，因违规行为造成严重后果和恶劣影响的，除追究直接负责人的责任外，还应当根据领导干部问责的相关规定，对有关责任人实行问责。"},{"i":13,"n":"第十三条","txt":"对在高校招生工作中违规人员的处理，由有权查处的部门按照管理权限，依据《中华人民共和国行政监察法》《行政机关公务员处分条例》《事业单位工作人员处分暂行规定》等相关规定，依法予以监察处理、作出处分决定或者给予其他处理。"},{"i":14,"n":"第十四条","txt":"高校招生工作以外的其他人员违规插手、干预招生工作，影响公平公正、造成严重影响和后果的，相关案件线索移送纪检监察机关或者司法机关查处。"},{"i":15,"n":"第十五条","txt":"出现本办法第二章规定的违规情形的，有关主管部门应当立即启动相关程序，进行调查处理。情节严重、影响恶劣或者案情复杂、社会影响大的，应当及时上报，必要时由国务院教育行政部门参与或者直接进行处理。"},{"i":16,"n":"第十六条","txt":"对有关责任人员违规行为的处理，应当按照国家规定的程序进行。对有关责任人员和考生的违规行为调查和收集证据，应当有2名以上工作人员。作出处理决定之前，应当听取当事人的陈述和申辩。"},{"i":17,"n":"第十七条","txt":"对处理决定不服的有关责任人员和考生，可以按照国家有关规定提出复核或者申诉；符合法律规定受案范围的，可以依法提起行政复议或者诉讼。"},{"i":18,"n":"第十八条","txt":"本办法所称特殊类型招生，是指自主选拔录取、艺术类专业、体育类专业、保送生等类型的高校招生。"},{"i":19,"n":"第十九条","txt":"研究生招生、成人高校招生有关违规行为的处理，参照本办法执行。"},{"i":20,"n":"第二十条","txt":"本办法自发布之日起施行。"}],"putonggaodengxuexiaojiaoyupingguzanxingguiding":[{"i":1,"n":"第一条","txt":"为了建设有中国特色的社会主义高等学校，加强国家对普通高等教育的宏观管理，指导普通高等学校的教育评估工作，特制定本规定。"},{"i":2,"n":"第二条","txt":"普通高等学校教育评估的主要目的，是增强高等学校主动适应社会需要的能力，发挥社会对学校教育的监督作用，自觉坚持高等教育的社会主义方向，不断提高办学水平和教育质量，更好地为社会主义建设服务。"},{"i":3,"n":"第三条","txt":"普通高等学校教育评估的基本任务，是根据一定的教育目标和标准，通过系统地搜集学校教育的主要信息，准确地了解实际情况，进行科学分析，对学校办学水平和教育质量作出评价，为学校改进工作、开展教育改革和教育管理部门改善宏观管理提供依据。"},{"i":4,"n":"第四条","txt":"普通高等学校教育评估坚持社会主义办学方向，认真贯彻教育为社会主义建设服务、与生产劳动相结合、德智体全面发展的方针，始终把坚定正确的政治方向放在首位，以能否培养适应社会主义建设实际需要的社会主义建设者和接班人作为评价学校办学水平和教育质量的基本标准。"},{"i":5,"n":"第五条","txt":"普通高等学校教育评估主要有合格评估（鉴定）、办学水平评估和选优评估三种基本形式。各种评估形式应制定相应的评估方案（含评估标准、评估指标体系和评估方法），评估方案要力求科学、简易、可行、注重实效，有利于调动各类学校的积极性，在保证基本教育质量的基础上办出各自的特色。"},{"i":6,"n":"第六条","txt":"普通高等学校教育评估是国家对高等学校实行监督的重要形式，由各级人民政府及其教育行政部门组织实施。 在学校自我评估的基础上，以组织党政有关部门和教育界、知识界以及用人部门进行的社会评估为重点，在政策上体现区别对待、奖优罚劣的原则，鼓励学术机构、社会团体参加教育评估。"},{"i":7,"n":"第七条","txt":"合格评估（鉴定）是国家对新建普通高等学校的基本办学条件和基本教育质量的一种认可制度，由国家教育委员会组织实施，在新建普通高等学校被批准建立之后有第一届毕业生时进行。"},{"i":8,"n":"第八条","txt":"办学条件鉴定的合格标准以《普通高等学校设置暂行条例》为依据，教育质量鉴定的合格标准以《中华人民共和国学位条例》中关于学位授权标准的规定和国家制订的有关不同层次教育的培养目标和专业（学科）的基本培养规格为依据。"},{"i":9,"n":"第九条","txt":"鉴定合格分合格、暂缓通过和不合格三种。鉴定合格的学校，由国家教育委员会公布名单并发给鉴定合格证书。鉴定暂缓通过的学校需在规定期限内采取措施，改善办学条件，提高教育质量，并需重新接受鉴定。经鉴定不合格的学校，由国家教育委员会区别情况，责令其限期整顿、停止招生或停办。"},{"i":10,"n":"第十条","txt":"办学水平评估，是对已经鉴定合格的学校进行的经常性评估，它分为整个学校办学水平的综合评估和学校中思想政治教育、专业（学科）、课程及其他教育工作的单项评估。"},{"i":11,"n":"第十一条","txt":"办学水平的综合评估，根据国家对不同类别学校所规定的任务与目标，由上级政府和有关学校主管部门组织实施，目的是全面考察学校的办学指导思想，贯彻执行党和国家的路线、方针、政策的情况，学校建设状况以及思想政治工作、人才培养、科学研究、为社会服务等方面的水平和质量。其中重点是学校领导班子等的组织建设、马列主义教育、学生思想政治教育的状况。这是各级人民政府和学校主管部门对学校实行监督和考核的重要形式。 办学水平的综合评估一般每四至五年进行一次（和学校领导班子任期相一致），综合评估结束后应作出结论，肯定成绩，指出不足，提出改进意见，必要时由上级人民政府或学校主管部门责令其限期整顿。学校应在综合评估结束后的三个月内向上级人民政府和学校主管部门写出改进报告，上级人民政府和学校主管部门应组织复查。"},{"i":12,"n":"第十二条","txt":"思想政治教育、专业（学科）、课程或其他教育工作的单项评估，主要由国务院有关部门和省（自治区、直辖市）教育行政部门组织实施。目的是通过校际间思想政治教育、专业（学科）、课程或其他单项教育工作的比较评估，诊断教育工作状况，交流教育工作经验，促进相互学习，共同提高。评估结束后应对每个被评单位分别提出评估报告并作出评估结论，结论分为优秀、良好、合格、不合格四种，不排名次。对结论定为不合格的由组织实施教育评估的国务院有关部门或省（自治区、直辖市）教育行政部门责令其限期整顿，并再次进行评估。"},{"i":13,"n":"第十三条","txt":"选优评估是在普通高等学校进行的评比选拔活动，其目的是在办学水平评估的基础上，遴选优秀，择优支持，促进竞争，提高水平。"},{"i":14,"n":"第十四条","txt":"选优评估分省（部门）、国家两级。根据选优评估结果排出名次或确定优选对象名单，予以公布，对成绩卓著的给予表彰、奖励。"},{"i":15,"n":"第十五条","txt":"学校内部评估，即学校内部自行组织实施的自我评估，是加强学校管理的重要手段，也是各级人民政府及其教育行政部门组织的普通高等学校教育评估工作的基础，其目的是通过自我评估，不断提高办学水平和教育质量，主动适应社会主义建设需要。学校主管部门应给予鼓励、支持和指导。"},{"i":16,"n":"第十六条","txt":"学校内部评估的重点是思想政治教育、专业（学科）、课程或其他教育工作的单项评估，基础是经常性的教学评估活动。评估计划、评估对象、评估方案、评估结论表达方式以及有关政策措施，由学校根据实际情况和本规定的要求自行确定。"},{"i":17,"n":"第十七条","txt":"学校应建设利毕业生跟踪调查和与社会用人部门经常联系的制度，了解社会需要，收集社会反馈信息，作为开展学校内部评估的重要依据。"},{"i":18,"n":"第十八条","txt":"在国务院和省（自治区、直辖市）人民政府领导下，国家教育委员会、国务院有关部门教育行政部门和省（自治区、直辖市）高校工委、教育行政部门建立普通高等学校教育评估领导小组，并确定有关具体机构负责教育评估的日常工作。"},{"i":19,"n":"第十九条","txt":"国家普通高等学校教育评估领导小组，在国家教育委员会的领导下，负责全国普通高等学校教育评估工作。其具体职责是： （一）制订普通高等学校教育评估的基本准则和实施细则； （二）指导、协调、检查各部门、各地区的普通高等学校教育评估工作，根据需要组织各种评估工作或试点； （三）审核、提出鉴定合格学校名单报国家教育委员会批准公布，接受并处理学校对教育评估工作及评估结论的额申诉； （四）收集、整理和分析全国教育评估信息，负责向教育管理决策部门提供； （五）推动全国教育评估理论和方法的研究，促进教育评估学术交流，组织教育评估骨干培训。"},{"i":20,"n":"第二十条","txt":"省（自治区、直辖市）普通高等学校教育评估领导小组在省（自治区、直辖市）的高校工委、教育行政部门和国家普通高等学校教育评估领导小组指导下，负责全省（自治区、直辖市）普通高等学校教育评估工作。其具体职责是：　　 （一）依据本规定和国家教育委员会有关文件，制订本地区的评估方案和实施细则； （二）指导、组织本地区所有普通高等学校的教育评估工作，接受国家教育委员会委托进行教育评估试点。 （三）审核、批准本地区有关高等学校思想政治教育、专业（学科）、课程及其他单项教育工作评估的结论； （四）收集、整理和分析本地区教育评估信息，负责向有关教育关利决策部门提供； （五）推动本地区教育评估理论和方法的研究，促进教育评估学术交流，组织教育评估骨干培训。"},{"i":21,"n":"第二十一条","txt":"国务院有关部门普通高等学校教育评估领导小组，在国务院有关部门教育行政部门和国家普通高等学校教育评估领导小组领导下，负责直属普通高等学校和国家教育委员会委托的对口专业（学科）的教育评估工作。其具体职责是： （一）依据本规定和国家教育委员会有关文件，制订本部门所属普通高等学校和国家教育委员会委托的对口专业（学科）的教育评估方案和实施细则； （二）领导和组织本部门直属普通高等学校的教育评估工作，审核、批准本部门直属普通高等学校教育评估的结论； （三）领导和组织国家教育委员会委托的对口专业（学科）教育评估，审核、提出对口专业（学科）教育评估结论，报国务院有关部门教育行政部门批准公布； （四）收集、整理、分析本部门和对口专业（学科）教育评估信息，负责向有关教育决策部门提供； （五）推动本部门和对口专业（学科）教育评估理论、方法的研究，促进教育评估学术交流，组织教育评估骨干培训。"},{"i":22,"n":"第二十二条","txt":"根据需要，在各级普通高等学校教育评估领导小组领导下，可设立新建普通高等学校鉴定委员会、普通高等学校专业（学科）教育评估委员会、普通高等学校课程教育评估委员会等专家组织，指导、组织新建普通高等学校的合格评估（鉴定）和专业（学科）、课程的办学水平评估工作。"},{"i":23,"n":"第二十三条","txt":"学校教育评估的一般程序是：学校提出申请；评估（鉴定）委员会审核申请；学校自评，写出自评报告；评估（鉴定）委员会派出视察小组到现场视察，写出视察报告，提出评估结论建议；评估（鉴定）委员会复核视察报告，提出正式评估结论；必要时报请有关教育行政部门和各级政府批准、公布评估结论。"},{"i":24,"n":"第二十四条","txt":"申请学校如对评估结论有不同意见，可在一个月内向上一级普通高等学校教育评估领导小组提出申诉，上一级教育评估领导小组应认真对待，进行仲裁，妥善处理。"},{"i":25,"n":"第二十五条","txt":"学校教育评估经费列入有关教育行政部门的年度预算，并鼓励社会资助；申请教育评估的学校也要承担一定的费用。"},{"i":26,"n":"第二十六条","txt":"本规定适用于普通高等学校。其他高等学校教育评估可参照实施。"},{"i":27,"n":"第二十七条","txt":"本规定由国家教育委员会负责解释。"},{"i":28,"n":"第二十八条","txt":"本规定自发布之日起施行。原发布的有关文件即行废止。"}],"putonggaodengxuexiaolishihuiguicheng":[{"i":1,"n":"第一条","txt":"为推进中国特色现代大学制度建设，健全高等学校内部治理结构，促进和规范高等学校理事会建设，增强高等学校与社会的联系、合作，根据《中华人民共和国高等教育法》及国家有关规定，制定本规程。"},{"i":2,"n":"第二条","txt":"本规程所称理事会，系指国家举办的普通高等学校（以下简称：高等学校）根据面向社会依法自主办学的需要，设立的由办学相关方面代表参加，支持学校发展的咨询、协商、审议与监督机构，是高等学校实现科学决策、民主监督、社会参与的重要组织形式和制度平台。 高等学校使用董事会、校务委员会等名称建立的相关机构适用本规程。"},{"i":3,"n":"第三条","txt":"高等学校应当依据本规程及学校章程建立并完善理事会制度，制定理事会章程，明确理事会在学校治理结构中的作用、职能，增强理事会的代表性和权威性，健全与理事会成员之间的协商、合作机制；为理事会及其成员了解和参与学校相关事务提供条件保障和工作便利。"},{"i":4,"n":"第四条","txt":"高等学校应当结合实际，在以下事项上充分发挥理事会的作用： （一）密切社会联系，提升社会服务能力，与相关方面建立长效合作机制； （二）扩大决策民主，保障与学校改革发展相关的重大事项，在决策前，能够充分听取相关方面意见； （三）争取社会支持，丰富社会参与和支持高校办学的方式与途径，探索、深化办学体制改革； （四）完善监督机制，健全社会对学校办学与管理活动的监督、评价机制，提升社会责任意识。"},{"i":5,"n":"第五条","txt":"理事会一般应包含以下方面的代表： （一）学校举办者、主管部门、共建单位的代表； （二）学校及职能部门相关负责人，相关学术组织负责人，教师、学生代表； （三）支持学校办学与发展的地方政府、行业组织、企业事业单位和其他社会组织等理事单位的代表； （四）杰出校友、社会知名人士、国内外知名专家等； （五）学校邀请的其他代表。 各方面代表在理事会所占的比例应当相对均衡，有利于理事会充分、有效地发挥作用。"},{"i":6,"n":"第六条","txt":"理事会组成人员一般不少于21人，可分为职务理事和个人理事。 职务理事由相关部门或者理事单位委派；理事单位和个人理事由学校指定机构推荐或者相关组织推选。学校主要领导和相关职能部门负责人可以确定为当然理事。 根据理事会组成规模及履行职能的需要和学校实际，可以设立常务理事、名誉理事等。"},{"i":7,"n":"第七条","txt":"理事会每届任期一般为5年，理事可以连任。 理事会可设理事长一名，副理事长若干名。理事长可以由学校提名，由理事会全体会议选举产生；也可以由学校举办者或者学校章程规定的其他方式产生。"},{"i":8,"n":"第八条","txt":"理事、名誉理事应当具有良好的社会声誉、在相关行业、领域具有广泛影响，积极关心、支持学校发展，有履行职责的能力和愿望。 理事、名誉理事不得以参加理事会及相关活动，获得薪酬或者其他物质利益；不得借职务便利获得不当利益。"},{"i":9,"n":"第九条","txt":"理事会主要履行以下职责： （一）审议通过理事会章程、章程修订案； （二）决定理事的增补或者退出； （三）就学校发展目标、战略规划、学科建设、专业设置、年度预决算报告、重大改革举措、学校章程拟定或者修订等重大问题进行决策咨询或者参与审议； （四）参与审议学校开展社会合作、校企合作、协同创新的整体方案及重要协议等，提出咨询建议，支持学校开展社会服务； （五）研究学校面向社会筹措资金、整合资源的目标、规划等，监督筹措资金的使用； （六）参与评议学校办学质量，就学校办学特色与教育质量进行评估，提出合理化建议或者意见； （七）学校章程规定或者学校委托的其他职能。"},{"i":10,"n":"第十条","txt":"理事会应当建立例会制度，每年至少召开一次全体会议；也可召开专题会议，或者设立若干专门小组负责相关具体事务。"},{"i":11,"n":"第十一条","txt":"理事会会议应遵循民主协商的原则，建立健全会议程序和议事规则，保障各方面代表能够就会议议题充分讨论、自主发表意见，并以协商或者表决等方式形成共识。"},{"i":12,"n":"第十二条","txt":"理事会可以设秘书处，负责安排理事会会议，联系理事会成员，处理理事会的日常事务等。 高等学校应当提供必要的经费保证理事会正常开展活动。"},{"i":13,"n":"第十三条","txt":"理事会组织、职责及运行的具体规则，会议制度，议事规则，理事的权利义务、产生办法等，应当通过理事会章程予以规定。 理事会章程经理事会全体会议批准后生效。"},{"i":14,"n":"第十四条","txt":"高等学校应当向社会公布理事会组成及其章程。 理事会应当主动公开相关信息及履行职责的情况，接受教职工、社会和高等学校主管部门的监督。"},{"i":15,"n":"第十五条","txt":"已设立理事会或相关机构的普通高等学校，其组成或者职责与本规程不一致的，应依据本规程予以调整。 高等职业学校可以参照本章程组建理事会，并可以按照法律和国家相关规定，进一步明确行业企业代表在理事会的地位与作用。 民办高等学校理事会或者董事会依据《民办教育促进法》组建并履行职责，不适用本规程；但可参照本规程，适当扩大理事会组成人员的代表性。"},{"i":16,"n":"第十六条","txt":"本规程自2014年9月1日起施行。"}],"putonggaodengxuexiaofudaoyuanduiwujiansheguiding":[{"i":1,"n":"第一条","txt":"为深入贯彻落实全国高校思想政治工作会议精神和《中共中央 国务院关于加强和改进新形势下高校思想政治工作的意见》，切实加强高等学校辅导员队伍专业化职业化建设，依据《高等教育法》等有关法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"辅导员是开展大学生思想政治教育的骨干力量，是高等学校学生日常思想政治教育和管理工作的组织者、实施者、指导者。辅导员应当努力成为学生成长成才的人生导师和健康生活的知心朋友。"},{"i":3,"n":"第三条","txt":"高等学校要坚持把立德树人作为中心环节，把辅导员队伍建设作为教师队伍和管理队伍建设的重要内容，整体规划、统筹安排，不断提高队伍的专业水平和职业能力，保证辅导员工作有条件、干事有平台、待遇有保障、发展有空间。"},{"i":4,"n":"第四条","txt":"辅导员工作的要求是：恪守爱国守法、敬业爱生、育人为本、终身学习、为人师表的职业守则；围绕学生、关照学生、服务学生，把握学生成长规律，不断提高学生思想水平、政治觉悟、道德品质、文化素养；引导学生正确认识世界和中国发展大势、正确认识中国特色和国际比较、正确认识时代责任和历史使命、正确认识远大抱负和脚踏实地，成为又红又专、德才兼备、全面发展的中国特色社会主义合格建设者和可靠接班人。"},{"i":5,"n":"第五条","txt":"辅导员的主要工作职责是： （一）思想理论教育和价值引领。引导学生深入学习习近平总书记系列重要讲话精神和治国理政新理念新思想新战略，深入开展中国特色社会主义、中国梦宣传教育和社会主义核心价值观教育，帮助学生不断坚定中国特色社会主义道路自信、理论自信、制度自信、文化自信，牢固树立正确的世界观、人生观、价值观。掌握学生思想行为特点及思想政治状况，有针对性地帮助学生处理好思想认识、价值取向、学习生活、择业交友等方面的具体问题。 （二）党团和班级建设。开展学生骨干的遴选、培养、激励工作，开展学生入党积极分子培养教育工作，开展学生党员发展和教育管理服务工作，指导学生党支部和班团组织建设。 （三）学风建设。熟悉了解学生所学专业的基本情况，激发学生学习兴趣，引导学生养成良好的学习习惯，掌握正确的学习方法。指导学生开展课外科技学术实践活动，营造浓厚学习氛围。 （四）学生日常事务管理。开展入学教育、毕业生"},{"i":6,"n":"第六条","txt":"高等学校应当按总体上师生比不低于1:200的比例设置专职辅导员岗位，按照专兼结合、以专为主的原则，足额配备到位。 专职辅导员是指在院（系）专职从事大学生日常思想政治教育工作的人员，包括院（系）党委（党总支）副书记、学工组长、团委（团总支）书记等专职工作人员，具有教师和管理人员双重身份。高等学校应参照专任教师聘任的待遇和保障，与专职辅导员建立人事聘用关系。 高等学校可以从优秀专任教师、管理人员、研究生中选聘一定数量兼职辅导员。兼职辅导员工作量按专职辅导员工作量的三分之一核定。"},{"i":7,"n":"第七条","txt":"辅导员应当符合以下基本条件： （一）具有较高的政治素质和坚定的理想信念，坚决贯彻执行党的基本路线和各项方针政策，有较强的政治敏感性和政治辨别力； （二）具备本科以上学历，热爱大学生思想政治教育事业，甘于奉献，潜心育人，具有强烈的事业心和责任感； （三）具有从事思想政治教育工作相关学科的宽口径知识储备，掌握思想政治教育工作相关学科的基本原理和基础知识，掌握思想政治教育专业基本理论、知识和方法，掌握马克思主义中国化相关理论和知识，掌握大学生思想政治教育工作实务相关知识，掌握有关法律法规知识； （四）具备较强的组织管理能力和语言、文字表达能力，及教育引导能力、调查研究能力，具备开展思想理论教育和价值引领工作的能力； （五）具有较强的纪律观念和规矩意识，遵纪守法，为人正直，作风正派，廉洁自律。"},{"i":8,"n":"第八条","txt":"辅导员选聘工作要在高等学校党委统一领导下进行，由学生工作部门、组织、人事、纪检等相关部门共同组织开展。根据辅导员基本条件要求和实际岗位需要，确定具体选拔条件，通过组织推荐和公开招聘相结合的方式，经过笔试、面试、公示等相关程序进行选拔。"},{"i":9,"n":"第九条","txt":"青年教师晋升高一级专业技术职务（职称），须有至少一年担任辅导员或班主任工作经历并考核合格。高等学校要鼓励新入职教师以多种形式参与辅导员或班主任工作。"},{"i":10,"n":"第十条","txt":"高等学校应当制定专门办法和激励保障机制，落实专职辅导员职务职级“双线”晋升要求，推动辅导员队伍专业化职业化建设。"},{"i":11,"n":"第十一条","txt":"高等学校应当结合实际，按专任教师职务岗位结构比例合理设置专职辅导员的相应教师职务岗位，专职辅导员可按教师职务（职称）要求评聘思想政治教育学科或其他相关学科的专业技术职务（职称）。 专职辅导员专业技术职务（职称）评聘应更加注重考察工作业绩和育人实效，单列计划、单设标准、单独评审。将优秀网络文化成果纳入专职辅导员的科研成果统计、职务（职称）评聘范围。"},{"i":12,"n":"第十二条","txt":"高等学校可以成立专职辅导员专业技术职务（职称）聘任委员会，具体负责本校专职辅导员专业技术职务（职称）聘任工作。聘任委员会一般应由学校党委有关负责人、学生工作、组织人事、教学科研部门负责人、相关学科专家等人员组成。"},{"i":13,"n":"第十三条","txt":"高等学校应当制定辅导员管理岗位聘任办法，根据辅导员的任职年限及实际工作表现，确定相应级别的管理岗位等级。"},{"i":14,"n":"第十四条","txt":"辅导员培训应当纳入高等学校师资队伍和干部队伍培训整体规划。 建立国家、省级和高等学校三级辅导员培训体系。教育部设立高等学校辅导员培训和研修基地，开展国家级示范培训。省级教育部门应当根据区域内现有高等学校辅导员规模数量设立辅导员培训专项经费，建立辅导员培训和研修基地，承担所在区域内高等学校辅导员的岗前培训、日常培训和骨干培训。高等学校负责对本校辅导员的系统培训，确保每名专职辅导员每年参加不少于16个学时的校级培训，每5年参加1次国家级或省级培训。"},{"i":15,"n":"第十五条","txt":"省级教育部门、高等学校要积极选拔优秀辅导员参加国内国际交流学习和研修深造，创造条件支持辅导员到地方党政机关、企业、基层等挂职锻炼，支持辅导员结合大学生思想政治教育的工作实践和思想政治教育学科的发展开展研究。高等学校要鼓励辅导员在做好工作的基础上攻读相关专业学位，承担思想政治理论课等相关课程的教学工作，为辅导员提升专业水平和科研能力提供条件保障。"},{"i":16,"n":"第十六条","txt":"高等学校要积极为辅导员的工作和生活创造便利条件，应根据辅导员的工作特点，在岗位津贴、办公条件、通讯经费等方面制定相关政策，为辅导员的工作和生活提供必要保障。"},{"i":17,"n":"第十七条","txt":"高等学校辅导员实行学校和院（系）双重管理。 学生工作部门牵头负责辅导员的培养、培训和考核等工作，同时要与院（系）党委（党总支）共同做好辅导员日常管理工作。院（系）党委（党总支）负责对辅导员进行直接领导和管理。"},{"i":18,"n":"第十八条","txt":"高等学校要根据辅导员职业能力标准，制定辅导员工作考核的具体办法，健全辅导员队伍的考核评价体系。对辅导员的考核评价应由学生工作部门牵头，组织人事部门、院（系）党委（党总支）和学生共同参与。考核结果与辅导员的职务聘任、奖惩、晋级等挂钩。"},{"i":19,"n":"第十九条","txt":"教育部在全国教育系统先进集体和先进个人表彰中对高校优秀辅导员进行表彰。各地教育部门和高等学校要结合实际情况建立辅导员单独表彰体系并将优秀辅导员表彰奖励纳入各级教师、教育工作者表彰奖励体系中。"},{"i":20,"n":"第二十条","txt":"本规定适用于普通高等学校辅导员队伍建设。其他类型高等学校的辅导员队伍建设或思想政治工作其他队伍建设可以参照本规定执行。"},{"i":21,"n":"第二十一条","txt":"高等学校要根据本规定，结合实际制定相关实施细则，并报主管教育部门备案。"},{"i":22,"n":"第二十二条","txt":"本规定自2017年10月1日起施行。原《普通高等学校辅导员队伍建设规定》同时废止。"}],"weichengnianrenxuexiaobaohuguiding":[{"i":1,"n":"第一条","txt":"为了落实学校保护职责，保障未成年人合法权益，促进未成年人德智体美劳全面发展、健康成长，根据《中华人民共和国教育法》《中华人民共和国未成年人保护法》等法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"普通中小学、中等职业学校（以下简称学校）对本校未成年人（以下统称学生）在校学习、生活期间合法权益的保护，适用本规定。"},{"i":3,"n":"第三条","txt":"学校应当全面贯彻国家教育方针，落实立德树人根本任务，弘扬社会主义核心价值观，依法办学、依法治校，履行学生权益保护法定职责，健全保护制度，完善保护机制。"},{"i":4,"n":"第四条","txt":"学校学生保护工作应当坚持最有利于未成年人的原则，注重保护和教育相结合，适应学生身心健康发展的规律和特点；关心爱护每个学生，尊重学生权利，听取学生意见。"},{"i":5,"n":"第五条","txt":"教育行政部门应当落实工作职责，会同有关部门健全学校学生保护的支持措施、服务体系，加强对学校学生保护工作的支持、指导、监督和评价。"},{"i":6,"n":"第六条","txt":"学校应当平等对待每个学生，不得因学生及其父母或者其他监护人（以下统称家长）的民族、种族、性别、户籍、职业、宗教信仰、教育程度、家庭状况、身心健康情况等歧视学生或者对学生进行区别对待。"},{"i":7,"n":"第七条","txt":"学校应当落实安全管理职责，保护学生在校期间人身安全。学校不得组织、安排学生从事抢险救灾、参与危险性工作，不得安排学生参加商业性活动及其他不宜学生参加的活动。 学生在校内或者本校组织的校外活动中发生人身伤害事故的，学校应当依据有关规定妥善处理，及时通知学生家长；情形严重的，应当按规定向有关部门报告。"},{"i":8,"n":"第八条","txt":"学校不得设置侵犯学生人身自由的管理措施，不得对学生在课间及其他非教学时间的正当交流、游戏、出教室活动等言行自由设置不必要的约束。"},{"i":9,"n":"第九条","txt":"学校应当尊重和保护学生的人格尊严，尊重学生名誉，保护和培育学生的荣誉感、责任感，表彰、奖励学生做到公开、公平、公正；在教育、管理中不得使用任何贬损、侮辱学生及其家长或者所属特定群体的言行、方式。"},{"i":10,"n":"第十条","txt":"学校采集学生个人信息，应当告知学生及其家长，并对所获得的学生及其家庭信息负有管理、保密义务，不得毁弃以及非法删除、泄露、公开、买卖。 学校在奖励、资助、申请贫困救助等工作中，不得泄露学生个人及其家庭隐私；学生的考试成绩、名次等学业信息，学校应当便利学生本人和家长知晓，但不得公开，不得宣传升学情况；除因法定事由，不得查阅学生的信件、日记、电子邮件或者其他网络通讯内容。"},{"i":11,"n":"第十一条","txt":"学校应当尊重和保护学生的受教育权利，保障学生平等使用教育教学设施设备、参加教育教学计划安排的各种活动，并在学业成绩和品行上获得公正评价。 对身心有障碍的学生，应当提供合理便利，实施融合教育，给予特别支持；对学习困难、行为异常的学生，应当以适当方式教育、帮助，必要时，可以通过安排教师或者专业人员课后辅导等方式给予帮助或者支持。 学校应当建立留守学生、困境学生档案，配合政府有关部门做好关爱帮扶工作，避免学生因家庭因素失学、辍学。"},{"i":12,"n":"第十二条","txt":"义务教育学校不得开除或者变相开除学生，不得以长期停课、劝退等方式，剥夺学生在校接受并完成义务教育的权利；对转入专门学校的学生，应当保留学籍，原决定机关决定转回的学生，不得拒绝接收。 义务教育学校应当落实学籍管理制度，健全辍学或者休学、长期请假学生的报告备案制度，对辍学学生应当及时进行劝返，劝返无效的，应当报告有关主管部门。"},{"i":13,"n":"第十三条","txt":"学校应当按规定科学合理安排学生在校作息时间，保证学生有休息、参加文娱活动和体育锻炼的机会和时间，不得统一要求学生在规定的上课时间前到校参加课程教学活动。 义务教育学校不得占用国家法定节假日、休息日及寒暑假，组织学生集体补课；不得以集体补课等形式侵占学生休息时间。"},{"i":14,"n":"第十四条","txt":"学校不得采用毁坏财物的方式对学生进行教育管理，对学生携带进入校园的违法违规物品，按规定予以暂扣的，应当统一管理，并依照有关规定予以处理。 学校不得违反规定向学生收费，不得强制要求或者设置条件要求学生及家长捐款捐物、购买商品或者服务，或者要求家长提供物质帮助、需支付费用的服务等。"},{"i":15,"n":"第十五条","txt":"学校以发布、汇编、出版等方式使用学生作品，对外宣传或者公开使用学生个体肖像的，应当取得学生及其家长许可，并依法保护学生的权利。"},{"i":16,"n":"第十六条","txt":"学校应当尊重学生的参与权和表达权，指导、支持学生参与学校章程、校规校纪、班级公约的制定，处理与学生权益相关的事务时，应当以适当方式听取学生意见。"},{"i":17,"n":"第十七条","txt":"学校对学生实施教育惩戒或者处分学生的，应当依据有关规定，听取学生的陈述、申辩，遵循审慎、公平、公正的原则作出决定。 除开除学籍处分以外，处分学生应当设置期限，对受到处分的学生应当跟踪观察、有针对性地实施教育，确有改正的，到期应当予以解除。解除处分后，学生获得表彰、奖励及其他权益，不再受原处分影响。"},{"i":18,"n":"第十八条","txt":"学校应当落实法律规定建立学生欺凌防控和预防性侵害、性骚扰等专项制度，建立对学生欺凌、性侵害、性骚扰行为的零容忍处理机制和受伤害学生的关爱、帮扶机制。"},{"i":19,"n":"第十九条","txt":"学校应当成立由校内相关人员、法治副校长、法律顾问、有关专家、家长代表、学生代表等参与的学生欺凌治理组织，负责学生欺凌行为的预防和宣传教育、组织认定、实施矫治、提供援助等。 学校应当定期针对全体学生开展防治欺凌专项调查，对学校是否存在欺凌等情形进行评估。"},{"i":20,"n":"第二十条","txt":"学校应当教育、引导学生建立平等、友善、互助的同学关系，组织教职工学习预防、处理学生欺凌的相关政策、措施和方法，对学生开展相应的专题教育，并且应当根据情况给予相关学生家长必要的家庭教育指导。"},{"i":21,"n":"第二十一条","txt":"教职工发现学生实施下列行为的，应当及时制止： （一）殴打、脚踢、掌掴、抓咬、推撞、拉扯等侵犯他人身体或者恐吓威胁他人； （二）以辱骂、讥讽、嘲弄、挖苦、起侮辱性绰号等方式侵犯他人人格尊严； （三）抢夺、强拿硬要或者故意毁坏他人财物； （四）恶意排斥、孤立他人，影响他人参加学校活动或者社会交往； （五）通过网络或者其他信息传播方式捏造事实诽谤他人、散布谣言或者错误信息诋毁他人、恶意传播他人隐私。 学生之间，在年龄、身体或者人数等方面占优势的一方蓄意或者恶意对另一方实施前款行为，或者以其他方式欺压、侮辱另一方，造成人身伤害、财产损失或者精神损害的，可以认定为构成欺凌。"},{"i":22,"n":"第二十二条","txt":"教职工应当关注因身体条件、家庭背景或者学习成绩等可能处于弱势或者特殊地位的学生，发现学生存在被孤立、排挤等情形的，应当及时干预。 教职工发现学生有明显的情绪反常、身体损伤等情形，应当及时沟通了解情况，可能存在被欺凌情形的，应当及时向学校报告。 学校应当教育、支持学生主动、及时报告所发现的欺凌情形，保护自身和他人的合法权益。"},{"i":23,"n":"第二十三条","txt":"学校接到关于学生欺凌报告的，应当立即开展调查，认为可能构成欺凌的，应当及时提交学生欺凌治理组织认定和处置，并通知相关学生的家长参与欺凌行为的认定和处理。认定构成欺凌的，应当对实施或者参与欺凌行为的学生作出教育惩戒或者纪律处分，并对其家长提出加强管教的要求，必要时，可以由法治副校长、辅导员对学生及其家长进行训导、教育。 对违反治安管理或者涉嫌犯罪等严重欺凌行为，学校不得隐瞒，应当及时向公安机关、教育行政部门报告，并配合相关部门依法处理。 不同学校学生之间发生的学生欺凌事件，应当在主管教育行政部门的指导下建立联合调查机制，进行认定和处理。"},{"i":24,"n":"第二十四条","txt":"学校应当建立健全教职工与学生交往行为准则、学生宿舍安全管理规定、视频监控管理规定等制度，建立预防、报告、处置性侵害、性骚扰工作机制。 学校应当采取必要措施预防并制止教职工以及其他进入校园的人员实施以下行为： （一）与学生发生恋爱关系、性关系； （二）抚摸、故意触碰学生身体特定部位等猥亵行为； （三）对学生作出调戏、挑逗或者具有性暗示的言行； （四）向学生展示传播包含色情、淫秽内容的信息、书刊、影片、音像、图片或者其他淫秽物品； （五）持有包含淫秽、色情内容的视听、图文资料； （六）其他构成性骚扰、性侵害的违法犯罪行为。"},{"i":25,"n":"第二十五条","txt":"学校应当制定规范教职工、学生行为的校规校纪。校规校纪应当内容合法、合理，制定程序完备，向学生及其家长公开，并按照要求报学校主管部门备案。"},{"i":26,"n":"第二十六条","txt":"学校应当严格执行国家课程方案，按照要求开齐开足课程、选用教材和教学辅助资料。学校开发的校本课程或者引进的课程应当经过科学论证，并报主管教育行政部门备案。 学校不得与校外培训机构合作向学生提供有偿的课程或者课程辅导。"},{"i":27,"n":"第二十七条","txt":"学校应当加强作业管理，指导和监督教师按照规定科学适度布置家庭作业，不得超出规定增加作业量，加重学生学习负担。"},{"i":28,"n":"第二十八条","txt":"学校应当按照规定设置图书馆、班级图书角，配备适合学生认知特点、内容积极向上的课外读物，营造良好阅读环境，培养学生阅读习惯，提升阅读质量。 学校应当加强读物和校园文化环境管理，禁止含有淫秽、色情、暴力、邪教、迷信、赌博、恐怖主义、分裂主义、极端主义等危害未成年人身心健康内容的读物、图片、视听作品等，以及商业广告、有悖于社会主义核心价值观的文化现象进入校园。"},{"i":29,"n":"第二十九条","txt":"学校应当建立健全安全风险防控体系，按照有关规定完善安全、卫生、食品等管理制度，提供符合标准的教育教学设施、设备等，制定自然灾害、突发事件、极端天气和意外伤害应急预案，配备相应设施并定期组织必要的演练。 学生在校期间学校应当对校园实行封闭管理，禁止无关人员进入校园。"},{"i":30,"n":"第三十条","txt":"学校应当以适当方式教育、提醒学生及家长，避免学生使用兴奋剂或者镇静催眠药、镇痛剂等成瘾性药物；发现学生使用的，应当予以制止、向主管部门或者公安机关报告，并应当及时通知家长，但学生因治疗需要并经执业医师诊断同意使用的除外。"},{"i":31,"n":"第三十一条","txt":"学校应当建立学生体质监测制度，发现学生出现营养不良、近视、肥胖、龋齿等倾向或者有导致体质下降的不良行为习惯，应当进行必要的管理、干预，并通知家长，督促、指导家长实施矫治。 学校应当完善管理制度，保障学生在课间、课后使用学校的体育运动场地、设施开展体育锻炼；在周末和节假日期间，按规定向学生和周边未成年人免费或者优惠开放。"},{"i":32,"n":"第三十二条","txt":"学校应当建立学生心理健康教育管理制度，建立学生心理健康问题的早期发现和及时干预机制，按照规定配备专职或者兼职心理健康教育教师、建设心理辅导室，或者通过购买专业社工服务等多种方式为学生提供专业化、个性化的指导和服务。 有条件的学校，可以定期组织教职工进行心理健康状况测评，指导、帮助教职工以积极、乐观的心态对待学生。"},{"i":33,"n":"第三十三条","txt":"学校可以禁止学生携带手机等智能终端产品进入学校或者在校园内使用；对经允许带入的，应当统一管理，除教学需要外，禁止带入课堂。"},{"i":34,"n":"第三十四条","txt":"学校应当将科学、文明、安全、合理使用网络纳入课程内容，对学生进行网络安全、网络文明和防止沉迷网络的教育，预防和干预学生过度使用网络。 学校为学生提供的上网设施，应当安装未成年人上网保护软件或者采取其他安全保护技术措施，避免学生接触不适宜未成年人接触的信息；发现网络产品、服务、信息有危害学生身心健康内容的，或者学生利用网络实施违法活动的，应当立即采取措施并向有关主管部门报告。"},{"i":35,"n":"第三十五条","txt":"任何人不得在校园内吸烟、饮酒。学校应当设置明显的禁止吸烟、饮酒的标识，并不得以烟草制品、酒精饮料的品牌冠名学校、教学楼、设施设备及各类教学、竞赛活动。"},{"i":36,"n":"第三十六条","txt":"学校应当严格执行入职报告和准入查询制度，不得聘用有下列情形的人员： （一）受到剥夺政治权利或者因故意犯罪受到有期徒刑以上刑事处罚的； （二）因卖淫、嫖娼、吸毒、赌博等违法行为受到治安管理处罚的； （三）因虐待、性骚扰、体罚或者侮辱学生等情形被开除或者解聘的； （四）实施其他被纳入教育领域从业禁止范围的行为的。 学校在聘用教职工或引入志愿者、社工等校外人员时，应当要求相关人员提交承诺书；对在聘人员应当按照规定定期开展核查，发现存在前款规定情形的人员应当及时解聘。"},{"i":37,"n":"第三十七条","txt":"学校发现拟聘人员或者在职教职工存在下列情形的，应当对有关人员是否符合相应岗位要求进行评估，必要时可以安排有专业资质的第三方机构进行评估，并将相关结论作为是否聘用或者调整工作岗位、解聘的依据： （一）有精神病史的； （二）有严重酗酒、滥用精神类药物史的； （三）有其他可能危害未成年人身心健康或者可能造成不良影响的身心疾病的。"},{"i":38,"n":"第三十八条","txt":"学校应当加强对教职工的管理，预防和制止教职工实施法律、法规、规章以及师德规范禁止的行为。学校及教职工不得实施下列行为： （一）利用管理学生的职务便利或者招生考试、评奖评优、推荐评价等机会，以任何形式向学生及其家长索取、收受财物或者接受宴请、其他利益； （二）以牟取利益为目的，向学生推销或者要求、指定学生购买特定辅导书、练习册等教辅材料或者其他商品、服务； （三）组织、要求学生参加校外有偿补课，或者与校外机构、个人合作向学生提供其他有偿服务； （四）诱导、组织或者要求学生及其家长登录特定经营性网站，参与视频直播、网络购物、网络投票、刷票等活动； （五）非法提供、泄露学生信息或者利用所掌握的学生信息牟取利益； （六）其他利用管理学生的职权牟取不正当利益的行为。"},{"i":39,"n":"第三十九条","txt":"学校根据《校车安全管理条例》配备、使用校车的，应当依法建立健全校车安全管理制度，向学生讲解校车安全乘坐知识，培养学生校车安全事故应急处理技能。"},{"i":40,"n":"第四十条","txt":"学校应当定期巡查校园及周边环境，发现存在法律禁止在学校周边设立的营业场所、销售网点的，应当及时采取应对措施，并报告主管教育部门或者其他有关主管部门。 学校及其教职工不得安排或者诱导、组织学生进入营业性娱乐场所、互联网上网服务营业场所、电子游戏场所、酒吧等不适宜未成年人活动的场所；发现学生进入上述场所的，应当及时予以制止、教育，并向上述场所的主管部门反映。"},{"i":41,"n":"第四十一条","txt":"校长是学生学校保护的第一责任人。学校应当指定一名校领导直接负责学生保护工作，并明确具体的工作机构，有条件的，可以设立学生保护专员开展学生保护工作。学校应当为从事学生保护工作的人员接受相关法律、理论和技能的培训提供条件和支持，对教职工开展未成年人保护专项培训。 有条件的学校可以整合欺凌防治、纪律处分等组织、工作机制，组建学生保护委员会，统筹负责学生权益保护及相关制度建设。"},{"i":42,"n":"第四十二条","txt":"学校要树立以生命关怀为核心的教育理念，利用安全教育、心理健康教育、环境保护教育、健康教育、禁毒和预防艾滋病教育等专题教育，引导学生热爱生命、尊重生命；要有针对性地开展青春期教育、性教育，使学生了解生理健康知识，提高防范性侵害、性骚扰的自我保护意识和能力。"},{"i":43,"n":"第四十三条","txt":"学校应当结合相关课程要求，根据学生的身心特点和成长需求开展以宪法教育为核心、以权利与义务教育为重点的法治教育，培养学生树立正确的权利观念，并开展有针对性的预防犯罪教育。"},{"i":44,"n":"第四十四条","txt":"学校可以根据实际组成由学校相关负责人、教师、法治副校长（辅导员）、司法和心理等方面专业人员参加的专业辅导工作机制，对有不良行为的学生进行矫治和帮扶；对有严重不良行为的学生，学校应当配合有关部门进行管教，无力管教或者管教无效的，可以依法向教育行政部门提出申请送专门学校接受专门教育。"},{"i":45,"n":"第四十五条","txt":"学校在作出与学生权益有关的决定前，应当告知学生及其家长，听取意见并酌情采纳。 学校应当发挥学生会、少代会、共青团等学生组织的作用，指导、支持学生参与权益保护，对于情节轻微的学生纠纷或者其他侵害学生权益的情形，可以安排学生代表参与调解。"},{"i":46,"n":"第四十六条","txt":"学校应当建立与家长有效联系机制，利用家访、家长课堂、家长会等多种方式与学生家长建立日常沟通。 学校应当建立学生重大生理、心理疾病报告制度，向家长及时告知学生身体及心理健康状况；学校发现学生身体状况或者情绪反应明显异常、突发疾病或者受到伤害的，应当及时通知学生家长。"},{"i":47,"n":"第四十七条","txt":"学校和教职工发现学生遭受或疑似遭受家庭暴力、虐待、遗弃、长期无人照料、失踪等不法侵害以及面临不法侵害危险的，应当依照规定及时向公安、民政、教育等有关部门报告。学校应当积极参与、配合有关部门做好侵害学生权利案件的调查处理工作。"},{"i":48,"n":"第四十八条","txt":"教职员工发现学生权益受到侵害，属于本职工作范围的，应当及时处理；不属于本职工作范围或者不能处理的，应当及时报告班主任或学校负责人；必要时可以直接向主管教育行政部门或者公安机关报告。"},{"i":49,"n":"第四十九条","txt":"学生因遭受遗弃、虐待向学校请求保护的，学校不得拒绝、推诿，需要采取救助措施的，应当先行救助。 学校应当关心爱护学生，为身体或者心理受到伤害的学生提供相应的心理健康辅导、帮扶教育。对因欺凌造成身体或者心理伤害，无法在原班级就读的学生，学生家长提出调整班级请求，学校经评估认为有必要的，应当予以支持。"},{"i":50,"n":"第五十条","txt":"教育行政部门应当积极探索与人民检察院、人民法院、公安、司法、民政、应急管理等部门以及从事未成年人保护工作的相关群团组织的协同机制，加强对学校学生保护工作的指导与监督。"},{"i":51,"n":"第五十一条","txt":"教育行政部门应当会同有关部门健全教职工从业禁止人员名单和查询机制，指导、监督学校健全准入和定期查询制度。"},{"i":52,"n":"第五十二条","txt":"教育行政部门可以通过政府购买服务的方式，组织具有相应资质的社会组织、专业机构及其他社会力量，为学校提供法律咨询、心理辅导、行为矫正等专业服务，为预防和处理学生权益受侵害的案件提供支持。 教育行政部门、学校在与有关部门、机构、社会组织及个人合作进行学生保护专业服务与支持过程中，应当与相关人员签订保密协议，保护学生个人及家庭隐私。"},{"i":53,"n":"第五十三条","txt":"教育行政部门应当指定专门机构或者人员承担学生保护的监督职责，有条件的，可以设立学生保护专兼职监察员负责学生保护工作，处理或者指导处理学生欺凌、性侵害、性骚扰以及其他侵害学生权益的事件，会同有关部门落实学校安全区域制度，健全依法处理涉校纠纷的工作机制。 负责学生保护职责的人员应当接受专门业务培训，具备学生保护的必要知识与能力。"},{"i":54,"n":"第五十四条","txt":"教育行政部门应当通过建立投诉举报电话、邮箱或其他途径，受理对学校或者教职工违反本规定或者其他法律法规、侵害学生权利的投诉、举报；处理过程中发现有关人员行为涉嫌违法犯罪的，应当及时向公安机关报案或者移送司法机关。"},{"i":55,"n":"第五十五条","txt":"县级教育行政部门应当会同民政部门，推动设立未成年人保护社会组织，协助受理涉及学生权益的投诉举报、开展侵害学生权益案件的调查和处理，指导、支持学校、教职工、家长开展学生保护工作。"},{"i":56,"n":"第五十六条","txt":"地方教育行政部门应当建立学生保护工作评估制度，定期组织或者委托第三方对管辖区域内学校履行保护学生法定职责情况进行评估，评估结果作为学校管理水平评价、校长考评考核的依据。 各级教育督导机构应当将学校学生保护工作情况纳入政府履行教育职责评价和学校督导评估的内容。"},{"i":57,"n":"第五十七条","txt":"学校未履行未成年人保护法规定的职责，违反本规定侵犯学生合法权利的，主管教育行政部门应当责令改正，并视情节和后果，依照有关规定和权限分别对学校的主要负责人、直接责任人或者其他责任人员进行诫勉谈话、通报批评、给予处分或者责令学校给予处分；同时，可以给予学校1至3年不得参与相应评奖评优，不得获评各类示范、标兵单位等荣誉的处理。"},{"i":58,"n":"第五十八条","txt":"学校未履行对教职工的管理、监督责任，致使发生教职工严重侵害学生身心健康的违法犯罪行为，或者有包庇、隐瞒不报，威胁、阻拦报案，妨碍调查、对学生打击报复等行为的，主管教育部门应当对主要负责人和直接责任人给予处分或者责令学校给予处分；情节严重的，应当移送有关部门查处，构成违法犯罪的，依法追究相应法律责任。因监管不力、造成严重后果而承担领导责任的校长，5年内不得再担任校长职务。"},{"i":59,"n":"第五十九条","txt":"学校未按本规定建立学生权利保护机制，或者制定的校规违反法律法规和本规定，由主管教育部门责令限期改正、给予通报批评；情节严重、影响较大或者逾期不改正的，可以对学校主要负责人和直接负责人给予处分或者责令学校给予处分。"},{"i":60,"n":"第六十条","txt":"教职工违反本规定的，由学校或者主管教育部门依照事业单位人员管理、中小学教师管理的规定予以处理。 教职工实施第二十四条第二款禁止行为的，应当依法予以开除或者解聘；有教师资格的，由主管教育行政部门撤销教师资格，纳入从业禁止人员名单；涉嫌犯罪的，移送有关部门依法追究责任。 教职工违反第三十八条规定牟取不当利益的，应当责令退还所收费用或者所获利益，给学生造成经济损失的，应当依法予以赔偿，并视情节给予处分，涉嫌违法犯罪的移送有关部门依法追究责任。 学校应当根据实际，建立健全校内其他工作人员聘用和管理制度，对其他人员违反本规定的，根据情节轻重予以校内纪律处分直至予以解聘，涉嫌违反治安管理或者犯罪的，移送有关部门依法追究责任。"},{"i":61,"n":"第六十一条","txt":"教育行政部门未履行对学校的指导、监督职责，管辖区域内学校出现严重侵害学生权益情形的，由上级教育行政部门、教育督导机构责令改正、予以通报批评，情节严重的依法追究主要负责人或者直接责任人的责任。"},{"i":62,"n":"第六十二条","txt":"幼儿园、特殊教育学校应当根据未成年人身心特点，依据本规定有针对性地加强在园、在校未成年人合法权益的保护，并参照本规定、结合实际建立保护制度。 幼儿园、特殊教育学校及其教职工违反保护职责，侵害在园、在校未成年人合法权益的，应当适用本规定从重处理。"},{"i":63,"n":"第六十三条","txt":"本规定自2021年9月1日起施行。"}],"xiaowaipeixunxingzhengchufazanxingbanfa":[{"i":1,"n":"第一条","txt":"为落实立德树人根本任务，发展素质教育，加强校外培训监管，规范校外培训行政处罚行为，保护自然人、法人和其他组织的合法权益，根据《中华人民共和国行政处罚法》《中华人民共和国未成年人保护法》《中华人民共和国民办教育促进法》《中华人民共和国民办教育促进法实施条例》等有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"自然人、法人或者其他组织面向社会招收3周岁以上学龄前儿童、中小学生，违法开展校外培训，应当给予行政处罚的，适用本办法。"},{"i":3,"n":"第三条","txt":"实施校外培训行政处罚，应当遵循公正、公开的原则，坚持处罚与教育相结合、宽严相济，做到事实清楚、证据确凿、依据正确、程序合法、处罚适当。"},{"i":4,"n":"第四条","txt":"对实施行政处罚过程中知悉的国家秘密、商业秘密和个人隐私，应当依法予以保密；为履行法定职责处理个人信息，应当依照法律、法规规定的权限、程序进行，不得超出履行法定职责所必需的范围和限度。"},{"i":5,"n":"第五条","txt":"校外培训行政处罚的种类包括： （一）警告、通报批评； （二）罚款、没收违法所得、没收非法财物； （三）责令停止招收学员； （四）责令停止举办； （五）吊销许可证件； （六）限制从业； （七）法律、行政法规规定的其他行政处罚。"},{"i":6,"n":"第六条","txt":"校外培训行政处罚由县级以上人民政府校外培训主管部门依法按照行政处罚权限实施。校外培训主管部门由省级人民政府根据国家有关规定确定。 校外培训行政处罚由综合行政执法部门实施的，校外培训主管部门应当与综合行政执法部门建立行政执法信息互联互通、执法过程协作配合、执法结果及时反馈的工作机制。 校外培训行政处罚由乡镇人民政府、街道办事处实施的，县级校外培训主管部门应当加强对乡镇街道校外培训行政处罚工作的组织协调、业务指导、执法监督。"},{"i":7,"n":"第七条","txt":"校外培训主管部门可以在法定权限内书面委托符合行政处罚法规定条件的组织实施行政处罚。 委托书应当载明委托的具体事项、权限、期限等内容，并应当将委托书向社会公布。 委托行政机关应当对受委托组织实施行政处罚的行为进行监督，并对该行为的后果承担法律责任。 受委托组织在委托范围内，以委托行政机关的名义实施行政处罚；不得再委托其他任何组织或者个人实施行政处罚。"},{"i":8,"n":"第八条","txt":"对线下校外培训违法行为的行政处罚，由违法行为发生地县级人民政府校外培训主管部门管辖。违法行为发生地与机构审批地不一致的，机构审批地有关部门应当依法予以协助。"},{"i":9,"n":"第九条","txt":"对经审批的线上校外培训机构违法行为的行政处罚，由机构审批机关管辖；对未经审批进行线上校外培训活动的行政处罚，由违法主体所在地省级人民政府校外培训主管部门管辖。 违法行为发生地省级人民政府校外培训主管部门先行发现线上校外培训违法线索或者收到投诉、举报的，也可以进行管辖，机构审批地或者违法主体所在地校外培训主管部门应当依法予以协助。"},{"i":10,"n":"第十条","txt":"两个以上校外培训主管部门对同一个校外培训违法行为都有管辖权的，由最先立案的校外培训主管部门管辖。 对管辖发生争议的，应当协商解决，协商不成的，报请共同的上一级校外培训主管部门或者同级人民政府指定管辖；也可以直接由共同的上一级校外培训主管部门指定管辖。 校外培训主管部门发现立案查处的案件不属于本部门管辖的，应当将案件移送有管辖权的校外培训主管部门。受移送的校外培训主管部门对管辖权有异议的，应当报请共同的上一级校外培训主管部门或者同级人民政府指定管辖，不得再自行移送。"},{"i":11,"n":"第十一条","txt":"上级人民政府校外培训主管部门有权直接查处下级部门管辖的校外培训违法案件。 上级人民政府校外培训主管部门可以将某个下级部门管辖的校外培训违法案件指定其他下级人民政府校外培训主管部门管辖。"},{"i":12,"n":"第十二条","txt":"地方各级人民政府校外培训主管部门发现校外培训违法行为涉嫌违反治安管理、出入境管理等法律法规的，应当及时移送公安机关予以处罚；涉嫌犯罪的，应当及时按照有关规定移送司法机关，依法追究刑事责任。"},{"i":13,"n":"第十三条","txt":"对当事人的同一个校外培训违法行为，不得给予两次以上罚款的行政处罚。 同一个校外培训违法行为违反多个法律规范，应当给予罚款处罚的，按照罚款数额高的规定处罚。"},{"i":14,"n":"第十四条","txt":"当事人有下列情形之一，应当从轻或者减轻行政处罚： （一）主动消除或者减轻违法行为危害后果的； （二）受他人胁迫或者诱骗实施违法行为的； （三）主动供述校外培训主管部门尚未掌握的违法行为的； （四）配合校外培训主管部门查处违法行为有立功表现的； （五）法律、法规、规章规定其他应当从轻或者减轻行政处罚的。"},{"i":15,"n":"第十五条","txt":"当事人有下列情形之一的，不予处罚，但应当对其进行教育： （一）校外培训违法行为轻微并及时改正，没有造成危害后果的； （二）当事人有证据足以证明没有主观过错的； （三）违法行为已经超过给予行政处罚的法定期限的； （四）法律、法规、规章规定的其他不予处罚情形。 初次违法且危害后果轻微并及时改正的，可以不予处罚。"},{"i":16,"n":"第十六条","txt":"当事人有下列情形之一，应当依法从重处罚： （一）实施校外培训违法行为被处理后两年内再次实施校外培训违法行为的； （二）危害后果严重，造成严重恶劣社会影响的； （三）同时违反突发事件应对措施的； （四）伪造、涂改或者转移、销毁证据的； （五）拒绝、阻碍或者以暴力威胁行政执法人员执法的； （六）属于中小学在职教师且培训内容为学科类校外培训的； （七）法律、法规、规章规定其他应当从重处罚的。"},{"i":17,"n":"第十七条","txt":"自然人、法人或者其他组织未经审批开展校外培训，同时符合下列条件的，构成擅自举办校外培训机构，由所在地县级人民政府校外培训主管部门会同同级公安、民政或者市场监督管理等有关部门责令停止举办、退还所收费用，并对举办者处违法所得一倍以上五倍以下罚款： （一）线下培训有专门的培训场所，线上培训有特定的网站或者应用程序； （二）有2名以上培训从业人员； （三）有相应的组织机构和分工。"},{"i":18,"n":"第十八条","txt":"自然人、法人或者其他组织变相开展学科类校外培训，尚不符合本办法第十七条规定条件，有下列行为之一的，由所在地县级以上人民政府校外培训主管部门会同其他有关部门责令改正，退还所收费用，予以警告或通报批评；情节严重的，处5万元以下罚款；情节特别严重的，处5万元以上10万元以下罚款： （一）通过即时通讯、网络会议、直播平台等方式有偿开展校外培训的； （二）利用居民楼、酒店、咖啡厅等场所有偿组织开展“一对一”“一对多”等校外培训的； （三）以咨询、文化传播、素质拓展、竞赛、思维训练、家政服务、家庭教育指导、住家教师、众筹私教、游学、研学、冬夏令营、托管等名义有偿开展校外培训的； （四）其他未经审批开展学科类校外培训，尚不符合本办法第十七条规定条件的。"},{"i":19,"n":"第十九条","txt":"自然人、法人或者其他组织知道或者应当知道违法校外培训活动的情况存在，仍为其开展校外培训提供场所的，由县级以上人民政府校外培训主管部门会同其他有关部门责令限期改正；逾期拒不改正的，予以警告或者通报批评。 网络平台运营者知道或者应当知道其用户通过即时通讯、网络会议、直播平台等方式违法开展线上校外培训，仍为其提供服务的，适用前款规定处理。"},{"i":20,"n":"第二十条","txt":"校外培训机构超出办学许可范围，有下列行为之一的，由县级以上人民政府校外培训主管部门或者其他有关部门责令限期改正，并予以警告；有违法所得的，退还所收费用后没收违法所得；情节严重的，责令停止招收学员、吊销许可证件： （一）线下培训机构开展线上校外培训的，但是以现代信息技术辅助开展培训活动的除外； （二）线上培训机构开展线下校外培训的； （三）非学科类培训机构开展学科类校外培训的； （四）学科类培训机构开展非学科类校外培训的； （五）其他超出办学许可范围开展培训活动的。"},{"i":21,"n":"第二十一条","txt":"校外培训机构违反法律、行政法规和国家有关规定开展培训活动，有下列行为之一的，由县级以上人民政府校外培训主管部门或者其他有关部门责令限期改正，并予以警告；有违法所得的，退还所收费用后没收违法所得；情节严重的，责令停止招收学员、吊销许可证件： （一）违背国家教育方针，偏离社会主义办学方向，阻碍国家教育制度实施的； （二）培训内容违反法律法规和国务院校外培训主管部门有关规定，影响未成年人身心健康的； （三）超前超标开展学科类培训的； （四）培训时间违反法律法规和国务院校外培训主管部门有关规定的； （五）其他违反法律、行政法规和国家有关规定开展培训活动的。 校外培训机构有前款第（一）（二）项规定行为的，从重处罚。"},{"i":22,"n":"第二十二条","txt":"校外培训机构管理混乱，有下列行为之一的，由县级以上人民政府校外培训主管部门或者其他有关部门责令限期改正，并予以警告；有违法所得的，退还所收费用后没收违法所得；情节严重的，责令停止招收学员、吊销许可证件： （一）与中小学联合招生等违反规定招收学员的； （二）校外培训机构从业人员的聘任与管理违反法律、法规和国务院校外培训主管部门有关规定的； （三）校外培训机构收费价格、收费行为、预收费管理等违反法律法规和国务院相关部门有关规定的； （四）线上校外培训包含与培训无关的网络游戏内容及链接的； （五）线上校外培训未按照国务院校外培训主管部门有关规定留存培训内容、培训数据、直播培训影像的； （六）校外培训机构违法违规发布广告的； （七）其他管理混乱严重影响教育教学的。 校外培训机构有前款第（一）项规定行为的，从重处罚。"},{"i":23,"n":"第二十三条","txt":"校外培训机构擅自组织或者参与组织面向3周岁以上学龄前儿童、中小学生的社会性竞赛活动，由县级以上人民政府教育行政部门会同其他有关部门责令改正，退还所收费用，予以警告或者通报批评；情节严重的，处5万元以下罚款；情节特别严重的，处5万元以上10万元以下罚款。"},{"i":24,"n":"第二十四条","txt":"校外培训机构有本办法第二十条、第二十一条、第二十二条规定行为的，校外培训主管部门或者其他有关部门可以对其决策机构负责人、行政负责人及直接责任人予以警告；情节严重的，依据民办教育促进法实施条例第六十四条规定，对有关责任人员给予限制从业处罚。"},{"i":25,"n":"第二十五条","txt":"校外培训机构举办者及实际控制人、决策机构或者监督机构组成人员违反民办教育促进法实施条例第六十二条的，由县级以上人民政府校外培训主管部门或者其他有关部门依据职责分工责令限期改正，有违法所得的，退还所收费用后没收违法所得；情节严重的，依据民办教育促进法实施条例第六十二条规定，给予限制从业处罚。"},{"i":26,"n":"第二十六条","txt":"校外培训主管部门发现涉嫌违反校外培训有关法律、法规和规章行为的，应当进行初步审查，同时符合下列条件的，应当予以立案： （一）有明确的违法当事人； （二）有证据初步证明存在违法事实； （三）依法应当给予行政处罚； （四）属于本部门管辖； （五）在给予行政处罚的法定期限内。 立案应当填写立案审批表，报本部门负责人审批。"},{"i":27,"n":"第二十七条","txt":"对于已经立案的案件，经调查发现不符合本办法第二十六条规定的立案条件的，校外培训主管部门应当撤销立案。"},{"i":28,"n":"第二十八条","txt":"校外培训主管部门应当全面、客观、公正地调查，收集有关证据，制作调查笔录、询问笔录等，在调查过程中可行使下列职权： （一）对当事人涉嫌开展违法活动的场所实施现场调查； （二）询问当事人或者有关人员； （三）查阅、复制与涉嫌违法培训有关的合同、票据、账簿、广告、宣传资料、花名册和其他有关资料； （四）在证据可能灭失或者以后难以取得的情况下，经校外培训主管部门负责人批准，可先行登记保存，并应当在七日内及时作出处理决定； （五）法律、法规规定的其他职权。"},{"i":29,"n":"第二十九条","txt":"拟给予行政处罚的案件，在作出行政处罚决定前，校外培训主管部门应当书面告知当事人拟作出的行政处罚内容及事实、理由、依据，并告知当事人依法享有的陈述权、申辩权。 当事人提出陈述、申辩意见的，校外培训主管部门应当充分听取当事人的意见，对当事人提出的事实、理由和证据进行复核，当事人提出的事实、理由或者证据成立的，校外培训主管部门应当采纳。"},{"i":30,"n":"第三十条","txt":"校外培训主管部门拟作出下列行政处罚决定的，应当告知当事人有要求听证的权利： （一）对自然人处3万元以上、对法人或者其他组织处10万元以上的罚款； （二）没收10万元以上违法所得； （三）本办法第五条第（三）（四）（五）（六）项行政处罚； （四）法律、法规、规章规定的其他情形。 当事人依法要求听证的，应当自告知书送达之日起五日内提出，由校外培训主管部门负责法制审核的机构按照行政处罚法等相关法律法规规定的程序组织听证程序。听证结束后，校外培训主管部门应当根据听证笔录，依法作出决定。"},{"i":31,"n":"第三十一条","txt":"当事人自告知书送达之日起五日内，未行使陈述、申辩权，视为放弃此权利。"},{"i":32,"n":"第三十二条","txt":"校外培训主管部门在作出行政处罚决定前，应当责令当事人限期改正，当事人及时改正并积极消除危害后果的，可以依法从轻、减轻或者免予处罚。"},{"i":33,"n":"第三十三条","txt":"有下列情形之一，在行政机关负责人作出行政处罚的决定前，应当由校外培训主管部门负责法制审核的机构进行法制审核，未经法制审核或者审核未通过的，不得作出决定： （一）涉及重大公共利益的； （二）直接关系当事人或者第三人重大权益，经过听证程序的； （三）案件情况疑难复杂、涉及多个法律关系的； （四）法律、法规规定应当进行法制审核的其他情形。 前款第二项规定的案件，应当在听证程序结束后进行法制审核。"},{"i":34,"n":"第三十四条","txt":"调查终结，校外培训主管部门负责人应当对调查结果进行审查，根据行政处罚法的规定作出决定。 对本办法第三十三条规定的情形以及其他情节复杂或者重大违法行为给予行政处罚，校外培训主管部门负责人应当在行政处罚事先告知书作出之前集体讨论决定。 校外培训主管部门作出行政处罚决定，应当制作行政处罚决定书，行政处罚决定书应当根据行政处罚法的规定载明有关内容，并加盖本部门印章。"},{"i":35,"n":"第三十五条","txt":"行政处罚决定书应当在宣告后当场交付当事人；当事人不在场的，应当在七日内依照民事诉讼法的有关规定送达当事人。 当事人同意并签订确认书的，校外培训主管部门可以采用传真、电子邮件等方式，将行政处罚决定书等送达当事人。 当事人下落不明，或者依照民事诉讼法规定的其他方式无法送达的，可以公告送达。自发出公告之日起，经过三十日，即视为送达。公告送达，应当在案卷中记明原因和经过。"},{"i":36,"n":"第三十六条","txt":"行政处罚决定书送达后当事人在法定期限内不申请行政复议或者提起行政诉讼，又不履行处罚决定的，校外培训主管部门可以自期限届满之日起三个月内依法申请人民法院强制执行。"},{"i":37,"n":"第三十七条","txt":"行政处罚有下列情形之一的，经校外培训主管部门负责人批准，案件结案： （一）处罚决定执行完毕的； （二）已依法申请人民法院强制执行的； （三）案件终止调查的； （四）其他应当结案的情形。 行政处罚案件材料应当按照有关法律法规和档案管理规定归档保存。"},{"i":38,"n":"第三十八条","txt":"校外培训主管部门应当建立执法监督制度。 上级校外培训主管部门应当加强对下级校外培训主管部门行政处罚工作的指导。 具有一定社会影响的校外培训行政处罚决定应当依法向社会公开。"},{"i":39,"n":"第三十九条","txt":"对于重大违法案件，上级校外培训主管部门可以挂牌督办，提出办理要求，督促下级部门限期办理。"},{"i":40,"n":"第四十条","txt":"县级以上人民政府校外培训主管部门应当建立违法案件统计报告制度，定期将本行政区域内的校外培训违法形势分析、案件发生情况、查处情况等逐级上报。"},{"i":41,"n":"第四十一条","txt":"校外培训主管部门实施校外培训行政处罚，有下列情形之一的，由有关部门对直接负责的主管人员和其他直接责任人员依法给予处分： （一）对违法行为未依法采取制止措施的； （二）应当依法给予行政处罚而未依法处罚的； （三）应当依法申请强制执行、移送有关机关追究责任，而未依法申请强制执行、移送有关机关的； （四）有行政处罚法、民办教育促进法等法律法规规定的其他超越职权、滥用职权、徇私舞弊、玩忽职守情形的。"},{"i":42,"n":"第四十二条","txt":"本办法中的“违法所得”是指违法开展校外培训所收取的全部款项，依法已经予以退还的预收费未消课款项，可以扣除。法律、行政法规、规章对违法所得的计算另有规定的，从其规定。"},{"i":43,"n":"第四十三条","txt":"本办法中“以上”“以下”含本数，“五日”“七日”的规定是指工作日，不含法定节假日。"},{"i":44,"n":"第四十四条","txt":"本办法自2023年10月15日起施行。"}],"minbangaodengxuexiaobanxueguanliruoganguiding":[{"i":1,"n":"第一条","txt":"为规范实施专科以上高等学历教育的民办学校(以下简称民办高校)的办学行为，维护民办高校举办者和学校、教师、学生的合法权益，引导民办高校健康发展，根据民办教育促进法及其实施条例和国家有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"民办高校及其举办者应当遵守法律、法规、规章和国家有关规定，贯彻国家的教育方针，坚持社会主义办学方向和教育公益性原则，保证教育质量。"},{"i":3,"n":"第三条","txt":"教育行政部门应当将民办高等教育纳入教育事业发展规划。按照积极鼓励、大力支持、正确引导、依法管理的方针，引导民办高等教育健康发展。 　　　教育行政部门对民办高等教育事业做出突出贡献的集体和个人予以表彰奖励。"},{"i":4,"n":"第四条","txt":"国务院教育行政部门负责全国民办教育统筹规划、综合协调和宏观管理工作。 　　　省、自治区、直辖市人民政府教育行政部门(以下简称省级教育行政部门)主管本行政区域内的民办教育工作。对民办高校依法履行下列职责： 　　　(一)办学许可证管理； 　　　(二)民办高校招生简章和广告备案的审查； 　　　(三)民办高校相关信息的发布； 　　　(四)民办高校的年度检查； 　　　(五)民办高校的表彰奖励； 　　　(六)民办高校违法违规行为的查处； 　　　(七)法律法规规定的其他职责。"},{"i":5,"n":"第五条","txt":"民办高校的办学条件必须符合国家规定的设置标准和普通高等学校基本办学条件指标的要求。 　　　民办高校设置本、专科专业，按照国家有关规定执行。"},{"i":6,"n":"第六条","txt":"民办高校的举办者应当按照民办教育促进法及其实施条例的规定，按时、足额履行出资义务。 　　　民办高校的借款、向学生收取的学费、接受的捐赠财产和国家的资助，不属于举办者的出资。 　　　民办高校对举办者投入学校的资产、国有资产、受赠的财产、办学积累依法享有法人财产权，并分别登记建账。任何组织和个人不得截留、挪用或侵占民办高校的资产。"},{"i":7,"n":"第七条","txt":"民办高校的资产必须于批准设立之日起1年内过户到学校名下。 　　　本规定下发前资产未过户到学校名下的，自本规定下发之日起1年内完成过户工作。 　　　资产未过户到学校名下前，举办者对学校债务承担连带责任。"},{"i":8,"n":"第八条","txt":"民办高校符合举办者、学校名称、办学地址和办学层次变更条件的，按照民办教育促进法规定的程序，报审批机关批准。 　　　民办高校应当按照办学许可证核定的学校名称、办学地点、办学类型、办学层次组织招生工作，开展教育教学活动。 　　　民办高校不得在办学许可证核定的办学地点之外办学。不得设立分支机构。不得出租、出借办学许可证。"},{"i":9,"n":"第九条","txt":"民办高校必须根据有关规定，建立健全党团组织。民办高校党组织应当发挥政治核心作用，民办高校团组织应当发挥团结教育学生的重要作用。"},{"i":10,"n":"第十条","txt":"民办高校校长应当具备国家规定的任职条件，具有10年以上从事高等教育管理经历，年龄不超过70岁。校长报审批机关核准后，方可行使民办教育促进法及其实施条例规定的职权。 　　　校长任期原则上为4年。报经审批机关同意后可以连任。"},{"i":11,"n":"第十一条","txt":"未列入国务院教育行政部门当年公布的具有学历教育招生资格学校名单的民办高校，不得招收学历教育学生。"},{"i":12,"n":"第十二条","txt":"民办高校招生简章和广告必须载明学校名称、办学地点、办学性质、招生类型、学历层次、学习年限、收费项目和标准、退费办法、招生人数、证书类别和颁发办法等。 　　　民办高校应当依法将招生简章和广告报审批机关或其委托的机关备案。发布的招生简章和广告必须与备案的内容相一致。未经备案的招生简章和广告不得发布。"},{"i":13,"n":"第十三条","txt":"民办高校招收学历教育学生的，必须严格执行国家下达的招生计划，按照国家招生规定和程序招收学生。对纳入国家计划、经省级招生部门统一录取的学生发放录取通知书。"},{"i":14,"n":"第十四条","txt":"民办高校应当按照普通高等学校学生管理规定的要求完善学籍管理制度。纳入国家计划、经省级招生部门统一录取的学生入学后，学校招生部门按照国家规定对其进行复查，复查合格后予以电子注册并取得相应的学籍。"},{"i":15,"n":"第十五条","txt":"民办高校自行招收的学生为非学历教育学生，学校对其发放学习通知书。学习通知书必须明确学习形式、学习年限、取得学习证书办法等。 　　　民办高校对学习时间1年以上的非学历教育学生实行登记制度。已登记的学生名单及有关情况，必须于登记后7日内报省级教育行政部门备案。备案后的学生名单在校内予以公布。"},{"i":16,"n":"第十六条","txt":"民办高校应当按照民办教育促进法及其实施条例的要求，配备教师，不断提高专职教师数量和比例。 　　　民办高校应当依法聘任具有国家规定任教资格的教师，与教师签订聘任合同，明确双方的责任、权利、义务。保障教师的工资、福利待遇，按国家有关规定为教师办理社会保险和补充保险。"},{"i":17,"n":"第十七条","txt":"民办高校应当加强教师的培养和培训，提高教师队伍整体素质。"},{"i":18,"n":"第十八条","txt":"民办高校应当按照国家有关规定建立学生管理队伍。按不低于1：200的师生比配备辅导员，每个班级配备1名班主任。"},{"i":19,"n":"第十九条","txt":"民办高校应当建立健全教学管理机构，加强教学管理队伍建设。改进教学方式方法，不断提高教育质量。 　　　不得以任何形式将承担的教育教学任务转交其他组织和个人。"},{"i":20,"n":"第二十条","txt":"民办高校应当建立教师、学生校内申诉渠道，依法妥善处理教师、学生提出的申诉。"},{"i":21,"n":"第二十一条","txt":"民办高校依法设置会计机构，配备会计人员。会计人员必须取得会计业务资格证书。建立健全内部控制制度，严格执行国家统一的会计制度。"},{"i":22,"n":"第二十二条","txt":"民办高校必须严格执行政府有关部门批准的收费项目和标准。收取的费用主要用于教育教学活动和改善办学条件。"},{"i":23,"n":"第二十三条","txt":"民办高校应当在每学年结束时制作财务会计报告，委托会计师事务所进行审计。必要时，省级教育行政部门可会同有关部门对民办高校进行财务审计。"},{"i":24,"n":"第二十四条","txt":"民办高校的法定代表人为学校安全和稳定工作第一责任人。民办高校应当加强应急管理，建立健全安全稳定工作机制。推进学校安全保卫工作队伍建设，加强对学校教学、生活、活动设施的安全检查，落实各项安全防范措施，维护校园安全和教学秩序。"},{"i":25,"n":"第二十五条","txt":"建立对民办高校的督导制度。 　　　省级教育部门按照国家有关规定向民办高校委派的督导专员应当拥护宪法确定的基本原则，具有从事高等教育管理工作经历，熟悉高等学校情况，具有较强的贯彻国家法律、法规和政策的能力，年龄不超过70岁。督导专员的级别、工资、日常工作经费等由委派机构商有关部门确定。 　　　督导专员任期原则上为4年。因工作需要的，委派机构可根据具体情况适当延长其任期。"},{"i":26,"n":"第二十六条","txt":"督导专员行使下列职权： 　　　(一)监督学校贯彻执行有关法律、法规、政策的情况； 　　　(二)监督、引导学校的办学方向、办学行为和办学质量； 　　　(三)参加学校发展规划、人事安排、财产财务管理、基本建设、招生、收退费等重大事项的研究讨论； 　　　(四)向委派机构报告学校办学情况，提出意见建议； 　　　(五)有关党政部门规定的其他职责。"},{"i":27,"n":"第二十七条","txt":"省级教育行政部门应当建立健全民办高校办学过程监控机制，及时向社会发布民办高校的有关信息。"},{"i":28,"n":"第二十八条","txt":"省级教育行政部门按照国家规定对民办高校实行年度检查制度。年度检查工作于每年12月31日前完成。省级教育行政部门根据年度检查情况和国务院教育行政部门基本办学条件核查的结果，在办学许可证副本上加盖年度检查结论戳记。 　　　年度检查时，民办高校应当向省级教育行政部门提交年度学校自查报告、财务审计报告和要求提供的其他材料。"},{"i":29,"n":"第二十九条","txt":"省级教育行政部门对民办高校年度检查的主要内容： 　　　(一)遵守法律、法规和政策的情况； 　　　(二)党团组织建设、和谐校园建设、安全稳定工作的情况； 　　　(三)按照章程开展活动的情况； 　　　(四)内部管理机构设置及人员配备情况； 　　　(五)办学许可证核定项目的变动情况； 　　　(六)财务状况，收入支出情况或现金流动情况； 　　　(七)法人财产权的落实情况； 　　　(八)其他需要检查的情况。"},{"i":30,"n":"第三十条","txt":"民办高校出现以下行为的，由省级教育行政部门责令改正；并可给予1至3万元的罚款、减少招生计划或者暂停招生的处罚。 　　　(一)学校资产不按期过户的； 　　　(二)办学条件不达标的； 　　　(三)发布未经备案的招生简章和广告的； 　　　(四)年度检查不合格的。"},{"i":31,"n":"第三十一条","txt":"民办高校违反民办教育促进法及其实施条例以及其他法律法规规定的，由省级教育行政部门或者会同相关部门依法予以处罚。"},{"i":32,"n":"第三十二条","txt":"省级教育行政部门应当配合相关主管部门对发布违法招生广告的广告主、广告经营者、广告发布者和非法办学机构、非法中介进行查处。"},{"i":33,"n":"第三十三条","txt":"教育行政部门会同民政部门加强对民办高等教育领域行业协会的业务指导和监督管理。充分发挥行业协会在民办高等教育健康发展中提供服务、反映诉求、行业自律的作用。"},{"i":34,"n":"第三十四条","txt":"教育行政部门配合新闻单位做好引导民办高等教育健康发展的舆论宣传工作，营造有利于民办高校健康发展的舆论环境。"},{"i":35,"n":"第三十五条","txt":"教育行政部门及其工作人员滥用职权、玩忽职守，违反民办教育促进法及其实施条例规定的，依法予以处理。"},{"i":36,"n":"第三十六条","txt":"本规定自2007年2月10日起施行。"}],"hanyuzuoweiwaiyujiaoxuenenglirendingbanfa":[{"i":1,"n":"第一条","txt":"为了提高汉语作为外语教学的水平，做好汉语作为外语教学能力认定工作，加强汉语作为外语教学师资队伍的建设，促进对外汉语教学事业的发展，依据《教育法》和《教师法》制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于对从事汉语作为外语教学工作的中国公民和外国公民所具备的相应专业知识水平和技能的认定。对经认定达到相应标准的，颁发《汉语作为外语教学能力证书》（以下简称《能力证书》）。"},{"i":3,"n":"第三条","txt":"汉语作为外语教学能力认定工作由汉语作为外语教学能力认定工作委员会（以下简称“认定委员会”）根据本办法进行组织。认定委员会成员由教育部任命。认定委员会的职责是制订能力认定的考试标准，规范能力证书课程，组织考试和认定工作，颁发《能力证书》。"},{"i":4,"n":"第四条","txt":"《能力证书》申请者应热爱汉语教学工作、热心介绍中国文化、遵守法律法规、具有良好的职业素养，须具有大专（含）以上学历和必要的普通话水平。其中的中国公民应具有相当于大学英语四级以上或全国外语水平考试（WSK）合格水平。"},{"i":5,"n":"第五条","txt":"《能力证书》分为初级、中级、高级三类。 取得初级证书者应当具备汉语作为外语教学的基本知识，能够对母语为非汉语学习者进行基础性的汉语教学工作。 取得中级证书者应当具备汉语作为外语教学的较完备的知识，能够对母语为非汉语学习者进行较为系统的汉语教学工作。 取得高级证书者应当具备汉语作为外语教学的完备的知识，能够对母语为非汉语学习者进行系统性、专业性的汉语教学和相关的科学研究。"},{"i":6,"n":"第六条","txt":"申请《能力证书》须通过下列考试： 初级证书的考试科目为：现代汉语基本知识、中国文化基础常识、普通话水平 中级证书的考试科目为：现代汉语、汉语作为外语教学理论、中国文化基本知识 高级证书的考试科目为：现代汉语及古代汉语、语言学及汉语作为外语教学理论、中国文化。"},{"i":7,"n":"第七条","txt":"申请中级、高级证书者普通话水平需达到中国国家语言文字工作委员会规定的二级甲等以上。"},{"i":8,"n":"第八条","txt":"对外汉语专业毕业的本科生可免试申请《能力证书（中级）》； 对外汉语专业方向毕业的研究生可免试申请《能力证书（高级）》。 中国语言文学专业毕业的本科生和研究生，可免试汉语类科目。"},{"i":9,"n":"第九条","txt":"汉语作为外语教学能力认定工作每年定期进行。申请证书者须先通过能力考试，凭考试合格成绩申请证书。申报考试和申请证书的具体时间及承办机构由认定委员会决定。"},{"i":10,"n":"第十条","txt":"《能力证书》申请者须向申请受理机构提交以下材料： （一）《汉语作为外语教学能力证书申请表》（一式两份）； （二）身份证明原件及复印件； （三）学历证书原件及复印件； （四）考试成绩证明原件及复印件（符合免考试科目者须提交所要求的证书原件及复印件）； （五）普通话水平测试等级证书原件及复印件； （六）外语水平证明原件及复印件。"},{"i":11,"n":"第十一条","txt":"《能力证书》由认定委员会监制。"},{"i":12,"n":"第十二条","txt":"申请证书过程中弄虚作假的，经认定委员会核实，不予认定；已经获得《汉语作为外语教学能力证书》者，由认定委员会予以注销。"},{"i":13,"n":"第十三条","txt":"为了提高汉语作为外语教师的专业能力，认定委员会规定《能力证书》的标准化课程和大纲。"},{"i":14,"n":"第十四条","txt":"本办法自2004年10月1日起施行，1990年6月23日发布的《对外汉语教师资格审定办法》（中华人民共和国国家教育委员会令第12号）同时废止，《对外汉语教师资格证书》同时失效，须更换《能力证书（高级）》。"}],"teshujiaoyuxuexiaozanxingguicheng":[{"i":1,"n":"第一条","txt":"为加强特殊教育学校内部的规范化管理，全面贯彻教育方针，全面提高教育质量，依据国家有关教育法律、法规制定本规程。"},{"i":2,"n":"第二条","txt":"本规程所指的特殊教育学校是指由政府、企业事业组织、社会团体、其他社会组织及公民个人依法举办的专门对残疾儿童、少年实施义务教育的机构。"},{"i":3,"n":"第三条","txt":"特殊教育学校的学制一般为九年一贯制。"},{"i":4,"n":"第四条","txt":"特殊教育学校要贯彻国家教育方针，根据学生身心特点和需要实施教育，为其平等参与社会生活，继续接受教育，成为社会主义事业的建设者和接班人奠定基础。"},{"i":5,"n":"第五条","txt":"特殊教育学校的培养目标是：培养学生初步具有爱祖国、爱人民、爱劳动、爱科学、爱社会主义的情感，具有良好的品德，养成文明、礼貌、遵纪守法的行为习惯；掌握基础的文化科学知识和基本技能，初步具有运用所学知识分析问题、解决问题的能力；掌握锻炼身体的基本方法，具有较好的个人卫生习惯，身体素质和健康水平得到提高；具有健康的审美情趣；掌握一定的日常生活、劳动、生产的知识和技能；初步掌握补偿自身缺陷的基本方法，身心缺陷得到一定程度的康复；初步树立自尊、自信、自强、自立的精神和维护自身合法权益的意识，形成适应社会的基本能力。"},{"i":6,"n":"第六条","txt":"特殊教育学校的基本教学语言文字为汉语言文字。学校应当推广使用全国通用的普通话和规范字以及国家推行的盲文、手语。 招收少数民族学生为主的学校，可使用本民族或当地民族通用语言文字和盲文、手语进行教学，并应根据实际情况在适当年级开设汉语文课程，开设汉语文课程应当使用普通话和规范汉字。"},{"i":7,"n":"第七条","txt":"特殊教育学校实行校长负责制，校长全面负责学校的教学和其它行政工作。"},{"i":8,"n":"第八条","txt":"按照“分级管理、分工负责”的原则，特殊教育学校在当地人民政府领导下实施教育工作。特殊教育学校应接受教育行政部门或上级主管部门的检查、监督和指导，要如实报告工作，反映情况。学年末，学校要向主管教育行政部门报告工作，重大问题应随时报告。"},{"i":9,"n":"第九条","txt":"特殊教育学校招收适合在校学习的义务教育阶段学龄残疾儿童、少年入学。招生范围由主管教育行政部门确定。学校实行秋季始业。 学校应对入学残疾儿童、少年的残疾类别、原因、程度和身心发展状况等进行必要的了解和测评。"},{"i":10,"n":"第十条","txt":"特殊教育学校应根据有利于教育教学和学生心理健康的原则确定教学班学额。"},{"i":11,"n":"第十一条","txt":"特殊教育学校对因病无法继续学习的学生（须具备县级以上医疗单位的证明）在报经主管教育行政部门批准后，准其休学。休学时间超过三个月，复学时学校可根据其实际情况并征求本人及其父母或其他监护人的意见后编入相应年级。"},{"i":12,"n":"第十二条","txt":"特殊教育学校应接纳其主管教育行政部门批准、不适应继续在普通学校就读申请转学的残疾儿童、少年，并根据其实际情况，编入相应年级。 学校对因户籍变更申请转入，并经主管教育行政部门审核符合条件的残疾儿童、少年，应及时予以妥善安置，不得拒收。 学校对招生范围以外的申请就学的残疾儿童、少年，经主管教育行政部门批准后，可准其借读，并可按有关规定收取借读费。"},{"i":13,"n":"第十三条","txt":"特殊教育学校对修完规定课程且成绩合格者，发给毕业证书，对不合格者发给结业证书；对已修满义务教育年限但未修完规定课程者，发给肄业证书；对未修满义务教育年限者，可视情况出具学业证明。学校一般不实行留级制度。"},{"i":14,"n":"第十四条","txt":"特殊教育学校对学业能力提前达到更高年级程度的学生，可准其提前升入相应年级学习或者提前学习相应年级的有关课程。经考查能够在普通学校随班就读的学生，在经得本人、其父母或者其他监护人的同意后，应向主管教育行政部门申请转学。"},{"i":15,"n":"第十五条","txt":"特殊教育学校对品学兼优的学生应予表彰，对犯有错误的学生应给予帮助或批评教育，对极少数错误严重的学生，可分别给予警告、严重警告和记过处分。学校一般不得开除义务教育阶段学龄学生。"},{"i":16,"n":"第十六条","txt":"特殊教育学校应防止未修满义务教育年限的学龄学生辍学，发现学生辍学，应立即向主管部门报告，配合有关部门依法使其复学。"},{"i":17,"n":"第十七条","txt":"特殊教育学校的学籍管理办法由省级教育行政部门制定。"},{"i":18,"n":"第十八条","txt":"特殊教育学校的主要任务是教育教学工作，其他各项工作应有利于教育教学工作的开展。 学校的教育教学工作要面向全体学生，坚持因材施教，改进教育教学方法，充分发挥各类课程的整体功能，促进学生全面发展。"},{"i":19,"n":"第十九条","txt":"特殊教育学校应按照国家制定的特殊教育学校课程计划、教学大纲进行教育教学工作。 学校使用的教材，须经省级以上教育行政部门审查通过；实验教材、乡土教材须经主管教育行政部门批准后方可使用。 学校应根据学生的实际情况和特殊需要，采用不同的授课制和多种教学组织形式。"},{"i":20,"n":"第二十条","txt":"特殊教育学校应当依照教育行政部门颁布的校历安排教育教学工作。特殊教育学校不得随意停课，若遇特殊情况必须停课的，一天以内的由校长决定，并报县级教育行政部门备案；一天以上的，应经县级人民政府批准。"},{"i":21,"n":"第二十一条","txt":"特殊教育学校不得组织学生参加商业性的庆典、演出等活动，参加其他社会活动不应影响教育教学秩序和学校正常工作。"},{"i":22,"n":"第二十二条","txt":"特殊教育学校要把德育工作放在重要位置，要结合学校和学生的实际实施德育工作，注重实效。 学校的德育工作由校长负责，教职工参与，做到组织落实、制度落实、内容落实、基地落实、时间落实；要与家庭教育、社会教育密切结合。"},{"i":23,"n":"第二十三条","txt":"特殊教育学校对学生应坚持正面教育，注意保护学生的自信心、自尊心，不得讽刺挖苦、粗暴压服，严禁体罚和变相体罚。"},{"i":24,"n":"第二十四条","txt":"特殊教育学校要在每个教学班设置班主任教师，负责管理、指导班级全面工作。班主任教师要履行国家规定的班主任职责，加强同各科任课教师、学校其他人员和学生家长的联系，了解学生思想、品德、学业、身心康复等方面的情况，协调教育和康复工作。 班主任教师每学期要根据学生的表现写出评语。"},{"i":25,"n":"第二十五条","txt":"特殊教育学校要根据学生的实际情况有针对性地给学生布置巩固知识、发展技能和康复训练等方面的作业。"},{"i":26,"n":"第二十六条","txt":"特殊教育学校应重视体育美育工作。 学校要结合学生实际，积极开展多种形式的体育活动，增强学生的体质。学校应保证学生每天不少于一小时的体育活动时间。 学校要上好艺术类课程，注意培养学生的兴趣、爱好和特长，其他学科也要从本学科特点出发，发挥美育功能。美育要结合学生日常生活，提出服饰、仪表、语言行为等方面审美要求。"},{"i":27,"n":"第二十七条","txt":"特殊教育学校要特别重视劳动教育、劳动技术教育和职业教育。学校要对低、中年级学生实施劳动教育，培养学生爱劳动、爱劳动人民、珍惜劳动成果的思想，培养从事自我服务、家务劳动和简单生产劳动的能力，养成良好的劳动习惯；要根据实际情况对高年级学生实施劳动技术教育和职业教育，提高学生的劳动、就业能力。 学校劳动教育、劳动技术教育和职业教育，应做到内容落实、师资落实、场地落实。 学校要积极开展勤工俭学活动，办好校办产业；勤工俭学和校办产业的生产、服务活动要努力与劳动教育、劳动技术教育和职业教育相结合。学校参加勤工俭学活动，应以有利于学生的身心健康和发展为原则。"},{"i":28,"n":"第二十八条","txt":"特殊教育学校要把学生的身心康复作为教育教学的重要内容，根据学生的残疾类别和程度，有针对性地进行康复训练，提高训练质量。要指导学生正确运用康复设备和器具。"},{"i":29,"n":"第二十九条","txt":"特殊教育学校要重视学生的身心健康教育，培养学生良好的心理素质和卫生习惯，提高学生保护和合理使用自身残存功能的能力；适时、适度地进行青春期教育。"},{"i":30,"n":"第三十条","txt":"特殊教育学校应加强活动课程和课外活动的指导，做到内容落实、指导教师落实、活动场地落实；要与普通学校、青少年校外教育机构和学生家庭联系，组织开展有益活动，安排好学生的课余生活。学校组织学生参加竞赛、评奖活动，要执行教育行政部门的有关规定。"},{"i":31,"n":"第三十一条","txt":"特殊教育学校要在课程计划和教学大纲的指导下，通过多种形式评价教育教学质量，尤其要重视教学过程的评价。学校不得仅以学生的学业考试成绩评价教育教学质量和教师工作。 学校每学年要对学生德、智、体和身心缺陷康复等方面进行1－2次评价，毕业时要进行终结性评价，评价报告要收入学生档案。 视力和听力言语残疾学生，1－6年级学期末考试科目为语文、数学两科，其它学科通过考查确定成绩；7－9年级学生学期末考试科目为语文、数学、劳动技术或职业技能三科，其它学科通过考查评定成绩。学期末考试由学校命题，考试方法要多样，试题的难易程度和数量要适度。 视力和听力言语残疾学生的毕业考试科目、考试办法及命题权限由省级教育行政部门确定。 智力残疾学生主要通过平时考查确定成绩，考查科目、办法由学校确定。"},{"i":32,"n":"第三十二条","txt":"特殊教育学校要积极开展教育教学研究，运用科学的教育理论指导教育教学工作，积极推广科研成果及成功的教育教学经验。"},{"i":33,"n":"第三十三条","txt":"特殊教育学校应合理安排作息时间，学生每日在校用于教学活动时间，不得超过课程计划规定的课时，接受劳动技术教育和职业教育的学生，用于劳动实习的时间，每天不超过3小时；毕业年级集中生产实习每天不超过6小时，并要严格控制劳动强度。"},{"i":34,"n":"第三十四条","txt":"特殊教育学校可按编制设校长、副校长、主任、教师和其他人员。"},{"i":35,"n":"第三十五条","txt":"特殊教育学校校长是学校的行政负责人，校长应具备、符合国家规定的任职条件和岗位要求，履行国家规定的职责。校长由学校举办者或举办者的上级主管部门任命或聘任；副校长及教导（总务）主任等人员由校长提名，按有关规定权限和程序任命或聘任。社会力量举办的特殊教育学校校长应报教育行政部门核准后，由校董会或学校举办者聘任。校长要加强教育及其有关法律法规、教育理论的学习，要熟悉特殊教育业务，不断加强自身修养，提高管理水平，依法对学校实施管理。"},{"i":36,"n":"第三十六条","txt":"特殊教育学校教师应具备国家规定的相应教师资格和任职条件，具有社会主义的人道主义精神，关心残疾学生，掌握特殊教育的专业知识和技能，遵守职业道德，完成教育教学工作，享受和履行法律规定的权利和义务。"},{"i":37,"n":"第三十七条","txt":"特殊教育学校其他人员应具备相应的思想政治、业务素质，其具体任职条件、职责由教育行政部门或学校按照国家的有关规定制定。"},{"i":38,"n":"第三十八条","txt":"特殊教育学校要根据国家有关规定实行教师聘任、职务制度，对教师和其他人员实行科学管理。"},{"i":39,"n":"第三十九条","txt":"特殊教育学校要加强教师的思想政治、职业道德教育，重视教师和其他人员的业务培训和继续教育，制定进修计划，积极为教师和其他人员进修创造条件。教师和其他人员进修应根据学校工作需要，以在职、自学、所教学科和所从事工作为主。"},{"i":40,"n":"第四十条","txt":"特殊教育学校应建立健全考核奖惩制度和业务考核档案，从德、能、勤、绩等方面全面、科学考核教师和其他人员工作，注意工作表现和实绩，并根据考核结果奖优罚劣。"},{"i":41,"n":"第四十一条","txt":"特殊教育学校可根据规模，内设分管教务、总务等工作的机构（或岗位）和人员，协助校长做好有关工作。招收两类以上残疾学生的特殊教育学校，可设置相应的管理岗位，其具体职责由学校确定。"},{"i":42,"n":"第四十二条","txt":"特殊教育学校应按国家有关规定建立教职工代表会议制度，加强对学校民主管理和民主监督。"},{"i":43,"n":"第四十三条","txt":"校长要依靠党的学校（地方）基层组织，并充分发挥工会、共青团、少先队及其他组织在学校工作中的作用。"},{"i":44,"n":"第四十四条","txt":"特殊教育学校应根据国家有关法律法规和政策建立健全各项规章制度，建立完整的学生、教育教学和其它档案。"},{"i":45,"n":"第四十五条","txt":"特殊教育学校应建立学生日常管理制度，并保证落实。学生日常管理工作应与社区、家庭密切配合。"},{"i":46,"n":"第四十六条","txt":"特殊教育学校应按有利于管理，有利于教育教学，有利于安全的原则设置教学区和生活区。"},{"i":47,"n":"第四十七条","txt":"寄宿制特殊教育学校实行24小时监护制度。要设专职或兼职人员，负责学生的生活指导和管理工作。并经常与班主任教师保持联系。"},{"i":48,"n":"第四十八条","txt":"特殊教育学校应认真执行国家有关学校卫生工作的法规、政策，建立健全学校卫生工作制度。"},{"i":49,"n":"第四十九条","txt":"特殊教育学校的校园、校舍、设备、教具、学具和图书资料等应有利于学生身心健康。学校要做好预防传染病、常见病的工作。"},{"i":50,"n":"第五十条","txt":"特殊教育学校要特别重视学生的安全防护工作，建立健全安全工作制度，学校校舍、设施、设备、教具、学具等都应符合安全要求。学校组织的各项校内、外活动，应采取安全防护措施，确保师生的安全。 学校要根据学生特点，开展安全教育和训练，培养学生的安全意识和在危险情况下自护自救能力。"},{"i":51,"n":"第五十一条","txt":"特殊教育学校应配备专职或兼职校医，在校长的领导下，负责学校卫生保健工作和教学、生活卫生监督工作。 学校应建立学生健康档案，每年至少对学生进行一次身体检查；注重保护学生的残存功能。"},{"i":52,"n":"第五十二条","txt":"特殊教育学校要加强饮食管理。食堂的场地、设备、用具、膳食要符合国家规定的卫生标准，要注意学生饮食的营养合理搭配。要制定预防肠道传染病和食物中毒的措施，建立食堂工作人员定期体检制度。"},{"i":53,"n":"第五十三条","txt":"特殊教育学校的办学条件及经费由学校举办者负责提供，校园、校舍建设应执行国家颁布《特殊教育学校建设标准》。 学校应具备符合规定标准的教学仪器设备、专用检测设备、康复设备、文体器材、图书资料等；要创造条件配置现代化教育教学和康复设备。"},{"i":54,"n":"第五十四条","txt":"特殊教育学校要重视校园环境建设，搞好校园的绿化和美化，搞好校园文化建设，形成良好的育人环境。"},{"i":55,"n":"第五十五条","txt":"特殊教育学校应遵照有关规定管理和使用校舍、场地等，未经主管部门批准，不得改变其用途；要及时对校舍设施进行维修和维护，保持坚固、实用、清洁、美观，发现危房立即停止使用，并报主管部门。"},{"i":56,"n":"第五十六条","txt":"特殊教育学校应加强对仪器、设备、器材和图书资料等的管理，分别按有关规定建立健全管理制度，保持完好率，提高使用率。"},{"i":57,"n":"第五十七条","txt":"特殊教育学校对义务教育阶段学生免收学费，对家庭生活困难的学生减免杂费。特殊教育学校收费应严格按照省级人民政府规定的收费项目和县级以上人民政府制定的标准及办法执行。 各级政府应设立助学金，用于帮助经济困难学生就学。"},{"i":58,"n":"第五十八条","txt":"特殊教育学校的校办产业和勤工俭学收入上缴学校部分应用于改善办学条件，提高教职工福利待遇，改善学生学习和生活条件。学校可按有关规定接受社会捐助。"},{"i":59,"n":"第五十九条","txt":"特殊教育学校应科学管理、合理使用学校经费，提高使用效益。要建立经费管理制度，并接受上级财务和审计部门的监督。"},{"i":60,"n":"第六十条","txt":"特殊教育学校应同街道（社区）、村民委员会及附近的普通学校、机关、团体、部队、企事业单位联系，争取社会各界支持学校工作，优化育人环境。"},{"i":61,"n":"第六十一条","txt":"特殊教育学校要在当地教育行政部门领导下，指导普通学校特殊教育班和残疾儿童、少年随班就读工作，培训普通学校特殊教育师资，组织教育教学研究活动，提出本地特殊教育改革与发展的建议。"},{"i":62,"n":"第六十二条","txt":"特殊教育学校应通过多种形式与学生家长建立联系制度，使家长了解学校工作，征求家长对学校工作的意见，帮助家长创设良好的家庭育人环境。"},{"i":63,"n":"第六十三条","txt":"特殊教育学校应特别加强与当地残疾人组织和企事业单位的联系，了解社会对残疾人就业的需求，征求毕业生接收单位对学校教育工作的意见、建议，促进学校教育教学工作的改革。"},{"i":64,"n":"第六十四条","txt":"特殊教育学校应为当地校外残疾人工作者、残疾儿童、少年及家长等提供教育、康复方面的咨询和服务。"},{"i":65,"n":"第六十五条","txt":"特殊教育学校应当根据《中华人民共和国教育法》、《中华人民共和国义务教育法》、《残疾人教育条例》和本规程的规定，结合实际情况制定学校章程。承担教育改革试点任务的特殊教育学校，在报经省级主管教育行政部门批准后，可调整本规程中的某些要求。"},{"i":66,"n":"第六十六条","txt":"本规程适用于特殊教育学校。普通学校附设的特殊教育班、特殊教育学校的非义务教育机构和实施职业教育的特殊教育学校可参照执行有关内容。"},{"i":67,"n":"第六十七条","txt":"各省、自治区、直辖市教育行政部门可根据本规程制定实施办法。"},{"i":68,"n":"第六十八条","txt":"本规程自发布之日起施行。"}],"dulixueyuanshezhiyuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范普通高等学校与社会组织或者个人合作举办独立学院活动，维护受教育者和独立学院的合法权益，促进高等教育事业健康发展，根据高等教育法、民办教育促进法、民办教育促进法实施条例，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称独立学院，是指实施本科以上学历教育的普通高等学校与国家机构以外的社会组织或者个人合作，利用非国家财政性经费举办的实施本科学历教育的高等学校。"},{"i":3,"n":"第三条","txt":"独立学院是民办高等教育的重要组成部分，属于公益性事业。 　　　 设立独立学院，应当符合国家和地方高等教育发展规划。"},{"i":4,"n":"第四条","txt":"独立学院及其举办者应当遵守法律、法规、规章和国家有关规定，贯彻国家的教育方针，坚持社会主义办学方向和教育公益性原则。"},{"i":5,"n":"第五条","txt":"国家保障独立学院及其举办者的合法权益。 　　　 独立学院依法享有民办教育促进法、民办教育促进法实施条例规定的各项奖励与扶持政策。"},{"i":6,"n":"第六条","txt":"国务院教育行政部门负责全国独立学院的统筹规划、综合协调和宏观管理。 　　　 省、自治区、直辖市人民政府教育行政部门（以下简称省级教育行政部门）主管本行政区域内的独立学院工作，依法履行下列职责： 　　　 （一）独立学院办学许可证的管理； 　　　 （二）独立学院招生简章和广告备案的审查； 　　　 （三）独立学院相关信息的发布； 　　　 （四）独立学院的年度检查； 　　　 （五）独立学院的表彰奖励； 　　　 （六）独立学院违法违规行为的查处； 　　　 （七）法律法规规定的其他职责。"},{"i":7,"n":"第七条","txt":"参与举办独立学院的普通高等学校须具有较高的教学水平和管理水平，较好的办学条件，一般应具有博士学位授予权。"},{"i":8,"n":"第八条","txt":"参与举办独立学院的社会组织，应当具有法人资格。注册资金不低于5000万元，总资产不少于3亿元，净资产不少于1.2亿元，资产负债率低于60%。 　　　 参与举办独立学院的个人，应当具有政治权利和完全民事行为能力。个人总资产不低于3亿元，其中货币资金不少于1.2亿元。"},{"i":9,"n":"第九条","txt":"独立学院的设置标准参照普通本科高等学校的设置标准执行。 　　　 独立学院应当具备法人条件。"},{"i":10,"n":"第十条","txt":"参与举办独立学院的普通高等学校与社会组织或者个人，应当签订合作办学协议。 　　　 合作办学协议应当包括办学宗旨、培养目标、出资数额和方式、各方权利义务、合作期限、争议解决办法等内容。"},{"i":11,"n":"第十一条","txt":"普通高等学校主要利用学校名称、知识产权、管理资源、教育教学资源等参与办学。社会组织或者个人主要利用资金、实物、土地使用权等参与办学。 　　　 国家的资助、向学生收取的学费和独立学院的借款、接受的捐赠财产，不属于独立学院举办者的出资。"},{"i":12,"n":"第十二条","txt":"独立学院举办者的出资须经依法验资，于筹设期内过户到独立学院名下。 　　　 本办法施行前资产未过户到独立学院名下的，自本办法施行之日起1年内完成过户工作。"},{"i":13,"n":"第十三条","txt":"普通高等学校投入办学的无形资产，应当依法作价。无形资产的作价，应当委托具有资产评估资质的评估机构进行评估；无形资产占办学总投入的比例，由合作办学双方按照国家法律、行政法规的有关规定予以约定，并依法办理有关手续。"},{"i":14,"n":"第十四条","txt":"独立学院举办者应当依法按时、足额履行出资义务。独立学院存续期间，举办者不得抽逃办学资金，不得挪用办学经费。"},{"i":15,"n":"第十五条","txt":"符合条件的普通高等学校一般只可以参与举办1所独立学院。"},{"i":16,"n":"第十六条","txt":"设立独立学院，分筹设和正式设立两个阶段。筹设期1至3年，筹设期内不得招生。筹设期满未申请正式设立的，自然终止筹设。"},{"i":17,"n":"第十七条","txt":"设立独立学院由参与举办独立学院的普通高等学校向拟设立的独立学院所在地的省级教育行政部门提出申请，按照普通本科高等学校设置程序，报国务院教育行政部门审批。"},{"i":18,"n":"第十八条","txt":"申请筹设独立学院，须提交下列材料： 　　　 （一）筹设申请书。内容包括：举办者、拟设立独立学院的名称、培养目标、办学规模、办学条件、内部管理体制、经费筹措与管理使用等。 　　　 （二）合作办学协议。 　　　 （三）普通高等学校的基本办学条件，专业设置、学科建设情况，在校学生、专任教师及管理人员状况，本科教学水平评估情况，博士点设置情况。 　　　 （四）社会组织或者个人的法人登记证书或者个人身份证明材料。 　　　 （五）资产来源、资金数额及有效证明文件，并载明产权。其中包括不少于500亩的国有土地使用证或国有土地建设用地规划许可证。 　　　 （六）普通高等学校主管部门审核同意的意见。"},{"i":19,"n":"第十九条","txt":"申请筹设独立学院的，审批机关应当按照民办教育促进法规定的期限，作出是否批准的决定。批准的，发给筹设批准书；不批准的，应当说明理由。"},{"i":20,"n":"第二十条","txt":"完成筹设申请正式设立的，应当提交下列材料： 　　　 （一）正式设立申请书； 　　　 （二）筹设批准书； 　　　 （三）筹设情况报告； 　　　 （四）独立学院章程，理事会或董事会组成人员名单； 　　　 （五）独立学院资产的有效证明文件； 　　　 （六）独立学院院长、教师、财会人员的资格证明文件； 　　　 （七）省级教育行政部门组织的专家评审意见。"},{"i":21,"n":"第二十一条","txt":"独立学院的章程应当规定下列主要事项： 　　　 （一）独立学院的名称、地址； 　　　 （二）办学宗旨、规模等； 　　　 （三）独立学院资产的数额、来源、性质以及财务制度； 　　　 （四）出资人是否要求取得合理回报； 　　　 （五）理事会或者董事会的产生方法、人员构成、权限、任期、议事规则等； 　　　 （六）法定代表人的产生和罢免程序； 　　　 （七）独立学院自行终止的事由； 　　　 （八）章程修改程序。"},{"i":22,"n":"第二十二条","txt":"独立学院的名称前冠以参与举办的普通高等学校的名称，不得使用普通高等学校内设院系和学科的名称。"},{"i":23,"n":"第二十三条","txt":"申请正式设立独立学院，审批机关应当按照民办教育促进法规定的期限，作出是否批准的决定。批准的，发给办学许可证；不批准的，应当说明理由。 　　　 依法设立的独立学院，应当按照国家有关规定办理法人登记。"},{"i":24,"n":"第二十四条","txt":"国务院教育行政部门受理申请筹设和正式设立独立学院的时间为每年第三季度。省级教育行政部门应当在每年9月30日前完成审核工作并提出申请。 　　　 审批机关审批独立学院，应当组织专家评议。专家评议的时间，不计算在审批期限内。"},{"i":25,"n":"第二十五条","txt":"独立学院设立理事会或者董事会，作为独立学院的决策机构。理事会或者董事会由参与举办独立学院的普通高等学校代表、社会组织或者个人代表、独立学院院长、教职工代表等人员组成。理事会或者董事会中，普通高等学校的代表不得少于五分之二。 　　　 理事会或者董事会由5人以上组成，设理事长或者董事长1人。理事长、理事或者董事长、董事名单报审批机关备案。"},{"i":26,"n":"第二十六条","txt":"独立学院的理事会或者董事会每年至少召开2次会议。经三分之一以上组成人员提议，可以召开理事会或者董事会临时会议。 　　　 理事会或者董事会会议应由二分之一以上的理事或者董事出席方可举行。"},{"i":27,"n":"第二十七条","txt":"独立学院理事会或者董事会应当对所议事项形成记录，出席会议的理事或者董事和记录员应当在记录上签名。"},{"i":28,"n":"第二十八条","txt":"独立学院理事会或者董事会会议作出决议，须经全体理事或者董事的过半数通过。但是讨论下列重大事项，须经理事会或者董事会三分之二以上组成人员同意方可通过： 　　　 （一）聘任、解聘独立学院院长； 　　　 （二）修改独立学院章程； 　　　 （三）制定发展规划； 　　　 （四）审核预算、决算； 　　　 （五）决定独立学院的合并、终止； 　　　 （六）独立学院章程规定的其他重大事项。"},{"i":29,"n":"第二十九条","txt":"独立学院院长应当具备国家规定的任职条件，年龄不超过70岁，由参与举办独立学院的普通高等学校优先推荐，理事会或者董事会聘任，并报审批机关核准。 　　　 独立学院院长负责独立学院的教育教学和行政管理工作。"},{"i":30,"n":"第三十条","txt":"独立学院应当按照办学许可证核定的名称、办学地址和办学范围组织开展教育教学活动。不得设立分支机构。不得出租、出借办学许可证。"},{"i":31,"n":"第三十一条","txt":"独立学院必须根据有关规定，建立健全中国共产党和中国共产主义青年团的基层组织。独立学院党组织应当发挥政治核心作用，独立学院团组织应当发挥团结教育学生的重要作用。 　　　 独立学院应当建立教职工代表大会制度，保障教职工参与民主管理和监督。"},{"i":32,"n":"第三十二条","txt":"独立学院的法定代表人为学校安全稳定工作第一责任人。独立学院应当建立健全安全稳定工作机制，建立学校安全保卫工作队伍。落实各项维护安全稳定措施，开展校园及周边治安综合治理，维护校园安全和教学秩序。 　　　 参与举办独立学院的普通高等学校应当根据独立学院的实际情况，积极采取措施，做好安全稳定工作。"},{"i":33,"n":"第三十三条","txt":"独立学院应当按照国家核定的招生规模和国家有关规定招收学生，完善学籍管理制度，做好家庭经济困难学生的资助工作。"},{"i":34,"n":"第三十四条","txt":"独立学院应当按照国家有关规定建立学生管理队伍。按不低于1∶200的师生比配备辅导员，每个班级配备1名班主任。"},{"i":35,"n":"第三十五条","txt":"独立学院应当建立健全教学管理机构，加强教学管理队伍建设。改进教学方式方法，不断提高教育质量。"},{"i":36,"n":"第三十六条","txt":"独立学院应当按照国家有关规定完善教师聘用和管理制度，依法落实和保障教师的相关待遇。"},{"i":37,"n":"第三十七条","txt":"独立学院应当根据核定的办学规模充实办学条件，并符合普通本科高等学校基本办学条件指标的各项要求。"},{"i":38,"n":"第三十八条","txt":"独立学院对学习期满且成绩合格的学生，颁发毕业证书，并以独立学院名称具印。 　　　 独立学院按照国家有关规定申请取得学士学位授予资格，对符合条件的学生颁发独立学院的学士学位证书。"},{"i":39,"n":"第三十九条","txt":"独立学院应当按照国家有关规定建立财务、会计制度和资产管理制度。 　　　 独立学院资产中的国有资产的监督、管理，按照国家有关规定执行。独立学院接受的捐赠财产的使用和管理，按照公益事业捐赠法的有关规定执行。"},{"i":40,"n":"第四十条","txt":"独立学院使用普通高等学校的管理资源和师资、课程等教育教学资源，其相关费用应当按照双方约定或者国家有关规定，列入独立学院的办学成本。"},{"i":41,"n":"第四十一条","txt":"独立学院收费项目和标准的确定，按照国家有关规定执行，并在招生简章和广告中载明。"},{"i":42,"n":"第四十二条","txt":"独立学院存续期间，所有资产由独立学院依法管理和使用，任何组织和个人不得侵占。"},{"i":43,"n":"第四十三条","txt":"独立学院在扣除办学成本、预留发展基金以及按照国家有关规定提取其他必需的费用后，出资人可以从办学结余中取得合理回报。 　　　 出资人取得合理回报的标准和程序，按照民办教育促进法实施条例和国家有关规定执行。"},{"i":44,"n":"第四十四条","txt":"教育行政部门应当加强对独立学院教育教学工作、教师培训工作的指导。 　　　 参与举办独立学院的普通高等学校，应当按照合作办学协议和国家有关规定，对独立学院的教学和管理工作予以指导，完善独立学院教学水平的监测和评估体系。"},{"i":45,"n":"第四十五条","txt":"独立学院的招生简章和广告的样本，应当及时报省级教育行政部门备案。 　　　 未经备案的招生简章和广告，不得发布。"},{"i":46,"n":"第四十六条","txt":"省级教育行政部门应当按照国家有关规定，加强对独立学院的督导和年检工作，对独立学院的办学质量进行监控。"},{"i":47,"n":"第四十七条","txt":"独立学院资产的使用和财务管理受审批机关和其他有关部门的监督。 　　　 独立学院应当在每个会计年度结束时制作财务会计报告，委托会计师事务所依法进行审计，并公布审计结果。"},{"i":48,"n":"第四十八条","txt":"独立学院变更举办者，须由举办者提出，在进行财务清算后，经独立学院理事会或者董事会同意，报审批机关核准。 　　　 独立学院变更地址，应当报审批机关核准。"},{"i":49,"n":"第四十九条","txt":"独立学院变更名称，应当报审批机关批准。"},{"i":50,"n":"第五十条","txt":"独立学院有下述情形之一的，应当终止： 　　　 （一）根据独立学院章程规定要求终止，并经审批机关批准的； 　　　 （二）资不抵债无法继续办学的； 　　　 （三）被吊销办学许可证的。"},{"i":51,"n":"第五十一条","txt":"独立学院终止时，在妥善安置在校学生后，按照民办教育促进法的有关规定进行财务清算和财产清偿。 　　　 独立学院举办者未履行出资义务或者抽逃、挪用办学资金造成独立学院资不抵债无法继续办学的，除依法承担相应的法律责任外，须提供在校学生的后续教育经费。"},{"i":52,"n":"第五十二条","txt":"独立学院终止时仍未毕业的在校学生由参与举办的普通高等学校托管。对学习期满且成绩合格的学生，发给独立学院的毕业证书；符合学位授予条件的，授予独立学院的学士学位证书。"},{"i":53,"n":"第五十三条","txt":"终止的独立学院，除被依法吊销办学许可证的外，按照国家有关规定收回其办学许可证、印章，注销登记。"},{"i":54,"n":"第五十四条","txt":"审批机关及其工作人员，利用职务上的便利收取他人财物或者获取其他利益，滥用职权、玩忽职守，对不符合本办法规定条件者颁发办学许可证，或者发现违法行为不予以查处，情节严重的，对直接负责的主管人员和其他直接人员，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":55,"n":"第五十五条","txt":"独立学院举办者虚假出资或者在独立学院设立后抽逃资金、挪用办学经费的，由省级教育行政部门会同有关部门责令限期改正，并按照民办教育促进法的有关规定给予处罚。"},{"i":56,"n":"第五十六条","txt":"独立学院有下列情形之一的，由省级教育行政部门责令限期改正，并视情节轻重，给予警告、1至3万元的罚款、减少招生计划或者暂停招生的处罚： 　　　 （一）独立学院资产不按期过户的； 　　　 （二）发布未经备案的招生简章或广告的； 　　　 （三）年检不合格的； 　　　 （四）违反国家招生计划擅自招收学生的。"},{"i":57,"n":"第五十七条","txt":"独立学院违反民办教育促进法以及其他法律法规规定的，由省级教育行政部门或者会同有关部门给予处罚。"},{"i":58,"n":"第五十八条","txt":"本办法施行前设立的独立学院，按照本办法的规定进行调整，充实办学条件，完成有关工作。本办法施行之日起5年内，基本符合本办法要求的，由独立学院提出考察验收申请，经省级教育行政部门审核后报国务院教育行政部门组织考察验收，考察验收合格的，核发办学许可证。"},{"i":59,"n":"第五十九条","txt":"本办法自2008年4月1日起施行。此前国务院教育行政部门发布的有关独立学院设置与管理的文件与本办法不一致的，以本办法为准。"}],"gaodengxuexiaoxinxigongkaibanfa":[{"i":1,"n":"第一条","txt":"为了保障公民、法人和其他组织依法获取高等学校信息，促进高等学校依法治校，根据高等教育法和政府信息公开条例的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"高等学校在开展办学活动和提供社会公共服务过程中产生、制作、获取的以一定形式记录、保存的信息，应当按照有关法律法规和本办法的规定公开。"},{"i":3,"n":"第三条","txt":"国务院教育行政部门负责指导、监督全国高等学校信息公开工作。 省级教育行政部门负责统筹推进、协调、监督本行政区域内高等学校信息公开工作。"},{"i":4,"n":"第四条","txt":"高等学校应当遵循公正、公平、便民的原则，建立信息公开工作机制和各项工作制度。 高等学校公开信息，不得危及国家安全、公共安全、经济安全、社会稳定和学校安全稳定。"},{"i":5,"n":"第五条","txt":"高等学校应当建立健全信息发布保密审查机制，明确审查的程序和责任。高等学校公开信息前，应当依照法律法规和国家其他有关规定对拟公开的信息进行保密审查。 有关信息依照国家有关规定或者根据实际情况需要审批的，高等学校应当按照规定程序履行审批手续，未经批准不得公开。"},{"i":6,"n":"第六条","txt":"高等学校发现不利于校园和社会稳定的虚假信息或者不完整信息的，应当在其职责范围内及时发布准确信息予以澄清。"},{"i":7,"n":"第七条","txt":"高等学校应当主动公开以下信息： （一）学校名称、办学地点、办学性质、办学宗旨、办学层次、办学规模，内部管理体制、机构设置、学校领导等基本情况； （二）学校章程以及学校制定的各项规章制度； （三）学校发展规划和年度工作计划； （四）各层次、类型学历教育招生、考试与录取规定，学籍管理、学位评定办法，学生申诉途径与处理程序；毕业生就业指导与服务情况等; （五）学科与专业设置，重点学科建设情况，课程与教学计划，实验室、仪器设备配置与图书藏量，教学与科研成果评选，国家组织的教学评估结果等； （六）学生奖学金、助学金、学费减免、助学贷款与勤工俭学的申请与管理规定等； （七）教师和其他专业技术人员数量、专业技术职务等级，岗位设置管理与聘用办法，教师争议解决办法等; （八）收费的项目、依据、标准与投诉方式； （九）财务、资产与财务管理制度，学校经费来源、年度经费预算决算方案，财政性资金、受捐赠财产的使"},{"i":8,"n":"第八条","txt":"除第七条规定需要公开的信息外，高等学校应当明确其他需要主动公开的信息内容与公开范围。"},{"i":9,"n":"第九条","txt":"除高等学校已公开的信息外，公民、法人和其他组织还可以根据自身学习、科研、工作等特殊需要，以书面形式（包括数据电文形式）向学校申请获取相关信息。"},{"i":10,"n":"第十条","txt":"高等学校对下列信息不予公开： （一）涉及国家秘密的； （二）涉及商业秘密的； （三）涉及个人隐私的； （四）法律、法规和规章以及学校规定的不予公开的其他信息。 其中第（二）项、第（三）项所列的信息，经权利人同意公开或者高校认为不公开可能对公共利益造成重大影响的，可以予以公开。"},{"i":11,"n":"第十一条","txt":"高等学校校长领导学校的信息公开工作。校长（学校）办公室为信息公开工作机构，负责学校信息公开的日常工作，具体职责是： （一）具体承办本校信息公开事宜； （二）管理、协调、维护和更新本校公开的信息； （三）统一受理、协调处理、统一答复向本校提出的信息公开申请； （四）组织编制本校的信息公开指南、信息公开目录和信息公开工作年度报告； （五）协调对拟公开的学校信息进行保密审查； （六）组织学校信息公开工作的内部评议； （七）推进、监督学校内设组织机构的信息公开； （八）承担与本校信息公开有关的其他职责。 高等学校应当向社会公开信息公开工作机构的名称、负责人、办公地址、办公时间、联系电话、传真号码、电子邮箱等。"},{"i":12,"n":"第十二条","txt":"对依照本办法规定需要公开的信息，高等学校应当根据实际情况，通过学校网站、校报校刊、校内广播等校内媒体和报刊、杂志、广播、电视等校外媒体以及新闻发布会、年鉴、会议纪要或者简报等方式予以公开；并根据需要设置公共查阅室、资料索取点、信息公告栏或者电子屏幕等场所、设施。"},{"i":13,"n":"第十三条","txt":"高等学校应当在学校网站开设信息公开意见箱，设置信息公开专栏、建立有效链接，及时更新信息，并通过信息公开意见箱听取对学校信息公开工作的意见和建议。"},{"i":14,"n":"第十四条","txt":"高等学校应当编制信息公开指南和目录，并及时公布和更新。信息公开指南应当明确信息公开工作机构，信息的分类、编排体系和获取方式，依申请公开的处理和答复流程等。信息公开目录应当包括信息的索引、名称、生成日期、责任部门等内容。"},{"i":15,"n":"第十五条","txt":"高等学校应当将学校基本的规章制度汇编成册，置于学校有关内部组织机构的办公地点、档案馆、图书馆等场所，提供免费查阅。 高等学校应当将学生管理制度、教师管理制度分别汇编成册，在新生和新聘教师报到时发放。"},{"i":16,"n":"第十六条","txt":"高等学校完成信息制作或者获取信息后，应当及时明确该信息是否公开。确定公开的，应当明确公开的受众；确定不予公开的，应当说明理由；难以确定是否公开的，应当及时报请高等学校所在地省级教育行政部门或者上级主管部门审定。"},{"i":17,"n":"第十七条","txt":"属于主动公开的信息，高等学校应当自该信息制作完成或者获取之日起20个工作日内予以公开。公开的信息内容发生变更的，应当在变更后20个工作日内予以更新。 学校决策事项需要征求教师、学生和学校其他工作人员意见的，公开征求意见的期限不得少于10个工作日。 法律法规对信息内容公开的期限另有规定的，从其规定。"},{"i":18,"n":"第十八条","txt":"对申请人的信息公开申请，高等学校根据下列情况在15个工作日内分别作出答复： （一）属于公开范围的，应当告知申请人获取该信息的方式和途径； （二）属于不予公开范围的，应当告知申请人并说明理由； （三）不属于本校职责范围的或者该信息不存在的，应当告知申请人，对能够确定该信息的职责单位的，应当告知申请人该单位的名称、联系方式； （四）申请公开的信息含有不应当公开的内容但能够区分处理的，应当告知申请人并提供可以公开的信息内容，对不予公开的部分，应当说明理由； （五）申请内容不明确的，应当告知申请人作出更改、补充；申请人逾期未补正的，视为放弃本次申请； （六）同一申请人无正当理由重复向同一高等学校申请公开同一信息，高等学校已经作出答复且该信息未发生变化的，应当告知申请人，不再重复处理； （七）高等学校根据实际情况作出的其他答复。"},{"i":19,"n":"第十九条","txt":"申请人向高等学校申请公开信息的，应当出示有效身份证件或者证明文件。 申请人有证据证明高等学校提供的与自身相关的信息记录不准确的，有权要求该高等学校予以更正；该高等学校无权更正的，应当转送有权更正的单位处理，并告知申请人。"},{"i":20,"n":"第二十条","txt":"高等学校向申请人提供信息，可以按照学校所在地省级价格部门和财政部门规定的收费标准收取检索、复制、邮寄等费用。收取的费用应当纳入学校财务管理。 高等学校不得通过其他组织、个人以有偿方式提供信息。"},{"i":21,"n":"第二十一条","txt":"高等学校应当健全内部组织机构的信息公开制度，明确其信息公开的具体内容。"},{"i":22,"n":"第二十二条","txt":"国务院教育行政部门开展对全国高等学校推进信息公开工作的监督检查。 省级教育行政部门应当加强对本行政区域内高等学校信息公开工作的日常监督检查。 高等学校主管部门应当将信息公开工作开展情况纳入高等学校领导干部考核内容。"},{"i":23,"n":"第二十三条","txt":"省级教育行政部门和高等学校应当将信息公开工作纳入干部岗位责任考核内容。考核工作可与年终考核结合进行。 高等学校内设监察部门负责组织对本校信息公开工作的监督检查，监督检查应当有教师、学生和学校其他工作人员代表参加。"},{"i":24,"n":"第二十四条","txt":"高等学校应当编制学校上一学年信息公开工作年度报告，并于每年10月底前报送所在地省级教育行政部门。中央部门所属高校，还应当报送其上级主管部门。"},{"i":25,"n":"第二十五条","txt":"省级教育行政部门应当建立健全高等学校信息公开评议制度，聘请人大代表、政协委员、家长、教师、学生等有关人员成立信息公开评议委员会或者以其他形式，定期对本行政区域内高等学校信息公开工作进行评议，并向社会公布评议结果。"},{"i":26,"n":"第二十六条","txt":"公民、法人和其他组织认为高等学校未按照本办法规定履行信息公开义务的，可以向学校内设监察部门、省级教育行政部门举报；对于中央部委所属高等学校，还可向其上级主管部门举报。收到举报的部门应当及时处理，并以适当方式向举报人告知处理结果。"},{"i":27,"n":"第二十七条","txt":"高等学校违反有关法律法规或者本办法规定，有下列情形之一的，由省级教育行政部门责令改正；情节严重的，由省级教育行政部门或者国务院教育行政部门予以通报批评；对高等学校直接负责的主管领导和其他直接责任人员，由高等学校主管部门依据有关规定给予处分： （一）不依法履行信息公开义务的； （二）不及时更新公开的信息内容、信息公开指南和目录的； （三）公开不应当公开的信息的； （四）在信息公开工作中隐瞒或者捏造事实的； （五）违反规定收取费用的； （六）通过其他组织、个人以有偿服务方式提供信息的； （七）违反有关法律法规和本办法规定的其他行为的。 高等学校上述行为侵害当事人合法权益，造成损失的，应当依法承担民事责任。"},{"i":28,"n":"第二十八条","txt":"高等学校应当将开展信息公开工作所需经费纳入年度预算，为学校信息公开工作提供经费保障。"},{"i":29,"n":"第二十九条","txt":"本办法所称的高等学校，是指大学、独立设置的学院和高等专科学校，其中包括高等职业学校和成人高等学校。 高等学校以外其他高等教育机构的信息公开，参照本办法执行。"},{"i":30,"n":"第三十条","txt":"已经移交档案工作机构的高等学校信息的公开，依照有关档案管理的法律、法规和规章执行。"},{"i":31,"n":"第三十一条","txt":"省级教育行政部门可以根据需要制订实施办法。高等学校应当依据本办法制订实施细则。"},{"i":32,"n":"第三十二条","txt":"本办法自2010年9月1日起施行。"}],"gaodengxuexiaoxueshuweiyuanhuiguicheng":[{"i":1,"n":"第一条","txt":"为促进高等学校规范和加强学术委员会建设，完善内部治理结构，保障学术委员会在教学、科研等学术事务中有效发挥作用，根据《中华人民共和国高等教育法》及相关规定，制定本规程。"},{"i":2,"n":"第二条","txt":"高等学校应当依法设立学术委员会，健全以学术委员会为核心的学术管理体系与组织架构；并以学术委员会作为校内最高学术机构，统筹行使学术事务的决策、审议、评定和咨询等职权。 实施本科以上教育的普通高等学校学术委员会的组成、职责与运行等，适用本规程。"},{"i":3,"n":"第三条","txt":"高等学校应当充分发挥学术委员会在学科建设、学术评价、学术发展和学风建设等事项上的重要作用，完善学术管理的体制、制度和规范，积极探索教授治学的有效途径，尊重并支持学术委员会独立行使职权，并为学术委员会正常开展工作提供必要的条件保障。"},{"i":4,"n":"第四条","txt":"高等学校学术委员会应当遵循学术规律，尊重学术自由、学术平等，鼓励学术创新，促进学术发展和人才培养，提高学术质量；应当公平、公正、公开地履行职责，保障教师、科研人员和学生在教学、科研和学术事务管理中充分发挥主体作用，促进学校科学发展。"},{"i":5,"n":"第五条","txt":"高等学校应当结合实际，依据本规程，制定学术委员会章程或者通过学校章程，具体明确学术委员会组成、职责，以及委员的产生程序、增补办法，会议制度和议事规则及其他本规程未尽事宜。"},{"i":6,"n":"第六条","txt":"学术委员会一般应当由学校不同学科、专业的教授及具有正高级以上专业技术职务的人员组成，并应当有一定比例的青年教师。 学术委员会人数应当与学校的学科、专业设置相匹配，并为不低于15人的单数。其中，担任学校及职能部门党政领导职务的委员，不超过委员总人数的1/4；不担任党政领导职务及院系主要负责人的专任教授，不少于委员总人数的1/2。 学校可以根据需要聘请校外专家及有关方面代表，担任专门学术事项的特邀委员。"},{"i":7,"n":"第七条","txt":"学术委员会委员应当具备以下条件： （一）遵守宪法法律，学风端正、治学严谨、公道正派； （二）学术造诣高，在本学科或者专业领域具有良好的学术声誉和公认的学术成果； （三） 关心学校建设和发展，有参与学术议事的意愿和能力，能够正常履行职责； （四）学校规定的其他条件。"},{"i":8,"n":"第八条","txt":"学校应当根据学科、专业构成情况，合理确定院系（学部）的委员名额，保证学术委员会的组成具有广泛的学科代表性和公平性。 学术委员会委员的产生，应当经自下而上的民主推荐、公开公正的遴选等方式产生候选人，由民主选举等程序确定，充分反映基层学术组织和广大教师的意见。 特邀委员由校长、学术委员会主任委员或者1/3以上学术委员会委员提名，经学术委员会同意后确定。"},{"i":9,"n":"第九条","txt":"学术委员会委员由校长聘任。 学术委员会委员实行任期制，任期一般可为4年，可连选连任，但连任最长不超过2届。 学术委员会每次换届，连任的委员人数应不高于委员总数的2/3。"},{"i":10,"n":"第十条","txt":"学术委员会设主任委员1名，可根据需要设若干名副主任委员。主任委员可由校长提名，全体委员选举产生；也可以采取直接由全体委员选举等方式产生，具体办法由学校规定。"},{"i":11,"n":"第十一条","txt":"学术委员会可以就学科建设、教师聘任、教学指导、科学研究、学术道德等事项设立若干专门委员会，具体承担相关职责和学术事务；应当根据需要，在院系（学部）设置或者按照学科领域设置学术分委员会，也可以委托基层学术组织承担相应职责。 各专门委员会和学术分委员会根据法律规定、学术委员会的授权及各自章程开展工作，向学术委员会报告工作，接受学术委员会的指导和监督。 学术委员会设立秘书处，处理学术委员会的日常事务；学术委员会的运行经费，应当纳入学校预算安排。"},{"i":12,"n":"第十二条","txt":"学术委员会委员在任期内有下列情形，经学术委员会全体会议讨论决定，可免除或同意其辞去委员职务： （一）主动申请辞去委员职务的； （二）因身体、年龄及职务变动等原因不能履行职责的； （三）怠于履行职责或者违反委员义务的； （四）有违法、违反教师职业道德或者学术不端行为的； （五）因其他原因不能或不宜担任委员职务的。"},{"i":13,"n":"第十三条","txt":"学术委员会委员享有以下权利： （一）知悉与学术事务相关的学校各项管理制度、信息等； （二）就学术事务向学校相关职能部门提出咨询或质询； （三）在学术委员会会议中自由、独立地发表意见，讨论、审议和表决各项决议； （四）对学校学术事务及学术委员会工作提出建议、实施监督； （五）学校章程或者学术委员会章程规定的其他权利。 特邀委员根据学校的规定，享有相应权利。"},{"i":14,"n":"第十四条","txt":"学术委员会委员须履行以下义务： （一）遵守国家宪法、法律和法规，遵守学术规范、恪守学术道德； （二）遵守学术委员会章程，坚守学术专业判断，公正履行职责； （三）勤勉尽职，积极参加学术委员会会议及有关活动； （四）学校章程或者学术委员会章程规定的其他义务。"},{"i":15,"n":"第十五条","txt":"学校下列事务决策前，应当提交学术委员会审议，或者交由学术委员会审议并直接做出决定： （一）学科、专业及教师队伍建设规划，以及科学研究、对外学术交流合作等重大学术规划； （二）自主设置或者申请设置学科专业； （三）学术机构设置方案，交叉学科、跨学科协同创新机制的建设方案、学科资源的配置方案； （四）教学科研成果、人才培养质量的评价标准及考核办法； （五）学位授予标准及细则，学历教育的培养标准、教学计划方案、招生的标准与办法； （六）学校教师职务聘任的学术标准与办法； （七）学术评价、争议处理规则，学术道德规范； （八）学术委员会专门委员会组织规程，学术分委员会章程； （九）学校认为需要提交审议的其他学术事务。"},{"i":16,"n":"第十六条","txt":"学校实施以下事项，涉及对学术水平做出评价的，应当由学术委员会或者其授权的学术组织进行评定： （一）学校教学、科学研究成果和奖励，对外推荐教学、科学研究成果奖； （二）高层次人才引进岗位人选、名誉（客座）教授聘任人选，推荐国内外重要学术组织的任职人选、人才选拔培养计划人选； （三）自主设立各类学术、科研基金、科研项目以及教学、科研奖项等； （四）需要评价学术水平的其他事项。"},{"i":17,"n":"第十七条","txt":"学校做出下列决策前，应当通报学术委员会，由学术委员会提出咨询意见： （一）制订与学术事务相关的全局性、重大发展规划和发展战略； （二）学校预算决算中教学、科研经费的安排和分配及使用； （三）教学、科研重大项目的申报及资金的分配使用； （四）开展中外合作办学、赴境外办学，对外开展重大项目合作； （五）学校认为需要听取学术委员会意见的其他事项。 学术委员会对上述事项提出明确不同意见的，学校应当做出说明、重新协商研究或者暂缓执行。"},{"i":18,"n":"第十八条","txt":"学术委员会按照有关规定及学校委托，受理有关学术不端行为的举报并进行调查，裁决学术纠纷。 学术委员会调查学术不端行为、裁决学术纠纷，应当组织具有权威性和中立性的专家组，从学术角度独立调查取证，客观公正地进行调查认定。专家组的认定结论，当事人有异议的，学术委员会应当组织复议，必要的可以举行听证。 对违反学术道德的行为，学术委员会可以依职权直接撤销或者建议相关部门撤销当事人相应的学术称号、学术待遇，并可以同时向学校、相关部门提出处理建议。"},{"i":19,"n":"第十九条","txt":"学术委员会实行例会制度，每学期至少召开1次全体会议。根据工作需要，经学术委员会主任委员或者校长提议，或者1/3以上委员联名提议，可以临时召开学术委员会全体会议，商讨、决定相关事项。 学术委员会可以授权专门委员会处理专项学术事务，履行相应职责。"},{"i":20,"n":"第二十条","txt":"学术委员会主任委员负责召集和主持学术委员会会议，必要时，可以委托副主任委员召集和主持会议。学术委员会委员全体会议应有2/3以上委员出席方可举行。 学术委员会全体会议应当提前确定议题并通知与会委员。经与会1/3以上委员同意，可以临时增加议题。"},{"i":21,"n":"第二十一条","txt":"学术委员会议事决策实行少数服从多数的原则，重大事项应当以与会委员的2/3以上同意，方可通过。 学术委员会会议审议决定或者评定的事项，一般应当以无记名投票方式做出决定；也可以根据事项性质，采取实名投票方式。 学术委员会审议或者评定的事项与委员本人及其配偶和直系亲属有关，或者具有利益关联的，相关委员应当回避。"},{"i":22,"n":"第二十二条","txt":"学术委员会会议可以根据议题，设立旁听席，允许相关学校职能部门、教师及学生代表列席旁听。 学术委员会做出的决定应当予以公示，并设置异议期。在异议期内如有异议，经1/3以上委员同意，可召开全体会议复议。经复议的决定为终局结论。"},{"i":23,"n":"第二十三条","txt":"学术委员会应当建立年度报告制度，每年度对学校整体的学术水平、学科发展、人才培养质量等进行全面评价，提出意见、建议；对学术委员会的运行及履行职责的情况进行总结。 学术委员会年度报告应提交教职工代表大会审议，有关意见、建议的采纳情况，校长应当做出说明。"},{"i":24,"n":"第二十四条","txt":"高等职业学校、成人高等学校可以参照本规程，结合自身特点，确定学术委员会的组成及职责，制定学术委员会章程。"},{"i":25,"n":"第二十五条","txt":"高等学校现有学术委员会的组成、职责等与本规程不一致的，学校通过经核准的章程已予以规范的，可以按照学校章程的规定实施；学校章程未规定的，应当按照本规程进行调整、规范。"},{"i":26,"n":"第二十六条","txt":"本规程自2014年3月1日起施行。 教育部此前发布的有关规章、文件中的相关规定与本规程不一致的，以本规程为准。"}],"gaodengxuexiaoshiyanshigongzuoguicheng":[{"i":1,"n":"第一条","txt":"为了加强高等学校实验室的建设和管理，保障学校的教育质量和科学研究水平，提高办学效益，特制定本规程。"},{"i":2,"n":"第二条","txt":"高等学校实验室（包括各种操作、训练室），是隶属学校或依托学校管理，从事实验教学或科学研究、生产试验、技术开发的教学或科研实体。"},{"i":3,"n":"第三条","txt":"高等学校实验室，必须努力贯彻国家的教育方针，保证完成实验教学任务，不断提高实验教学水平；根据需要与可能，积极开展科学研究、生产试验和技术开发工作，为经济建设与社会发展服务。"},{"i":4,"n":"第四条","txt":"实验室的建设，要从实际出发，统筹规划，合理设置。要做到建筑设施、仪器设备、技术队伍与科学管理协调发展，提高投资效益。"},{"i":5,"n":"第五条","txt":"根据学校教学计划承担实验教学任务。实验室完善实验指导书、实验教材教学资料，安排实验指导人员，保证完成实验教学任务。"},{"i":6,"n":"第六条","txt":"努力提高实验教学质量。实验室应当吸收科学和教学的新成果，更新实验内容，改革教学方法，通过实验培养学生理论联系实际的学风，严谨的科学态度和分析问题、解决问题的能力。"},{"i":7,"n":"第七条","txt":"根据承担的科研任务，积极开展科学实验工作。努力提高实验技术，完善技术条件和工作环境，以保障高效率、高水平地完成科学实验任务。"},{"i":8,"n":"第八条","txt":"实验室在保证完成教学科研任务的前提下，积极开展社会服务和技术开发，开展学术、技术交流活动。"},{"i":9,"n":"第九条","txt":"完成仪器设备的管理、维修、计量及标定工作，使仪器设备经常处于完好状态。开展实验装置的研究和自制工作。"},{"i":10,"n":"第十条","txt":"严格执行实验室工作的各项规范，加强对工作人员的培训和管理。"},{"i":11,"n":"第十一条","txt":"高等学校实验室的设置，应当具备以下基本条件： （一）有稳定的学科发展方向和饱满的实验教学或科研、技术开发等项任务； （二）有符合实验技术工作要求的房舍、设施及环境； （三）有足够数量、配套的仪器设备； （四）有合格的实验室主任和一定数量的专职工作人员； （五）有科学的工作规范和完善的管理制度。"},{"i":12,"n":"第十二条","txt":"实验室建设、调整与撤销，必须经学校正式批准。依托在高等学校中的部门开放实验室、国家重点实验室的建设、调整与撤销，要经过的上级主管部门批准。"},{"i":13,"n":"第十三条","txt":"实验室的建设与发展规划，要纳入学校及事业总体发展规划，要考虑环境、设施、仪器设备、人员结构、经费投入等综合配套因素，按照立项、论证、实施、监督、竣工、验收、效益考核等“项目管理”办法的程序，由学校或上级主管部门统一归口，全面规划。"},{"i":14,"n":"第十四条","txt":"实验室的建设要按计划进行。其中，房舍、设施及大型设备要依据规划的方案纳入学校基本建设计划；一般仪器设备和运行、维修费要纳入学校财务计划；工作人员的配备与结构调整要纳入学校人事计划。"},{"i":15,"n":"第十五条","txt":"实验室建设经费、要采取多渠道集资的办法。要从教育事业费、基建费、科研费、计划外收入、各种基金中划出一定比例用于实验室建设。凡利用实验室进行有偿服务的，都要将收入的一部分用于实验室建设。"},{"i":16,"n":"第十六条","txt":"有条件的高等学校要积极申请筹建开放型的国家重点实验室、重点学科实验室或工程研究中心等实验室，以适应高科技发展和高层次人才培养的需要。"},{"i":17,"n":"第十七条","txt":"高等学校应通过校际间联合，共同筹建专业实验室或中心实验室。也可以同厂企业、科研单位联合，或引进外资，利用国外先进技术设备，建立对外开放的实验室。"},{"i":18,"n":"第十八条","txt":"凡具备法人条件的高等学校实验室，经有关部门的批准，可取得法人资格。"},{"i":19,"n":"第十九条","txt":"高等学校实验室工作，由国家教育委员会归口管理。省、自治区、直辖市、国务院有关部委的教育主管部门负责本地区或本系统高等学校实验室工作。"},{"i":20,"n":"第二十条","txt":"高等学校应有一名（院）长主管全校实验室工作并建立或确定主管实验室工作的行政机构（处、科）。该机构的主要职责是： （一）贯彻执行国家有关的方针、政策和法令，结合实验室工作的实际，拟定本规程的实施办法； （二）检查督促各实验室完成各项工作任务； （三）组织制定和实施实验室建设规划和年度计划，归口拟定并审查仪器设备配备方案，负责分配实验室建设的仪器设备运行经费，并进行投资效益评估； （四）完善实验室管理制度。包括：实验教学、科研、社会服务情况的审核评估制度；实验室工作人员的任用、管理制度；实验室在用物资的管理制度；经费使用制度等； （五）主管实验室仪器设备、材料等物资，提高其使用效益； （六）主管实验室队伍建设。与人事部门一起做好实验室人员定编、岗位培训、考核、奖惩、晋级职务评聘工作。 规模较大的高校，系一级也可设立相应的实验室管理岗位或机构。"},{"i":21,"n":"第二十一条","txt":"高等学校实验室逐步实行以校、系管理为主的二级管理。规模较大、师资与技术力量较强的高校、也可实行校、系、教研室三级管理。"},{"i":22,"n":"第二十二条","txt":"实验室实行主任负责制。高等学校实验室主任负责实验室的全面工作。"},{"i":23,"n":"第二十三条","txt":"高等学校可根据需要设立实验室工作委员会，由主管校长、有关部门行政负责人和学术、技术、管理等方面的专家组成。对实验室建设、高档仪器设备布局科学管理、人员培训等重大问题进行研究、咨询，提出建议。"},{"i":24,"n":"第二十四条","txt":"实验室要做好工作环境管理和劳动保护工作。要针对高温、低温、辐射、病菌、毒性、激光、粉尘、超净等对人体有害的环境，切实加强实验室环境的监督和劳动保护工作。凡经技术安全的环境保护部门检查认定不合格的实验室，要停止使用，限期进行技术改造，落实管理工作。待重新通过检查合格后，才能投入使用。"},{"i":25,"n":"第二十五条","txt":"实验室要严格遵守国务院颁发的《化学危险品安全管理条例》及《中华人民共和国保守国家秘密法》等有关安全保密的法规的制度，定期检查防火、防爆、防盗、防事故等方面安全措施的落实情况。要经常对师生开展安全保密教育，切实保障人身和财产安全。"},{"i":26,"n":"第二十六条","txt":"实验室要严格遵守国家环境保护工作的有关规定，不随意排放废气、废水、废物、不得污染环境。"},{"i":27,"n":"第二十七条","txt":"实验室仪器设备的材料、低值易耗品等物资的管理，按照《高等学校仪器设备管理办法》、《高等学校材料、低值易耗品管理办法》、《高等学校物资工作的若干规定》等有关法规、规章执行。"},{"i":28,"n":"第二十八条","txt":"实验室所需要的实验动物，要按照国家科委发布的《实验动物管理条例》，以及各地实验动物管理委员会的具体规定,进行饲育、管理、检疫和使用。"},{"i":29,"n":"第二十九条","txt":"计量认证工作先按高校隶属关系由上级主管部门组织对实验室验收合格后部委所属院校的实验室，由国家教委与国家技术监督局组织进行计量认证；地方院校的实验室，由各地省政府高校主管部门与计量行政部门负责计量认证。"},{"i":30,"n":"第三十条","txt":"实验室要建立和健全岗位责任制。要定期对实验室工作人员的工作量和水平考核。"},{"i":31,"n":"第三十一条","txt":"实验室要实行科学管理，完善各项管理规章制度。要采用计算机等现代化手段，对实验室的工作、人员、物资、经费、环境状态信息进行记录、统计和分析，及时为学校或上级主管部门提供实验室情况的准确数据。"},{"i":32,"n":"第三十二条","txt":"要逐步建立高等学校实验室的评估制度。高等学校的各主管部门，可以按照实验室基本条件、实验室管理水平、实验室效益、实验室特色等方面的要求制定评估指标体系细则，对高等学校的实验室开展评估工作。评估结果作为确定各高等学校办学条件和水平的重要因素。"},{"i":33,"n":"第三十三条","txt":"实验室主任要由具有较高的思想政党觉悟，有一定的专业理论修养，有实验教学或科研工作经验，组织管理能力较强的相应专业的讲师（或工程师）以上人员担任。学校系一级以及基础课的实验室，要由相应专业的副教授（或高级工程师）以上的人员担任。"},{"i":34,"n":"第三十四条","txt":"高等学校的实验室主任、副主任均由学校聘任或任命；国家、部门或地区的实验室、实验中心的主任，副主任，由上级主管部门聘任或任命。"},{"i":35,"n":"第三十五条","txt":"实验室主任的主要职责是： （一）负责编制实验室建设规划和计划，并组织实施和检查执行情况； （二）领导并组织完成本地规程第二章规定的实验室工作任务； （三）搞好实验室的科学管理，贯彻、实施有关规章制度； （四）领导本室各类人员的工作，制定岗位责任制，负责对本室专职工作人员的培训及考核； （五）负责本室精神文明建设，抓好工作人员和学生思想政治教育； （六）定期检查、总结实验室工作，开展评比活动等。"},{"i":36,"n":"第三十六条","txt":"高等学校实验室工作人员包括：从事实验室工作的教师、研究人员、工程技术人员、实验技术人员、管理人员和工作。各类人员要有明确的职责分工。要各司其职，同时要做到团结协作，积极完成各项任务。"},{"i":37,"n":"第三十七条","txt":"实验室工程技术人员与实验技术人员的编制，要参照在校学生数，不同类型学校实验教学、科研工作量及实验室仪器设备状况，合理折算后确定。有条件的学校可以进行流动编制。"},{"i":38,"n":"第三十八条","txt":"对于在实验室中从事有害健康工种的工作人员，可参照国家教委（1988）教备局字008号文件《高等学校从事有害健康工种人员营养保健等级和标准的暂行规定》，在严格考勤记录制度的基础上享受保健待遇。"},{"i":39,"n":"第三十九条","txt":"实验室工作人员的岗位职责,由实验室主任根据学校的工作目标,按照国家对不同专业技术干部和工作职责的有关条例定及实施细则具体确定。"},{"i":40,"n":"第四十条","txt":"实验室各类人员的职务聘任、级别晋升工作。根据实验室的工作特点和本人的工作实绩,按照国家和学校的有关规定执行。"},{"i":41,"n":"第四十一条","txt":"高等学校要定期开展实验室工作的检查、评比活动。对成绩显著的集体和个人要进行表彰和鼓励，对违章失职或因工作不负责任造成损失者，提行批评教育或行政处分，直至追究法律责任。"},{"i":42,"n":"第四十二条","txt":"各高等学校要根据本规程，结合本校实际情况，制定各项具体实施办法。"},{"i":43,"n":"第四十三条","txt":"本规程自发布之日起执行。教育部一九八三年十二月十五日印发的《高等学校实验室工作暂行条例》即行失效。"}],"gaodengxuexiaodanganguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范高等学校档案工作，提高档案管理水平，有效保护和利用档案，根据《中华人民共和国档案法》及其实施办法，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称的高等学校档案(以下简称高校档案)，是指高等学校从事招生、教学、科研、管理等活动直接形成的对学生、学校和社会有保存价值的各种文字、图表、声像等不同形式、载体的历史记录。"},{"i":3,"n":"第三条","txt":"高校档案工作是高等学校重要的基础性工作，学校应当加强管理，将之纳入学校整体发展规划。"},{"i":4,"n":"第四条","txt":"国务院教育行政部门主管全国高校档案工作。省、自治区、直辖市人民政府教育行政部门主管本行政区域内高校档案工作。 　 国家档案行政部门和省、自治区、直辖市人民政府档案行政部门在职责范围内负责对高校档案工作的业务指导、监督和检查。"},{"i":5,"n":"第五条","txt":"高校档案工作由高等学校校长领导，其主要职责是： 　 (一)贯彻执行国家关于档案管理的法律法规和方针政策，批准学校档案工作规章制度； 　 (二)将档案工作纳入学校整体发展规划，促进档案信息化建设与学校其他工作同步发展； 　 (三)建立健全与办学规模相适应的高校档案机构，落实人员编制、档案库房、发展档案事业所需设备以及经费； 　 (四)研究决定高校档案工作中的重要奖惩和其他重大问题。 　 分管档案工作的校领导协助校长负责档案工作。"},{"i":6,"n":"第六条","txt":"高校档案机构包括档案馆和综合档案室。 　 具备下列条件之一的高等学校应当设立档案馆： 　 (一)建校历史在50年以上； 　 (二)全日制在校生规模在1万人以上； 　 (三)已集中保管的档案、资料在3万卷(长度300延长米)以上。 　 未设立档案馆的高等学校应当设立综合档案室。"},{"i":7,"n":"第七条","txt":"高校档案机构是保存和提供利用学校档案的专门机构，应当具备符合要求的档案库房和管理设施。 　 需要特殊条件保管或者利用频繁且具有一定独立性的档案，可以根据实际需要设立分室单独保管。分室是高校档案机构的分支机构。"},{"i":8,"n":"第八条","txt":"高校档案机构的管理职责是： 　 (一)贯彻执行国家有关档案工作的法律法规和方针政策，综合规划学校档案工作； 　 (二)拟订学校档案工作规章制度，并负责贯彻落实； 　 (三)负责接收(征集)、整理、鉴定、统计、保管学校的各类档案及有关资料； 　 (四)编制检索工具，编研、出版档案史料，开发档案信息资源； 　 (五)组织实施档案信息化建设和电子文件归档工作； 　 (六)开展档案的开放和利用工作； 　 (七)开展学校档案工作人员的业务培训； 　 (八)利用档案开展多种形式的宣传教育活动，充分发挥档案的文化教育功能； 　 (九)开展国内外档案学术研究和交流活动。 　 有条件的高校档案机构，可以申请创设爱国主义教育基地。"},{"i":9,"n":"第九条","txt":"高校档案馆设馆长一名，根据需要可以设副馆长一至二名。综合档案室设主任一名，根据需要可以设副主任一至二名。 　 馆长、副馆长和综合档案室主任(馆长和综合档案室主任，以下简称为高校档案机构负责人)，应当具备以下条件： 　 (一)热心档案事业，具有高级以上专业技术职务任职经历； 　 (二)有组织管理能力，具有开拓创新意识和精神； 　 (三)年富力强，身体健康。"},{"i":10,"n":"第十条","txt":"高等学校应当为高校档案机构配备专职档案工作人员。 　 高校专职档案工作人员列入学校事业编制。其编制人数由学校根据本校档案机构的档案数量和工作任务确定。"},{"i":11,"n":"第十一条","txt":"高校档案工作人员应当遵纪守法，爱岗敬业，忠于职守，具备档案业务知识和相应的科学文化知识以及现代化管理技能。"},{"i":12,"n":"第十二条","txt":"高校档案机构中的专职档案工作人员，实行专业技术职务聘任制或者职员职级制，享受学校教学、科研和管理人员同等待遇。"},{"i":13,"n":"第十三条","txt":"高等学校对长期接触有毒有害物质的档案工作人员，应当按照法律法规的有关规定采取有效的防护措施防止职业中毒事故的发生，保障其依法享有工伤社会保险待遇以及其他有关待遇，并可以按照有关规定予以补助。"},{"i":14,"n":"第十四条","txt":"高等学校应当建立、健全档案工作的检查、考核与评估制度，定期布置、检查、总结、验收档案工作，明确岗位职责，强化责任意识，提高学校档案管理水平。"},{"i":15,"n":"第十五条","txt":"高等学校应当对纸质档案材料和电子档案材料同步归档。文件材料的归档范围是： 　 (一)党群类：主要包括高等学校党委、工会、团委、民主党派等组织的各种会议文件、会议记录及纪要；各党群部门的工作计划、总结；上级机关与学校关于党群管理的文件材料。 　 (二)行政类：主要包括高等学校行政工作的各种会议文件、会议纪录及纪要；上级机关与学校关于人事管理、行政管理的材料。 　 (三)学生类：主要包括高等学校培养的学历教育学生的高中档案、入学登记表、体检表、学籍档案、奖惩记录、党团组织档案、毕业生登记表等。 　 (四)教学类：主要包括反映教学管理、教学实践和教学研究等活动的文件材料。按原国家教委、国家档案局发布的《高等学校教学文件材料归档范围》((87)教办字016号)的相关规定执行。 　 (五)科研类：按原国家科委、国家档案局发布的《科学技术研究档案管理暂行规定》(国档发〔1987〕6号)执行。"},{"i":16,"n":"第十六条","txt":"高等学校实行档案材料形成单位、课题组立卷的归档制度。 　 学校各部门负责档案工作的人员应当按照归档要求，组织本部门的教学、科研和管理等人员及时整理档案和立卷。立卷人应当按照纸质文件材料和电子文件材料的自然形成规律，对文件材料系统整理组卷，编制页号或者件号，制作卷内目录，交本部门负责档案工作的人员检查合格后向高校档案机构移交。"},{"i":17,"n":"第十七条","txt":"归档的档案材料应当质地优良，书绘工整，声像清晰，符合有关规范和标准的要求。电子文件的归档要求按照国家档案局发布的《电子公文归档管理暂行办法》以及《电子文件归档与管理规范》(GB／T 18894-2002)执行。"},{"i":18,"n":"第十八条","txt":"高校档案材料归档时间为： 　 (一)学校各部门应当在次学年6月底前归档； 　 (二)各院系等应当在次学年寒假前归档； 　 (三)科研类档案应当在项目完成后两个月内归档，基建类档案应当在项目完成后三个月内归档。"},{"i":19,"n":"第十九条","txt":"高校档案机构应当对档案进行整理、分类、鉴定和编号。"},{"i":20,"n":"第二十条","txt":"高校档案机构应当按照国家档案局《机关文件材料归档范围和文书档案保管期限规定》，确定档案材料的保管期限。对保管期限已满、已失去保存价值的档案，经有关部门鉴定并登记造册报校长批准后，予以销毁。未经鉴定和批准，不得销毁任何档案。"},{"i":21,"n":"第二十一条","txt":"高校档案机构应当采用先进的档案保护技术，防止档案的破损、褪色、霉变和散失。对已经破损或者字迹褪色的档案，应当及时修复或者复制。对重要档案和破损、褪色修复的档案应当及时数字化，加工成电子档案保管。"},{"i":22,"n":"第二十二条","txt":"高校档案由高校档案机构保管。在国家需要时，高等学校应当提供所需的档案原件或者复制件。"},{"i":23,"n":"第二十三条","txt":"高等学校与其他单位分工协作完成的项目，高校档案机构应当至少保存一整套档案。协作单位除保存与自己承担任务有关的档案正本以外，应当将复制件送交高校档案机构保存。"},{"i":24,"n":"第二十四条","txt":"高等学校中的个人对其从事教学、科研、管理等职务活动所形成的各种载体形式的档案材料，应当按照规定及时归档，任何个人不得据为己有。 　 对于个人在其非职务活动中形成的重要档案材料，高校档案机构可以通过征集、代管等形式进行管理。 　 高校档案机构对于与学校有关的各种档案史料的征集，应当制定专门的制度和办法。"},{"i":25,"n":"第二十五条","txt":"高校档案机构应当对所存档案和资料的保管情况定期检查，消除安全隐患，遇有特殊情况，应当立即向校长报告，及时处理。 　 档案库房的技术管理工作，应当建立、健全有关规章制度，由专人负责。"},{"i":26,"n":"第二十六条","txt":"高校档案机构应当认真执行档案统计年报制度，并按照国家有关规定报送档案工作基本情况统计报表。"},{"i":27,"n":"第二十七条","txt":"高校档案机构应当按照国家有关规定公布档案。未经高等学校授权，其他任何组织或者个人无权公布学校档案。 　 属下列情况之一者，不对外公布： 　 (一)涉及国家秘密的； 　 (二)涉及专利或者技术秘密的； 　 (三)涉及个人隐私的； 　 (四)档案形成单位规定限制利用的。"},{"i":28,"n":"第二十八条","txt":"凡持有合法证明的单位或者持有合法身份证明的个人，在表明利用档案的目的和范围并履行相关登记手续后，均可以利用已公布的档案。 　 境外组织或者个人利用档案的，按照国家有关规定办理。"},{"i":29,"n":"第二十九条","txt":"查阅、摘录、复制未开放的档案，应当经档案机构负责人批准。涉及未公开的技术问题，应当经档案形成单位或者本人同意，必要时报请校长审查批准。需要利用的档案涉及重大问题或者国家秘密，应当经学校保密工作部门批准。"},{"i":30,"n":"第三十条","txt":"高校档案机构提供利用的重要、珍贵档案，一般不提供原件。如有特殊需要，应当经档案机构负责人批准。 　 加盖高校档案机构公章的档案复制件，与原件具有同等效力。"},{"i":31,"n":"第三十一条","txt":"高校档案开放应当设立专门的阅览室，并编制必要的检索工具(著录标准按《档案著录规则》(DA／T18-1999)执行)，提供开放档案目录、全宗指南、档案馆指南、计算机查询系统等，为社会利用档案创造便利条件。"},{"i":32,"n":"第三十二条","txt":"高校档案机构是学校出具档案证明的唯一机构。 　 高校档案机构应当为社会利用档案创造便利条件，用于公益目的的，不得收取费用；用于个人或者商业目的的，可以按照有关规定合理收取费用。 　 社会组织和个人利用其所移交、捐赠的档案，高校档案机构应当无偿和优先提供。"},{"i":33,"n":"第三十三条","txt":"寄存在高校档案机构的档案，归寄存者所有。高校档案机构如果需要向社会提供利用，应当征得寄存者同意。"},{"i":34,"n":"第三十四条","txt":"高校档案机构应当积极开展档案的编研工作。出版档案史料和公布档案，应当经档案形成单位同意，并报请校长批准。"},{"i":35,"n":"第三十五条","txt":"高校档案机构应当采取多种形式(如举办档案展览、陈列、建设档案网站等)，积极开展档案宣传工作。有条件的高校，应当在相关专业的高年级开设有关档案管理的选修课。"},{"i":36,"n":"第三十六条","txt":"高等学校应当将高校档案工作所需经费列入学校预算，保证档案工作的需求。"},{"i":37,"n":"第三十七条","txt":"高等学校应当为档案机构提供专用的、符合档案管理要求的档案库房，对不适应档案事业发展需要或者不符合档案保管要求的馆库，按照《档案馆建设标准》(建标103-2008)的要求及时进行改扩建或者新建。 　 存放涉密档案应当设有专门库房。 　 存放声像、电子等特殊载体档案，应当配置恒温、恒湿、防火、防渍、防有害生物等必要设施。"},{"i":38,"n":"第三十八条","txt":"高等学校应当设立专项经费，为档案机构配置档案管理现代化、档案信息化所需的设备设施，加快数字档案馆(室)建设，保障档案信息化建设与学校数字化校园建设同步进行。"},{"i":39,"n":"第三十九条","txt":"高等学校对在档案工作中做出下列贡献的单位或者个人，给予表彰与奖励： 　 (一)在档案的收集、整理、提供利用工作中做出显著成绩的； 　 (二)在档案的保护和现代化管理工作中做出显著成绩的； 　 (三)在档案学研究及档案史料研究工作中做出重要贡献的； 　 (四)将重要的或者珍贵的档案捐赠给高校档案机构的； 　 (五)同违反档案法律法规的行为作斗争，表现突出的。"},{"i":40,"n":"第四十条","txt":"有下列行为之一的，高等学校应当对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，由司法机关依法追究刑事责任。 　 (一)玩忽职守，造成档案损坏、丢失或者擅自销毁档案的； 　 (二)违反保密规定，擅自提供、抄录、公布档案的； 　 (三)涂改、伪造档案的； 　 (四)擅自出卖、赠送、交换档案的； 　 (五)不按规定归档，拒绝归档或者将档案据为己有的； 　 (六)其他违反档案法律法规的行为。"},{"i":41,"n":"第四十一条","txt":"本办法适用于各类普通高等学校、成人高等学校。"},{"i":42,"n":"第四十二条","txt":"高等学校可以根据本办法制订实施细则。 　 高等学校附属单位(包括附属医院、校办企业等)的档案管理，由学校根据实际情况自主确定。"},{"i":43,"n":"第四十三条","txt":"本办法自2008年9月1日起施行。国家教育委员会1989年10月10日发布的《普通高等学校档案管理办法》(国家教育委员会令第6号)同时废止。"}],"gaodengxuexiaoxiaofanganquanguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强和规范高等学校的消防安全管理，预防和减少火灾危害，保障师生员工生命财产和学校财产安全，根据消防法、高等教育法等法律、法规，制定本规定。"},{"i":2,"n":"第二条","txt":"普通高等学校和成人高等学校（以下简称学校）的消防安全管理，适用本规定。 驻校内其他单位的消防安全管理，按照本规定的有关规定执行。"},{"i":3,"n":"第三条","txt":"学校在消防安全工作中，应当遵守消防法律、法规和规章，贯彻预防为主、防消结合的方针，履行消防安全职责，保障消防安全。"},{"i":4,"n":"第四条","txt":"学校应当落实逐级消防安全责任制和岗位消防安全责任制，明确逐级和岗位消防安全职责，确定各级、各岗位消防安全责任人。"},{"i":5,"n":"第五条","txt":"学校应当开展消防安全教育和培训，加强消防演练，提高师生员工的消防安全意识和自救逃生技能。"},{"i":6,"n":"第六条","txt":"学校各单位和师生员工应当依法履行保护消防设施、预防火灾、报告火警和扑救初起火灾等维护消防安全的义务。"},{"i":7,"n":"第七条","txt":"教育行政部门依法履行对高等学校消防安全工作的管理职责，检查、指导和监督高等学校开展消防安全工作，督促高等学校建立健全并落实消防安全责任制和消防安全管理制度。 公安机关依法履行对高等学校消防安全工作的监督管理职责，加强消防监督检查，指导和监督高等学校做好消防安全工作。"},{"i":8,"n":"第八条","txt":"学校法定代表人是学校消防安全责任人，全面负责学校消防安全工作，履行下列消防安全职责： （一）贯彻落实消防法律、法规和规章，批准实施学校消防安全责任制、学校消防安全管理制度； （二）批准消防安全年度工作计划、年度经费预算，定期召开学校消防安全工作会议； （三）提供消防安全经费保障和组织保障； （四）督促开展消防安全检查和重大火灾隐患整改，及时处理涉及消防安全的重大问题； （五）依法建立志愿消防队等多种形式的消防组织，开展群众性自防自救工作； （六）与学校二级单位负责人签订消防安全责任书； （七）组织制定灭火和应急疏散预案； （八）促进消防科学研究和技术创新； （九）法律、法规规定的其他消防安全职责。"},{"i":9,"n":"第九条","txt":"分管学校消防安全的校领导是学校消防安全管理人，协助学校法定代表人负责消防安全工作，履行下列消防安全职责： （一）组织制定学校消防安全管理制度，组织、实施和协调校内各单位的消防安全工作； （二）组织制定消防安全年度工作计划； （三）审核消防安全工作年度经费预算； （四）组织实施消防安全检查和火灾隐患整改； （五）督促落实消防设施、器材的维护、维修及检测,确保其完好有效，确保疏散通道、安全出口、消防车通道畅通； （六）组织管理志愿消防队等消防组织； （七）组织开展师生员工消防知识、技能的宣传教育和培训，组织灭火和应急疏散预案的实施和演练； （八）协助学校消防安全责任人做好其他消防安全工作。 其他校领导在分管工作范围内对消防工作负有领导、监督、检查、教育和管理职责。"},{"i":10,"n":"第十条","txt":"学校必须设立或者明确负责日常消防安全工作的机构（以下简称学校消防机构），配备专职消防管理人员，履行下列消防安全职责： （一）拟订学校消防安全年度工作计划、年度经费预算，拟订学校消防安全责任制、灭火和应急疏散预案等消防安全管理制度，并报学校消防安全责任人批准后实施； （二）监督检查校内各单位消防安全责任制的落实情况； （三）监督检查消防设施、设备、器材的使用与管理、以及消防基础设施的运转，定期组织检验、检测和维修； （四）确定学校消防安全重点单位（部位）并监督指导其做好消防安全工作； （五）监督检查有关单位做好易燃易爆等危险品的储存、使用和管理工作，审批校内各单位动用明火作业； （六）开展消防安全教育培训，组织消防演练，普及消防知识，提高师生员工的消防安全意识、扑救初起火灾和自救逃生技能； （七）定期对志愿消防队等消防组织进行消防知识和灭火技能培训； （八）推进消防安全技术防范工作，做好"},{"i":11,"n":"第十一条","txt":"学校二级单位和其他驻校单位应当履行下列消防安全职责： （一）落实学校的消防安全管理规定，结合本单位实际制定并落实本单位的消防安全制度和消防安全操作规程； （二）建立本单位的消防安全责任考核、奖惩制度； （三）开展经常性的消防安全教育、培训及演练； （四）定期进行防火检查，做好检查记录，及时消除火灾隐患； （五）按规定配置消防设施、器材并确保其完好有效； （六）按规定设置安全疏散指示标志和应急照明设施，并保证疏散通道、安全出口畅通； （七）消防控制室配备消防值班人员，制定值班岗位职责，做好监督检查工作； （八）新建、扩建、改建及装饰装修工程报学校消防机构备案； （九）按照规定的程序与措施处置火灾事故； （十）学校规定的其他消防安全职责。"},{"i":12,"n":"第十二条","txt":"校内各单位主要负责人是本单位消防安全责任人，驻校内其他单位主要负责人是该单位消防安全责任人，负责本单位的消防安全工作。"},{"i":13,"n":"第十三条","txt":"除本规定第十一条外，学生宿舍管理部门还应当履行下列安全管理职责： （一）建立由学生参加的志愿消防组织，定期进行消防演练； （二）加强学生宿舍用火、用电安全教育与检查； （三）加强夜间防火巡查，发现火灾立即组织扑救和疏散学生。"},{"i":14,"n":"第十四条","txt":"学校应当将下列单位（部位）列为学校消防安全重点单位（部位）： （一）学生宿舍、食堂（餐厅）、教学楼、校医院、体育场（馆）、会堂（会议中心）、超市（市场）、宾馆（招待所）、托儿所、幼儿园以及其他文体活动、公共娱乐等人员密集场所； （二）学校网络、广播电台、电视台等传媒部门和驻校内邮政、通信、金融等单位； （三）车库、油库、加油站等部位； （四）图书馆、展览馆、档案馆、博物馆、文物古建筑； （五）供水、供电、供气、供热等系统； （六）易燃易爆等危险化学物品的生产、充装、储存、供应、使用部门； （七）实验室、计算机房、电化教学中心和承担国家重点科研项目或配备有先进精密仪器设备的部位，监控中心、消防控制中心； （八）学校保密要害部门及部位； （九）高层建筑及地下室、半地下室； （十）建设工程的施工现场以及有人员居住的临时性建筑； （十一）其他发生火灾可能性较大以及一旦发生火灾可能造成重大人身伤"},{"i":15,"n":"第十五条","txt":"在学校内举办文艺、体育、集会、招生和就业咨询等大型活动和展览，主办单位应当确定专人负责消防安全工作，明确并落实消防安全职责和措施，保证消防设施和消防器材配置齐全、完好有效，保证疏散通道、安全出口、疏散指示标志、应急照明和消防车通道符合消防技术标准和管理规定，制定灭火和应急疏散预案并组织演练，并经学校消防机构对活动现场检查合格后方可举办。 依法应当报请当地人民政府有关部门审批的，经有关部门审核同意后方可举办。"},{"i":16,"n":"第十六条","txt":"学校应当按照国家有关规定，配置消防设施和器材，设置消防安全疏散指示标志和应急照明设施，每年组织检测维修，确保消防设施和器材完好有效。 学校应当保障疏散通道、安全出口、消防车通道畅通。"},{"i":17,"n":"第十七条","txt":"学校进行新建、改建、扩建、装修、装饰等活动，必须严格执行消防法规和国家工程建设消防技术标准，并依法办理建设工程消防设计审核、消防验收或者备案手续。学校各项工程及驻校内各单位在校内的各项工程消防设施的招标和验收，应当有学校消防机构参加。 施工单位负责施工现场的消防安全，并接受学校消防机构的监督、检查。竣工后，建筑工程的有关图纸、资料、文件等应当报学校档案机构和消防机构备案。"},{"i":18,"n":"第十八条","txt":"地下室、半地下室和用于生产、经营、储存易燃易爆、有毒有害等危险物品场所的建筑不得用作学生宿舍。 生产、经营、储存其他物品的场所与学生宿舍等居住场所设置在同一建筑物内的，应当符合国家工程建设消防技术标准。 学生宿舍、教室和礼堂等人员密集场所，禁止违规使用大功率电器，在门窗、阳台等部位不得设置影响逃生和灭火救援的障碍物。"},{"i":19,"n":"第十九条","txt":"利用地下空间开设公共活动场所，应当符合国家有关规定，并报学校消防机构备案。"},{"i":20,"n":"第二十条","txt":"学校消防控制室应当配备专职值班人员，持证上岗。 消防控制室不得挪作他用。"},{"i":21,"n":"第二十一条","txt":"学校购买、储存、使用和销毁易燃易爆等危险品，应当按照国家有关规定严格管理、规范操作，并制定应急处置预案和防范措施。 学校对管理和操作易燃易爆等危险品的人员，上岗前必须进行培训，持证上岗。"},{"i":22,"n":"第二十二条","txt":"学校应当对动用明火实行严格的消防安全管理。禁止在具有火灾、爆炸危险的场所吸烟、使用明火；因特殊原因确需进行电、气焊等明火作业的，动火单位和人员应当向学校消防机构申办审批手续，落实现场监管人，采取相应的消防安全措施。作业人员应当遵守消防安全规定。"},{"i":23,"n":"第二十三条","txt":"学校内出租房屋的，当事人应当签订房屋租赁合同，明确消防安全责任。出租方负责对出租房屋的消防安全管理。学校授权的管理单位应当加强监督检查。 外来务工人员的消防安全管理由校内用人单位负责。"},{"i":24,"n":"第二十四条","txt":"发生火灾时，学校应当及时报警并立即启动应急预案，迅速扑救初起火灾，及时疏散人员。 学校应当在火灾事故发生后两个小时内向所在地教育行政主管部门报告。较大以上火灾同时报教育部。 火灾扑灭后，事故单位应当保护现场并接受事故调查，协助公安机关消防机构调查火灾原因、统计火灾损失。未经公安机关消防机构同意，任何人不得擅自清理火灾现场。"},{"i":25,"n":"第二十五条","txt":"学校及其重点单位应当建立健全消防档案。 消防档案应当全面反映消防安全和消防安全管理情况，并根据情况变化及时更新。"},{"i":26,"n":"第二十六条","txt":"学校每季度至少进行一次消防安全检查。检查的主要内容包括： （一）消防安全宣传教育及培训情况； （二）消防安全制度及责任制落实情况； （三）消防安全工作档案建立健全情况； （四）单位防火检查及每日防火巡查落实及记录情况； （五）火灾隐患和隐患整改及防范措施落实情况； （六）消防设施、器材配置及完好有效情况； （七）灭火和应急疏散预案的制定和组织消防演练情况； （八）其他需要检查的内容。"},{"i":27,"n":"第二十七条","txt":"学校消防安全检查应当填写检查记录，检查人员、被检查单位负责人或者相关人员应当在检查记录上签名，发现火灾隐患应当及时填发《火灾隐患整改通知书》。"},{"i":28,"n":"第二十八条","txt":"校内各单位每月至少进行一次防火检查。检查的主要内容包括： （一）火灾隐患和隐患整改情况以及防范措施的落实情况； （二）疏散通道、疏散指示标志、应急照明和安全出口情况； （三）消防车通道、消防水源情况； （四）消防设施、器材配置及有效情况； （五）消防安全标志设置及其完好、有效情况； （六）用火、用电有无违章情况； （七）重点工种人员以及其他员工消防知识掌握情况； （八）消防安全重点单位（部位）管理情况； （九）易燃易爆危险物品和场所防火防爆措施落实情况以及其他重要物资防火安全情况； （十）消防（控制室）值班情况和设施、设备运行、记录情况； （十一）防火巡查落实及记录情况； （十二）其他需要检查的内容。 防火检查应当填写检查记录。检查人员和被检查部门负责人应当在检查记录上签名。"},{"i":29,"n":"第二十九条","txt":"校内消防安全重点单位（部位）应当进行每日防火巡查，并确定巡查的人员、内容、部位和频次。其他单位可以根据需要组织防火巡查。巡查的内容主要包括： （一）用火、用电有无违章情况； （二）安全出口、疏散通道是否畅通，安全疏散指示标志、应急照明是否完好； （三）消防设施、器材和消防安全标志是否在位、完整； （四）常闭式防火门是否处于关闭状态，防火卷帘下是否堆放物品影响使用； （五）消防安全重点部位的人员在岗情况； （六）其他消防安全情况。 校医院、学生宿舍、公共教室、实验室、文物古建筑等应当加强夜间防火巡查。 防火巡查人员应当及时纠正消防违章行为，妥善处置火灾隐患，无法当场处置的，应当立即报告。发现初起火灾应当立即报警、通知人员疏散、及时扑救。 防火巡查应当填写巡查记录，巡查人员及其主管人员应当在巡查记录上签名。"},{"i":30,"n":"第三十条","txt":"对下列违反消防安全规定的行为，检查、巡查人员应当责成有关人员改正并督促落实： （一）消防设施、器材或者消防安全标志的配置、设置不符合国家标准、行业标准，或者未保持完好有效的； （二）损坏、挪用或者擅自拆除、停用消防设施、器材的； （三）占用、堵塞、封闭消防通道、安全出口的； （四）埋压、圈占、遮挡消火栓或者占用防火间距的； （五）占用、堵塞、封闭消防车通道，妨碍消防车通行的； （六）人员密集场所在门窗上设置影响逃生和灭火救援的障碍物的； （七）常闭式防火门处于开启状态，防火卷帘下堆放物品影响使用的； （八）违章进入易燃易爆危险物品生产、储存等场所的； （九）违章使用明火作业或者在具有火灾、爆炸危险的场所吸烟、使用明火等违反禁令的； （十）消防设施管理、值班人员和防火巡查人员脱岗的； （十一）对火灾隐患经公安机关消防机构通知后不及时采取措施消除的； （十二）其他违反消防安全管理规定的行为"},{"i":31,"n":"第三十一条","txt":"学校对教育行政主管部门和公安机关消防机构、公安派出所指出的各类火灾隐患，应当及时予以核查、消除。 对公安机关消防机构、公安派出所责令限期改正的火灾隐患，学校应当在规定的期限内整改。"},{"i":32,"n":"第三十二条","txt":"对不能及时消除的火灾隐患，隐患单位应当及时向学校及相关单位的消防安全责任人或者消防安全工作主管领导报告，提出整改方案，确定整改措施、期限以及负责整改的部门、人员，并落实整改资金。 火灾隐患尚未消除的，隐患单位应当落实防范措施，保障消防安全。对于随时可能引发火灾或者一旦发生火灾将严重危及人身安全的，应当将危险部位停止使用或停业整改。"},{"i":33,"n":"第三十三条","txt":"对于涉及城市规划布局等学校无力解决的重大火灾隐患，学校应当及时向其上级主管部门或者当地人民政府报告。"},{"i":34,"n":"第三十四条","txt":"火灾隐患整改完毕，整改单位应当将整改情况记录报送相应的消防安全工作责任人或者消防安全工作主管领导签字确认后存档备查。"},{"i":35,"n":"第三十五条","txt":"学校应当将师生员工的消防安全教育和培训纳入学校消防安全年度工作计划。 消防安全教育和培训的主要内容包括： （一）国家消防工作方针、政策，消防法律、法规； （二）本单位、本岗位的火灾危险性，火灾预防知识和措施； （三）有关消防设施的性能、灭火器材的使用方法； （四）报火警、扑救初起火灾和自救互救技能； （五）组织、引导在场人员疏散的方法。"},{"i":36,"n":"第三十六条","txt":"学校应当采取下列措施对学生进行消防安全教育，使其了解防火、灭火知识，掌握报警、扑救初起火灾和自救、逃生方法。 （一）开展学生自救、逃生等防火安全常识的模拟演练，每学年至少组织一次学生消防演练； （二）根据消防安全教育的需要，将消防安全知识纳入教学和培训内容； （三）对每届新生进行不低于4学时的消防安全教育和培训； （四）对进入实验室的学生进行必要的安全技能和操作规程培训； （五）每学年至少举办一次消防安全专题讲座，并在校园网络、广播、校内报刊开设消防安全教育栏目。"},{"i":37,"n":"第三十七条","txt":"学校二级单位应当组织新上岗和进入新岗位的员工进行上岗前的消防安全培训。 消防安全重点单位（部位）对员工每年至少进行一次消防安全培训。"},{"i":38,"n":"第三十八条","txt":"下列人员应当依法接受消防安全培训： （一）学校及各二级单位的消防安全责任人、消防安全管理人； （二）专职消防管理人员、学生宿舍管理人员； （三）消防控制室的值班、操作人员； （四）其他依照规定应当接受消防安全培训的人员。 前款规定中的第（三）项人员必须持证上岗。"},{"i":39,"n":"第三十九条","txt":"学校、二级单位、消防安全重点单位（部位）应当制定相应的灭火和应急疏散预案，建立应急反应和处置机制，为火灾扑救和应急救援工作提供人员、装备等保障。 灭火和应急疏散预案应当包括以下内容： （一）组织机构：指挥协调组、灭火行动组、通讯联络组、疏散引导组、安全防护救护组； （二）报警和接警处置程序； （三）应急疏散的组织程序和措施； （四）扑救初起火灾的程序和措施； （五）通讯联络、安全防护救护的程序和措施。 （六）其他需要明确的内容。"},{"i":40,"n":"第四十条","txt":"学校实验室应当有针对性地制定突发事件应急处置预案，并将应急处置预案涉及到的生物、化学及易燃易爆物品的种类、性质、数量、危险性和应对措施及处置药品的名称、产地和储备等内容报学校消防机构备案。"},{"i":41,"n":"第四十一条","txt":"校内消防安全重点单位应当按照灭火和应急疏散预案每半年至少组织一次消防演练，并结合实际，不断完善预案。 消防演练应当设置明显标识并事先告知演练范围内的人员，避免意外事故发生。"},{"i":42,"n":"第四十二条","txt":"学校应当将消防经费纳入学校年度经费预算，保证消防经费投入，保障消防工作的需要。"},{"i":43,"n":"第四十三条","txt":"学校日常消防经费用于校内灭火器材的配置、维修、更新，灭火和应急疏散预案的备用设施、材料，以及消防宣传教育、培训等，保证学校消防工作正常开展。"},{"i":44,"n":"第四十四条","txt":"学校安排专项经费，用于解决火灾隐患，维修、检测、改造消防专用给水管网、消防专用供水系统、灭火系统、自动报警系统、防排烟系统、消防通讯系统、消防监控系统等消防设施。"},{"i":45,"n":"第四十五条","txt":"消防经费使用坚持专款专用、统筹兼顾、保证重点、勤俭节约的原则。 任何单位和个人不得挤占、挪用消防经费。"},{"i":46,"n":"第四十六条","txt":"学校应当将消防安全工作纳入校内评估考核内容，对在消防安全工作中成绩突出的单位和个人给予表彰奖励。"},{"i":47,"n":"第四十七条","txt":"对未依法履行消防安全职责、违反消防安全管理制度、或者擅自挪用、损坏、破坏消防器材、设施等违反消防安全管理规定的，学校应当责令其限期整改，给予通报批评；对直接负责的主管人员和其他直接责任人员根据情节轻重给予警告等相应的处分。 前款涉及民事损失、损害的，有关责任单位和责任人应当依法承担民事责任。"},{"i":48,"n":"第四十八条","txt":"学校违反消防安全管理规定或者发生重特大火灾的，除依据消防法的规定进行处罚外，教育行政部门应当取消其当年评优资格，并按照国家有关规定对有关主管人员和责任人员依法予以处分。"},{"i":49,"n":"第四十九条","txt":"学校应当依据本规定，结合本校实际，制定本校消防安全管理办法。 高等学校以外的其他高等教育机构的消防安全管理，参照本规定执行。"},{"i":50,"n":"第五十条","txt":"本规定所称学校二级单位，包括学院、系、处、所、中心等。"},{"i":51,"n":"第五十一条","txt":"本规定自2010年1月1日起施行。"}],"gaodengxuexiaozhishichanquanbaohuguanliguiding":[{"i":1,"n":"第一条","txt":"为有效保护高等学校知识产权，鼓励广大教职员工和学生发明创造和智力创作的积极性，发挥高等学校的智力优势，促进科技成果产业化，依据国家知识产权法律、法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于国家举办的高等学校、高等学校所属教学科研机构和企业事业单位（以下简称“所属单位”）。社会力量举办的高等学校及其他教育机构参照适用本规定。"},{"i":3,"n":"第三条","txt":"本规定所称的知识产权包括： （一）专利权、商标权； （二）技术秘密和商业秘密； （三）著作权及其邻接权； （四）高等学校的校标和各种服务标记； （五）依照国家法律、法规规定或者依法由合同约定由高等学校享有或持有的其它知识产权。"},{"i":4,"n":"第四条","txt":"高等学校知识产权保护工作的任务是： （一）贯彻执行国家知识产权法律、法规，制定高等学校知识产权保护工作的方针、政策和规划； （二）宣传、普及知识产权法律知识，增强高等学校知识产　权保护意识和能力； （三）进一步完善高等学校知识产权管理制度，切实加强高等学校知识产权保护工作； （四）积极促进和规范管理高等学校科学技术成果及其他智力成果的开发、使用、转让和科技产业的发展。"},{"i":5,"n":"第五条","txt":"国务院教育行政部门和各省、自治区、直辖市人民政府教育行政部门，在其职责范围内，负责对全国或本行政区域的高等学校知识产权工作进行领导和宏观管理，全面规划、推动、指导和监督高等学校知识产权保护工作的开展。"},{"i":6,"n":"第六条","txt":"各高等学校在知识产权保护工作中应当履行的职责是： （一）结合本校的实际情况，制定知识产权工作的具体规划和保护规定； （二）加强对知识产权保护工作的组织和领导，完善本校知识产权保护制度，加强本校知识产权工作机构和队伍建设； （三）组织知识产权法律、法规的教育和培训，开展知识产权课程教学和研究工作； （四）组织开展本校知识产权的鉴定、申请、登记、注册、评估和管理工作； （五）组织签订、审核本校知识产权的开发、使用和转让合同； （六）协调解决本校内部有关知识产权的争议和纠纷； （七）对在科技开发、技术转移以及知识产权保护工作中有突出贡献人员予以奖励； （八）组织开展本校有关知识产权保护工作的国际交流与合作； （九）其他在知识产权保护工作中应当履行的职责。"},{"i":7,"n":"第七条","txt":"高等学校对以下标识依法享有专用权： （一）以高等学校名义申请注册的商标； （二）校标； （三）高等学校的其他服务性标记。"},{"i":8,"n":"第八条","txt":"执行本校及其所属单位任务，或主要利用本校及其所属单位的物质技术条件所完成的发明创造或者其他技术成果，是高等学校职务发明创造或职务技术成果。　职务发明创造申请专利的权利属于高等学校。专利权被依法授予后由高等学校持有。职务技术成果的使用权、转让权由高等学校享有。"},{"i":9,"n":"第九条","txt":"由高等学校主持、代表高等学校意志创作、并由高等学校承担责任的作品为高等学校法人作品，其著作权由高等学校享有。　为完成高等学校的工作任务所创作的作品是职务作品，除第十条规定情况外，著作权由完成者享有。高等学校在其业务范围内对职务作品享有优先使用权。作品完成二年内，未经高等学校同意，作者不得许可第三人以与高等学校相同的方式使用该作品。"},{"i":10,"n":"第十条","txt":"主要利用高等学校的物质技术条件创作，并由高等学校承担责任的工程设计、产品设计图纸、计算机软件、地图等职务作品以及法律、行政法规规定的或者合同约定著作权由高等学校享有的职务作品，作者享有署名权，著作权的其他权利由高等学校享有。"},{"i":11,"n":"第十一条","txt":"在执行高等学校科研等工作任务过程中所形成的信息、资料、程序等技术秘密属于高等学校所有。"},{"i":12,"n":"第十二条","txt":"高等学校派遣出国访问、进修、留学及开展合作项目研究的人员，对其在校已进行的研究，而在国外可能完成的发明创造、获得的知识产权，应当与派遣的高等学校签订协议，确定其发明创造及其他知识产权的归属。"},{"i":13,"n":"第十三条","txt":"在高等学校学习、进修或者开展合作项目研究的学生、研究人员，在校期间参与导师承担的本校研究课题或者承担学校安排的任务所完成的发明创造及其他技术成果，除另有协议外，应当归高等学校享有或持有。进入博士后流动站的人员，在进站前应就知识产权问题与流动站签定专门协议。"},{"i":14,"n":"第十四条","txt":"高等学校的离休、退休、停薪留职、调离以及被辞退的人员，在离开高等学校一年内完成的与其原承担的本职工作或任务有关的发明创造或技术成果，由高等学校享有或持有。"},{"i":15,"n":"第十五条","txt":"职务发明创造或职务技术成果，以及职务作品的完成人依法享有在有关技术文件和作品上署名及获得奖励和报酬的权利。"},{"i":16,"n":"第十六条","txt":"高等学校应建立知识产权办公会议制度，逐步建立健全知识产权工作机构。有条件的高等学校，可实行知识产权登记管理制度；设立知识产权保护与管理工作机构，归口管理本单位知识产权保护工作。暂未设立知识产权保护与管理机构的高等学校，应指定科研管理机构或其他机构担负相关职责。"},{"i":17,"n":"第十七条","txt":"高等学校科研管理机构负责本校科研项目的立项、成果和档案管理。　应用技术项目的课题组或课题研究人员，在申请立项之前应当进行专利文献及其相关文献的检索。　课题组或课题研究人员在科研工作过程中，应当做好技术资料的记录和保管工作。科研项囤完成后，课题负责人应当将全部实验报告、实验记录、图纸、声像、手稿等原始技术资料收集整理后交本校科研管理机构归档。"},{"i":18,"n":"第十八条","txt":"在科研活动中作出的职务发明创造或者形成的职务技术成果，课题负责人应当及时向本校科研管理机构叶口识产权管理机构）提出申请专利的建议，并提交相关资料。　高等学校的科研管理机构应当对课题负责人的建议和相关资料进行审查，对需要申请专利的应当及时办理专利申请，对不宜申请专利的技术秘密要采取措施予以保护。"},{"i":19,"n":"第十九条","txt":"高等学校应当规范和加强有关知识产权合同的签订、审核和管理工作。　高等学校及其所属单位与国内外单位或者个人合作进行科学研究和技术开发，对外进行知识产权转让或者许可使用，应当依法签订书面合同，明确知识产权的归属以及相应的权利、义务等内容。　高等学校的知识产权管理机构负责对高等学校及其所属单位签订的知识产权合同进行审核和管理。"},{"i":20,"n":"第二十条","txt":"高等学校所属单位对外进行知识产权转让或者许可使用前，应当经学校知识产权管理机构审查，并报学校批准。"},{"i":21,"n":"第二十一条","txt":"高等学校的教职员工和学生凡申请非职务专利，登记非职务计算机软件的，以及进行非职务专利、非职务技术成果以及非职务作品转让和许可的，应当向本校知识产权管理机构申报，接受审核。对于符合非职务条件的，学校应出具相应证明。"},{"i":22,"n":"第二十二条","txt":"高等学校要加强科技保密管理。高等学校的教职员工和学生，在开展国内外学术交流与合作过程中，对属于本校保密的信息和技术，要按照国家和本校的有关规定严格保密。　高等学校对在国内外科技展览会参展的项目应当加强审核和管理、做好科技保密管理工作。"},{"i":23,"n":"第二十三条","txt":"高等学校应当重视开展知识产权的资产评估工作，加强对知识产权资产评估的组织和管理。　高等学校对外进行知识产权转让、许可使用、作价投资入股或者作为对校办科技产业的投入，应当对知识产权进行资产评估。"},{"i":24,"n":"第二十四条","txt":"高等学校可根据情况逐步实行知识产权保证书制度，与有关教职员工和学生签订保护本校知识产权的保证书，明确保护本校知识产权的义务。"},{"i":25,"n":"第二十五条","txt":"高等学校应当依法保护职务发明创造、职务技术成果、高等学校法人作品及职务作品的研究、创作人员的合法权益，对在知识产权的产生、发展，科技成果产业化方面作出突出贡献的人员，按照国家的有关规定给予奖励。"},{"i":26,"n":"第二十六条","txt":"高等学校将其知识产权或职务发明创造、职务技术成果转让给他人或许可他人使用的，应当从转让或许可使用所取得的净收入中，提取不低于20％的比例，对完成该项职务发明创造、职务技术成果及其转化作出重要贡献的人员给予奖励。为促进科技成果产业化，对经学校许可，由职务发明创造、职务技术成果完成人进行产业化的，可以从转化收入中提取不低于30％的比例给予奖酬。"},{"i":27,"n":"第二十七条","txt":"高等学校及其所属单位独立研究开发或者与其他单位合作研究开发的科技成果实施转化成功投产后，高等学校应当连续三至五年从实施该项科技成果所取得的收入中提取不低于5％的比例，对完成该项科技成果及其产业化作出重要贡献的人员给予奖酬。　采用股份制形式的高等学校科技企业，或者主要以技术向其他股份制企业投资入股的高等学校，可以将在科技成果的研究开发、产业化中做出重要贡献的有关人员的报酬或者奖励，按照国家有关规定折算为相应的股份份额或者出资比例。该持股人依据其所持股份份额或出资比例分享收益。"},{"i":28,"n":"第二十八条","txt":"高等学校应当根据实际情况，采取有效措施，对知识产权的保护、管理工作提供必要的条件保障。高等学校应拨出专款或从技术实施收益中提取一定比例，设立知识产权专项基金，用于支持补贴专利申请，维持和知识产权保护方面的有关费用。对知识产权保护与管理做出突出贡献的单位和个人，高等学校应给予奖励，并作为工作业绩和职称评聘的重要参考。"},{"i":29,"n":"第二十九条","txt":"剽窃、窃取、篡改、非法占有、假冒或者以其他方式侵害由高等学校及其教职员工和学生依法享有或持有的知识产权的，高等学校有处理权的，应责令其改正，并对直接责任人给予相应的处分；对无处理权的，应提请并协助有关行政部门依法作出处理。构成犯罪的，应当依法追究刑事责任。"},{"i":30,"n":"第三十条","txt":"在高等学校教学、科研、创作以及成果的申报、评审、鉴定、产业化活动中，采取欺骗手段，获得优惠待遇或者奖励的，高等学校应当责令改正，退还非法所得，取消其获得的优惠待遇和奖励。"},{"i":31,"n":"第三十一条","txt":"违反本规定，泄漏本校的技术秘密，或者擅自转让、变相转让以及许可使用高等学校的职务发明创造、职务技术成果、高等学校法人作品或者职务作品的，或造成高等学校资产流失和损失的，由高等学校或其主管教育行政部门对直接责任人员给予行政处分。"},{"i":32,"n":"第三十二条","txt":"侵犯高等学校及其教职员工和学生依法享有或持有的知识产权，造成损失、损害的，应当依法承担民事责任。"},{"i":33,"n":"第三十三条","txt":"本规定自发布之日起施行。"}],"gaodengxuexiaozhangchengzhidingzanxingbanfa":[{"i":1,"n":"第一条","txt":"为完善中国特色现代大学制度，指导和规范高等学校章程建设，促进高等学校依法治校、科学发展，依据教育法、高等教育法及其他有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"国家举办的高等学校章程的起草、审议、修订以及核准、备案等，适用本办法。"},{"i":3,"n":"第三条","txt":"章程是高等学校依法自主办学、实施管理和履行公共职能的基本准则。高等学校应当以章程为依据，制定内部管理制度及规范性文件、实施办学和管理活动、开展社会合作。 高等学校应当公开章程，接受举办者、教育主管部门、其他有关机关以及教师、学生、社会公众依据章程实施的监督、评估。"},{"i":4,"n":"第四条","txt":"高等学校制定章程应当以中国特色社会主义理论体系为指导，以宪法、法律法规为依据，坚持社会主义办学方向，遵循高等教育规律，推进高等学校科学发展；应当促进改革创新，围绕人才培养、科学研究、服务社会、推进文化传承创新的任务，依法完善内部法人治理结构，体现和保护学校改革创新的成功经验与制度成果；应当着重完善学校自主管理、自我约束的体制、机制，反映学校的办学特色。"},{"i":5,"n":"第五条","txt":"高等学校的举办者、主管教育行政部门应当按照政校分开、管办分离的原则，以章程明确界定与学校的关系，明确学校的办学方向与发展原则，落实举办者权利义务，保障学校的办学自主权。"},{"i":6,"n":"第六条","txt":"章程用语应当准确、简洁、规范，条文内容应当明确、具体，具有可操作性。 章程根据内容需要，可以分编、章、节、条、款、项、目。"},{"i":7,"n":"第七条","txt":"章程应当按照高等教育法的规定，载明以下内容： （一）学校的登记名称、简称、英文译名等，学校办学地点、住所地； （二）学校的机构性质、发展定位，培养目标、办学方向； （三）经审批机关核定的办学层次、规模； （四）学校的主要学科门类，以及设置和调整的原则、程序； （五）学校实施的全日制与非全日制、学历教育与非学历教育、远程教育、中外合作办学等不同教育形式的性质、目的、要求； （六）学校的领导体制、法定代表人，组织结构、决策机制、民主管理和监督机制，内设机构的组成、职责、管理体制； （七）学校经费的来源渠道、财产属性、使用原则和管理制度，接受捐赠的规则与办法； （八）学校的举办者，举办者对学校进行管理或考核的方式、标准等，学校负责人的产生与任命机制，举办者的投入与保障义务； （九）章程修改的启动、审议程序，以及章程解释权的归属； （十）学校的分立、合并及终止事由，校徽、校歌等学校标志物、学校"},{"i":8,"n":"第八条","txt":"章程应当按照高等教育法的规定，健全学校办学自主权的行使与监督机制，明确以下事项的基本规则、决策程序与监督机制： （一）开展教学活动、科学研究、技术开发和社会服务； （二）设置和调整学科、专业； （三）制订招生方案，调节系科招生比例，确定选拔学生的条件、标准、办法和程序； （四）制订学校规划并组织实施； （五）设置教学、科研及行政职能部门； （六）确定内部收入分配原则； （七）招聘、管理和使用人才； （八）学校财产和经费的使用与管理； （九）其他学校可以自主决定的重大事项。"},{"i":9,"n":"第九条","txt":"章程应当依照法律及其他有关规定，健全中国共产党高等学校基层委员会领导下的校长负责制的具体实施规则、实施意见，规范学校党委集体领导的议事规则、决策程序，明确支持校长独立负责地行使职权的制度规范。 章程应当明确校长作为学校法定代表人和主要行政负责人，全面负责教学、科学研究和其他管理工作的职权范围；规范校长办公会议或者校务会议的组成、职责、议事规则等内容。"},{"i":10,"n":"第十条","txt":"章程应当根据学校实际与发展需要，科学设计学校的内部治理结构和组织框架，明确学校与内设机构，以及各管理层级、系统之间的职责权限，管理的程序与规则。 章程根据学校实际，可以按照有利于推进教授治学、民主管理，有利于调动基层组织积极性的原则，设置并规范学院（学部、系）、其他内设机构以及教学、科研基层组织的领导体制、管理制度。"},{"i":11,"n":"第十一条","txt":"章程应当明确规定学校学术委员会、学位评定委员会以及其他学术组织的组成原则、负责人产生机制、运行规则与监督机制，保障学术组织在学校的学科建设、专业设置、学术评价、学术发展、教学科研计划方案制定、教师队伍建设等方面充分发挥咨询、审议、决策作用，维护学术活动的独立性。 章程应当明确学校学术评价和学位授予的基本规则和办法；明确尊重和保障教师、学生在教学、研究和学习方面依法享有的学术自由、探索自由，营造宽松的学术环境。"},{"i":12,"n":"第十二条","txt":"章程应当明确规定教职工代表大会、学生代表大会的地位作用、职责权限、组成与负责人产生规则，以及议事程序等，维护师生员工通过教职工代表大会、学生代表大会参与学校相关事项的民主决策、实施监督的权利。 对学校根据发展需要自主设置的各类组织机构，如校务委员会、教授委员会、校友会等，章程中应明确其地位、宗旨以及基本的组织与议事规则。"},{"i":13,"n":"第十三条","txt":"章程应当明确学校开展社会服务、获得社会支持、接受社会监督的原则与办法，健全社会支持和监督学校发展的长效机制。 学校根据发展需要和办学特色，自主设置有政府、行业、企事业单位以及其他社会组织代表参加的学校理事会或者董事会的，应当在章程中明确理事会或者董事会的地位作用、组成和议事规则。"},{"i":14,"n":"第十四条","txt":"章程应当围绕提高质量的核心任务，明确学校保障和提高教育教学质量的原则与制度，规定学校对学科、专业、课程以及教学、科研的水平与质量进行评价、考核的基本规则，建立科学、规范的质量保障体系和评价机制。"},{"i":15,"n":"第十五条","txt":"章程应当体现以人为本的办学理念，健全教师、学生权益的救济机制，突出对教师、学生权益、地位的确认与保护，明确其权利义务；明确学校受理教师、学生申诉的机构与程序。"},{"i":16,"n":"第十六条","txt":"高等学校应当按照民主、公开的原则，成立专门起草组织开展章程起草工作。 章程起草组织应当由学校党政领导、学术组织负责人、教师代表、学生代表、相关专家，以及学校举办者或者主管部门的代表组成，可以邀请社会相关方面的代表、社会知名人士、退休教职工代表、校友代表等参加。"},{"i":17,"n":"第十七条","txt":"高等学校起草章程，应当深入研究、分析学校的特色与需求，总结实践经验，广泛听取政府有关部门、学校内部组织、师生员工的意见，充分反映学校举办者、管理者、办学者，以及教职员工、学生的要求与意愿，使章程起草成为学校凝聚共识、促进管理、增进和谐的过程。"},{"i":18,"n":"第十八条","txt":"章程起草过程中，应当在校内公开听取意见；涉及到关系学校发展定位、办学方向、培养目标、管理体制，以及与教职工、学生切身利益相关的重大问题，应当采取多种方式，征求意见、充分论证。"},{"i":19,"n":"第十九条","txt":"起草章程，涉及到与举办者权利关系的内容，高等学校应当与举办者、主管教育行政部门及其他相关部门充分沟通、协商。"},{"i":20,"n":"第二十条","txt":"章程草案应提交教职工代表大会讨论。学校章程起草组织负责人，应当就章程起草情况与主要问题，向教职工代表大会做出说明。"},{"i":21,"n":"第二十一条","txt":"章程草案征求意见结束后，起草组织应当将章程草案及其起草说明，以及征求意见的情况、主要问题的不同意见等，提交校长办公会议审议。"},{"i":22,"n":"第二十二条","txt":"章程草案经校长办公会议讨论通过后，由学校党委会讨论审定。 章程草案经讨论审定后，应当形成章程核准稿和说明，由学校法定代表人签发，报核准机关。"},{"i":23,"n":"第二十三条","txt":"地方政府举办的高等学校的章程由省级教育行政部门核准，其中本科以上高等学校的章程核准后，应当报教育部备案；教育部直属高等学校的章程由教育部核准；其他中央部门所属高校的章程，经主管部门同意，报教育部核准。"},{"i":24,"n":"第二十四条","txt":"章程报送核准应当提交以下材料： （一） 核准申请书； （二） 章程核准稿； （三） 对章程制定程序和主要内容的说明。"},{"i":25,"n":"第二十五条","txt":"核准机关应当指定专门机构依照本办法的要求，对章程核准稿的合法性、适当性、规范性以及制定程序，进行初步审查。审查通过的，提交核准机关组织的章程核准委员会评议。 章程核准委员会由核准机关、有关主管部门推荐代表，高校、社会代表以及相关领域的专家组成。"},{"i":26,"n":"第二十六条","txt":"核准机关应当自收到核准申请2个月内完成初步审查。涉及对核准稿条款、文字进行修改的，核准机关应当及时与学校进行沟通，提出修改意见。 有下列情形之一的，核准机关可以提出时限，要求学校修改后，重新申请核准： （一） 违反法律、法规的； （二） 超越高等学校职权的； （三） 章程核准委员会未予通过或者提出重大修改意见的； （四） 违反本办法相关规定的； （五） 核准期间发现学校内部存在重大分歧的； （六） 有其他不宜核准情形的。"},{"i":27,"n":"第二十七条","txt":"经核准机关核准的章程文本为正式文本。高等学校应当以学校名义发布章程的正式文本，并向本校和社会公开。"},{"i":28,"n":"第二十八条","txt":"高等学校应当保持章程的稳定。 高等学校发生分立、合并、终止，或者名称、类别层次、办学宗旨、发展目标、举办与管理体制变化等重大事项的，可以依据章程规定的程序，对章程进行修订。"},{"i":29,"n":"第二十九条","txt":"高等学校章程的修订案，应当依法报原核准机关核准。 章程修订案经核准后，高等学校应当重新发布章程。"},{"i":30,"n":"第三十条","txt":"高等学校应当指定专门机构监督章程的执行情况，依据章程审查学校内部规章制度、规范性文件，受理对违反章程的管理行为、办学活动的举报和投诉。"},{"i":31,"n":"第三十一条","txt":"高等学校的主管教育行政部门对章程中自主确定的不违反法律和国家政策强制性规定的办学形式、管理办法等，应当予以认可；对高等学校履行章程情况应当进行指导、监督；对高等学校不执行章程的情况或者违反章程规定自行实施的管理行为，应当责令限期改正。"},{"i":32,"n":"第三十二条","txt":"新设立的高等学校，由学校举办者或者其委托的筹设机构,依法制定章程,并报审批机关批准;其中新设立的国家举办的高等学校，其章程应当具备本办法规定的内容；民办高等学校和中外合作举办的高等学校，依据相关法律法规制定章程，章程内容可参照本办法的规定。"},{"i":33,"n":"第三十三条","txt":"本办法自2012年1月1日起施行。"}],"gaodengxuexiaoyufangyuchulixueshubuduanxingweibanf5a4d90":[{"i":1,"n":"第一条","txt":"为有效预防和严肃查处高等学校发生的学术不端行为，维护学术诚信，促进学术创新和发展，根据《中华人民共和国高等教育法》《中华人民共和国科学技术进步法》《中华人民共和国学位条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称学术不端行为是指高等学校及其教学科研人员、管理人员和学生，在科学研究及相关活动中发生的违反公认的学术准则、违背学术诚信的行为。"},{"i":3,"n":"第三条","txt":"高等学校预防与处理学术不端行为应坚持预防为主、教育与惩戒结合的原则。"},{"i":4,"n":"第四条","txt":"教育部、国务院有关部门和省级教育部门负责制定高等学校学风建设的宏观政策，指导和监督高等学校学风建设工作，建立健全对所主管高等学校重大学术不端行为的处理机制，建立高校学术不端行为的通报与相关信息公开制度。"},{"i":5,"n":"第五条","txt":"高等学校是学术不端行为预防与处理的主体。高等学校应当建设集教育、预防、监督、惩治于一体的学术诚信体系，建立由主要负责人领导的学风建设工作机制，明确职责分工；依据本办法完善本校学术不端行为预防与处理的规则与程序。 高等学校应当充分发挥学术委员会在学风建设方面的作用，支持和保障学术委员会依法履行职责，调查、认定学术不端行为。"},{"i":6,"n":"第六条","txt":"高等学校应当完善学术治理体系，建立科学公正的学术评价和学术发展制度，营造鼓励创新、宽容失败、不骄不躁、风清气正的学术环境。 高等学校教学科研人员、管理人员、学生在科研活动中应当遵循实事求是的科学精神和严谨认真的治学态度，恪守学术诚信，遵循学术准则，尊重和保护他人知识产权等合法权益。"},{"i":7,"n":"第七条","txt":"高等学校应当将学术规范和学术诚信教育，作为教师培训和学生教育的必要内容，以多种形式开展教育、培训。 教师对其指导的学生应当进行学术规范、学术诚信教育和指导，对学生公开发表论文、研究和撰写学位论文是否符合学术规范、学术诚信要求，进行必要的检查与审核。"},{"i":8,"n":"第八条","txt":"高等学校应当利用信息技术等手段，建立对学术成果、学位论文所涉及内容的知识产权查询制度，健全学术规范监督机制。"},{"i":9,"n":"第九条","txt":"高等学校应当建立健全科研管理制度，在合理期限内保存研究的原始数据和资料，保证科研档案和数据的真实性、完整性。 高等学校应当完善科研项目评审、学术成果鉴定程序，结合学科特点，对非涉密的科研项目申报材料、学术成果的基本信息以适当方式进行公开。"},{"i":10,"n":"第十条","txt":"高等学校应当遵循学术研究规律，建立科学的学术水平考核评价标准、办法，引导教学科研人员和学生潜心研究，形成具有创新性、独创性的研究成果。"},{"i":11,"n":"第十一条","txt":"高等学校应当建立教学科研人员学术诚信记录，在年度考核、职称评定、岗位聘用、课题立项、人才计划、评优奖励中强化学术诚信考核。"},{"i":12,"n":"第十二条","txt":"高等学校应当明确具体部门，负责受理社会组织、个人对本校教学科研人员、管理人员及学生学术不端行为的举报；有条件的，可以设立专门岗位或者指定专人，负责学术诚信和不端行为举报相关事宜的咨询、受理、调查等工作。"},{"i":13,"n":"第十三条","txt":"对学术不端行为的举报，一般应当以书面方式实名提出，并符合下列条件： （一）有明确的举报对象； （二）有实施学术不端行为的事实； （三）有客观的证据材料或者查证线索。 以匿名方式举报，但事实清楚、证据充分或者线索明确的，高等学校应当视情况予以受理。"},{"i":14,"n":"第十四条","txt":"高等学校对媒体公开报道、其他学术机构或者社会组织主动披露的涉及本校人员的学术不端行为，应当依据职权，主动进行调查处理。"},{"i":15,"n":"第十五条","txt":"高等学校受理机构认为举报材料符合条件的，应当及时作出受理决定，并通知举报人。不予受理的，应当书面说明理由。"},{"i":16,"n":"第十六条","txt":"学术不端行为举报受理后，应当交由学校学术委员会按照相关程序组织开展调查。 学术委员会可委托有关专家就举报内容的合理性、调查的可能性等进行初步审查，并作出是否进入正式调查的决定。 决定不进入正式调查的，应当告知举报人。举报人如有新的证据，可以提出异议。异议成立的，应当进入正式调查。"},{"i":17,"n":"第十七条","txt":"高等学校学术委员会决定进入正式调查的，应当通知被举报人。 被调查行为涉及资助项目的，可以同时通知项目资助方。"},{"i":18,"n":"第十八条","txt":"高等学校学术委员会应当组成调查组，负责对被举报行为进行调查；但对事实清楚、证据确凿、情节简单的被举报行为，也可以采用简易调查程序，具体办法由学术委员会确定。 调查组应当不少于３人，必要时应当包括学校纪检、监察机构指派的工作人员，可以邀请同行专家参与调查或者以咨询等方式提供学术判断。 被调查行为涉及资助项目的，可以邀请项目资助方委派相关专业人员参与调查组。"},{"i":19,"n":"第十九条","txt":"调查组的组成人员与举报人或者被举报人有合作研究、亲属或者导师学生等直接利害关系的，应当回避。"},{"i":20,"n":"第二十条","txt":"调查可通过查询资料、现场查看、实验检验、询问证人、询问举报人和被举报人等方式进行。调查组认为有必要的，可以委托无利害关系的专家或者第三方专业机构就有关事项进行独立调查或者验证。"},{"i":21,"n":"第二十一条","txt":"调查组在调查过程中，应当认真听取被举报人的陈述、申辩，对有关事实、理由和证据进行核实；认为必要的，可以采取听证方式。"},{"i":22,"n":"第二十二条","txt":"有关单位和个人应当为调查组开展工作提供必要的便利和协助。 举报人、被举报人、证人及其他有关人员应当如实回答询问，配合调查，提供相关证据材料，不得隐瞒或者提供虚假信息。"},{"i":23,"n":"第二十三条","txt":"调查过程中，出现知识产权等争议引发的法律纠纷的，且该争议可能影响行为定性的，应当中止调查，待争议解决后重启调查。"},{"i":24,"n":"第二十四条","txt":"调查组应当在查清事实的基础上形成调查报告。调查报告应当包括学术不端行为责任人的确认、调查过程、事实认定及理由、调查结论等。 学术不端行为由多人集体做出的，调查报告中应当区别各责任人在行为中所发挥的作用。"},{"i":25,"n":"第二十五条","txt":"接触举报材料和参与调查处理的人员，不得向无关人员透露举报人、被举报人个人信息及调查情况。"},{"i":26,"n":"第二十六条","txt":"高等学校学术委员会应当对调查组提交的调查报告进行审查；必要的，应当听取调查组的汇报。 学术委员会可以召开全体会议或者授权专门委员会对被调查行为是否构成学术不端行为以及行为的性质、情节等作出认定结论，并依职权作出处理或建议学校作出相应处理。"},{"i":27,"n":"第二十七条","txt":"经调查，确认被举报人在科学研究及相关活动中有下列行为之一的，应当认定为构成学术不端行为： （一）剽窃、抄袭、侵占他人学术成果； （二）篡改他人研究成果； （三）伪造科研数据、资料、文献、注释，或者捏造事实、编造虚假研究成果； （四）未参加研究或创作而在研究成果、学术论文上署名，未经他人许可而不当使用他人署名，虚构合作者共同署名，或者多人共同完成研究而在成果中未注明他人工作、贡献； （五）在申报课题、成果、奖励和职务评审评定、申请学位等过程中提供虚假学术信息； （六）买卖论文、由他人代写或者为他人代写论文； （七）其他根据高等学校或者有关学术组织、相关科研管理机构制定的规则，属于学术不端的行为。"},{"i":28,"n":"第二十八条","txt":"有学术不端行为且有下列情形之一的，应当认定为情节严重： （一）造成恶劣影响的； （二）存在利益输送或者利益交换的； （三）对举报人进行打击报复的； （四）有组织实施学术不端行为的； （五）多次实施学术不端行为的； （六）其他造成严重后果或者恶劣影响的。"},{"i":29,"n":"第二十九条","txt":"高等学校应当根据学术委员会的认定结论和处理建议，结合行为性质和情节轻重，依职权和规定程序对学术不端行为责任人作出如下处理： （一）通报批评； （二）终止或者撤销相关的科研项目，并在一定期限内取消申请资格； （三）撤销学术奖励或者荣誉称号； （四）辞退或解聘； （五）法律、法规及规章规定的其他处理措施。 同时，可以依照有关规定，给予警告、记过、降低岗位等级或者撤职、开除等处分。 学术不端行为责任人获得有关部门、机构设立的科研项目、学术奖励或者荣誉称号等利益的，学校应当同时向有关主管部门提出处理建议。 学生有学术不端行为的，还应当按照学生管理的相关规定，给予相应的学籍处分。 学术不端行为与获得学位有直接关联的，由学位授予单位作暂缓授予学位、不授予学位或者依法撤销学位等处理。"},{"i":30,"n":"第三十条","txt":"高等学校对学术不端行为作出处理决定，应当制作处理决定书，载明以下内容： （一）责任人的基本情况； （二）经查证的学术不端行为事实； （三）处理意见和依据； （四）救济途径和期限； （五）其他必要内容。"},{"i":31,"n":"第三十一条","txt":"经调查认定，不构成学术不端行为的，根据被举报人申请，高等学校应当通过一定方式为其消除影响、恢复名誉等。 调查处理过程中，发现举报人存在捏造事实、诬告陷害等行为的，应当认定为举报不实或者虚假举报，举报人应当承担相应责任。属于本单位人员的，高等学校应当按照有关规定给予处理；不属于本单位人员的，应通报其所在单位，并提出处理建议。"},{"i":32,"n":"第三十二条","txt":"参与举报受理、调查和处理的人员违反保密等规定，造成不良影响的，按照有关规定给予处分或其他处理。"},{"i":33,"n":"第三十三条","txt":"举报人或者学术不端行为责任人对处理决定不服的，可以在收到处理决定之日起30日内，以书面形式向高等学校提出异议或者复核申请。 异议和复核不影响处理决定的执行。"},{"i":34,"n":"第三十四条","txt":"高等学校收到异议或者复核申请后，应当交由学术委员会组织讨论，并于15日内作出是否受理的决定。 决定受理的，学校或者学术委员会可以另行组织调查组或者委托第三方机构进行调查；决定不予受理的，应当书面通知当事人。"},{"i":35,"n":"第三十五条","txt":"当事人对复核决定不服，仍以同一事实和理由提出异议或者申请复核的，不予受理；向有关主管部门提出申诉的，按照相关规定执行。"},{"i":36,"n":"第三十六条","txt":"高等学校应当按年度发布学风建设工作报告，并向社会公开，接受社会监督。"},{"i":37,"n":"第三十七条","txt":"高等学校处理学术不端行为推诿塞责、隐瞒包庇、查处不力的，主管部门可以直接组织或者委托相关机构查处。"},{"i":38,"n":"第三十八条","txt":"高等学校对本校发生的学术不端行为，未能及时查处并做出公正结论，造成恶劣影响的，主管部门应当追究相关领导的责任，并进行通报。 高等学校为获得相关利益，有组织实施学术不端行为的，主管部门调查确认后，应当撤销高等学校由此获得的相关权利、项目以及其他利益，并追究学校主要负责人、直接负责人的责任。"},{"i":39,"n":"第三十九条","txt":"高等学校应当根据本办法，结合学校实际和学科特点，制定本校学术不端行为查处规则及处理办法，明确各类学术不端行为的惩处标准。有关规则应当经学校学术委员会和教职工代表大会讨论通过。"},{"i":40,"n":"第四十条","txt":"高等学校主管部门对直接受理的学术不端案件，可自行组织调查组或者指定、委托高等学校、有关机构组织调查、认定。对学术不端行为责任人的处理，根据本办法及国家有关规定执行。 教育系统所属科研机构及其他单位有关人员学术不端行为的调查与处理，可参照本办法执行。"},{"i":41,"n":"第四十一条","txt":"本办法自2016年9月1日起施行。 教育部此前发布的有关规章、文件中的相关规定与本办法不一致的，以本办法为准。"}],"gaodengjiaoyuzixuekaoshimingtigongzuoguiding":[{"i":1,"n":"第一条","txt":"为组织和管理高等教育自学考试命题工作，确保考试质量，根据国务院发布的《高等教育自学考试暂行条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"高等教育自学考试的命题与普通高等学校相应学历层次水平和质量要求相一致。"},{"i":3,"n":"第三条","txt":"高等教育自学考试命题应体现专业和课程的特点，考核应考者系统掌握课程基础知识、基本理论、基本技能和分析问题、解决问题的能力，正确引导个人自学和社会助学，树立良好学风。"},{"i":4,"n":"第四条","txt":"命题必须以国家教育委员会批准颁发试行的或省、自治区、直辖市高等教育自学考试委员会（以下简称“省考委”）颁布的课程自学考试的大纲（以下简称“考试大纲”）为依据。"},{"i":5,"n":"第五条","txt":"加强命题工作的总体规划，统一领导，严密组织，严格管理，逐步实现命题工作的科学化、标准化和管理手段的现代化。"},{"i":6,"n":"第六条","txt":"命题应按照标准化、科学化的要求进行，内容稳定、考试次数多、规模大的课程以建立题库为主的方式组织实施。"},{"i":7,"n":"第七条","txt":"命题与辅导相分离。建立健全命题工作保密制度。"},{"i":8,"n":"第八条","txt":"命题经费列入有关教育行政事业部门的年度预算；业务部门委托考试的专业和课程，命题经费由业务部门承担。"},{"i":9,"n":"第九条","txt":"高等教育自学考试命题工作由全国高等教育自学考试指导委员会（以下简称“全国考委”）统筹安排，分级管理，实行全国统一命题、省际协作命题、省级命题三级命题体制。 凡全国统一命题的课程，省考委不得另行安排和自行命题考试。 使用全国统一命题和省际协作命题试卷，省考委不得进行改动。"},{"i":10,"n":"第十条","txt":"命题工作应在全国考委或省考委领导下，由考委及其办公室负责人、课程主命题教师组成课程命题领导小组负责实施。"},{"i":11,"n":"第十一条","txt":"省考委办公室（以下简称“省考办”）应设立命题管理工作的专门机构。 开考专业十个以下（含十个）的，专职命题工作管理人员应不少于五名，每增设五个专业增加一至二名专职管理人员。"},{"i":12,"n":"第十二条","txt":"全国统一命题的课程命题教师，由全国考委办公室（以下简称“全国考办”）或委托省考办商其所在学校，经资格审查合格后，由全国考委聘任。省际协作命题、省级命题的课程，命题教师由省考办商其所在学校，经资格审查合格后，由省考委聘任。"},{"i":13,"n":"第十三条","txt":"全国统一命题每门课程的命题教师一般应不少于十人；省际协作命题每门课程的命题教师一般应不少于七人；省级命题每门课程的命题教师一般应不少于五人。每门课程组配试卷或入闱命题的教师应为二至三人。 命题教师选聘应有地区和高等学校的代表性。被聘教师所在学校应对聘任工作予以协助。"},{"i":14,"n":"第十四条","txt":"编制试题、审题、组配试卷、题库建设等必须符合有关的技术要求。"},{"i":15,"n":"第十五条","txt":"全国统一命题题库的使用由全国考委决定；协作命题题库的使用由协作省考委协商确定；省级命题题库的使用由省考委决定。 题库的贮存、保管、使用等应符合《中华人民共和国保守国家秘密法》的规定。 题库在使用过程中，应不断修改、补充和完善。省考办应具备贮存题库的设施和用房，建立题库的技术档案，配备专人负责，并积极创造条件利用计算机等现代化手段进行题库管理。"},{"i":16,"n":"第十六条","txt":"命题经费的开支标准应按国家有关规定执行。"},{"i":17,"n":"第十七条","txt":"课程主命题教师是课程命题的业务负责人。课程主命题教师应是在本学科领域内业务水平较高、教学经验丰富、治学严谨、作风正派、善于合作、身体健康并热心自学考试工作的普通高等学校的教授或副教授。 课程主命题教师的职责是： （一）负责提名和推荐本课程命题教师人选； （二）起草课程命题实施意见，设计课程试卷蓝图； （三）协助全国考办或省考办组织全体命题教师学习、讨论有关命题文件，实施命题； （四）协助全国考办或省考办组织审题教师对所命试题进行审定； （五）协助全国考办或省考办组织试卷组配工作，并对题库和考试试卷质量负责； （六）参与课程试卷的质量分析。"},{"i":18,"n":"第十八条","txt":"命题教师应是在本学科领域内业务水平较高、教学经验丰富、治学严谨、作风正派、善于合作并热心自学考试工作的普通高等学校的教授或副教授，也可以有少量在教学第一线的讲师。 命题教师必须服从安排，保质保量按时完成命题任务。"},{"i":19,"n":"第十九条","txt":"命题工作管理人员应是坚持原则、遵守纪律、作风严谨、有独立工作能力、熟悉命题工作和教育测量学等有关知识、具有大学本科以上学历的全国考办或省考办正式干部。 命题工作管理人员的职责是： （一）制定高等教育自学考试的命题规划和工作安排； （二）组织课程主命题教师制定课程命题文件，设计试卷蓝图； （三）组织实施命题，指导和参与命题、审题、组卷工作，协调和处理命题中的有关问题； （四）组织实施试题的质量分析； （五）负责题库的管理和使用。"},{"i":20,"n":"第二十条","txt":"课程命题领导小组在命题前应对命题教师进行教育测量学理论、自学考试的性质与特点等有关知识的培训，并组织试命题。"},{"i":21,"n":"第二十一条","txt":"命题组应在熟悉考试大纲的基础上制定下列文件： （一）命题实施意见； （二）试卷蓝图； （三）命题教师任务分工表； （四）样题。"},{"i":22,"n":"第二十二条","txt":"按照考试大纲和教育测量学的要求编制试题。编制的试题应做到科学、合理、不超纲；题意明确、文字通顺、表述准确严密；标点符号无误，图表绘制规范；不出现政治性、科学性错误；避免学术上有争议的问题。 试题的答案应准确、全面、简洁、规范，主观性试题应规定评分要点和评分标准。 制定评分标准，需包括对应考者的逻辑思维、综合应用和语言表述能力的要求。"},{"i":23,"n":"第二十三条","txt":"按考试大纲、命题实施意见和试卷蓝图的要求审定试题。审定合格的试题应按科学的分类方法贮入题库。"},{"i":24,"n":"第二十四条","txt":"按照试卷蓝图的规定组配试卷。 每份试卷要突出课程的重点内容，覆盖考试大纲的各章。 组配的试卷须使不同能力层次试题的分数和不同难易程度试题的分数比例适当。 每次考试必须组配若干套平行试卷，由全国考委或省考委随机确定考试试卷。"},{"i":25,"n":"第二十五条","txt":"考试结束后，全国考办及省考办应组织力量对试卷进行评估和分析，并将结果贮入题库。"},{"i":26,"n":"第二十六条","txt":"试题、试卷、答案及评分标准在使用前均属绝密材料，任何人不得以任何方式泄露。"},{"i":27,"n":"第二十七条","txt":"凡本人或有直系亲属参加本课程自学考试的人员不得参加该课程的命题工作。"},{"i":28,"n":"第二十八条","txt":"所有参加命题工作的人员不得公开其命题人员身份，不得以任何形式泄露有关命题工作的文件或情况。"},{"i":29,"n":"第二十九条","txt":"课程主命题教师、组配试卷教师、命题教师在聘期内不得参与任何形式的与该课程自学考试有关的辅导活动（包括担任助学单位的职务或名誉职务）。"},{"i":30,"n":"第三十条","txt":"所有命题教师不得以任何形式向其所在单位汇报命题工作情况。"},{"i":31,"n":"第三十一条","txt":"所有参加命题工作的人员必须遵守命题工作纪律。凡违反者，取消其命题人员资格，视情节轻重给予行政处分，触犯法律的依法追究其法律责任。"},{"i":32,"n":"第三十二条","txt":"全国考委、各省考委可根据本规定结合工作实际，制定具体实施的办法。"},{"i":33,"n":"第三十三条","txt":"本规定由国家教育委员会负责解释。"},{"i":34,"n":"第三十四条","txt":"本规定自公布之日起执行。原公布的有关命题规定凡与本规定相抵触的，以本规定为准。"}]};
